#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_EVENT_SIZE 256

typedef struct {
    time_t timestamp;
    char type[32];
    void *metadata;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventProcessor;

EventProcessor* create_event_processor() {
    EventProcessor *processor = (EventProcessor*)malloc(sizeof(EventProcessor));
    processor->events = (NetworkEvent*)calloc(INITIAL_CAPACITY, sizeof(NetworkEvent));
    processor->capacity = INITIAL_CAPACITY;
    processor->count = 0;
    pthread_mutex_init(&processor->lock, NULL);
    return processor;
}

void destroy_event_processor(EventProcessor *processor) {
    for (size_t i = 0; i < processor->count; ++i) {
        free(processor->events[i].metadata);
    }
    free(processor->events);
    pthread_mutex_destroy(&processor->lock);
    free(processor);
}

int add_event(EventProcessor *processor, time_t timestamp, const char *type, void *metadata) {
    pthread_mutex_lock(&processor->lock);
    if (processor->count >= processor->capacity) {
        size_t new_capacity = processor->capacity * 2;
        NetworkEvent *new_events = realloc(processor->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            pthread_mutex_unlock(&processor->lock);
            return -1; // Memory allocation failed
        }
        processor->events = new_events;
        processor->capacity = new_capacity;
    }
    NetworkEvent *event = &processor->events[processor->count++];
    event->timestamp = timestamp;
    strncpy(event->type, type, sizeof(event->type) - 1);
    event->metadata = metadata;
    pthread_mutex_unlock(&processor->lock);
    return 0;
}

void log_critical_event(const NetworkEvent *event) {
    // Implementation of logging critical events
    printf("Critical Event: %s at %ld\n", event->type, event->timestamp);
}

int main() {
    EventProcessor *processor = create_event_processor();

    time_t timestamp = time(NULL);
    char type[] = "ConnectionEstablished";
    void *metadata = NULL; // Placeholder for actual metadata

    add_event(processor, timestamp, type, metadata);

    log_critical_event(&processor->events[0]);

    destroy_event_processor(processor);
    return 0;
}
```

