    int opt;
    char *log_type = NULL;
    char *time_range = NULL;

    while ((opt = getopt(argc, argv, "hsl:t:")) != -1) {
        switch (opt) {
            case 'h':
                display_help();
                return 0;
            case 's':
                compute_stats();
                break;
            case 'l':
                log_type = optarg;
                break;
            case 't':
                time_range = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", opt);
                display_help();
                return 1;
        }
    }

    if (log_type && time_range) {
        // Implement log processing logic here
        printf("Processing logs of type '%s' for the time range '%s'\n", log_type, time_range);
    } else if (log_type || time_range) {
        fprintf(stderr, "Both --log-type and --time-range must be specified\n");
        display_help();
        return 1;
