#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_INT_SIZE 12

void handle_client(int client_socket);
int process_network_stream(const char *network_data);
int validate_integer(const char *data, int *number);
void store_largest_integer(int number);

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(8080);

    // Binding the socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listening for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Accepting a new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        handle_client(new_socket);
    }

    return 0;
}

void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    while ((valread = read(client_socket, buffer, 1024)) > 0) {
        buffer[valread] = '\0';
        int largest_number = process_network_stream(buffer);
        if (largest_number != -1) {
            store_largest_integer(largest_number);
        }
    }

    close(client_socket);
}

int process_network_stream(const char *network_data) {
    int *numbers = NULL;
    size_t count = 0, i = 0;
    int largest = INT_MIN;

    while (network_data[i]) {
        if (network_data[i] == '\n' || network_data[i] == ' ') {
            char temp[MAX_INT_SIZE + 1];
            strncpy(temp, &network_data[j], i - j);
            temp[i - j] = '\0';

            int number;
            if (validate_integer(temp, &number)) {
                count++;
                numbers = realloc(numbers, count * sizeof(int));
                numbers[count - 1] = number;
                if (number > largest) {
                    largest = number;
                }
            }

            j = i + 1;
        }
        i++;
    }

    free(numbers);
    return largest == INT_MIN ? -1 : largest;
}

int validate_integer(const char *data, int *number) {
    char *endptr;
    *number = strtol(data, &endptr, 10);

    if (*data == '\0' || *endptr != '\0') {
        fprintf(stderr, "Invalid integer: %s\n", data);
        return 0;
    }

    return 1;
}

void store_largest_integer(int number) {
    // Simulate database storage
    printf("Storing largest integer: %d\n", number);
}
