class ConditionLogger {
public:
    ConditionLogger(int maxCapacity)
        : maxCapacity(maxCapacity), stop(false) {}

    ~ConditionLogger() {
        stop = true;
        cv.notify_all();
        for (std::thread& t : workerThreads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

    void log(const char* condition, int code, ...) {
        std::va_list args;
        va_start(args, code);
        std::string message = formatMessage(condition, args);
        va_end(args);

        if (code < 0) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return logQueue.size() < maxCapacity; });
            logQueue.push(message);
        }
    }

private:
    int maxCapacity;
    std::queue<std::string> logQueue;
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::thread> workerThreads;
    bool stop;

    std::string formatMessage(const char* condition, va_list args) {
        // Implement message formatting logic here
        return "Formatted Log Message";
    }

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !logQueue.empty() || stop; });
            if (stop && logQueue.empty()) {
                break;
            }
            std::string message = logQueue.front();
            logQueue.pop();
            lock.unlock();

            // Implement external logging logic here
            sendToExternalService(message);
        }
    }

    void sendToExternalService(const std::string& message) {
        try {
            // Implement network communication to send the message
        } catch (...) {
            // Handle errors gracefully
        }
    }
};

int main() {
    ConditionLogger logger(10);

    for (int i = 0; i < 20; ++i) {
