    private static final Logger logger = LoggerFactory.getLogger(PokémonTournamentService.class);
    private final Map<String, PokémonData> cache = new ConcurrentHashMap<>();
    private final ScheduledExecutorService cacheScheduler = Executors.newScheduledThreadPool(1);
    private final RateLimiter rateLimiter = RateLimiter.create(5.0); // 5 requests per second
    private final ThirdPartyService thirdPartyService;
    private final TranslationService translationService;

    public PokémonTournamentService() {
        cacheScheduler.scheduleAtFixedRate(this::updateCache, 0, 15, TimeUnit.MINUTES);
        this.thirdPartyService = new ThirdPartyService();
        this.translationService = new TranslationService();
    }

    @GET
    @Path("/strategy")
    @Produces(MediaType.APPLICATION_JSON)
    public Response getStrategyReport(@QueryParam("user") String user,
                                      @QueryParam("language") String language) {
        if (!rateLimiter.tryAcquire()) {
            return Response.status(Response.Status.TOO_MANY_REQUESTS).build();
        }

        PokémonData data = cache.get(user);
        if (data == null) {
            data = fetchPokémonData(user);
            if (data == null) {
                return Response.status(Response.Status.SERVICE_UNAVAILABLE).build();
            }
            cache.put(user, data);
        }

        String translatedRecommendations = translationService.translate(data.getStrategy(), language);
        if (translatedRecommendations == null) {
            logger.error("Failed to translate strategy for user: {}", user);
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).build();
        }

        return Response.ok(new StrategyReport(translatedRecommendations)).build();
    }

    private PokémonData fetchPokémonData(String user) {
        try {
            PokémonData data = thirdPartyService.getPokémonData(user);
            logger.info("Fetched Pokémon data for user: {}", user);
            return data;
