}

// Function to initialize the library
void init_library() {
    pthread_mutex_lock(&lock);
    if(time(NULL) - last_update_time > 3600) { // Update every hour
        load_algorithms();
        last_update_time = time(NULL);
    }
    pthread_mutex_unlock(&lock);
}

// Function to get a cryptographic algorithm by name
CryptoAlgorithm* get_algorithm(const char* name) {
    for(int i = 0; i < algorithm_count; i++) {
        if(strcmp(algorithms[i]->name, name) == 0)
            return algorithms[i];
    }
    return NULL;
}

// Function to encrypt data using a cryptographic algorithm
int encrypt_data(const CryptoAlgorithm* algo, const unsigned char* plaintext, int plaintext_len, unsigned char** ciphertext, int* ciphertext_len) {
    *ciphertext = (unsigned char*)malloc(EVP_CIPHER_block_size(algo->ctx));
    if(!*ciphertext)
        return -1;

    EVP_EncryptInit_ex(algo->ctx, NULL, NULL, NULL, NULL);
    if(!EVP_EncryptUpdate(algo->ctx, *ciphertext, ciphertext_len, plaintext, plaintext_len))
        return -1;
    if(!EVP_EncryptFinal_ex(algo->ctx, (*ciphertext) + *ciphertext_len, &plaintext_len))
        return -1;

    *ciphertext_len += plaintext_len;
    return 0;
}

// Function to decrypt data using a cryptographic algorithm
int decrypt_data(const CryptoAlgorithm* algo, const unsigned char* ciphertext, int ciphertext_len, unsigned char** plaintext, int* plaintext_len) {
    *plaintext = (unsigned char*)malloc(ciphertext_len);
    if(!*plaintext)
        return -1;

    EVP_DecryptInit_ex(algo->ctx, NULL, NULL, NULL, NULL);
    if(!EVP_DecryptUpdate(algo->ctx, *plaintext, plaintext_len, ciphertext, ciphertext_len))
        return -1;
    if(!EVP_DecryptFinal_ex(algo->ctx, (*plaintext) + *plaintext_len, &ciphertext_len))
        return -1;

    *plaintext_len += ciphertext_len;
    return 0;
}

// Function to free resources
void cleanup_library() {
    for(int i = 0; i < algorithm_count; i++) {
        EVP_CIPHER_CTX_free(algorithms[i]->ctx);
        free(algorithms[i]);
    }
    free(algorithms);
    free(api_cache);
}
