#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <string.h>

#define MAX_SEMAPHORES 1000

typedef struct {
    sem_t *sema;
    char name[50];
    int id;
} Semaphore;

Semaphore semaphore_pool[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t pool_lock;

void log_semaphore_operation(char* operation, int id) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    printf("%s: %s semaphore with ID %d\n", asctime(tm_info), operation, id);
}

int create_semaphore(const char* name, unsigned int value) {
    pthread_mutex_lock(&pool_lock);
    if (semaphore_count >= MAX_SEMAPHORES) {
        log_semaphore_operation("Error", -1);
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    Semaphore new_sema = {sem_init(name, 0, value), strdup(name), semaphore_count};
    if (new_sema.sema == SEM_FAILED || new_sema.name == NULL) {
        log_semaphore_operation("Error", -1);
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    semaphore_pool[semaphore_count++] = new_sema;
    log_semaphore_operation("Created", new_sema.id);
    pthread_mutex_unlock(&pool_lock);
    return new_sema.id;
}

int delete_semaphore(int id) {
    pthread_mutex_lock(&pool_lock);
    if (id < 0 || id >= semaphore_count) {
        log_semaphore_operation("Error", -1);
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    Semaphore sema = semaphore_pool[id];
    if (sem_destroy(sema.sema) == -1) {
        log_semaphore_operation("Error", -1);
        pthread_mutex_unlock(&pool_lock);
        return -1;
    }

    free(sema.name);
    for (int i = id; i < semaphore_count - 1; i++) {
        semaphore_pool[i] = semaphore_pool[i + 1];
    }
    semaphore_count--;
    log_semaphore_operation("Deleted", id);
    pthread_mutex_unlock(&pool_lock);
    return 0;
}

void* monitor_thread(void* arg) {
    while (1) {
        // Implement monitoring logic here
        // Check for abnormal activities and log them
        // Send real-time alerts if necessary
        sleep(1); // Simulate monitoring every second
    }
    return NULL;
}

int main() {
    pthread_mutex_init(&pool_lock, NULL);

    pthread_t monitor_tid;
    pthread_create(&monitor_tid, NULL, monitor_thread, NULL);

    create_semaphore("semaphore1", 1);
    create_semaphore("semaphore2", 5);
    delete_semaphore(0);

    pthread_join(monitor_tid, NULL);

    return 0;
}
