#include <forward_list>
#include <string>
#include <ctime>
#include <cstdarg>
#include <cstdio>

void logError(const char* format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(nullptr);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] Error: ", timestamp);
    vprintf(format, args);
    printf("\n");
    va_end(args);
}

void insertAfterOrLog(std::forward_list<std::string>& metadata, const std::string& target, const std::string& insert) {
    auto it = metadata.before_begin();
    for (auto prev = metadata.begin(); prev != metadata.end(); ++prev, ++it) {
        if (*prev == target) {
            try {
                it = metadata.insert_after(it, insert);
            } catch (...) {
                logError("Failed to insert '%s' after '%s': %s", insert.c_str(), target.c_str(), "Memory allocation failure");
                return;
            }
            return;
        }
    }
    try {
        metadata.push_back(insert);
    } catch (...) {
        logError("Failed to append '%s': %s", insert.c_str(), "Memory allocation failure");
    }
}
