#include <mutex>
#include <random>
#include <chrono>
#include <string>
#include <yaml-cpp/yaml.h>
#include <glog/logging.h>

namespace random_generator {

class ThreadSafeGenerator {
public:
    static ThreadSafeGenerator& getInstance() {
        static std::once_flag initFlag;
        std::call_once(initFlag, &ThreadSafeGenerator::init);
        return instance_;
    }

    void seed(uint32_t seed) {
        std::lock_guard<std::mutex> lock(mutex_);
        generator_.seed(seed);
    }

    uint32_t generate() {
        std::lock_guard<std::mutex> lock(mutex_);
        return generator_();
    }

private:
    ThreadSafeGenerator() : reseeder_(std::chrono::system_clock::now()) {}

    static void init() {
        instance_ = new ThreadSafeGenerator();
    }

    ~ThreadSafeGenerator() {}

    void reseedIfNecessary() {
        auto now = std::chrono::system_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - reseeder_).count() > 60) {
            reseeder_ = now;
            uint32_t seed = static_cast<uint32_t>(now.time_since_epoch().count());
            instance_->generator_.seed(seed);
        }
    }

    static ThreadSafeGenerator* instance_;
    std::mutex mutex_;
    std::mt19937 generator_;
    std::chrono::system_clock::time_point reseeder_;
};

ThreadSafeGenerator* ThreadSafeGenerator::instance_ = nullptr;

}  // namespace random_generator
