public class QueryService : IQueryService
{
    private readonly string _connectionString;
    private readonly ILogger<QueryService> _logger;

    public QueryService(IConfiguration configuration, ILogger<QueryService> logger)
    {
        _connectionString = configuration.GetConnectionString("RemoteDatabase");
        _logger = logger;
    }

    public async Task ExecuteAsync(string query, object parameters = null)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(query, connection))
                {
                    if (parameters != null)
                        command.Parameters.AddRange((SqlParameter[])parameters);

                    var result = await command.ExecuteNonQueryAsync();
                    _logger.LogInformation($"Executed query '{query}' with {result} rows affected.");
                }
            }
        }
        catch (SqlException ex)
        {
            _logger.LogError(ex, "Error executing query: {Query}", query);
            throw;
        }
    }

    public async Task<T> QueryAsync<T>(string query, object parameters = null)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                using (var command = new SqlCommand(query, connection))
                {
                    if (parameters != null)
                        command.Parameters.AddRange((SqlParameter[])parameters);

                    var result = await command.ExecuteScalarAsync<T>();
                    _logger.LogInformation($"Executed query '{query}' with result: {result}");
                    return result;
                }
            }
        }
        catch (SqlException ex)
        {
            _logger.LogError(ex, "Error executing query: {Query}", query);
            throw;
        }
    }

    // Additional methods and properties can be added here to meet the requirements.
}
