using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public interface IConfigurationService
{
    Task UpdateConfigurationAsync();
    T GetSetting<T>(string key);
}

public class ConfigurationService : IConfigurationService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, object> _configurationCache;
    private readonly string _apiUrl;
    private static readonly TimeSpan CacheExpiry = TimeSpan.FromMinutes(10);

    public ConfigurationService(HttpClient httpClient, string apiUrl)
    {
        _httpClient = httpClient;
        _configurationCache = new ConcurrentDictionary<string, object>();
        _apiUrl = apiUrl;
    }

    public async Task UpdateConfigurationAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync(_apiUrl);
            if (response.IsSuccessStatusCode)
            {
                var settingsJson = await response.Content.ReadAsStringAsync();
                var settings = JsonSerializer.Deserialize<Dictionary<string, object>>(settingsJson);

                foreach (var kvp in settings)
                {
                    if (_configurationCache.TryAdd(kvp.Key, kvp.Value) || _configurationCache.TryUpdate(kvp.Key, kvp.Value, _configurationCache[kvp.Key]))
                    {
                        LogConfigurationChange(kvp.Key, kvp.Value);
                    }
                }

                ClearExpiredCaches();
            }
            else
            {
                LogError($"Failed to fetch configuration. Status code: {response.StatusCode}");
            }
        }
        catch (Exception ex)
        {
            LogError($"An error occurred while fetching configuration: {ex.Message}");
        }
    }

    public T GetSetting<T>(string key)
    {
        if (_configurationCache.TryGetValue(key, out var value))
        {
            return Convert.ChangeType(value, typeof(T));
        }

        throw new KeyNotFoundException($"Configuration setting not found for key: {key}");
    }

    private void LogConfigurationChange(string key, object value)
    {
        Debug.WriteLine($"Configuration changed - Key: {key}, Value: {value}");
    }

    private void LogError(string message)
    {
        Debug.WriteLine(message);
    }

    private void ClearExpiredCaches()
    {
        var now = DateTime.UtcNow;
        foreach (var kvp in _configurationCache.ToList())
        {
            if ((now - kvp.Value.GetType().GetProperty("Timestamp").GetValue(kvp.Value)).TotalMinutes > CacheExpiry.TotalMinutes)
            {
                _configurationCache.TryRemove(kvp.Key, out _);
            }
        }
    }
}

public static class HttpClientExtensions
{
    public static async Task<string> ReadAsStringAsync(this HttpResponseMessage response)
    {
        using (var stream = await response.Content.ReadAsStreamAsync())
        using (var reader = new System.IO.StreamReader(stream))
        {
            return await reader.ReadToEndAsync();
        }
    }
}
```

