package main

import (
    "database/sql"
    "encoding/json"
    "errors"
    "fmt"
    "log"
    "net/http"
    "sync/atomic"

    _ "github.com/go-sql-driver/mysql"
    "gopkg.in/go-playground/validator.v10"
)

var db *sql.DB
var nextID uint64 = 1

type Resource struct {
    ID      uint64 `json:"id" validate:"required"`
    Name    string `json:"name" validate:"required"`
    Updated int64  `json:"updated"`
}

func init() {
    var err error
    db, err = sql.Open("mysql", "user:password@tcp(127.0.0.1:3306)/dbname")
    if err != nil {
        log.Fatal(err)
    }
    defer db.Close()

    // Create table if not exists
    _, err = db.Exec(`
        CREATE TABLE IF NOT EXISTS resources (
            id BIGINT AUTO_INCREMENT PRIMARY KEY,
            name VARCHAR(255) NOT NULL,
            updated BIGINT NOT NULL
        )
    `)
    if err != nil {
        log.Fatal(err)
    }
}

func updateResource(w http.ResponseWriter, r *http.Request) {
    var resource Resource
    decoder := json.NewDecoder(r.Body)
    err := decoder.Decode(&resource)
    if err != nil {
        http.Error(w, "Invalid request payload", http.StatusBadRequest)
        return
    }

    // Validate input
    validate := validator.New()
    err = validate.Struct(resource)
    if err != nil {
        http.Error(w, "Validation failed", http.StatusUnprocessableEntity)
        return
    }

    currentVersion := atomic.LoadInt64(&resource.Updated)

    // Lock record for update (optimistic locking)
    rows, err := db.Query("SELECT id FROM resources WHERE id = ? FOR UPDATE", resource.ID)
    if err != nil {
        http.Error(w, "Internal server error", http.StatusInternalServerError)
        return
    }
    defer rows.Close()

    if !rows.Next() {
        http.Error(w, "Resource not found", http.StatusNotFound)
        return
    }

    var lockedID uint64
    err = rows.Scan(&lockedID)
    if err != nil {
        http.Error(w, "Internal server error", http.StatusInternalServerError)
        return
    }

    // Check version
    if lockedID != resource.ID {
        http.Error(w, "Version mismatch", http.StatusConflict)
        return
    }

    // Update resource
    _, err = db.Exec("UPDATE resources SET name = ?, updated = ? WHERE id = ?", resource.Name, atomic.AddInt64(&resource.Updated, 1), resource.ID)
    if err != nil {
        http.Error(w, "Internal server error", http.StatusInternalServerError)
        return
    }

    // Log audit trail
    log.Printf("Resource %d updated by user: %s at %v", resource.ID, r.Header.Get("X-User-ID"), time.Now())

    w.WriteHeader(http.StatusOK)
}

func deleteResource(w http.ResponseWriter, r *http.Request) {
    idStr := r.URL.Query().Get("id")
    if idStr == "" {
        http.Error(w, "Missing resource ID", http.StatusBadRequest)
        return
    }

    id, err := strconv.ParseUint(idStr, 10, 64)
    if err != nil {
        http.Error(w, "Invalid resource ID", http.StatusBadRequest)
        return
    }

    // Soft delete (could also be hard delete with cascade or trigger)
    _, err = db.Exec("UPDATE resources SET deleted_at = NOW() WHERE id = ?", id)
    if err != nil {
        http.Error(w, "Internal server error", http.StatusInternalServerError)
        return
    }

    // Log audit trail
    log.Printf("Resource %d deleted by user: %s at %v", id, r.Header.Get("X-User-ID"), time.Now())

    w.WriteHeader(http.StatusOK)
}

func main() {
    mux := http.NewServeMux()
    mux.HandleFunc("/update", updateResource)
    mux.HandleFunc("/delete", deleteResource)

    log.Println("Starting server on :8080")
    if err := http.ListenAndServe(":8080", mux); err != nil {
        log.Fatal(err)
    }
}
