import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.http.ResponseEntity;
import javax.transaction.Transactional;
import java.util.Optional;

@Service
public class ResourceService {

    private final ResourceRepository resourceRepository;

    public ResourceService(ResourceRepository resourceRepository) {
        this.resourceRepository = resourceRepository;
    }

    @PutMapping("/resources/{id}")
    @Transactional
    public ResponseEntity<Resource> updateResource(@PathVariable Long id, @RequestBody UpdateRequest request) {
        try {
            Optional<Resource> existingResource = resourceRepository.findById(id);
            if (!existingResource.isPresent()) {
                return ResponseEntity.notFound().build();
            }

            Resource updatedResource = existingResource.get();
            updatedResource.setVersion(existingResource.get().getVersion() + 1);
            BeanUtils.copyProperties(request, updatedResource);

            Resource savedResource = resourceRepository.save(updatedResource);
            return ResponseEntity.ok(savedResource);
        } catch (Exception e) {
            // Log exception and retry logic
            return ResponseEntity.status(500).build();
        }
    }

    @DeleteMapping("/resources/{id}")
    public ResponseEntity<Resource> deleteResource(@PathVariable Long id) {
        try {
            Optional<Resource> existingResource = resourceRepository.findById(id);
            if (!existingResource.isPresent()) {
                return ResponseEntity.notFound().build();
            }

            Resource deletedResource = existingResource.get();
            deletedResource.setIsDeleted(true);

            Resource savedResource = resourceRepository.save(deletedResource);
            return ResponseEntity.ok(savedResource);
        } catch (Exception e) {
            // Log exception and retry logic
            return ResponseEntity.status(500).build();
        }
    }
}
