<?php

// Define the UserAccount class for handling CRUD operations
class UserAccount {
    private $db;
    private $authService;

    public function __construct($databaseConnection, $authenticationService) {
        $this->db = $databaseConnection;
        $this->authService = $authenticationService;
    }

    public function createUser($data) {
        // Sanitize and validate input
        $username = filter_var($data['username'], FILTER_SANITIZE_STRING);
        $email = filter_var($data['email'], FILTER_SANITIZE_EMAIL);
        $password = password_hash($data['password'], PASSWORD_DEFAULT);

        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new Exception("Invalid email format.");
        }

        // Insert user data into the database
        $stmt = $this->db->prepare("INSERT INTO users (username, email, password) VALUES (?, ?, ?)");
        $stmt->execute([$username, $email, $password]);

        return $stmt->rowCount();
    }

    public function readUser($id) {
        // Fetch user data from the database
        $stmt = $this->db->prepare("SELECT * FROM users WHERE id = ?");
        $stmt->execute([$id]);
        return $stmt->fetch(PDO::FETCH_ASSOC);
    }

    public function updateUser($id, $data) {
        // Sanitize and validate input
        $username = filter_var($data['username'], FILTER_SANITIZE_STRING);
        $email = filter_var($data['email'], FILTER_SANITIZE_EMAIL);

        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new Exception("Invalid email format.");
        }

        // Update user data in the database
        $stmt = $this->db->prepare("UPDATE users SET username = ?, email = ? WHERE id = ?");
        $stmt->execute([$username, $email, $id]);

        return $stmt->rowCount();
    }

    public function deleteUser($id) {
        // Delete user data from the database
        $stmt = $this->db->prepare("DELETE FROM users WHERE id = ?");
        $stmt->execute([$id]);

        return $stmt->rowCount();
    }
}

// Define the AuthenticationService class for external authentication
class AuthenticationService {
    private $authClient;

    public function __construct($client) {
        $this->authClient = $client;
    }

    public function authenticateUser($username, $password) {
        // Authenticate user using an external service
        return $this->authClient->authenticate($username, $password);
    }
}

// Define the DatabaseConnection class for handling database connections
class DatabaseConnection {
    private $pdo;

    public function __construct($dsn, $username, $password) {
        try {
            $this->pdo = new PDO($dsn, $username, $password);
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            throw new Exception("Database connection failed: " . $e->getMessage());
        }
    }

    public function getConnection() {
        return $this->pdo;
    }
}

// Define the Application class to handle incoming requests
class Application {
    private $userAccountService;

    public function __construct($dbConnection, $authService) {
        $this->userAccountService = new UserAccount($dbConnection, $authService);
    }

    public function handleRequest($request) {
        switch ($request['method']) {
            case 'POST':
                return $this->handleCreateUserRequest($request);
            case 'GET':
                return $this->handleReadUserRequest($request);
            case 'PUT':
                return $this->handleUpdateUserRequest($request);
            case 'DELETE':
                return $this->handleDeleteUserRequest($request);
        }
    }

    private function handleCreateUserRequest($request) {
        try {
            $userAccount = $this->userAccountService->createUser($request['data']);
            return ['status' => 'success', 'message' => 'User created successfully.', 'data' => $userAccount];
        } catch (Exception $e) {
            return ['status' => 'error', 'message' => $e->getMessage()];
        }
    }

    private function handleReadUserRequest($request) {
        try {
            $user = $this->userAccountService->readUser($request['id']);
            return ['status' => 'success', 'data' => $user];
        } catch (Exception $e) {
            return ['status' => 'error', 'message' => $e->getMessage()];
        }
    }

    private function handleUpdateUserRequest($request) {
        try {
            $userAccount = $this->userAccountService->updateUser($request['id'], $request['data']);
            return ['status' => 'success', 'message' => 'User updated successfully.', 'data' => $userAccount];
        } catch (Exception $e) {
            return ['status' => 'error', 'message' => $e->getMessage()];
        }
    }

    private function handleDeleteUserRequest($request) {
        try {
            $userAccount = $this->userAccountService->deleteUser($request['id']);
            return ['status' => 'success', 'message' => 'User deleted successfully.', 'data' => $userAccount];
        } catch (Exception $e) {
            return ['status' => 'error', 'message' => $e->getMessage()];
        }
    }
}

// Example usage
$dbConnection = new DatabaseConnection('mysql:host=localhost;dbname=testdb', 'username', 'password');
$authService = new AuthenticationService(new ExternalAuthenticationClient());
$app = new Application($dbConnection, $authService);

$request = ['method' => 'POST', 'data' => ['username' => 'john_doe', 'email' => 'john@example.com', 'password' => 'secure_password']];
$response = $app->handleRequest($request);
echo json_encode($response);
