const winston = require('winston');

const app = express();
const config = {
  storageServiceUrl: 'https://api.externalstorage.com',
  concurrencyLevel: 5,
  transformationFunctions: {
    default: (data) => data.toUpperCase(),
  },
};

app.use(express.json());

// Setup Winston Logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.Console(),
  ],
});

const readAndProcessFiles = async (directory) => {
  try {
    const files = await fs.readdir(directory);
    const tasks = files.map(async (file) => {
      const filePath = path.join(directory, file);
      const fileStat = await fs.stat(filePath);
      if (fileStat.isDirectory()) {
        return readAndProcessFiles(filePath);
      }
      const data = await fs.readFile(filePath, 'utf8');
      const transformationFunction = config.transformationFunctions.default;
      const transformedData = transformationFunction(data);
      logger.info(`Processed file ${filePath}`);
      return transformedData;
    });
    const results = await Promise.all(tasks.slice(0, config.concurrencyLevel));
    return results.flat();
  } catch (error) {
    logger.error('Error processing files:', error);
    throw error;
  }
};

app.post('/process-files', async (req, res) => {
  try {
    const { directory } = req.body;
    if (!directory) {
      return res.status(400).json({ message: 'Directory path is required' });
    }
    const results = await readAndProcessFiles(directory);
    res.json(results);
  } catch (error) {
    logger.error('Error in /process-files:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
