function runTests(moduleName, testCases, externalDataSources, mockLib) {
    let module;
    const maxRetries = 3;
    const dataFetchTimeout = 10000; // 10 seconds

    function loadModule() {
        for (let attempt = 1; attempt <= maxRetries; attempt++) {
            try {
                module = require(moduleName);
                return true;
            } catch (error) {
                if (attempt === maxRetries) {
                    console.error(`Failed to load ${moduleName} after ${maxRetries} attempts.`);
                    return false;
                }
                console.log(`Attempt ${attempt} failed. Retrying...`);
            }
        }
    }

    function fetchExternalData() {
        const failedSources = [];
        return Promise.all(externalDataSources.map(source => 
            new Promise((resolve, reject) => {
                setTimeout(() => {
                    try {
                        const data = fetchDataFromUrl(source);
                        resolve(data);
                    } catch (error) {
                        console.error(`Failed to fetch data from ${source}. Using default values.`);
                        resolve(null); // Use default values or handle accordingly
                    }
                }, dataFetchTimeout);
            })
        )).catch(error => {
            failedSources.push(error.message);
            return null; // Fallback mechanism for data sources
        }).then(data => ({ data, failedSources }));
    }

    function runTestCase(testCase) {
        console.log(`[TEST] ${moduleName} - ${testCase.name}`);
        mockLib.reset(); // Reset the mock library
        try {
            testCase.callback(module);
        } catch (error) {
            console.error(`Test case ${testCase.name} failed:`, error);
        }
    }

    function logSummary(successfulTests, totalTests, failures) {
        console.log(`${totalTests} tests executed.`);
        console.log(`${successfulTests} tests successful.`);
        if (failures.length > 0) {
            console.log('Failures encountered:');
            failures.forEach(failure => console.error(failure));
        }
    }

    if (!loadModule()) {
        return;
    }

    fetchExternalData().then(({ data, failedSources }) => {
        let successfulTests = 0;
        const failures = [];
        for (let testCase of testCases) {
            if (testCase.name.startsWith('skip_') || (testConfig.skipList && testConfig.skipList.includes(testCase.name))) {
                console.log(`Skipping ${testCase.name}`);
                continue;
            }
            try {
                runTestCase(testCase);
                successfulTests++;
            } catch (error) {
                failures.push(error.message);
            }
        }
        logSummary(successfulTests, testCases.length, failures);
    }).catch(error => {
        console.error('Error fetching external data:', error);
    });
}
