        results = {}
        for future in futures.as_completed(futures):
            document_id = futures[future]
            try:
                result = future.result()
                results.update(result)
            except Exception as e:
                self.log_error(document_id, str(e))
        return results

    def process_document(self, doc):
        locations = self.extract_locations(doc)
        normalized_locations = self.normalize_locations(locations)
        geolocation_data = self.get_geolocation(normalized_locations)
        return {loc: count for loc, count in geolocation_data.items() if count > 1}

    def extract_locations(self, text):
