function renderFooterScripts(scripts, config) {
  const { useCDN, fallbackToLocal, enableLazyLoading, logLevel } = config;
  const scriptsContainer = document.querySelector('footer');

  if (!scriptsContainer) {
    console.error('Footer container not found');
    return;
  }

  scripts.forEach(script => {
    const scriptElement = document.createElement('script');
    scriptElement.src = useCDN ? `https://cdn.example.com/${script.key}.js` : script.src;
    scriptElement.type = script.type;

    if (enableLazyLoading && ['text/javascript', 'application/json'].includes(script.type)) {
      scriptElement.async = true;
      scriptElement.defer = true;
    }

    scriptElement.onload = () => {
      console.log(`Script loaded successfully: ${script.key}`);
    };

    scriptElement.onerror = () => {
      if (fallbackToLocal) {
        scriptElement.src = useCDN ? `/assets/js/${script.key}.js` : script.src;
        scriptElement.onload();
      } else {
        logError(`Failed to load script: ${script.key}`, logLevel);
      }
    };

    scriptsContainer.appendChild(scriptElement);
  });
}

function logError(message, level) {
  if (level === 'debug') {
    console.debug(message);
  } else if (level === 'info') {
    console.info(message);
  } else if (level === 'warn') {
    console.warn(message);
  } else if (level === 'error') {
    console.error(message);
  }
}
