            var fullUrl = url.replace(':id', resourceId);
            if (cache[fullUrl]) {
                return $q.when(cache[fullUrl]);
            }
            return $http.get(fullUrl).then(function(response) {
                cache[fullUrl] = response.data;
                return response.data;
            }, function(error) {
                console.error("Failed to fetch data for resource ID: " + resourceId);
                return $q.reject(error);
            });
        })).then(function(updatedDataArray) {
            var updatedFields = {};
            fieldNames.forEach(function(fieldName, index) {
                if (updatedDataArray[index] && updatedDataArray[index][fieldName]) {
                    updatedFields[fieldName] = updatedDataArray[index][fieldName];
                }
            });
            return updatedFields;
        }).then(function(updatedFields) {
            var bookMentions = Object.keys(updatedFields).reduce(function(accumulator, fieldName) {
                var fieldContent = updatedFields[fieldName].replace(/[^\w\s]/gi, '').toLowerCase();
                var mentions = fieldContent.match(bookRegex);
                if (mentions) {
                    accumulator[fieldName] = mentions;
                }
                return accumulator;
            }, {});
            return bookMentions;
        }).catch(function(error) {
            console.error("Error refreshing fields for resource ID: " + resourceId);
            return $q.reject(error);
        });
    };

    // Method to update the list of Old Testament books
    service.updateOldTestamentBooks = function(newBooks) {
        oldTestamentBooks = newBooks;
        bookRegex = new RegExp("\\b(" + oldTestamentBooks.join("|") + ")\\b", "gi");
    };
}]);
