// stream-manager.js

import axios from 'axios';
import LRU from 'lru-cache';

const cache = new LRU({ max: 100 });

async function fetchData(url) {
    try {
        const response = await axios.get(url);
        return response.data;
    } catch (error) {
        console.error(`Failed to fetch data from ${url}:`, error);
        throw error;
    }
}

async function cacheBitmaps(bitmaps) {
    bitmaps.forEach(bitmap => {
        if (!cache.has(bitmap.id)) {
            cache.set(bitmap.id, bitmap);
        }
    });
}

async function fetchAndCacheThemeBitmaps(themeId, retryCount = 0, maxRetries = 3) {
    const url = `https://api.example.com/themes/${themeId}/bitmaps`;
    try {
        const bitmaps = await fetchData(url);
        await cacheBitmaps(bitmaps);
    } catch (error) {
        if (retryCount < maxRetries) {
            const backoffTime = Math.pow(2, retryCount) * 100;
            setTimeout(() => fetchAndCacheThemeBitmaps(themeId, retryCount + 1), backoffTime);
        } else {
            console.error(`Failed to cache theme bitmaps after ${maxRetries} retries`);
        }
    }
}

export default {
    pause: () => {},
    resume: () => {},
    loadThemeBitmaps: (themeId) => fetchAndCacheThemeBitmaps(themeId),
    getBitmap: (bitmapId) => cache.get(bitmapId)
};
