async function mergeBuffer(...dataChunks) {
    // Initialize buffer
    let unifiedBuffer = new Uint8Array(0);

    // Error handling for malformed data or network timeouts
    try {
        for (let chunk of dataChunks) {
            if (!isValidChunk(chunk)) {
                throw new Error('Malformed data chunk');
            }

            // Asynchronously process and merge chunks
            unifiedBuffer = await mergeAsync(unifiedBuffer, chunk);
        }
    } catch (error) {
        console.error('Error merging buffer:', error.message);
        return null;
    }

    return unifiedBuffer;
}

// Helper function to check if a data chunk is valid
function isValidChunk(chunk) {
    // Implement validation logic here
    return true;
}

// Asynchronous function to merge chunks efficiently
async function mergeAsync(buffer, chunk) {
    // Use asynchronous operations to avoid blocking the main thread
    const newBuffer = new Uint8Array(buffer.length + chunk.length);
    newBuffer.set(buffer);
    newBuffer.set(chunk, buffer.length);

    return newBuffer;
}

// Example usage
(async () => {
    try {
        const dataChunks = [
            new Uint8Array([1, 2, 3]),
            new Uint8Array([4, 5, 6]),
            new Uint8Array([7, 8, 9])
        ];

        const unifiedBuffer = await mergeBuffer(...dataChunks);
        console.log('Unified Buffer:', unifiedBuffer);
    } catch (error) {
        console.error('Error in main execution:', error.message);
    }
})();
