['```java
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class DisjointPairService {

    private static final int MAX_INT = Integer.MAX_VALUE;
    private static final int MIN_INT = Integer.MIN_VALUE;
    private final ConcurrentHashMap<Integer, Integer> parentMap;
    private final ConcurrentHashMap<Integer, Integer> rankMap;
    private final ReentrantLock lock;

    public DisjointPairService() {
        this.parentMap = new ConcurrentHashMap<>();
        this.rankMap = new ConcurrentHashMap<>();
        this.lock = new ReentrantLock();
    }

    public void addElement(int element) {
        lock.lock();
        try {
            if (!parentMap.containsKey(element)) {
                parentMap.put(element, element);
                rankMap.put(element, 0);
            }
        } finally {
            lock.unlock();
        }
    }

    public boolean areDisjoint(int a, int b) {
        long startTime = System.nanoTime();
        int rootA = find(a);
        int rootB = find(b);

        if (rootA != rootB) {
            addElement(rootA);
            addElement(rootB);
            parentMap.put(rootA, rootB);
        }

        long endTime = System.nanoTime();
        logExecutionTime(startTime, endTime);
        return rootA == rootB;
    }

    private int find(int element) {
        if (!parentMap.containsKey(element)) {
            return element;
        }
        int parent = parentMap.get(element);
        if (parent != element) {
            parentMap.put(element, find(parent)); // Path compression
        }
        return parent;
    }

    private void logExecutionTime(long startTime, long endTime) {
        System.out.println("Execution time: " + (endTime - startTime) + " ns");
    }

    public static void main(String[] args) {
        DisjointPairService service = new DisjointPairService();
        service.addElement(1);
        service.addElement(2);
        service.addElement(3);

        System.out.println(service.areDisjoint(1, 2)); // Should return true
        System.out.println(service.areDisjoint(2, 3)); // Should return false
    }
}
