public class SecureConnectionService {
    public static void main(String[] args) {
        // Initialize the server with NIO selector and port
        int port = 8080;
        ServerSocketChannel serverChannel = ServerSocketChannel.open();
        serverChannel.bind(new InetSocketAddress(port));
        serverChannel.configureBlocking(false);

        // Create a selector to manage channels
        Selector selector = Selector.open();

        // Register the server channel with the selector for ACCEPT events
        serverChannel.register(selector, SelectionKey.OP_ACCEPT);

        // Start handling connections in an infinite loop
        while (true) {
            selector.select();
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isAcceptable()) {
                    // Accept new connections
                    SocketChannel clientChannel = serverChannel.accept();
                    clientChannel.configureBlocking(false);
                    clientChannel.register(selector, SelectionKey.OP_READ);

                    // Authenticate and cache the session
                    authenticateAndCacheSession(clientChannel);
                } else if (key.isReadable()) {
                    // Handle incoming data from clients
                    SocketChannel clientChannel = (SocketChannel) key.channel();
                    handleIncomingData(clientChannel);
                }

                // Remove processed keys to avoid re-processing them
                keyIterator.remove();
            }
        }
    }

