// src/compilation.rs
use std::time::{Instant, SystemTime};
use std::process::Command;
use log::{info, error};
use rustc_driver::catch_with_exit_code;

struct Compiler {
    config_path: String,
}

impl Compiler {
    fn new(config_path: String) -> Self {
        Compiler { config_path }
    }

    fn load_config(&self) -> Result<(), Box<dyn std::error::Error>> {
        // Load and parse the TOML configuration file
        toml::from_str(include_str!(self.config_path.as_str()))?;
        Ok(())
    }

    fn install_logging_hooks(&self) {
        log::set_logger(&structlog::logger()).unwrap();
        log::set_max_level(log::LevelFilter::Info);
    }

    fn measure_metrics<F>(&self, func: F) -> Result<(), Box<dyn std::error::Error>>
    where
        F: FnOnce() -> Result<(), Box<dyn std::error::Error>>,
    {
        let start = Instant::now();
        let rss_before = get_resident_set_size();
        let result = catch_with_exit_code(func)?;
        let elapsed = start.elapsed().as_secs_f64();
        let rss_after = get_resident_set_size();
        info!("Compilation time: {} seconds", elapsed);
        info!("Resident set size before: {} bytes, after: {} bytes", rss_before, rss_after);
        Ok(result)
    }

    fn compile(&self) -> Result<i32, Box<dyn std::error::Error>> {
        self.load_config()?;
        self.install_logging_hooks();
        self.measure_metrics(|| {
            // Simulate compilation using rustc_driver
            let output = Command::new("rustc")
                .arg("--crate-type=bin")
                .arg("src/main.rs")
                .output()?;
            if !output.status.success() {
                early_error(log::Level::Error, "Compilation failed");
            }
            Ok(())
        })?;
        info!("Compilation successful");
        Ok(0)
    }
}

