### C Code for `createAndDeleteSemaphore`

```c
#include <stdio.h>
#include <semaphore.h>

sem_t semaphore;

int createSemaphore(int initialValue) {
    if (sem_init(&semaphore, 0, initialValue) != 0) {
        perror("Failed to initialize semaphore");
        return -1;
    }
    printf("Semaphore initialized with value %d\n", initialValue);
    return 0;
}

void deleteSemaphore() {
    if (sem_destroy(&semaphore) != 0) {
        perror("Failed to destroy semaphore");
    } else {
        printf("Semaphore destroyed successfully\n");
    }
}

void acquireSemaphore() {
    sem_wait(&semaphore);
    printf("Acquired semaphore by thread %ld\n", pthread_self());
}

void releaseSemaphore() {
    sem_post(&semaphore);
    printf("Released semaphore by thread %ld\n", pthread_self());
}

int main() {
    if (createSemaphore(1) != 0) {
        return -1;
    }

    // Simulate semaphore usage in a multi-threaded environment
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, acquireSemaphore, NULL);
    pthread_create(&thread2, NULL, releaseSemaphore, NULL);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    deleteSemaphore();
    return 0;
}
```

