// Import necessary libraries
use openssl::pkey::{PKey, Private};
use openssl::x509::{X509Builder, X509Name, X509VerifyResult};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use tokio::sync::mpsc;

// Define the service struct
struct CertificateService {
    ca_url: String,
    kms_client: KmsClient,
    cache: Arc<Mutex<HashMap<String, X509>>>,
}

impl CertificateService {
    // Constructor to initialize the service
    fn new(ca_url: String, kms_client: KmsClient) -> Self {
        CertificateService {
            ca_url,
            kms_client,
            cache: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    // Function to process OAuth requests and generate certificates
    async fn process_request(&self, request: &OAuthRequest) -> Result<String, String> {
        let mut cache = self.cache.lock().unwrap();
        if let Some(cert) = cache.get(request.certificate_id.as_str()) {
            return Ok(cert.to_pem());
        }

        let private_key = self.kms_client.get_private_key(request.key_id).await?;
        let cert = self.generate_certificate(&private_key, request).await?;
        cache.insert(request.certificate_id.clone(), cert.clone());

        Ok(cert.to_pem())
    }

    // Function to generate a certificate from a private key and OAuth request
    async fn generate_certificate(
        &self,
        private_key: &PKey<Private>,
        request: &OAuthRequest,
    ) -> Result<X509, String> {
        let mut builder = X509Builder::new().unwrap();
        let subject_name = X509Name::builder()
            .add_entry_by_nid(NID_COMMON_NAME, request.user_id.as_str())
            .build()?;
        builder.set_subject_name(&subject_name);
        builder.set_issuer_name(&self.get_ca_certificate()?.subject_name());
        builder.set_pubkey(private_key)?;
        builder.sign(private_key, MessageDigest::sha256())?;
        Ok(builder.build())
    }

    // Function to retrieve the CA certificate
    async fn get_ca_certificate(&self) -> Result<X509, String> {
        let response = reqwest::get(&self.ca_url).await?;
        let ca_cert_pem = response.text().await?;
        X509::from_pem(ca_cert_pem.as_bytes()).map_err(|e| e.to_string())
    }
}

