class AttackExecutor {
public:
    void executeAttack(const std::string& attackType) {
        auto details = fetchAttackDetails(attackType);
        if (details != nullptr) {
            int damage = cJSON_GetNumber(cJSON_GetObjectItem(details.get(), "damage"));
            int cooldown = cJSON_GetNumber(cJSON_GetObjectItem(details.get(), "cooldown"));
            // Simulate attack execution
            std::cout << "Executing attack: " << attackType << " Damage: " << damage << " Cooldown: " << cooldown << std::endl;
        } else {
            std::cerr << "Failed to fetch attack details for: " << attackType << std::endl;
        }
    }

private:
    void handleAttackFailure(const std::string& attackType, int attempt) {
        // Retry logic with exponential backoff
        std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << attempt)));
        fetchAttackDetails(attackType);
    }
};

class Character {
public:
    void executeStrategicAttackSequence(const std::vector<std::string>& attackSequence) {
        for (const auto& attack : attackSequence) {
            executeAttackWithCooldown(attack, cooldowns[attack]);
        }
    }

private:
    AttackExecutor executor;
    std::unordered_map<std::string, int> cooldowns = {{"slash", 2}, {"fireball", 5}}; // Example cooldowns

    void executeAttackWithCooldown(const std::string& attack, int cooldown) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this, &attack] { return !isOnCooldown(attack); });
        executor.executeAttack(attack);
        setCooldown(attack);
    }

    bool isOnCooldown(const std::string& attack) {
        // Check if the attack is on cooldown
        auto now = std::chrono::steady_clock::now();
        auto lastExecuted = lastExecutionTimes[attack];
        return (now - lastExecuted) < std::chrono::seconds(cooldown);
    }

    void setCooldown(const std::string& attack) {
        // Set the cooldown for the attack
        lastExecutionTimes[attack] = std::chrono::steady_clock::now();
    }

    std::mutex mutex;
    std::unordered_map<std::string, std::chrono::time_point<std::chrono::steady_clock>> lastExecutionTimes;
};

int main() {
    Character player;
    std::vector<std::string> attackSequence = {"slash", "fireball", "slash"};
    player.executeStrategicAttackSequence(attackSequence);
    return 0;
}
