using System;
using System.Collections.Concurrent;
using System.Linq;

namespace RandomValueGenerator
{
    public class RandomValueGenerator : IRandomValueGenerator
    {
        private readonly ConcurrentDictionary<string, Random> _randomizers = new ConcurrentDictionary<string, Random>();
        private readonly object _cacheLock = new object();
        private readonly int[] _recentlyUsedSeeds;
        private int _seedIndex;

        public RandomValueGenerator(int cacheSize = 10)
        {
            _recentlyUsedSeeds = Enumerable.Range(0, cacheSize).Select(i => new Random().Next()).ToArray();
            _seedIndex = 0;
        }

        public double GenerateDouble(double min, double max)
        {
            EnsureValidRange(min, max);
            return GetRandomizer().NextDouble() * (max - min) + min;
        }

        public int GenerateInt(int min, int max)
        {
            EnsureValidRange(min, max);
            return GetRandomizer().Next(min, max);
        }

        private Random GetRandomizer()
        {
            var seed = _recentlyUsedSeeds[_seedIndex];
            _seedIndex = (_seedIndex + 1) % _recentlyUsedSeeds.Length;
            lock (_cacheLock)
            {
                if (!_randomizers.ContainsKey(seed.ToString()))
                    _randomizers.TryAdd(seed.ToString(), new Random(seed));
            }
            return _randomizers[seed.ToString()];
        }

        private void EnsureValidRange(double min, double max)
        {
            if (min > max)
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }
    }

    public interface IRandomValueGenerator
    {
        double GenerateDouble(double min, double max);
        int GenerateInt(int min, int max);
    }
}
