#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256
#define INITIAL_CAPACITY 1024

typedef struct {
    char key[MAX_KEY_LENGTH];
    char value[MAX_KEY_LENGTH];
} Resource;

typedef struct HashNode {
    int occupied;
    Resource resource;
    struct HashNode *next;
} HashNode;

typedef struct {
    HashNode **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ResourceBundle;

ResourceBundle* createResourceBundle(size_t maxSize) {
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) return NULL;

    bundle->capacity = INITIAL_CAPACITY;
    bundle->size = 0;
    bundle->buckets = calloc(bundle->capacity, sizeof(HashNode *));
    if (!bundle->buckets) {
        free(bundle);
        return NULL;
    }

    pthread_mutex_init(&bundle->lock, NULL);

    // Load keys from configuration file and limit size
    // ...

    return bundle;
}

void destroyResourceBundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->capacity; ++i) {
        HashNode *node = bundle->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(bundle->buckets);
    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

int loadResourceBundle(ResourceBundle *bundle, const char *configFile, size_t maxSize) {
    // Lock the bundle during loading to ensure thread safety
    pthread_mutex_lock(&bundle->lock);

    // Load keys from configuration file and limit size
    FILE *file = fopen(configFile, "r");
    if (!file) {
        perror("Failed to open config file");
        pthread_mutex_unlock(&bundle->lock);
        return -1; // File error
    }

    char key[MAX_KEY_LENGTH];
    while (fgets(key, MAX_KEY_LENGTH, file)) {
        key[strcspn(key, "\r\n")] = '\0'; // Remove newline character

        if (strlen(key) == 0) continue; // Skip empty lines

        if (bundle->size >= maxSize) {
            fclose(file);
            pthread_mutex_unlock(&bundle->lock);
            return -2; // Max size exceeded
        }

        // Insert key into hash table
        size_t index = hashFunction(key, bundle->capacity);
        HashNode *node = bundle->buckets[index];

        while (node && node->occupied) {
            if (strcmp(node->resource.key, key) == 0) {
                fclose(file);
                pthread_mutex_unlock(&bundle->lock);
                return -3; // Duplicate key
            }
            node = node->next;
        }

        HashNode *newNode = malloc(sizeof(HashNode));
        if (!newNode) {
            fclose(file);
            pthread_mutex_unlock(&bundle->lock);
            return -4; // Memory allocation error
        }
        newNode->occupied = 1;
        strcpy(newNode->resource.key, key);
        // Load value from file or other source
        // ...
        newNode->next = bundle->buckets[index];
        bundle->buckets[index] = newNode;
        ++bundle->size;
    }

    fclose(file);
    pthread_mutex_unlock(&bundle->lock);
    return 0; // Success
}

// Example hash function (simplified)
size_t hashFunction(const char *key, size_t capacity) {
    size_t hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

// Example usage
int main() {
    ResourceBundle *bundle = createResourceBundle(100);
    if (!bundle) {
        fprintf(stderr, "Failed to create resource bundle\n");
        return EXIT_FAILURE;
    }

    int result = loadResourceBundle(bundle, "config.txt", 100);
    if (result != 0) {
        fprintf(stderr, "Failed to load resource bundle: %d\n", result);
        destroyResourceBundle(bundle);
        return EXIT_FAILURE;
    }

    // Use the bundle
    // ...

    destroyResourceBundle(bundle);
    return EXIT_SUCCESS;
}
