#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LOG_LINE_LENGTH 1024
#define NUM_ENTRIES_FOR_AVERAGE 10

typedef struct LogEntry {
    char timestamp[MAX_LOG_LINE_LENGTH];
    int userId;
    char sessionId[MAX_LOG_LINE_LENGTH];
    double responseTime;
    int errorCount;
    struct LogEntry *next;
} LogEntry;

double calculateMovingAverage(LogEntry *last, int count) {
    double sum = 0.0;
    for (int i = 0; i < count && last != NULL; ++i) {
        sum += last->responseTime;
        last = last->next;
    }
    return sum / count;
}

void processLogEntry(LogEntry **head, char *line) {
    LogEntry *newEntry = (LogEntry *)malloc(sizeof(LogEntry));
    if (sscanf(line, "%[^,],%d,%[^,],%lf,%d", newEntry->timestamp, &newEntry->userId, newEntry->sessionId, &newEntry->responseTime, &newEntry->errorCount) != 5) {
        free(newEntry);
        return;
    }

    if (*head == NULL) {
        *head = newEntry;
        newEntry->next = NULL;
    } else {
        LogEntry *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntry;
        newEntry->next = NULL;
    }

    if (*head != NULL && *head->next != NULL && *head->next->next != NULL) {
        double movingAverage = calculateMovingAverage(*head, NUM_ENTRIES_FOR_AVERAGE);
        printf("New Entry: %s - Moving Average Response Time: %.2f\n", newEntry->timestamp, movingAverage);

        // Remove the oldest entry to keep only the last 10
        LogEntry *temp = (*head);
        (*head) = (*head)->next;
        free(temp);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file_path>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    LogEntry *head = NULL;

    char line[MAX_LOG_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        processLogEntry(&head, line);
    }

    fclose(file);

    // Free all allocated memory
    while (head != NULL) {
        LogEntry *temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
