        key[i] = rand() % 256;
    }

    // Encrypt the plaintext using AES
    aes_encrypt(plaintext, sizeof(plaintext), key, ciphertext);

    // Decrypt the ciphertext back to plaintext
    unsigned char decrypted_text[128];
    rsa_decrypt(ciphertext, strlen((char*)ciphertext), key, decrypted_text);

    // Print the decrypted text
    printf("Decrypted Text: %s\n", decrypted_text);

    return 0;
}

// Function definitions
void aes_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, unsigned char *ciphertext) {
    AES_KEY enc_key;
    AES_set_encrypt_key(key, 128, &enc_key);
    AES_ecb_encrypt(plaintext, ciphertext, &enc_key, AES_ENCRYPT);
}

void camellia_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, unsigned char *ciphertext) {
    Camellia_KEY enc_key;
    Camellia_set_encrypt_key(key, 128, &enc_key);
    Camellia_ecb_encrypt(plaintext, ciphertext, &enc_key, Camellia_ENCRYPT);
}

unsigned char* md5_hash(const unsigned char *input, size_t len) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5(input, len, (unsigned char*)&digest);
    return digest;
}

unsigned char* sha_hash(const unsigned char *input, size_t len, int sha_type) {
    unsigned char digest[SHA_DIGEST_LENGTH];
    if (sha_type == SHA_TYPE_SHA1) {
        SHA1(input, len, digest);
    } else if (sha_type == SHA_TYPE_SHA256) {
        SHA256(input, len, digest);
    }
    return digest;
}

RSA* rsa_generate_key(int bits) {
    RSA *rsa = RSA_new();
    BIGNUM *bn_e = BN_new();
    BN_set_word(bn_e, 0x10001);

    if (RSA_generate_key_ex(rsa, bits, bn_e, NULL)) {
        return rsa;
    } else {
        RSA_free(rsa);
        BN_free(bn_e);
        return NULL;
    }
}

int rsa_encrypt(const unsigned char *data, int data_len, RSA *key, unsigned char *encrypted_data) {
    return RSA_public_encrypt(data_len, (const unsigned char*)data, encrypted_data, key, RSA_PKCS1_PADDING);
}

int rsa_decrypt(const unsigned char *encrypted_data, int encrypted_data_len, RSA *key, unsigned char *decrypted_data) {
    return RSA_private_decrypt(encrypted_data_len, encrypted_data, decrypted_data, key, RSA_PKCS1_PADDING);
}
