#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sodium.h>

// Function to derive encryption keys using Argon2
void derive_key(const char *password, unsigned char *key, size_t key_len) {
    // Argon2 parameters: m_cost=1G, t_cost=3, parallelism=4
    sodium_memzero(key, key_len);
    if (crypto_pwhash_str(key, password, strlen(password), 1024*1024, 3, 4) != 0) {
        fprintf(stderr, "Failed to derive key\n");
        exit(EXIT_FAILURE);
    }
}

// Function to encrypt data
void encrypt_data(const unsigned char *key, const unsigned char *data, size_t data_len,
                   unsigned char *encrypted_data, size_t encrypted_data_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1) {
        fprintf(stderr, "Failed to initialize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    int len;
    if (EVP_EncryptUpdate(ctx, encrypted_data, &len, data, data_len) != 1) {
        fprintf(stderr, "Failed to encrypt data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    size_t written = len;
    if (EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len) != 1) {
        fprintf(stderr, "Failed to finalize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    written += len;
    if (written > encrypted_data_len) {
        fprintf(stderr, "Buffer too small for encrypted data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data
void decrypt_data(const unsigned char *key, const unsigned char *encrypted_data, size_t encrypted_data_len,
                   unsigned char *decrypted_data, size_t decrypted_data_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        exit(EXIT_FAILURE);
    }
    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL) != 1) {
        fprintf(stderr, "Failed to initialize decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    int len;
    if (EVP_DecryptUpdate(ctx, decrypted_data, &len, encrypted_data, encrypted_data_len) != 1) {
        fprintf(stderr, "Failed to decrypt data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    size_t written = len;
    if (EVP_DecryptFinal_ex(ctx, decrypted_data + len, &len) != 1) {
        fprintf(stderr, "Failed to finalize decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    written += len;
    if (written > decrypted_data_len) {
        fprintf(stderr, "Buffer too small for decrypted data\n");
        EVP_CIPHER_CTX_free(ctx);
        exit(EXIT_FAILURE);
    }
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    const char *password = "user_password";
    unsigned char key[32];
    derive_key(password, key, sizeof(key));

    const unsigned char plaintext[] = "This is a secret message";
    size_t encrypted_len = strlen((const char *)plaintext) + EVP_CIPHER_BLOCK_SIZE;
    unsigned char encrypted[encrypted_len];

    encrypt_data(key, (const unsigned char *)plaintext, strlen((const char *)plaintext),
                 encrypted, encrypted_len);

    unsigned char decrypted[strlen((const char *)plaintext)];
    decrypt_data(key, encrypted, encrypted_len, decrypted, sizeof(decrypted));

    printf("Decrypted: %s\n", decrypted);

    return 0;
}
