using System;
using System.IO;
using System.Xml.Schema;
using System.Threading.Tasks;
using Microsoft.ApplicationInsights;

public class DeploymentManager
{
    private readonly TelemetryClient _telemetryClient = new TelemetryClient();

    public async Task DeployWebApplication(string applicationName, string configurationFilePath, string deploymentTarget)
    {
        try
        {
            ValidateConfigurationFilePath(configurationFilePath);
            EnsureValidApplicationName(applicationName);

            await DeployAsync(applicationName, configurationFilePath, deploymentTarget);
        }
        catch (Exception ex)
        {
            LogDeploymentFailure(ex);
            throw;
        }
    }

    private void ValidateConfigurationFilePath(string filePath)
    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("Configuration file not found.");
        }

        if (new FileInfo(filePath).Length < 5 * 1024) // 5KB
        {
            throw new InvalidOperationException("Configuration file size is too small.");
        }

        var schema = new XmlSchemaSet();
        schema.Add(null, "http://schemas.microsoft.com/.NetConfiguration/v2.0", Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Web.config.xsd"));

        using (var reader = XmlReader.Create(filePath))
        {
            if (!reader.ReadToFollowing("configuration"))
                throw new InvalidOperationException("Configuration file is not well-formed.");

            var validationEventHandler = delegate(object sender, ValidationEventArgs e)
            {
                throw new InvalidOperationException($"Configuration error: {e.Message}");
            };

            reader.Settings.ValidationType = System.Xml.ValidationType.Schema;
            reader.Settings.Schemas = schema;
            reader.Settings.ValidationEventHandler += validationEventHandler;

            if (!reader.Read())
                throw new InvalidOperationException("Configuration file is not well-formed.");
        }
    }

    private void EnsureValidApplicationName(string applicationName)
    {
        if (string.IsNullOrEmpty(applicationName) ||
            !System.Text.RegularExpressions.Regex.IsMatch(applicationName, @"^[a-zA-Z0-9_-]+$"))
        {
            throw new ArgumentException("Invalid application name.");
        }
    }

    private async Task DeployAsync(string applicationName, string configurationFilePath, string deploymentTarget)
    {
        var maxRetries = 5;
        var delay = TimeSpan.FromSeconds(2);

        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                // Simulate deployment process
                await Task.Delay(delay);
                LogDeploymentSuccess(applicationName, deploymentTarget);
                return;
            }
            catch (OutOfMemoryException)
            {
                LogError("Out of memory exception during deployment.");
            }
            catch (IOException)
            {
                LogError("IO exception during deployment.");
            }
            catch (InvalidOperationException)
            {
                LogError("Invalid operation exception during deployment.");
            }

            delay = TimeSpan.FromSeconds(delay.TotalSeconds * 2);
        }

        throw new InvalidOperationException("Deployment failed after multiple attempts.");
    }

    private void LogDeploymentSuccess(string applicationName, string deploymentTarget)
    {
        _telemetryClient.TrackEvent($"DeploymentSuccess", new { ApplicationName = applicationName, DeploymentTarget = deploymentTarget });
    }

    private void LogDeploymentFailure(Exception ex)
    {
        var properties = new Dictionary<string, string>
        {
            { "ErrorMessage", ex.Message },
            { "StackTrace", ex.StackTrace }
        };

        _telemetryClient.TrackEvent("DeploymentFailure", properties);
    }

    private void LogError(string message)
    {
        _telemetryClient.TrackEvent("Error", new { Message = message });
    }
}
