// Strategy Pattern for API Selection
public interface ApiStrategy {
    boolean isReliable();
    void deleteFile(String fileUrl);
}

public class ReliableApiStrategy implements ApiStrategy {
    @Override
    public boolean isReliable() {
        // Logic to check historical performance
        return true;
    }

    @Override
    public void deleteFile(String fileUrl) {
        // Implementation for deleting files using the reliable API
    }
}

// Asynchronous File Deletion Service
public class AsyncFileDeletionService implements FileDeletionService {
    private ExecutorService executor = Executors.newCachedThreadPool();
    private List<ApiStrategy> strategies;

    public AsyncFileDeletionService(List<ApiStrategy> strategies) {
        this.strategies = strategies;
    }

    @Override
    public void deleteFiles(final List<String> fileUrls) throws Exception {
        CompletableFuture.allOf(fileUrls.stream()
                .map(this::deleteFileAsync)
                .toArray(CompletableFuture[]::new))
                .get();
    }

    private CompletableFuture<Void> deleteFileAsync(String fileUrl) {
        return CompletableFuture.runAsync(() -> {
            for (ApiStrategy strategy : strategies) {
                if (strategy.isReliable()) {
                    strategy.deleteFile(fileUrl);
                    break;
                }
            }
        }, executor);
    }
}

// Shell Command Execution
public class ShellCommandExecutor {
    public void executeCommands(List<String> commands) throws Exception {
        ProcessBuilder pb = new ProcessBuilder(commands);
        pb.redirectErrorStream(true);
        try (Process process = pb.start()) {
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("Command execution failed with exit code: " + exitCode);
            }
        }
    }
}

// RESTful API Endpoint
@RestController
public class FileDeletionController {
    @Autowired
    private FileDeletionService fileDeletionService;

    @PostMapping("/delete-files")
    public ResponseEntity<String> deleteFiles(@RequestBody List<String> fileUrls) throws Exception {
        fileDeletionService.deleteFiles(fileUrls);
        return ResponseEntity.ok("File deletion initiated");
    }

    @PostMapping("/execute-commands")
    public ResponseEntity<String> executeCommands(@RequestBody List<String> commands) throws Exception {
        ShellCommandExecutor executor = new ShellCommandExecutor();
        executor.executeCommands(commands);
        return ResponseEntity.ok("Commands executed successfully");
    }
}

