public class DataProcessingPipeline : IDataProcessingPipeline
{
    private readonly HttpClient _httpClient;
    private readonly IConnectionMultiplexer _redisConnection;
    private readonly IMessageBroker _messageBroker;
    private readonly ILogger<DataProcessingPipeline> _logger;

    public DataProcessingPipeline(HttpClient httpClient, IConnectionMultiplexer redisConnection, IMessageBroker messageBroker, ILogger<DataProcessingPipeline> logger)
    {
        _httpClient = httpClient;
        _redisConnection = redisConnection;
