    {
        _redisConnection = redisConnection;
    }

    public async Task SendMessage(byte[] data, Metadata metadata)
    {
        var db = _redisConnection.GetDatabase();
        await db.ListRightPushAsync("messages", $"{metadata.Id}:{Convert.ToBase64String(data)}");
    }
}

