public class HashLibrary
{
    private readonly IHashStorage _storage;
    private readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private readonly ILogger<HashLibrary> _logger;

    public HashLibrary(IHashStorage storage, ILogger<HashLibrary> logger)
    {
        _storage = storage;
        _logger = logger;
    }

    public async Task<string> GetHashAsync(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            _logger.LogError("Invalid input provided");
            throw new ArgumentException("Input cannot be null or empty");
        }

        string hash = _cache.TryGetValue(input, out var cachedHash) ? cachedHash : null;
        if (hash == null)
        {
            hash = ComputeHash(input);
            await _storage.SetHashAsync(input, hash);
            _cache.TryAdd(input, hash);
            _logger.LogInformation("Hash computed and stored: {Input}", input);
        }
        else
        {
            _logger.LogInformation("Hash retrieved from cache: {Input}", input);
        }

        return hash;
    }

    private string ComputeHash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(bytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }
}
