        Err(Error::new(reqwest::StatusCode::UNAUTHORIZED, "Token expired"))
    }
}

async fn delete_user(state: web::Data<AppState>, user_id: web::Path<String>) -> impl Responder {
    let token = state.token.read().await.clone();
    if let Some(token) = token {
        // Make API request to delete user
        Ok("User deleted".to_string())
    } else {
        Err(Error::new(reqwest::StatusCode::UNAUTHORIZED, "Token expired"))
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    dotenv().ok();

    let auth_url = AuthUrl::new(env::var("AUTH_URL").expect("Missing AUTH_URL environment variable")).unwrap();
    let token_url = TokenUrl::new(env::var("TOKEN_URL").expect("Missing TOKEN_URL environment variable")).unwrap();
    let client_id = ClientId::new(env::var("CLIENT_ID").expect("Missing CLIENT_ID environment variable"));
    let client_secret = ClientSecret::new(env::var("CLIENT_SECRET").expect("Missing CLIENT_SECRET environment variable"));

    let client = BasicClient::new(client_id, Some(client_secret), auth_url, Some(token_url));

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(AppState { client: client.clone(), token: RwLock::new(None) }))
            .route("/users", web::post().to(create_user))
            .route("/users/{user_id}", web::get().to(read_user))
            .route("/users/{user_id}", web::put().to(update_user))
            .route("/users/{user_id}", web::delete().to(delete_user))
            .wrap(TraceLayer::new_for_http())
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}

