import abc
import json

class DataModel(metaclass=abc.ABCMeta):
    @abc.abstractmethod
    def serialize(self):
        pass

    @classmethod
    @abc.abstractmethod
    def deserialize(cls, data):
        pass

class Factory:
    _registry = {}

    @staticmethod
    def register(id, constructor):
        Factory._registry[id] = constructor

    @staticmethod
    def get_factory(id):
        return Factory._registry.get(id)

class Registry:
    _factories = {}

    @classmethod
    def add_factory(cls, id, factory_function):
        with cls._lock:
            if id in cls._factories:
                raise ValueError(f"Factory with id {id} already exists")
            cls._factories[id] = factory_function

    @classmethod
    def get_factory(cls, id):
        with cls._lock:
            return cls._factories.get(id)

    @classmethod
    def remove_factory(cls, id):
        with cls._lock:
            if id not in cls._factories:
                raise ValueError(f"No factory with id {id} found")
            del cls._factories[id]

class DataSerializer:
    def __init__(self, registry):
        self.registry = registry

    def serialize(self, data_model_id, data):
        factory = self.registry.get_factory(data_model_id)
        if not factory:
            raise ValueError(f"No factory registered for id {data_model_id}")

        model_instance = factory().deserialize(data)
        return json.dumps(model_instance.serialize())

class DataDeserializer:
    def __init__(self, registry):
        self.registry = registry

    def deserialize(self, data, data_model_id):
        factory = self.registry.get_factory(data_model_id)
        if not factory:
            raise ValueError(f"No factory registered for id {data_model_id}")

        model_instance = factory().deserialize(json.loads(data))
        return model_instance

# Example usage
class User(DataModel):
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def serialize(self):
        return {
            "name": self.name,
            "age": self.age
        }

    @classmethod
    def deserialize(cls, data):
        return cls(data["name"], data["age"])

# Registering factories
Factory.register("user", User)

# Creating registry and serializer/deserializer instances
registry = Registry()
registry.add_factory("user", Factory.get_factory("user"))

serializer = DataSerializer(registry)
deserializer = DataDeserializer(registry)

# Serialization example
user_data = {"name": "John Doe", "age": 30}
serialized_data = serializer.serialize("user", user_data)
print(serialized_data)  # Output: '{"name": "John Doe", "age": 30}'

# Deserialization example
deserialized_user = deserializer.deserialize('{"name": "Jane Doe", "age": 25}', "user")
print(deserialized_user.name, deserialized_user.age)  # Output: Jane Doe 25
```']

