#include <stdbool.h>
#include <string.h>

bool validate_oauth2_token(const char* token_response) {
    const char* access_token_key = "\"access_token\":";
    const char* expires_in_key = "\"expires_in\":";
    const char* token_type_key = "\"token_type\":\"Bearer\"";

    if (strstr(token_response, access_token_key) == NULL ||
        strstr(token_response, expires_in_key) == NULL ||
        strstr(token_response, token_type_key) == NULL) {
        return false;
    }

    int expires_in_value_start = strlen(expires_in_key) + 2;
    const char* expires_in_value_end = strchr(&token_response[expires_in_value_start], ',');
    if (expires_in_value_end == NULL) {
        return false;
    }

    long expires_in = atol(&token_response[expires_in_value_start]);
    if (expires_in <= 0) {
        return false;
    }

    return true;
}
