#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1024

typedef struct {
    long timestamp;
    char type[32];
    void* metadata;
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    int size;
    pthread_mutex_t lock;
} EventQueue;

void init_queue(EventQueue* q) {
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
}

int enqueue_event(EventQueue* q, Event e) {
    pthread_mutex_lock(&q->lock);
    if (q->size < MAX_EVENTS) {
        q->events[q->size++] = e;
        pthread_mutex_unlock(&q->lock);
        return 1;
    }
    pthread_mutex_unlock(&q->lock);
    return 0;
}

Event dequeue_event(EventQueue* q) {
    Event e = {0};
    pthread_mutex_lock(&q->lock);
    if (q->size > 0) {
        e = q->events[0];
        for (int i = 1; i < q->size; ++i) {
            q->events[i-1] = q->events[i];
        }
        --q->size;
    }
    pthread_mutex_unlock(&q->lock);
    return e;
}

void* event_processor(void* arg) {
    EventQueue* queue = (EventQueue*)arg;
    while (1) {
        Event e = dequeue_event(queue);
