#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 1024

typedef struct {
    int sock;
    int priority;
} NetworkSource;

typedef struct {
    int value;
    pthread_mutex_t lock;
} SharedData;

SharedData shared_data = {0, PTHREAD_MUTEX_INITIALIZER};

void* process_stream(void* arg) {
    NetworkSource* source = (NetworkSource*)arg;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(source->sock, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        int new_value = atoi(buffer);

        pthread_mutex_lock(&shared_data.lock);
        if (new_value > shared_data.value) {
            shared_data.value = new_value;
        }
        pthread_mutex_unlock(&shared_data.lock);
    }

    close(source->sock);
    free(source);
    return NULL;
}

int main() {
    int server_sock, client_sock;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);

    // Create socket
    if ((server_sock = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set up address structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(8080);

    // Bind socket to port
    if (bind(server_sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind failed");
        close(server_sock);
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_sock, MAX_THREADS) == -1) {
        perror("listen failed");
        close(server_sock);
        exit(EXIT_FAILURE);
    }

    pthread_t threads[MAX_THREADS];
    NetworkSource* sources[MAX_THREADS];

    int thread_count = 0;

    while ((client_sock = accept(server_sock, (struct sockaddr*)&client_addr, &addr_len)) > 0) {
        if (thread_count >= MAX_THREADS) {
            close(client_sock);
            continue;
        }

        sources[thread_count] = (NetworkSource*)malloc(sizeof(NetworkSource));
        sources[thread_count]->sock = client_sock;
        sources[thread_count]->priority = /* get priority based on source */;

        if (pthread_create(&threads[thread_count], NULL, process_stream, sources[thread_count]) != 0) {
            perror("thread creation failed");
            free(sources[thread_count]);
            close(client_sock);
            continue;
        }

        thread_count++;
    }

    // Wait for all threads to finish
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
        free(sources[i]);
    }

    close(server_sock);

    return 0;
}
```

