// Define the structure for cached data
typedef struct {
    unsigned char *key;
    int key_length;
    DES_cblock des_key;
} CachedKey;

// Cache mechanism
#define CACHE_SIZE 100
CachedKey cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a key to the cache
void add_to_cache(unsigned char *key, int key_length) {
    pthread_mutex_lock(&cache_lock);
    if (cache_count < CACHE_SIZE) {
        cache[cache_count].key = malloc(key_length);
        memcpy(cache[cache_count].key, key, key_length);
        cache[cache_count].key_length = key_length;
        DES_set_key_unchecked((const_DES_cblock *)cache[cache_count].key, &cache[cache_count].des_key);
        cache_count++;
    }
    pthread_mutex_unlock(&cache_lock);
}

// Function to get a key from the cache
CachedKey *get_from_cache(unsigned char *key, int key_length) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; i++) {
        if (cache[i].key_length == key_length && memcmp(cache[i].key, key, key_length) == 0) {
            CachedKey *result = &cache[i];
            memmove(&cache[i], &cache[i + 1], sizeof(CachedKey) * (cache_count - i - 1));
            cache_count--;
            pthread_mutex_unlock(&cache_lock);
            return result;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

