        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    DES_ecb3_crypt((const_DES_cblock *)input, (DES_cblock *)output, &key_info->des_key, &key_info->des_key, &key_info->des_key, DES_DECRYPT);
}

