#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 10000

typedef struct semaphore_node {
    sem_t *sem;
    struct semaphore_node *next;
} SemaphoreNode;

SemaphoreNode *head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t list_condition = PTHREAD_COND_INITIALIZER;

sem_t *get_semaphore() {
    pthread_mutex_lock(&list_mutex);
    while (head == NULL) {
        pthread_cond_wait(&list_condition, &list_mutex);
    }
    SemaphoreNode *node = head;
    head = node->next;
    sem_t *sem = node->sem;
    free(node);
    pthread_mutex_unlock(&list_mutex);
    return sem;
}

void release_semaphore(sem_t *sem) {
    SemaphoreNode *node = (SemaphoreNode *)malloc(sizeof(SemaphoreNode));
    node->sem = sem;
    node->next = head;
    head = node;
    pthread_cond_signal(&list_condition);
}

void *semaphore_thread(void *arg) {
    int id = *(int *)arg;
    sem_t *sem = get_semaphore();
    if (sem != NULL) {
        // Perform semaphore operations
        sem_post(sem);
        release_semaphore(sem);
    }
    return NULL;
}

int main() {
    pthread_t threads[MAX_SEMAPHORES];
    int ids[MAX_SEMAPHORES];

    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        sem_t *sem = sem_open("/semaphore", O_CREAT, 0644, 1);
        if (sem == SEM_FAILED) {
            perror("Failed to create semaphore");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        ids[i] = i;
        if (pthread_create(&threads[i], NULL, semaphore_thread, &ids[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

This code provides a basic structure for managing semaphores in a distributed system. It includes functions to get and release semaphores, which are used by multiple threads concurrently. The semaphore operations are protected using mutexes and condition variables to ensure thread safety. This example demonstrates how to create and manage semaphores efficiently, but it does not include the more complex features such as cloud integration, monitoring, or self-healing mechanisms described in the task.']

