class DataIngestionPipeline {
public:
    void insertAfterOrLog(std::forward_list<std::string>& metadata, const std::string& target, const std::string& insert) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto it = std::find(metadata.begin(), metadata.end(), target);
        if (it != metadata.end()) {
            try {
                it = metadata.insert_after(it, insert);
            } catch (const std::bad_alloc& e) {
                logError("Memory allocation failed", *it, "std::bad_alloc");
                return;
            }
        } else {
            try {
                metadata.push_back(insert);
            } catch (const std::bad_alloc& e) {
                logError("Memory allocation failed", insert, "std::bad_alloc");
                return;
            }
        }

        // Simulate external service validation
        if (!validateInsert(*it)) {
            logError("Validation failed", *it, "Service error");
            metadata.erase_after(it);
        }
    }

private:
    std::mutex mutex_;

    bool validateInsert(const std::string& entry) {
        // Placeholder for external service validation logic
        return true;
    }

    void logError(const std::string& errorMessage, const std::string& entry, const std::string& errorType) {
        time_t now = time(nullptr);
        std::cout << "ERROR [" << ctime(&now) << "] Entry: " << entry << ", Error: " << errorMessage << ", Type: " << errorType << std::endl;
    }
};

