    private readonly IDistributedCache _cache;

    public MissionCriticalService(IOptions<ConnectionSettings> settings, IExternalApiService apiService, IDistributedCache cache)
    {
        _connectionString = settings.Value.ConnectionString;
        _apiService = apiService;
        _cache = cache;
    }

    public async Task ExecuteQueryAsync(string query, object parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (var command = new SqlCommand(query, connection))
            {
                command.Parameters.AddRange((SqlParameter[])parameters);
                await command.ExecuteNonQueryAsync();
            }
        }
    }

    public async Task<object> GetCachedDataAsync(string key)
    {
        var cachedData = await _cache.GetStringAsync(key);
        if (cachedData != null) return JsonConvert.DeserializeObject(cachedData);

        // Fetch data from database or external API
        var data = await _apiService.GetDataAsync(key);

        // Store in cache with expiration
        await _cache.SetStringAsync(key, JsonConvert.SerializeObject(data), new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10) });

        return data;
    }
}

public class ConnectionSettings
{
    public string ConnectionString { get; set; }
}

