#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <chrono>
#include <unordered_map>
#include <memory>

// Define the event structure
struct Event {
    std::string timestamp;
    std::string type;
    std::unordered_map<std::string, std::string> metadata;
};

// Define a simple NoSQL database interface
class NoSQLDatabase {
public:
    void insert(const Event& event) {
        // Implementation for inserting an event into the database
        std::cout << "Inserting event into database" << std::endl;
    }
};

// Define a third-party logging service interface
class LoggingService {
public:
    void logEvent(const Event& event) {
        // Implementation for logging an event to the third-party service
        std::cout << "Logging event to third-party service" << std::endl;
    }
};

// Event Processor class
class EventProcessor {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    bool stopProcessing;
    NoSQLDatabase db;
    LoggingService logger;

public:
    EventProcessor() : stopProcessing(false) {}

    void addEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        notEmpty.notify_one();
    }

    void startProcessing() {
        std::thread([this]() {
            while (!stopProcessing) {
                Event event;
                {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    notEmpty.wait(lock, [this] { return !eventQueue.empty() || stopProcessing; });
                    if (stopProcessing && eventQueue.empty()) {
                        return;
                    }
                    event = eventQueue.front();
                    eventQueue.pop();
                }

                // Process the event
                processEvent(event);
            }
        }).detach();
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stopProcessing = true;
        }
        notEmpty.notify_all();
    }

private:
    void processEvent(const Event& event) {
        try {
            // Validate the event
            if (event.timestamp.empty() || event.type.empty()) {
                throw std::runtime_error("Invalid event");
            }

            // Log the event to the third-party service
            logger.logEvent(event);

            // Store the event in the NoSQL database
            db.insert(event);
        } catch (const std::exception& e) {
            std::cerr << "Error processing event: " << e.what() << std::endl;
        }
    }
};

int main() {
    EventProcessor processor;
    processor.startProcessing();

    // Simulate adding events
    for (int i = 0; i < 10; ++i) {
        Event event = {"2023-04-01T12:00:00Z", "Type" + std::to_string(i), {}};
        processor.addEvent(event);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    // Stop the processor
    processor.stop();

    return 0;
}
