public interface IConfigurationService
{
    Task<List<ConfigurationSetting>> GetAllSettingsAsync();
    Task<ConfigurationSetting> GetSettingByIdAsync(string id);
    Task UpdateSettingAsync(ConfigurationSetting setting);
    Task DeleteSettingAsync(string id);
}

public class ConfigurationSetting
{
    public string Id { get; set; }
    public string Key { get; set; }
    public string Value { get; set; }
    public string Description { get; set; }
    public DateTime LastUpdated { get; set; }
}

public class ConfigurationService : IConfigurationService
{
    private readonly List<ConfigurationSetting> _settings;

    public ConfigurationService()
    {
        _settings = new List<ConfigurationSetting>();
    }

    public async Task<List<ConfigurationSetting>> GetAllSettingsAsync()
    {
        return await Task.FromResult(_settings);
    }

    public async Task<ConfigurationSetting> GetSettingByIdAsync(string id)
    {
        var setting = _settings.Find(s => s.Id == id);
        if (setting != null)
            return await Task.FromResult(setting);
        throw new ArgumentException("Setting not found", nameof(id));
    }

    public async Task UpdateSettingAsync(ConfigurationSetting setting)
    {
        var existingSetting = _settings.Find(s => s.Id == setting.Id);
        if (existingSetting != null)
        {
            existingSetting.Value = setting.Value;
            existingSetting.Description = setting.Description;
            existingSetting.LastUpdated = DateTime.UtcNow;
        }
        else
        {
            setting.Id = Guid.NewGuid().ToString();
            setting.LastUpdated = DateTime.UtcNow;
            _settings.Add(setting);
        }
    }

    public async Task DeleteSettingAsync(string id)
    {
        var setting = _settings.Find(s => s.Id == id);
        if (setting != null)
            _settings.Remove(setting);
    }
}
