public class XmlServiceClient
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;

    public XmlServiceClient(HttpClient httpClient, IMemoryCache cache)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public async Task<XDocument> GetXmlAsync(string url)
    {
        var cacheKey = "xml_" + url.GetHashCode();
        if (_cache.TryGetValue(cacheKey, out XDocument cachedXml))
        {
            return cachedXml;
        }

        var response = await _httpClient.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using (var stream = await response.Content.ReadAsStreamAsync())
        using (var reader = XmlReader.Create(stream, new XmlReaderSettings { Async = true }))
        {
            var xml = XDocument.Load(reader);
            _cache.Set(cacheKey, xml, TimeSpan.FromHours(1));
            return xml;
        }
    }

    public async Task<XDocument> ParseLargeXmlAsync(string filePath)
    {
        using (var reader = XmlReader.Create(filePath, new XmlReaderSettings { Async = true }))
        {
            var settings = new XmlWriterSettings { Indent = false, Async = true };
            using (var stream = new MemoryStream())
            using (var writer = XmlWriter.Create(stream, settings))
            {
                await reader.ReadAsync();
                while (!reader.EOF)
                {
                    await writer.WriteNodeAsync(reader, true);
                    await reader.ReadAsync();
                }

                stream.Position = 0;
                return XDocument.Load(stream);
            }
        }
    }

    public async Task<string> EncryptXmlAsync(string xmlContent, string key)
    {
