use actix_web::{web, App, HttpServer};
use std::sync::{Arc, Mutex};
use tokio::sync::Semaphore;
use rand::Rng;

#[derive(Debug)]
struct User {
    username: String,
    password_hash: String,
}

#[derive(Debug)]
struct AuthProvider {
    name: String,
    url: String,
}

#[derive(Debug)]
enum AuthMethod {
    TwoFactor,
    MultiFactor,
}

#[derive(Debug)]
struct UserManager {
    users: Arc<Mutex<Vec<User>>>,
    auth_providers: Vec<AuthProvider>,
    semaphore: Arc<Semaphore>,
}

impl UserManager {
    fn new() -> Self {
        Self {
            users: Arc::new(Mutex::new(Vec::new())),
            auth_providers: vec![
                AuthProvider {
                    name: "Google".to_string(),
                    url: "https://accounts.google.com/o/oauth2/v2/auth".to_string(),
                },
                AuthProvider {
                    name: "Facebook".to_string(),
                    url: "https://www.facebook.com/v15.0/dialog/oauth".to_string(),
                },
            ],
            semaphore: Arc::new(Semaphore::new(10)),
        }
    }

    async fn add_user(&self, user: User) {
        let mut users = self.users.lock().unwrap();
        users.push(user);
    }

    async fn authenticate(
        &self,
        username: &str,
        password_hash: &str,
        auth_method: AuthMethod,
    ) -> Result<(), &'static str> {
        let permit = self.semaphore.acquire().await.map_err(|_| "Too many concurrent requests")?;
        // Simulate authentication with an external service
        if auth_method == AuthMethod::TwoFactor && rand::thread_rng().gen_range(0..2) == 0 {
            return Err("Authentication failed");
        }
        Ok(())
    }

    async fn add_auth_provider(&self, provider: AuthProvider) {
        self.auth_providers.push(provider);
    }
}

async fn handle_add_user(user_manager: web::Data<UserManager>, user: User) -> Result<web::Json<User>, &'static str> {
    user_manager.add_user(user).await;
    Ok(web::Json(user))
}

async fn handle_auth(
    user_manager: web::Data<UserManager>,
    username: web::Form<String>,
    password_hash: web::Form<String>,
    auth_method: web::Query<AuthMethod>,
) -> Result<(), &'static str> {
    user_manager.authenticate(&username.0, &password_hash.0, auth_method.into_inner()).await
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let user_manager = web::Data::new(UserManager::new());

    HttpServer::new(move || {
        App::new()
            .app_data(user_manager.clone())
            .route("/users", web::post().to(handle_add_user))
            .route("/auth", web::post().to(handle_auth))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
