const fs = require('fs').promises;
const path = require('path');
const { CloudStorageService } = require('./cloud-storage-service'); // Mock third-party API for cloud storage

class FileAggregator {
  constructor(service, logging) {
    this.service = service;
    this.logging = logging;
  }

  async fetchAndConcatenate(directory, extensions) {
    try {
      const files = await this.listFiles(directory);
      if (files.length === 0) {
        this.logging.info(`No files found in ${directory}`);
        return '';
      }

      const filteredFiles = files.filter(file => extensions.includes(path.extname(file).toLowerCase()));
      if (filteredFiles.length === 0) {
        this.logging.info(`No files with specified extensions found in ${directory}`);
        return '';
      }

      let concatenatedContent = '';
      for (const file of filteredFiles) {
        const content = await this.fetchFileContent(directory, file);
        if (content !== null) {
          concatenatedContent += content;
        }
      }

      this.logging.info(`Successfully fetched and concatenated files from ${directory}`);
      return concatenatedContent;
    } catch (error) {
      this.logging.error(`Error fetching and concatenating files: ${error.message}`);
      throw error;
    }
  }

  async listFiles(directory) {
    try {
      const files = await fs.readdir(directory);
      this.logging.info(`Listed files in directory: ${files.join(', ')}`);
      return files;
    } catch (error) {
      if (error.code === 'ENOENT') {
        this.logging.error(`Directory not found: ${directory}`);
        throw new Error(`Directory not found: ${directory}`);
      }
      this.logging.error(`Error listing files: ${error.message}`);
      throw error;
    }
  }

  async fetchFileContent(directory, file) {
    try {
      const filePath = path.join(directory, file);
      const stats = await fs.stat(filePath);
      if (stats.isDirectory()) {
        return null; // Skip directories
      }

      let content = '';
      let position = 0;
      while (position < stats.size) {
        const chunkSize = 1024 * 1024; // 1MB chunk size for memory efficiency
        const chunk = await fs.readFile(filePath, { start: position, end: Math.min(position + chunkSize - 1, stats.size) });
        content += chunk.toString('utf8');
        position += chunk.length;
      }

      this.logging.info(`Fetched file content: ${file}`);
      return content;
    } catch (error) {
      if (error.code === 'ENOENT') {
        this.logging.error(`File not found: ${path.join(directory, file)}`);
        throw new Error(`File not found: ${path.join(directory, file)}`);
      }
      this.logging.error(`Error fetching file content: ${error.message}`);
      throw error;
    }
  }

  static async test() {
    const service = new CloudStorageService();
    const logging = { info: console.log, error: console.error };
    const aggregator = new FileAggregator(service, logging);

    try {
      const result = await aggregator.fetchAndConcatenate('/path/to/directory', ['.txt', '.json']);
      console.log(`Concatenated content:\n${result}`);
    } catch (error) {
      console.error('Test failed:', error);
    }
  }
}

// Uncomment the following line to run tests
// FileAggregator.test();
