  max: 500,
  maxAge: 1000 * 60 * 60 // Cache entries expire after one hour
};
const bookCache = new LRUCache(cacheConfig);

// Function to fetch the list of Bible books from the API with exponential backoff
async function fetchBibleBooks() {
  let retries = 5;
  while (retries > 0) {
    try {
      const response = await axios.get(bibleApiUrl);
      return response.data.books;
    } catch (error) {
      if (axios.isAxiosError(error)) {
        console.error('API request failed:', error.message);
        if (error.response && error.response.status >= 500) {
          retries--;
          const backoffTime = Math.pow(2, 5 - retries) * 100; // Exponential backoff
          await new Promise(resolve => setTimeout(resolve, backoffTime));
        } else {
          throw error;
        }
      } else {
        throw error;
      }
    }
  }
  throw new Error('Failed to fetch Bible books after multiple attempts');
}

// Function to count book references in the given text using regular expressions
function countBookReferences(text) {
  const books = {
    oldTestament: [],
    newTestament: []
  };
  let match;

  // Find matches for Old Testament book names
  while ((match = oldTestamentBooksRegex.exec(text)) !== null) {
    books.oldTestament.push(match[0]);
  }

  // Find matches for New Testament book names
  while ((match = newTestamentBooksRegex.exec(text)) !== null) {
    books.newTestament.push(match[0]);
  }

  return books;
}

// Function to process the input text and return counts of Old and New Testament book references
async function processText(inputText) {
  if (!inputText || inputText.trim() === '') {
    throw new Error('Input text cannot be empty');
  }

  // Fetch the list of Bible books from the cache or API
  let bibleBooks = bookCache.get('bibleBooks');
  if (!bibleBooks) {
    try {
      bibleBooks = await fetchBibleBooks();
      bookCache.set('bibleBooks', bibleBooks);
    } catch (error) {
      throw new Error('Failed to fetch Bible books: ' + error.message);
    }
  }

  // Count the occurrences of each book in the input text
  const counts = countBookReferences(inputText);

  // Log the results
  console.log('Old Testament books referenced:', counts.oldTestament.length);
  console.log('New Testament books referenced:', counts.newTestament.length);

  return {
    oldTestament: counts.oldTestament,
    newTestament: counts.newTestament
  };
}

// Example usage of the processText function
(async () => {
  try {
    const input = "John wrote in John's Gospel, but Genesis is part of Old Testament.";
    const result = await processText(input);
    console.log(result);
  } catch (error) {
    console.error('Error processing text:', error.message);
  }
})();
