// AngularJS Service for Dialog Field Refresh

angular.module('dialogServiceModule', [])
.service('DialogFieldRefreshService', ['$q', '$http', 'CacheFactory', function($q, $http, CacheFactory) {
    var cache = CacheFactory.get('oldTestamentBooks') || CacheFactory.createCache('oldTestamentBooks');

    var oldTestamentBooks = [
        "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", "Judges", 
        "Ruth", "1 Samuel", "2 Samuel", "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles", 
        "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "Song of Songs", 
        "Isaiahus", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", 
        "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"
    ];

    function refreshDialogFields(resourceId, url) {
        var deferred = $q.defer();
        var cachedData = cache.get(resourceId);

        if (cachedData && cachedData.timestamp > Date.now() - 60 * 1000) {
            deferred.resolve(cachedData.fields);
        } else {
            $http.get(url + '/' + resourceId)
                .then(function(response) {
                    var fields = response.data;
                    if (fields) {
                        analyzeFieldsForBooks(fields);
                        cache.put(resourceId, { timestamp: Date.now(), fields: fields });
                        deferred.resolve(fields);
                    } else {
                        deferred.reject('No data received for resource ID ' + resourceId);
                    }
                })
                .catch(function(error) {
                    deferred.reject('Error refreshing dialog fields for resource ID ' + resourceId);
                });
        }

        return deferred.promise;
    }

    function analyzeFieldsForBooks(fields) {
        var regex = new RegExp('\\b(?:' + oldTestamentBooks.join('|') + ')\\b', 'gi');
        Object.keys(fields).forEach(function(key) {
            if (typeof fields[key] === 'string') {
                fields[key] = fields[key].replace(regex, function(match) {
                    return '<strong>' + match + '</strong>';
                });
            }
        });
    }

    this.refreshDialogFields = refreshDialogFields;
}]);
