const express = require('express');
const bodyParser = require('body-parser');
const amqp = require('amqplib');
const mongodb = require('mongodb');
const { MongoClient } = require('mongodb');
const retry = require('retry');

const app = express();
app.use(bodyParser.json());

let rabbitConnection, mongoClient;

async function initRabbitMQ() {
  rabbitConnection = await amqp.connect('amqp://localhost');
  const channel = await rabbitConnection.createChannel();
  await channel.assertQueue('iot_device_queue', { durable: true });
  return channel;
}

async function initMongoDB() {
  mongoClient = await MongoClient.connect('mongodb://localhost:27017/mydb', { useNewUrlParser: true, useUnifiedTopology: true });
  return mongoClient.db('mydb').collection('sensor_data');
}

function createRetryStrategy(attempt) {
  const maxAttempts = 5;
  const minTimeout = 1000;
  const maxTimeout = 64 * 1000;

  return retry.operation({
    retries: maxAttempts - attempt,
    factor: 2,
    minTimeout: minTimeout,
    maxTimeout: maxTimeout
  });
}

app.post('/webhook', async (req, res) => {
  const data = req.body;
  try {
    const db = await initMongoDB();
    await db.insertOne(data);
    res.status(201).send('Data received and stored');
  } catch (error) {
    console.error('Error storing webhook data:', error);
    res.status(500).send('Failed to store data');
  }
});

app.post('/iot_device', async (req, res) => {
  const data = req.body;
  try {
    await rabbitChannel.sendToQueue('iot_device_queue', Buffer.from(JSON.stringify(data)), { persistent: true });
    res.status(201).send('Data received and queued');
  } catch (error) {
    console.error('Error queuing IoT device data:', error);
    res.status(500).send('Failed to queue data');
  }
});

rabbitChannel.consume('iot_device_queue', async (msg) => {
  const data = JSON.parse(msg.content.toString());
  try {
    const db = await initMongoDB();
    await db.insertOne(data);
    rabbitChannel.ack(msg);
  } catch (error) {
    console.error('Error storing IoT device data:', error);
    rabbitChannel.nack(msg, false, true); // Retry message
  }
}, { noAck: false });

setInterval(() => {
  const operation = createRetryStrategy(1);
  operation.attempt(async () => {
    try {
      await initMongoDB();
      console.log('Database connection re-established');
    } catch (error) {
      console.error('Failed to reconnect to database:', error);
      if (!operation.retry(error)) {
        throw error;
      }
    }
  });
}, 30 * 1000);

app.listen(3000, () => {
  initRabbitMQ().then((channel) => {
    rabbitChannel = channel;
    console.log('Server started and RabbitMQ initialized');
  }).catch((error) => {
    console.error('Error initializing RabbitMQ:', error);
  });
});
