import java.util.concurrent.*;
import org.reactivestreams.Publisher;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

public class UnionFindMicroservice {
    // Define Union-Find data structure with path compression and union by rank

    public Publisher<DisjointPair> processDataset(Publisher<Integer> inputStream) {
        return Flux.from(inputStream)
                .flatMap(this::processElement)
                .reduce(DisjointPair.empty(), (a, b) -> a.merge(b))
                .log("TotalProcessingTime", LoggingOperator.of(Duration.ofSeconds(1)))
                .log("MaxSingleCheckTime", LoggingOperator.of(Duration.ofMillis(500)));
    }

    private Mono<DisjointPair> processElement(Integer element) {
        // Implement logic to process each element using Union-Find
        return Mono.just(new DisjointPair(element, element))
                .doOnNext(pair -> System.out.println("Processing pair: " + pair));
    }
}

class DisjointPair {
    private int first;
    private int second;

    public static DisjointPair empty() {
        return new DisjointPair(0, 0);
    }

    public DisjointPair(int first, int second) {
        this.first = first;
        this.second = second;
    }

    public DisjointPair merge(DisjointPair other) {
        // Implement logic to merge disjoint pairs
        return new DisjointPair(this.first, other.second);
    }
}

class LoggingOperator<T> implements Function<Flux<T>, Flux<T>> {
    private Duration duration;

    public LoggingOperator(Duration duration) {
        this.duration = duration;
    }

    @Override
    public Flux<T> apply(Flux<T> flux) {
        return flux
                .timestamp()
                .window(duration)
                .flatMap(window -> window.reduce((a, b) -> a.withTimestamp(b.timestamp()))
                        .map(t -> t.value()));
    }
}
