use std::sync::{Arc, Mutex};
use tokio::time::{self, Duration};

#[derive(Debug)]
enum Command {
    Process,
    Quit,
}

async fn process_data(command: Command) {
    match command {
        Command::Process => {
            // Implement data processing logic using Tokio for asynchronous programming
            println!("Processing data...");
            time::sleep(Duration::from_secs(1)).await;
            println!("Data processed.");
        }
        Command::Quit => {
            println!("Quitting...");
        }
    }
}

#[tokio::main]
async fn main() {
    let command = Arc::new(Mutex::new(Command::Process));

    tokio::spawn(async move {
        loop {
            let mut guard = command.lock().unwrap();
            match *guard {
                Command::Process => process_data(Command::Process).await,
                Command::Quit => break,
            }
        }
    });

    // Simulate receiving a quit command after 5 seconds
    time::sleep(Duration::from_secs(5)).await;
    let mut guard = command.lock().unwrap();
    *guard = Command::Quit;
}
