    const char* jpegFilePath = "example.jpg";
    const char* pdfFilePath = "output.pdf";

    int result = convertJpegToPdf(jpegFilePath, pdfFilePath);
    if (result == 0) {
        printf("JPEG to PDF conversion successful.\n");
    } else {
        printf("JPEG to PDF conversion failed.\n");
    }

    return 0;
}
