// This code snippet provides a high-level outline for implementing an HTTP client library in Rust
// that meets the specified requirements.

use reqwest::{Client, Error, Method};
use std::sync::Arc;
use tokio::sync::Mutex;

pub struct HttpClient {
    client: Arc<Mutex<Client>>,
}

impl HttpClient {
    pub fn new() -> Self {
        HttpClient {
            client: Arc::new(Mutex::new(Client::new())),
        }
    }

    pub async fn update_resource(&self, url: &str, body: String) -> Result<String, Error> {
        let mut client = self.client.lock().await;
        let response = client
            .request(Method::PUT, url)
            .header("Content-Type", "application/json")
            .body(body)
            .send()
            .await?;

        // Handle response and errors here
        Ok(response.text().await?)
    }

    pub async fn delete_resource(&self, url: &str) -> Result<String, Error> {
        let mut client = self.client.lock().await;
        let response = client.request(Method::DELETE, url).send().await?;

        // Handle response and errors here
        Ok(response.text().await?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_update_resource() {
        let http_client = HttpClient::new();
        let url = "https://example.com/resource";
        let body = r#"{"key": "value"}"#;

        let response = http_client.update_resource(url, body.into()).await;
        assert!(response.is_ok());
    }

    #[tokio::test]
    async fn test_delete_resource() {
        let http_client = HttpClient::new();
        let url = "https://example.com/resource";

        let response = http_client.delete_resource(url).await;
        assert!(response.is_ok());
    }
}
