use std::sync::{Arc, Mutex};

pub struct Logger {
    loggers: Arc<Mutex<Vec<Box<dyn Log>>>>,
}

impl Logger {
    pub fn new() -> Self {
        Logger {
            loggers: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn add_logger(&self, logger: Box<dyn Log>) {
        self.loggers.lock().unwrap().push(logger);
    }

    pub fn log(&self, message: &str, details: &str) {
        for logger in self.loggers.lock().unwrap().iter() {
            logger.log(message, details);
        }
    }
}

pub trait Log {
    fn log(&self, message: &str, details: &str);
}

