const axios = require('axios');
const fs = require('fs');
const path = require('path');

async function uploadFileFromURL(url, destinationPath, userId) {
    try {
        const response = await axios({
            method: 'get',
            url,
            responseType: 'stream'
        });

        const writer = fs.createWriteStream(destinationPath);

        response.data.pipe(writer);

        return new Promise((resolve, reject) => {
            writer.on('finish', resolve);
            writer.on('error', reject);
        });
    } catch (error) {
        console.error(`Failed to upload file from ${url} for user ${userId}:`, error);
        throw error;
    }
}

// Example usage:
const url = 'https://example.com/largefile.zip';
const destinationPath = path.join(__dirname, 'largefile.zip');
const userId = 12345;

uploadFileFromURL(url, destinationPath, userId)
    .then(() => console.log('File uploaded successfully'))
    .catch(error => console.error('Error uploading file:', error));
