['```rust
use actix_web::{web, App, HttpResponse, HttpServer};
use awc::Client;
use jsonwebtoken::{encode, decode, Header, EncodingKey, DecodingKey, Validation};
use serde::{Deserialize, Serialize};
use tokio::sync::Mutex;
use std::collections::HashMap;

#[derive(Serialize)]
struct Claims {
    tenant_id: String,
    user_id: String,
    custom_claims: HashMap<String, String>,
}

#[derive(Deserialize)]
struct IdpResponse {
    access_token: String,
    expires_in: u64,
}

async fn generate_jwt(
    payload: web::Json<Claims>,
    secret_key: web::Data<Mutex<String>>,
) -> HttpResponse {
    let secret = secret_key.lock().await;
    let token = encode(&Header::default(), &payload.into_inner(), &EncodingKey::from_secret(secret.as_bytes())).unwrap();
    HttpResponse::Ok().body(token)
}

async fn validate_jwt(
    token: web::Query<String>,
    idp_client: web::Data<Client>,
    idp_config: web::Data<Mutex<HashMap<String, IdpConfig>>>,
) -> HttpResponse {
    let token = &token.token;
    let config = idp_config.lock().await;

    if let Some(idp) = config.get(token.split('.').next().unwrap_or_default()) {
        let response: IdpResponse = idp_client.get(&idp.validate_url)
            .send()
            .await
            .map_err(|_| HttpResponse::InternalServerError().body("Failed to validate token"))?
            .json()
            .await
            .map_err(|_| HttpResponse::InternalServerError().body("Invalid response from IdP"))?;

        let claims = decode::<Claims>(&token, &DecodingKey::from_secret(idp.secret_key.as_bytes()), &Validation::default()).unwrap();
        if claims.claims.tenant_id == idp.tenant_id && claims.claims.user_id == idp.user_id {
            return HttpResponse::Ok().body("Token is valid");
        }
    }

    HttpResponse::Unauthorized().body("Invalid token")
}

#[derive(Deserialize)]
struct IdpConfig {
    validate_url: String,
    secret_key: String,
    tenant_id: String,
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .app_data(web::Data::new(Mutex::new("your_secret_key".to_string())))
            .app_data(web::Data::new(Mutex::new(HashMap::new())))
            .route("/generate_jwt", web::post().to(generate_jwt))
            .route("/validate_jwt", web::get().to(validate_jwt))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
```

