<?php

namespace App\Services;

use GuzzleHttp\Client;
use GuzzleHttp\Exception\RequestException;
use Illuminate\Support\Facades\Redis;
use Illuminate\Support\Facades\Log;

class UserService
{
    private $imsUrl;
    private $client;
    private $redis;

    public function __construct($imsUrl)
    {
        $this->imsUrl = $imsUrl;
        $this->client = new Client(['base_uri' => $imsUrl]);
        $this->redis = Redis::connection();
    }

    public function authenticateUser($username, $password)
    {
        try {
            $response = $this->client->post('api/auth', [
                'form_params' => [
                    'username' => $username,
                    'password' => $password,
                ],
            ]);

            return json_decode($response->getBody(), true);
        } catch (RequestException $e) {
            if ($e->hasResponse() && $e->getResponse()->getStatusCode() == 401) {
                Log::warning('Authentication failed for user: ' . $username);
                return null;
            }

            Log::error('Request to IMS failed: ' . $e->getMessage());
            return null;
        }
    }

    public function enqueuePasswordReset($userId)
    {
        $this->redis->rPush('password_resets', json_encode(['user_id' => $userId]));
    }

    public function passwordStrengthPolicy($policy = [])
    {
        $defaultPolicy = [
            'min_length' => 8,
            'require_uppercase' => true,
            'require_lowercase' => true,
            'require_numbers' => true,
            'require_special_chars' => true,
            'max_retries' => 3,
        ];

        return array_merge($defaultPolicy, $policy);
    }

    public function hashPassword($password)
    {
        $hash = password_hash($password, PASSWORD_BCRYPT);

        if ($hash === false) {
            throw new \RuntimeException('Hashing failed');
        }

