void LogProcessor::calculate_response_time_moving_average(const Json::Value& entry) {
    double response_time = entry["response_time"].asDouble();
    if (response_time_count_ < 10) {
        response_time_sum_ += response_time;
        response_time_count_++;
    } else {
        response_time_sum_ -= log_queue_.back()["response_time"].asDouble() / response_time_count_;
        response_time_sum_ += response_time;
    }
}

int main() {
    LogProcessor processor("config.yaml");
    processor.start_processing();

    // Simulate log file processing
