        Json::Value entry;
        entry["timestamp"] = "2023-10-01T12:00:00Z";
        entry["user_id"] = "user" + std::to_string(i);
        entry["session_id"] = "session" + std::to_string(i);
        entry["response_time"] = 5.0;
        entry["error_count"] = 0;
        entry["geographical_location"] = "US";

        processor.queue_cv_.notify_all();
    }

