#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
#include <functional>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class Task {
public:
    virtual void execute() = 0;
};

class TaskManager {
private:
    std::vector<std::shared_ptr<Task>> tasks;
    std::priority_queue<std::shared_ptr<Task>, std::vector<std::shared_ptr<Task>>, std::function<bool(std::shared_ptr<Task>, std::shared_ptr<Task>)>> taskQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool running;

public:
    TaskManager() : running(false) {}

    void start() {
        running = true;
        for (size_t i = 0; i < 200; ++i) {
            std::thread([this]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    cv.wait(lock, [this] { return !taskQueue.empty() || !running; });
                    if (!running && taskQueue.empty()) break;
                    auto task = taskQueue.top();
                    taskQueue.pop();
                    lock.unlock();
                    task->execute();
                }
            }).detach();
        }
    }

    void stop() {
        running = false;
        cv.notify_all();
    }

    void addTask(std::shared_ptr<Task> task) {
        std::unique_lock<std::mutex> lock(queueMutex);
        taskQueue.push(task);
        cv.notify_one();
    }
};

class ConsoleNotificationService {
public:
    void sendAlert(const std::string& message) {
        std::cout << "Alert: " << message << std::endl;
    }
};

int main() {
    TaskManager manager;
    ConsoleNotificationService notificationService;

    manager.start();

    // Add tasks to the manager
    for (size_t i = 0; i < 100; ++i) {
        auto task = std::make_shared<Task>([&notificationService]() {
            // Simulate task execution
            std::this_thread::sleep_for(std::chrono::seconds(2));
            notificationService.sendAlert("Task completed");
        });
        manager.addTask(task);
    }

    std::this_thread::sleep_for(std::chrono::minutes(1));
    manager.stop();

    return 0;
}
