typedef struct {
    char *token_type;
    int expires_in;
    char **scopes;
    int scope_count;
    time_t issued_at;
    time_t not_before;
} OAuthTokenResponse;

// Function to validate an individual scope string
int validate_scope(const char *scope) {
    for (size_t i = 0; i < strlen(scope); ++i) {
        if (!isalnum((unsigned char)scope[i]) && scope[i] != '-') {
            return 0;
        }
    }
    return 1;
}

// Function to parse and validate the OAuth2 token response
int validate_oauth_token_response(const char *json, OAuthTokenResponse *response) {
    // Placeholder for JSON parsing logic
    // This should be replaced with actual JSON parsing code (e.g., using a library like cJSON)
    // For demonstration purposes, assume the JSON is correctly parsed and we just check the values

    // Example values for demonstration
    response->token_type = strdup("Bearer");
    response->expires_in = 3600;
    char *scope_string = "read write";
    response->scopes = (char **)malloc(2 * sizeof(char *));
    response->scopes[0] = strdup(strtok(scope_string, " "));
    response->scopes[1] = strdup(strtok(NULL, " "));
    response->scope_count = 2;
    response->issued_at = time(NULL);
    response->not_before = time(NULL);

    // Validate the token_type
    if (strcmp(response->token_type, "Bearer") != 0) {
        fprintf(stderr, "Invalid token type: %s\n", response->token_type);
        return -1;
    }

    // Validate expires_in as a positive integer
    if (response->expires_in <= 0) {
        fprintf(stderr, "Expires_in must be a positive integer.\n");
        return -1;
    }

    // Validate scopes
    for (int i = 0; i < response->scope_count; ++i) {
        if (!validate_scope(response->scopes[i])) {
            fprintf(stderr, "Invalid scope: %s\n", response->scopes[i]);
            return -1;
        }
    }

    // Validate optional claims
    if (!response->issued_at || !response->not_before) {
        fprintf(stderr, "Optional claims iat and nbf must be present.\n");
        return -1;
    }

    return 0;
}

// Function to free resources allocated for the OAuthTokenResponse structure
void free_oauth_token_response(OAuthTokenResponse *response) {
    if (response->token_type) {
        free(response->token_type);
    }
    if (response->scopes) {
        for (int i = 0; i < response->scope_count; ++i) {
            free(response->scopes[i]);
        }
        free(response->scopes);
    }
}

// Example usage
int main() {
    const char *json_response = "{\"token_type\":\"Bearer\",\"expires_in\":3600,\"scope\":\"read write\",\"issued_at\":1633072800,\"not_before\":1633072800}";
    OAuthTokenResponse token_response;
    int result = validate_oauth_token_response(json_response, &token_response);
    if (result == 0) {
        printf("Token response is valid.\n");
    } else {
        printf("Token response is invalid.\n");
    }
    free_oauth_token_response(&token_response);
    return 0;
}
```

