    {
        var userJson = JsonSerializer.Serialize(new { UserData = userData });
        var firstDatabaseResponse = await QueryFirstDatabaseAsync(userJson);

        if (firstDatabaseResponse == null) return false;

        var selectedDatabase = GetSelectedDatabase(firstDatabaseResponse);
        var credentials = _configuration.GetSection("Databases:" + selectedDatabase).Get<DatabaseCredentials>();

        try
        {
            using (var connection = new SqlConnection(credentials.ConnectionString))
            {
                await connection.OpenAsync();
                var tokenData = await ValidateTokenWithRetryAsync(connection, token);
                return IsTokenValid(tokenData);
            }
        }
        catch (Exception ex)
        {
            LogError(ex, "Validation failed");
            throw;
        }
    }

    private async Task<string> QueryFirstDatabaseAsync(string userJson)
    {
        var apiKey = _configuration["FirstDatabase:ApiKey"];
        var requestUrl = _configuration["FirstDatabase:RequestUrl"];

        using (var content = new StringContent(userJson, System.Text.Encoding.UTF8, "application/json"))
        {
            content.Headers.Add("Authorization", $"Bearer {apiKey}");
            var response = await _httpClient.PostAsync(requestUrl, content);
            if (!response.IsSuccessStatusCode) return null;
            var responseContent = await response.Content.ReadAsStringAsync();
            return JsonSerializer.Deserialize<string>(responseContent);
        }
    }

