        return "SelectedDatabase";
    }

    private async Task<TokenData> ValidateTokenWithRetryAsync(IDbConnection connection, string token)
    {
        var retryPolicy = new RetryPolicy(3); // Retry up to 3 times

        return await retryPolicy.ExecuteAsync(async () =>
        {
            var query = "SELECT * FROM Tokens WHERE Token = @token";
            var tokenData = await connection.QueryFirstOrDefaultAsync<TokenData>(query, new { token });
            return tokenData;
        });
    }

    private bool IsTokenValid(TokenData tokenData)
    {
        if (tokenData == null) return false;

        if (tokenData.TokenType != "Bearer") return false;
        if (!int.TryParse(tokenData.ExpiresIn, out var expiresIn)) return false;
        if (expiresIn <= 0) return false;

        // Additional validation logic as needed

        return true;
    }

