using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DynamicDataProcessor : IDecryptionService
{
    private readonly TripleDESCryptoServiceProvider _tripleDes;
    private readonly List<IDecryptionProvider> _providers;
    private readonly ICache _cache;
    private readonly ILogger _logger;

    public DynamicDataProcessor(string encryptionKey, string iv, IEnumerable<IDecryptionProvider> providers, ICache cache, ILogger logger)
    {
        _tripleDes = new TripleDESCryptoServiceProvider
        {
            Key = Convert.FromBase64String(encryptionKey),
            IV = Convert.FromBase64String(iv)
        };
        _providers = providers.ToList();
        _cache = cache;
        _logger = logger;
    }

    public async Task<int> DecryptAsync(string base64EncodedData)
    {
        if (_cache.TryGetValue(base64EncodedData, out int result))
        {
            return result;
        }

        byte[] data = Convert.FromBase64String(base64EncodedData);
        byte[] decryptedBytes = _tripleDes.CreateDecryptor().TransformFinalBlock(data, 0, data.Length);

        try
        {
            string decryptedData = Encoding.UTF8.GetString(decryptedBytes);
            int number = int.Parse(decryptedData);

            if (number >= 1 && number <= 1000)
            {
                _cache.Set(base64EncodedData, number);
                return number;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Decryption failed");
        }

        foreach (var provider in _providers.OrderBy(p => p.GetLatency()))
        {
            try
            {
                result = await provider.DecryptAsync(base64EncodedData);
                if (result >= 1 && result <= 1000)
                {
                    _cache.Set(base64EncodedData, result);
                    return result;
                }
                break; // If the decrypted number is out of range, no need to try other providers
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Decryption failed with provider");
            }
        }

        throw new InvalidOperationException("Decryption failed after trying all providers");
    }
}

public interface IDecryptionService
{
    Task<int> DecryptAsync(string base64EncodedData);
}

public interface IDecryptionProvider
{
    Task<int> DecryptAsync(string base64EncodedData);
    double GetLatency();
}

public class HttpDecryptionProvider : IDecryptionProvider
{
