    public async Task<int> DecryptAsync(string base64EncodedData)
    {
        var response = await _httpClient.PostAsync(_endpoint, new StringContent(base64EncodedData));
        if (response.IsSuccessStatusCode)
        {
            string decryptedData = await response.Content.ReadAsStringAsync();
            return int.Parse(decryptedData);
        }
        throw new InvalidOperationException("Failed to decrypt data");
    }

    public double GetLatency()
    {
