    }
}

public interface ICache
{
    T TryGetValue<TKey, T>(TKey key, out T result);
    void Set<TKey, T>(TKey key, T value);
}

public class LruCache : ICache
{
    private readonly int _capacity;
    private readonly Dictionary<string, CacheItem> _cache;
    private readonly LinkedList<string> _order;

    public LruCache(int capacity)
    {
        _capacity = capacity;
        _cache = new Dictionary<string, CacheItem>();
        _order = new LinkedList<string>();
    }

    public T TryGetValue<TKey, T>(TKey key, out T result)
    {
        if (_cache.TryGetValue(key.ToString(), out var item))
        {
            _order.Remove(item.Key);
            _order.AddFirst(item.Key);
            result = (T)item.Value;
            return result;
        }
        result = default(T);
        return false;
    }

    public void Set<TKey, T>(TKey key, T value)
    {
        string keyStr = key.ToString();
        if (_cache.ContainsKey(keyStr))
        {
            _order.Remove(keyStr);
        }
        else if (_cache.Count >= _capacity)
        {
            var lastKey = _order.Last.Value;
            _cache.Remove(lastKey);
            _order.RemoveLast();
        }

        _cache[keyStr] = new CacheItem
        {
            Key = keyStr,
            Value = value
        };
        _order.AddFirst(keyStr);
    }
}

public class CacheItem
{
    public string Key { get; set; }
    public object Value { get; set; }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}

public class ConsoleLogger : ILogger
{
    public void LogError(Exception ex, string message)
    {
        Console.Error.WriteLine($"{message}: {ex.Message}");
    }
}
