@Service
public class TransactionService {

    private final WebClient webClient;

    @Autowired
    public TransactionService(WebClient.Builder webClientBuilder) {
        this.webClient = webClientBuilder.baseUrl("https://api.external.com/").build();
    }

    @Async
    public void processTransaction(Transaction transaction) {
        try {
            // Process transaction with retry mechanism
            RetryConfig retryConfig = Retry.fixedDelay(3, Duration.ofMillis(100));
            RetryTemplate retryTemplate = RetryTemplate.builder()
                    .fixedBackOffPolicy(new FixedBackOffPolicy().withFixedBackOffPeriod(Duration.ofMillis(100)))
                    .maxAttempts(3)
                    .build();

            String response = retryTemplate.execute(context -> {
                return webClient.post()
                        .uri("/process")
                        .contentType(MediaType.APPLICATION_JSON)
                        .bodyValue(transaction)
                        .retrieve()
                        .bodyToMono(String.class)
                        .block();
            });

            // Handle response
        } catch (Exception e) {
            // Handle error and fallback mechanism
        }
    }
}

