@Configuration
public class Resilience4jConfig {

    @Bean
    public RetryRegistry retryRegistry() {
        return RetryRegistry.ofDefaults();
    }

    @Bean
    public RateLimiterRegistry rateLimiterRegistry() {
        return RateLimiterRegistry.ofDefaults();
    }
}

// Define a Circuit Breaker for external API calls
@Service
public class ExternalApiCircuitBreaker {

    private final Retry retry;
    private final RateLimiter rateLimiter;

    @Autowired
    public ExternalApiCircuitBreaker(RetryRegistry retryRegistry, RateLimiterRegistry rateLimiterRegistry) {
        this.retry = Retry.of("external-api", RetryConfig.ofDefaults());
        this.rateLimiter = RateLimiter.of("external-api", RateLimiterConfig.custom()
                .limitForPeriod(20)
                .limitRefreshPeriod(Duration.ofSeconds(1))
                .timeoutDuration(Duration.ofSeconds(5))
                .build());
    }

    public String callExternalApi(Transaction transaction) {
        return rateLimiter.execute(() -> retry.executeSupplier(context -> 
            WebClient.builder().baseUrl("https://api.external.com/")
                    .post()
                    .uri("/process")
                    .contentType(MediaType.APPLICATION_JSON)
                    .bodyValue(transaction)
                    .retrieve()
                    .bodyToMono(String.class)
                    .block()));
    }
}
