using System;
using System.Collections.Generic;
using System.Net.WebSockets;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

public class StreamingDataProcessor : IHostedService, IDisposable
{
    private readonly List<WebSocket> _webSockets = new();
    private readonly IConfiguration _configuration;
    private readonly IServiceScopeFactory _serviceScopeFactory;

    public StreamingDataProcessor(IConfiguration configuration, IServiceScopeFactory serviceScopeFactory)
    {
        _configuration = configuration;
        _serviceScopeFactory = serviceScopeFactory;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        // Connect to WebSocket and message broker
        for (int i = 0; i < _configuration.GetValue<int>("WebSocketCount"); i++)
        {
            var webSocket = new ClientWebSocket();
            await webSocket.ConnectAsync(new Uri(_configuration.GetValue<string>("WebSocketUrl")), cancellationToken);
            _webSockets.Add(webSocket);
        }

        // Start processing messages
        await Task.WhenAll(_webSockets.Select(ProcessMessagesAsync));
    }

    private async Task ProcessMessagesAsync(WebSocket webSocket)
    {
        var buffer = new byte[1024 * 4];
        while (webSocket.State == WebSocketState.Open)
        {
            var result = await webSocket.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);
            if (result.MessageType == WebSocketMessageType.Text)
            {
                // Process the message
                using (var scope = _serviceScopeFactory.CreateScope())
                {
                    var messageProcessor = scope.ServiceProvider.GetRequiredService<IMessageProcessor>();
                    await messageProcessor.ProcessMessageAsync(result.Buffer, result.Count);
                }
            }
        }
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        foreach (var webSocket in _webSockets)
        {
            await webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, "Closing", CancellationToken.None);
        }
    }

    public void Dispose()
    {
        foreach (var webSocket in _webSockets)
        {
            webSocket.Dispose();
        }
    }
}

public interface IMessageProcessor
{
    Task ProcessMessageAsync(byte[] buffer, int count);
}

public class MessageProcessor : IMessageProcessor
{
    public async Task ProcessMessageAsync(byte[] buffer, int count)
    {
        // Implement message processing logic here
    }
}
