const AWS = require('aws-sdk');
const express = require('express');
const multer = require('multer');
const { v4: uuidv4 } = require('uuid');
const fs = require('fs');
const path = require('path');

// Initialize AWS S3 client
AWS.config.update({ region: 'us-west-2' });
const s3 = new AWS.S3();

// Configuration
const config = {
  allowedFileTypes: ['image/jpeg', 'image/png'],
  maxFileSize: 5 * 1024 * 1024, // 5MB
};

// Middleware for handling file uploads with Multer
const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: config.maxFileSize },
});

// Express application setup
const app = express();
app.use(express.json());

// Function to generate tenant-specific directory
function getTenantDirectory(tenantId) {
  return `tenant-${tenantId}/`;
}

// Function to validate file type and size
function validateFile(file) {
  const fileType = file.mimetype;
  const fileSize = file.size;

  if (!config.allowedFileTypes.includes(fileType)) {
    throw new Error('Invalid file type');
  }
  if (fileSize > config.maxFileSize) {
    throw new Error('File size exceeds limit');
  }
}

// Function to upload file to S3
async function uploadToS3(tenantId, fileBuffer, fileName) {
  const bucketName = 'your-bucket-name';
  const directory = getTenantDirectory(tenantId);
  const params = {
    Bucket: bucketName,
    Key: `${directory}${fileName}`,
    Body: fileBuffer,
    ContentType: file.mimetype,
  };

  return s3.upload(params).promise();
}

// Main upload function
async function uploadFileWithValidation(req, res) {
  try {
    const tenantId = req.headers['x-tenant-id'];
    if (!tenantId) throw new Error('Tenant ID is required');

    const file = req.file;
    if (!file) throw new Error('No file uploaded');

    validateFile(file);

    const fileName = `${uuidv4()}-${path.extname(file.originalname).toLowerCase()}`;
    await uploadToS3(tenantId, file.buffer, fileName);

    res.status(200).json({ url: `https://${bucketName}.s3.amazonaws.com/${getTenantDirectory(tenantId)}${fileName}` });
  } catch (error) {
    console.error(error);
    res.status(400).json({ error: error.message });
  }
}

// Route for handling file uploads
app.post('/upload', upload.single('file'), uploadFileWithValidation);

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

