        pub retry_limit: u32,
        pub logging_level: log::LevelFilter,
    }

    impl Config {
        pub fn load_config() -> Self {
            let host = env::var("HOST").unwrap_or_else(|_| "127.0.0.1".to_string());
            let port: u16 = env::var("PORT")
                .map(|v| v.parse().expect("Invalid PORT"))
                .unwrap_or(8080);
            let api_endpoint = env::var("API_ENDPOINT").unwrap();
            let timeout: u64 = env::var("TIMEOUT")
                .map(|v| v.parse().expect("Invalid TIMEOUT"))
                .unwrap_or(5);
            let retry_limit: u32 = env::var("RETRY_LIMIT")
                .map(|v| v.parse().expect("Invalid RETRY_LIMIT"))
                .unwrap_or(3);
            let logging_level = env::var("LOGGING_LEVEL")
                .map(|v| log::LevelFilter::from_str(&v).expect("Invalid LOGGING_LEVEL"))
                .unwrap_or(log::LevelFilter::Info);

            Config {
                host,
                port,
                api_endpoint,
                timeout,
                retry_limit,
                logging_level,
            }
        }
    }
}

