import abc
from collections import defaultdict
from threading import Lock
import json

class DataModel(abc.ABC):
    @abc.abstractmethod
    def serialize(self) -> dict:
        pass

    @abc.abstractmethod
    def deserialize(self, data: dict) -> None:
        pass

class Factory:
    _registry = defaultdict(list)
    _lock = Lock()

    @staticmethod
    def register(model_id, factory_function):
        with Factory._lock:
            Factory._registry[model_id].append(factory_function)

    @staticmethod
    def get_factory(model_id) -> callable:
        factories = Factory._registry.get(model_id, [])
        if not factories:
            raise ValueError(f"No factories registered for model ID: {model_id}")
        return factories[0]

class Registry:
    _instances = {}
    _lock = Lock()

    @staticmethod
    def get_instance(model_id):
        with Registry._lock:
            instance = Registry._instances.get(model_id)
            if not instance:
                factory = Factory.get_factory(model_id)
                instance = factory()
                Registry._instances[model_id] = instance
            return instance

class DataSerializer:
    @staticmethod
    def serialize(data_model: DataModel) -> str:
        data_dict = data_model.serialize()
        return json.dumps(data_dict)

class DataDeserializer:
    @staticmethod
    def deserialize(json_str, model_id):
        data_dict = json.loads(json_str)
        instance = Registry.get_instance(model_id)
        instance.deserialize(data_dict)
        return instance

# Example usage
class User(DataModel):
    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age

    def serialize(self) -> dict:
        return {"name": self.name, "age": self.age}

    def deserialize(self, data: dict) -> None:
        self.name = data["name"]
        self.age = data["age"]

# Registering the factory for User model
Factory.register("user", lambda: User("", 0))

# Simulating data ingestion and transformation
json_input = '{"name": "John Doe", "age": 30}'
model_id = "user"
deserialized_user = DataDeserializer.deserialize(json_input, model_id)
print(f"Deserialized User: {deserialized_user.name}, Age: {deserialized_user.age}")

serialized_user = DataSerializer.serialize(deserialized_user)
print(f"Serialized User JSON: {serialized_user}")
```']

