use std::sync::{Arc, Mutex};
use tokio::sync::mpsc;
use tokio::time::{self, Duration};
use tracing::{error, info, instrument};

#[derive(Debug)]
struct Event {
    timestamp: time::Instant,
    event_type: String,
    metadata: serde_json::Value,
}

#[derive(Debug)]
enum ExternalServiceError {
    NetworkFailure,
    LoggingServiceOutage,
    InvalidTimestamp,
}

struct EventProcessor {
    analytics_platform: Arc<Mutex<dyn AnalyticsPlatform>>,
    message_broker: Arc<Mutex<dyn MessageBroker>>,
    log_service: Arc<Mutex<dyn SecureLoggingService>>,
    cache: Cache,
}

impl EventProcessor {
    fn new(
        analytics_platform: Arc<Mutex<dyn AnalyticsPlatform>>,
        message_broker: Arc<Mutex<dyn MessageBroker>>,
        log_service: Arc<Mutex<dyn SecureLoggingService>>,
        cache_size: usize,
    ) -> Self {
        EventProcessor {
            analytics_platform,
            message_broker,
            log_service,
            cache: Cache::new(cache_size),
        }
    }

    #[instrument]
    async fn process_event(&self, event: Event) {
        if self.cache.contains(&event.timestamp) {
            return;
        }

        self.cache.insert(event.timestamp.clone());

        match self.analytics_platform.lock().unwrap().process_event(&event).await {
            Ok(_) => {}
            Err(e) => error!("Failed to process event with analytics platform: {:?}", e),
        }

        match self.message_broker.lock().unwrap().send_event(&event).await {
            Ok(_) => {}
            Err(e) => error!("Failed to send event through message broker: {:?}", e),
        }

        if let Err(e) = self.log_service.lock().unwrap().log_event(&event).await {
            error!("Failed to log event using secure logging service: {:?}", e);
        }
    }
}

trait AnalyticsPlatform {
    async fn process_event(&self, event: &Event) -> Result<(), ExternalServiceError>;
}

trait MessageBroker {
    async fn send_event(&self, event: &Event) -> Result<(), ExternalServiceError>;
}

trait SecureLoggingService {
    async fn log_event(&self, event: &Event) -> Result<(), ExternalServiceError>;
}

struct Cache {
    inner: std::collections::HashSet<time::Instant>,
}

impl Cache {
    fn new(size: usize) -> Self {
        Cache {
            inner: std::collections::HashSet::with_capacity(size),
        }
    }

    fn contains(&self, timestamp: &time::Instant) -> bool {
        self.inner.contains(timestamp)
    }

    fn insert(&mut self, timestamp: time::Instant) {
        if self.inner.len() >= 1000 {
            self.inner.clear();
        }
        self.inner.insert(timestamp);
    }
}

#[tokio::main]
async fn main() {
    // Setup tracing
    tracing_subscriber::fmt::init();

    let analytics_platform = Arc::new(Mutex::new(MockAnalyticsPlatform {}));
    let message_broker = Arc::new(Mutex::new(MockMessageBroker {}));
    let log_service = Arc::new(Mutex::new(MockSecureLoggingService {}));

    let event_processor = EventProcessor::new(analytics_platform, message_broker, log_service, 1000);

    let (tx, mut rx) = mpsc::channel(32);
    tokio::spawn(async move {
        while let Some(event) = rx.recv().await {
            event_processor.process_event(event).await;
        }
    });

    // Simulate incoming events
    for _ in 0..100 {
        tx.send(Event {
            timestamp: time::Instant::now(),
            event_type: "click".to_string(),
            metadata: serde_json::json!({}),
        })
        .await
        .unwrap();
        time::sleep(Duration::from_millis(100)).await;
    }
}

struct MockAnalyticsPlatform {}

impl AnalyticsPlatform for MockAnalyticsPlatform {
    async fn process_event(&self, _event: &Event) -> Result<(), ExternalServiceError> {
        Ok(())
    }
}

struct MockMessageBroker {}

impl MessageBroker for MockMessageBroker {
    async fn send_event(&self, _event: &Event) -> Result<(), ExternalServiceError> {
        Ok(())
    }
}

struct MockSecureLoggingService {}

impl SecureLoggingService for MockSecureLoggingService {
    async fn log_event(&self, _event: &Event) -> Result<(), ExternalServiceError> {
        Ok(())
    }
}
