#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <unordered_map>
#include <atomic>
#include <iostream>
#include "packet_capture_library.h" // Hypothetical external library

class NetworkPacket {
public:
    std::string sourceIP;
    size_t packetSize;
    int ttl;
    int packetID;
};

class PacketQueueManager {
private:
    static constexpr size_t MAX_PACKETS = 100;
    static constexpr size_t TTL_CHECK_INTERVAL = 5 * 1000; // 5 seconds
    static constexpr size_t AVG_SIZE_CALCULATION_INTERVAL = 10 * 1000; // 10 seconds

    std::queue<NetworkPacket> packetQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    std::unordered_map<int, NetworkPacket> packetMap;
    std::atomic<size_t> totalPacketSize{0};
    size_t packetCount = 0;

    void ttlChecker() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(TTL_CHECK_INTERVAL));
            auto now = std::chrono::steady_clock::now();
            std::unique_lock<std::mutex> lock(queueMutex);
            while (!packetQueue.empty()) {
                NetworkPacket packet = packetQueue.front();
                if (now - packetQueue.front().creationTime > std::chrono::seconds(5)) {
                    packetQueue.pop();
                    packetMap.erase(packet.packetID);
                    totalPacketSize -= packet.packetSize;
                    packetCount--;
                } else {
                    break;
                }
            }
        }
    }

    void averageSizeCalculator() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(AVG_SIZE_CALCULATION_INTERVAL));
            size_t avgSize = 0;
            for (const auto& pair : packetMap) {
                avgSize += pair.second.packetSize;
            }
            avgSize /= packetMap.size();
            std::cout << "Average Packet Size: " << avgSize << std::endl;
        }
    }

public:
    void pushPacket(const NetworkPacket& packet) {
        std::unique_lock<std::mutex> lock(queueMutex);
        if (packetQueue.size() >= MAX_PACKETS) {
            auto oldest = packetQueue.front();
            packetQueue.pop();
            packetMap.erase(oldest.packetID);
            totalPacketSize -= oldest.packetSize;
            packetCount--;
        }
        packetQueue.push(packet);
        packetMap[packet.packetID] = packet;
        totalPacketSize += packet.packetSize;
        packetCount++;
        lock.unlock();
        notEmpty.notify_one();
    }

    NetworkPacket popPacket() {
        std::unique_lock<std::mutex> lock(queueMutex);
        notEmpty.wait(lock, [this]{ return !packetQueue.empty(); });
        NetworkPacket packet = packetQueue.front();
        packetQueue.pop();
        packetMap.erase(packet.packetID);
        totalPacketSize -= packet.packetSize;
        packetCount--;
        return packet;
    }

    void start() {
        std::thread ttlThread(&PacketQueueManager::ttlChecker, this);
        std::thread avgThread(&PacketQueueManager::averageSizeCalculator, this);
        ttlThread.detach();
        avgThread.detach();
    }
};
