// Function to handle JSON requests and validate tokens
void handle_request(const char* json_request) {
    // Parse JSON request to extract access token
    const char* token_start = strstr(json_request, "access_token=");
    if (token_start == NULL) {
        printf("Invalid JSON structure\n");
        return;
    }
    token_start += 15; // Length of "access_token="
    const char* token_end = strchr(token_start, '"');
    if (token_end == NULL) {
        printf("Invalid JSON structure\n");
        return;
    }
    size_t token_length = token_end - token_start;
    char token[token_length + 1];
    strncpy(token, token_start, token_length);
    token[token_length] = '\0';

    // Validate the access token
    int result = validate_token(token);
    if (result == 0) {
        printf("Token is valid\n");
    } else {
        printf("Token is invalid\n");
    }
}

int main() {
    const char* json_request = "{\"access_token\":\"abc123\"}";
    handle_request(json_request);

    return 0;
}
