#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/websocket.hpp>
#include <boost/property_tree/json_parser.hpp>
#include <boost/property_tree/ptree.hpp>
#include <redis-plus-plus/include/all.h>
#include <spdlog/spdlog.h>
#include <spdlog/sinks/async.h>

// Define event structure
struct Event {
    std::chrono::system_clock::time_point timestamp;
    std::string type;
    std::map<std::string, std::string> metadata;
};

// Function to handle incoming network events
void handle_event(const Event& event) {
    // Log event details
    spdlog::info("Received event: Type={}, Timestamp={}, Metadata={}",
                 event.type, event.timestamp.time_since_epoch().count(), 
                 event.metadata);

    // Store event in NoSQL database
    redis::client client("tcp://localhost:6379");
    client.set(event.type + ":" + std::to_string(std::chrono::duration_cast<std::chrono::milliseconds>(event.timestamp.time_since_epoch()).count()), event.metadata);
}

// WebSocket server to receive network events
int main() {
    try {
        boost::asio::io_context ioc;
        boost::beast::websocket::server<boost::beast::tcp_stream> ws_server(ioc);

        // Configure and start WebSocket server
        ws_server.listen(boost::beast::ip::make_address("0.0.0.0"), 8080);
        ws_server.start_accept();

        // Run the I/O service to block until all work is done
        ioc.run();
    } catch (std::exception& e) {
        spdlog::error("Exception: {}", e.what());
    }
    return 0;
}
```

This code snippet demonstrates setting up a basic WebSocket server using Boost.Asio and Boost.Beast libraries to receive real-time network events. Each event is logged using Spdlog for asynchronous, secure communication and stored in a Redis database. The system can be further developed to include distributed caching, custom load balancing, error handling, monitoring, and automated testing as per the requirements specified.']

