#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef enum {
    AES_128,
    AES_192,
    AES_256,
    DES,
    CHACHA20
} EncryptionAlgorithm;

typedef enum {
    ECB,
    CBC,
    CFB,
    OFB,
    GCM_CCM
} EncryptionMode;

typedef struct {
    EncryptionAlgorithm algorithm;
    EncryptionMode mode;
    void* key;
    int key_size;
} EncryptionContext;

void initialize_encryption_context(EncryptionContext* ctx, EncryptionAlgorithm algo, EncryptionMode mode, void* key, int key_size) {
    ctx->algorithm = algo;
    ctx->mode = mode;
    ctx->key = malloc(key_size);
    memcpy(ctx->key, key, key_size);
    ctx->key_size = key_size;
}

void cleanup_encryption_context(EncryptionContext* ctx) {
    free(ctx->key);
}

int encrypt_data(const EncryptionContext* ctx, const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext, unsigned char* iv) {
    EVP_CIPHER_CTX* ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) return -1;

    int len;
    if (EVP_EncryptInit_ex(ctx_evp, get_cipher_from_algorithm(ctx->algorithm), NULL, ctx->key, iv) != 1 ||
        EVP_EncryptUpdate(ctx_evp, ciphertext, &len, plaintext, plaintext_len) != 1 ||
        EVP_EncryptFinal_ex(ctx_evp, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx_evp);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx_evp);
    return len;
}

EVP_CIPHER* get_cipher_from_algorithm(EncryptionAlgorithm algo) {
    switch (algo) {
        case AES_128: return EVP_aes_128_ecb();
        case AES_192: return EVP_aes_192_ecb();
        case AES_256: return EVP_aes_256_ecb();
        case DES:     return EVP_des_ecb();
        case CHACHA20:return EVP_chacha20_poly1305();
        default:      return NULL;
    }
}

int main() {
    unsigned char key[32] = {0}; // Example key
    unsigned char iv[16]  = {0};  // Example IV
    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[sizeof(plaintext)];

    EncryptionContext ctx;
    initialize_encryption_context(&ctx, AES_256, ECB, key, sizeof(key));

    int encrypted_len = encrypt_data(&ctx, plaintext, sizeof(plaintext), ciphertext, iv);
    if (encrypted_len < 0) {
        printf("Encryption failed\n");
    } else {
        printf("Encrypted message: %.*s\n", encrypted_len, ciphertext);
    }

    cleanup_encryption_context(&ctx);

    return 0;
}
