#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/enable_shared_from_this.hpp>
#include <iostream>
#include <memory>
#include <string>

namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

class session : public std::enable_shared_from_this<session> {
    tcp::socket socket_;
    beast::flat_buffer buffer_;

public:
    explicit session(tcp::socket socket) : socket_(std::move(socket)) {}

    void do_read() {
        http::async_read(socket_, buffer_, [this](beast::error_code ec, std::size_t bytes_transferred) {
            if (!ec)
                this->do_write(bytes_transferred);
        });
    }

    void do_write(std::size_t bytes_transferred) {
        http::write(socket_, buffer_);
    }
};

class server {
    tcp::acceptor acceptor_;

public:
    server(net::io_context& ioc, tcp::endpoint endpoint)
        : acceptor_(ioc, endpoint) {}

    void start() {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            [this](beast::error_code ec, tcp::socket socket) {
                if (!ec)
                    std::make_shared<session>(std::move(socket))->start();

                do_accept();
            });
    }
};

int main(int argc, char** argv) {
    try {
        auto const address = net::ip::make_address("0.0.0.0");
        auto const port = static_cast<unsigned short>(8080);
        tcp::endpoint endpoint(address, port);

        net::io_context ioc{1};

        server s(ioc, endpoint);
        s.start();

        return ioc.run();
    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }
}
