// Function to encrypt data using DES cipher modes (ECB, EDE, EDE3)
int des_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key,
               const unsigned char *iv, unsigned char *ciphertext, const char *mode) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (strcmp(mode, "ECB") == 0) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
    } else if (strcmp(mode, "EDE") == 0) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_des_ede(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
    } else if (strcmp(mode, "EDE3") == 0) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_des_ede3(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
    } else if (strcmp(mode, "CFB") == 0) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_des_cfb8(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to hash data using MD5
void md5_hash(const unsigned char *data, int data_len, unsigned char *hash) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, data, data_len);
    MD5_Final(hash, &md5);
}

// Function to perform a custom logging
void custom_log(const char *message) {
