#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/des.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

#define MAX_THREADS 100

typedef enum {
    ENCRYPTION,
    DECRYPTION
} Operation;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CryptoContext;

CryptoContext* create_context(EVP_CIPHER *cipher, const unsigned char *key, const unsigned char *iv) {
    CryptoContext *context = (CryptoContext*)malloc(sizeof(CryptoContext));
    context->ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(context->ctx, cipher, NULL, key, iv);
    return context;
}

void destroy_context(CryptoContext *context) {
    EVP_CIPHER_CTX_free(context->ctx);
    free(context);
}

void encrypt_decrypt(Operation operation, CryptoContext *context, unsigned char *in_data, int in_len, unsigned char *out_data) {
    if (operation == ENCRYPTION) {
        EVP_EncryptUpdate(context->ctx, out_data, &in_len, in_data, in_len);
        EVP_EncryptFinal_ex(context->ctx, out_data + in_len, &in_len);
    } else {
        EVP_DecryptUpdate(context->ctx, out_data, &in_len, in_data, in_len);
        EVP_DecryptFinal_ex(context->ctx, out_data + in_len, &in_len);
    }
}

void *worker_thread(void *arg) {
    // Simulate work
    pthread_exit(NULL);
}

int main() {
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    EVP_CIPHER *cipher = EVP_aes_256_cbc();

    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate random bytes\n");
        return 1;
    }

    CryptoContext *context = create_context(cipher, key, iv);
    if (!context) {
        fprintf(stderr, "Failed to create context\n");
        return 1;
    }

    unsigned char in_data[] = "Hello, World!";
    int in_len = strlen((char*)in_data);
    unsigned char out_data[in_len + EVP_CIPHER_block_size(cipher)];

    encrypt_decrypt(ENCRYPTION, context, (unsigned char*)in_data, in_len, out_data);

    printf("Encrypted: ");
    for (int i = 0; i < in_len; i++) {
        printf("%02x", out_data[i]);
    }
    printf("\n");

    // Simulate thread pool
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_context(context);

    return 0;
}
