class PaymentGateway {
public:
    virtual ~PaymentGateway() {}
    virtual bool processTransaction(const std::string& transactionData) = 0;
};

class CreditCardGateway : public PaymentGateway {
public:
    bool processTransaction(const std::string& transactionData) override {
        // Simulate credit card processing
        std::cout << "Processing credit card transaction: " << transactionData << std::endl;
        return true; // Simulated success
    }
};

class BankTransferGateway : public PaymentGateway {
public:
    bool processTransaction(const std::string& transactionData) override {
        // Simulate bank transfer processing
        std::cout << "Processing bank transfer: " << transactionData << std::endl;
        return true; // Simulated success
    }
};

class CryptoGateway : public PaymentGateway {
public:
    bool processTransaction(const std::string& transactionData) override {
        // Simulate cryptocurrency processing
        std::cout << "Processing cryptocurrency transaction: " << transactionData << std::endl;
        return true; // Simulated success
    }
};

class PaymentProcessor {
public:
    void addGateway(std::unique_ptr<PaymentGateway> gateway) {
        gateways_.push_back(std::move(gateway));
    }

    void processTransaction(const std::string& transactionData) {
        std::lock_guard<std::mutex> lock(mutex_);
        transactions_.push(transactionData);
        cv_.notify_one();
    }

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !transactions_.empty(); });
            std::string transaction = transactions_.front();
            transactions_.pop();

            lock.unlock();
            for (auto& gateway : gateways_) {
                if (gateway->processTransaction(transaction)) {
                    std::cout << "Transaction processed successfully." << std::endl;
                } else {
                    std::cout << "Transaction failed." << std::endl;
                }
            }
        }
    }

private:
    std::vector<std::unique_ptr<PaymentGateway>> gateways_;
    std::queue<std::string> transactions_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

int main() {
    PaymentProcessor processor;

    processor.addGateway(std::make_unique<CreditCardGateway>());
    processor.addGateway(std::make_unique<BankTransferGateway>());
    processor.addGateway(std::make_unique<CryptoGateway>());

    std::vector<std::thread> workers;
    for (int i = 0; i < 3; ++i) {
        workers.emplace_back(&PaymentProcessor::worker, &processor);
    }

    // Simulate processing transactions
    processor.processTransaction("CreditCard:1234-5678-9012-3456");
    processor.processTransaction("BankTransfer:1234567890");
    processor.processTransaction("Crypto:abcdef123456");

    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
