#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <unordered_map>
#include <vector>

class NetworkPacket {
public:
    std::string sourceIP;
    int size;
    int ttl;
    int packetID;

    NetworkPacket(std::string ip, int sz, int ttl, int id) : sourceIP(ip), size(sz), ttl(ttl), packetID(id) {}
};

class PacketQueueManager {
private:
    std::queue<NetworkPacket> queue_;
    std::mutex mtx_;
    std::condition_variable cv_;
    std::unordered_map<int, std::chrono::time_point<std::chrono::system_clock>> packetTimes_;
    int maxActivePackets_ = 100;
    double avgPacketSize_ = 0;

public:
    void enqueue(const NetworkPacket& packet) {
        std::unique_lock<std::mutex> lock(mtx_);
        while (queue_.size() >= maxActivePackets_) cv_.wait(lock, [this]{ return queue_.size() < maxActivePackets_; });
        queue_.push(packet);
        packetTimes_[packet.packetID] = std::chrono::system_clock::now();
        avgPacketSize_ = ((avgPacketSize_ * (queue_.size() - 1)) + packet.size) / queue_.size();
        lock.unlock();
        cv_.notify_all();
    }

    NetworkPacket dequeue() {
        std::unique_lock<std::mutex> lock(mtx_);
        while (queue_.empty()) cv_.wait(lock);
        NetworkPacket packet = queue_.front();
        queue_.pop();
        packetTimes_.erase(packet.packetID);
        lock.unlock();
        cv_.notify_all();
        return packet;
    }

    void pruneOldPackets() {
        std::unique_lock<std::mutex> lock(mtx_);
        auto now = std::chrono::system_clock::now();
        while (!queue_.empty() && std::chrono::duration_cast<std::chrono::seconds>(now - packetTimes_[queue_.front().packetID]).count() > 5) {
            NetworkPacket packet = queue_.front();
            queue_.pop();
            packetTimes_.erase(packet.packetID);
        }
    }

    double getAveragePacketSize() const {
        return avgPacketSize_;
    }
};

class PacketCapture {
private:
    NetworkQueueManager& packetQueueManager;
    std::thread captureThread_;
    bool running_ = true;

public:
    PacketCapture(NetworkQueueManager& pqm) : packetQueueManager(pqm) {
        captureThread_ = std::thread([this]{ this->captureData(); });
    }

    ~PacketCapture() {
        running_ = false;
        captureThread_.join();
    }

    void captureData() {
        while (running_) {
            // Simulate capturing a packet
            NetworkPacket packet("192.168.1.1", 1024, 32, std::rand());
            packetQueueManager.enqueue(packet);
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }
};

int main() {
    NetworkQueueManager pqm;
    PacketCapture pc(pqm);

    // Simulate processing packets
    for (int i = 0; i < 1000; ++i) {
        NetworkPacket packet = pqm.dequeue();
        std::cout << "Processed packet ID: " << packet.packetID << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(20));
    }

    return 0;
}
