        EVP_CIPHER_CTX* ctx = createCipherContext();
        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, reinterpret_cast<unsigned char*>(const_cast<char*>(key.c_str())), NULL)) {
            destroyCipherContext(ctx);
            throw std::runtime_error("Encryption initialization failed");
        }
        // ... (implement encryption process)
        std::string encryptedData;
        // ... (store or return the encrypted data)
        destroyCipherContext(ctx);
        return encryptedData;
    }

    std::string decrypt(const std::string& encryptedData, const std::string& key) {
        EVP_CIPHER_CTX* ctx = createCipherContext();
        if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, reinterpret_cast<unsigned char*>(const_cast<char*>(key.c_str())), NULL)) {
            destroyCipherContext(ctx);
            throw std::runtime_error("Decryption initialization failed");
        }
        // ... (implement decryption process)
        std::string decryptedData;
        // ... (return the decrypted data)
        destroyCipherContext(ctx);
        return decryptedData;
    }

    void handleConcurrency() {
        std::mutex mutex;
        std::vector<std::future<void>> futures;

        for (int i = 0; i < 100; ++i) {
            auto task = [this, &mutex]() {
                std::lock_guard<std::mutex> lock(mutex);
                // ... (perform encryption or decryption)
            };
            futures.emplace_back(std::async(std::launch::async, task));
        }

        for (auto& future : futures) {
            future.wait();
        }
    }
};

// Example Usage
