    CloudStorageProvider* storage = new CloudStorageProviderImplementation();

    EncryptionService service(kms, storage);
    std::string data = "Sensitive user data";
    std::string key = service.kms->generateKey();

    std::string encryptedData = service.encrypt(data, key);
    service.storage->encryptData(encryptedData, key);

    std::string decryptedData = service.decrypt(encryptedData, key);
    service.storage->decryptData(decryptedData, key);

    delete kms;
    delete storage;

    return 0;
}
