#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <atomic>
#include <functional>
#include <memory>
#include <chrono>

// Event structure
struct Event {
    std::chrono::system_clock::time_point timestamp;
    std::string type;
    std::string metadata;
};

// Thread-safe queue for event processing
class ThreadSafeQueue {
public:
    void push(const Event& event) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(event);
        condition_.notify_one();
    }

    bool try_pop(Event& result) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_.empty()) return false;
        result = queue_.front();
        queue_.pop();
        return true;
    }

private:
    std::queue<Event> queue_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

// Event processor
class EventProcessor {
public:
    EventProcessor(size_t num_threads) : stop_(false) {
        for (size_t i = 0; i < num_threads; ++i) {
            workers_.emplace_back([this]{
                while (true) {
                    Event event;
                    if (queue_.try_pop(event)) {
                        process_event(event);
                    } else if (stop_) return;
                }
            });
        }
    }

    ~EventProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    void enqueue_event(const Event& event) {
        queue_.push(event);
    }

private:
    void process_event(const Event& event) {
        // Process the event
        std::cout << "Processing event at: " << event.timestamp << ", Type: " << event.type << ", Metadata: " << event.metadata << std::endl;
    }

    ThreadSafeQueue queue_;
    std::vector<std::thread> workers_;
    std::atomic<bool> stop_;
};

// Main function
int main() {
    EventProcessor processor(4);

    // Simulate adding events to the pipeline
    for (int i = 0; i < 10; ++i) {
        Event event;
        event.timestamp = std::chrono::system_clock::now();
        event.type = "Type" + std::to_string(i % 3);
        event.metadata = "Metadata" + std::to_string(i);
        processor.enqueue_event(event);
    }

    return 0;
}
```

