# Import necessary libraries
from flask import Flask, request, jsonify
import requests
import redis

# Initialize Flask app
app = Flask(__name__)

# Configure Redis client
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)

# Define a decorator to cache responses using Redis
def cache_response(timeout=5):
    def decorator(f):
        def new_func(*args, **kwargs):
            key = request.path + str(request.args)
            cached_response = redis_client.get(key)
            if cached_response:
                return jsonify(cached_response.decode('utf-8'))
            response = f(*args, **kwargs)
            redis_client.setex(key, timeout, response.json())
            return response
        return new_func
    return decorator

# Example route with caching
@app.route('/static-content', methods=['GET'])
@cache_response(timeout=3600)  # Cache for 1 hour
def get_static_content():
    content = {
        'message': 'This is static content'
    }
    return jsonify(content)

# Route to handle dynamic content updates
@app.route('/update-dynamic-content', methods=['POST'])
def update_dynamic_content():
    data = request.json
    # Logic to update dynamic content
    return jsonify({'status': 'success', 'data': data})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

