class NoSqlDatabase {
public:
    void store_event(const Event& event) {
        // Simulate storing an event in a distributed NoSQL database
        std::cout << "Storing event at " << event.timestamp << ": " << event.type << std::endl;
    }
};

// EventProcessor class
class EventProcessor {
public:
    EventProcessor(EventSource& source, NoSqlDatabase& db)
        : source(source), db(db) {}

    void process_events() {
        while (true) {
            try {
                Event event = source.get_next_event();
                db.store_event(event);
            } catch (const std::exception& e) {
                // Log error and retry
                std::cerr << "Error processing event: " << e.what() << std::endl;
            }
        }
    }

