int front = 0, rear = -1;
sem_t queue_mutex, empty_slots, filled_slots;

void* producer_thread(void* arg) {
    while (1) {
        Event new_event = get_new_event(); // Function to fetch new event
        sem_wait(&empty_slots);
        sem_wait(&queue_mutex);

        // Enqueue the event
        rear = (rear + 1) % 1000;
        event_queue[rear] = new_event;

        sem_post(&queue_mutex);
        sem_post(&filled_slots);
    }
}

void* consumer_thread(void* arg) {
    while (1) {
        sem_wait(&filled_slots);
        sem_wait(&queue_mutex);

        // Dequeue the event and process it
        Event event = event_queue[front];
        front = (front + 1) % 1000;

        process_event(event); // Function to handle event processing

        sem_post(&queue_mutex);
        sem_post(&empty_slots);
    }
}

int main() {
    pthread_t producer, consumer;

    // Initialize semaphore
    sem_init(&queue_mutex, 0, 1);
    sem_init(&empty_slots, 0, 1000); // Queue size is 1000
    sem_init(&filled_slots, 0, 0);

    // Create threads
    pthread_create(&producer, NULL, producer_thread, NULL);
    pthread_create(&consumer, NULL, consumer_thread, NULL);

    // Wait for threads to finish (never happens in this example)
