#include <mutex>
#include <thread>
#include <condition_variable>
#include <chrono>

class DistributedCache {
public:
    using Key = std::string;
    using Value = std::string;

    enum class Priority : int {
        LOW = 1,
        MEDIUM = 2,
        HIGH = 3
    };

    struct CacheEntry {
        Value value;
        std::chrono::time_point<std::chrono::system_clock> expiration_time;
        Priority priority;
    };

    void set(const Key& key, const Value& value, std::chrono::seconds ttl, Priority priority) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = {value, std::chrono::system_clock::now() + ttl, priority};
    }

    std::optional<Value> get(const Key& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end() && it->second.expiration_time > std::chrono::system_clock::now()) {
            return it->second.value;
        }
        return std::nullopt;
    }

    void remove(const Key& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_.erase(key);
    }

private:
    std::unordered_map<Key, CacheEntry> cache_;
    std::mutex mutex_;

    void eviction_thread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this]() {
                auto now = std::chrono::system_clock::now();
                return !cache_.empty() && cache_.begin()->second.expiration_time <= now;
            });
            if (!cache_.empty()) {
                cache_.erase(cache_.begin());
            }
        }
    }

    std::thread eviction_thread_;
    std::condition_variable cv_;
};

int main() {
    DistributedCache cache;
    cache.set("key1", "value1", std::chrono::seconds(5), DistributedCache::Priority::HIGH);
    auto value = cache.get("key1");
    if (value) {
        std::cout << "Value: " << *value << std::endl;
    } else {
        std::cout << "Key not found or expired" << std::endl;
    }
    return 0;
}
