    DataWorker(FinancialDataAPI& api, DistributedDatabase& db, std::atomic<bool>& stop)
        : api(api), db(db), stop(stop) {}

    void operator()() {
        while (!stop.load()) {
            auto tickValue = api.getHighestTickValue();
            if (tickValue.has_value()) {
                db.writeTickValue(tickValue.value());
            }
        }
