public class MetricProcessorService implements Runnable {
    private ExecutorService executor;
    private BlockingQueue<Metric> metricQueue;

    public MetricProcessorService(int numThreads, int queueCapacity) {
        this.executor = Executors.newFixedThreadPool(numThreads);
        this.metricQueue = new ArrayBlockingQueue<>(queueCapacity);
    }

    public void startProcessing() {
        for (int i = 0; i < executor.getPoolSize(); i++) {
            executor.submit(this);
        }
    }

    @Override
    public void run() {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                Metric metric = metricQueue.take();
                processMetric(metric);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void processMetric(Metric metric) {
        // Process the metric and store it
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }
}
