            response = await session.get(f"https://s3.amazonaws.com/{bucket_name}/{file_key}")
            response.raise_for_status()
            content_length = int(response.headers['Content-Length'])

            # Check for potential data corruption
            if content_length % CHUNK_SIZE != 0:
                raise ValueError("File size is not a multiple of chunk size, potential data corruption detected.")

            sha256_hash = hashlib.sha256()
            async for chunk in response.content.iter_chunked(CHUNK_SIZE):
                sha256_hash.update(chunk)

            return sha256_hash.hexdigest()
        except ClientError as e:
            print(f"Failed to download file from S3: {e}")
            raise
        finally:
            await session.close()

class ExternalHashVerifier:
    async def verify_hash(self, hash_value):
        # Simulate API call with retries and error handling
        for attempt in range(MAX_RETRIES + 1):
            try:
                # Replace with actual API call logic
                response = os.system(f"hash_verification_api {hash_value}")
                if response == 0:
                    return True
                else:
                    raise Exception("Hash verification failed")
            except Exception as e:
                if attempt < MAX_RETRIES:
                    print(f"API error: {e}, retrying in {RETRY_DELAY} seconds...")
                    time.sleep(RETRY_DELAY)
                else:
                    print(f"Max retries reached for hash verification: {e}")
                    raise

class FileIntegrityService:
    def __init__(self, bucket_name):
        self.bucket_name = bucket_name
        self.hasher = FileHasher()
        self.verifier = ExternalHashVerifier()

    async def process_file(self, file_key):
        try:
            hash_value = await self.hasher.hash_file(self.bucket_name, file_key)
            print(f"Computed SHA-256 hash: {hash_value}")

            if await self.verifier.verify_hash(hash_value):
                print("Hash verification successful.")
            else:
                raise Exception("Failed to verify hash.")
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Credential error: {e}")
        except ValueError as e:
            print(f"Data corruption detected: {e}")

async def main():
    service = FileIntegrityService("my-bucket")
    await service.process_file("large-file.txt")

# Run the service
asyncio.run(main())
