class Event {
public:
    Event(int id) : id(id), timestamp(std::chrono::system_clock::now()) {}
    int getId() const { return id; }
    std::chrono::time_point<std::chrono::system_clock> getTimestamp() const { return timestamp; }

private:
    int id;
    std::chrono::time_point<std::chrono::system_clock> timestamp;
};

class EventProcessor {
public:
    EventProcessor(int numThreads) : stop(false) {
        for (int i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void(Event)> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) {
                            return;
                        }
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task(Event(1)); // Replace with actual event processing logic
                }
            });
        }
    }

    ~EventProcessor() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }

    void addEvent(const Event &event) {
        {
            std::lock_guard<std::mutex> lock(queue_mutex);
            tasks.emplace([event]() { // Replace with actual event processing logic
                std::cout << "Processing event: ID=" << event.getId() << ", Timestamp=" << event.getTimestamp().time_since_epoch().count() << std::endl;
            });
        }
        condition.notify_one();
    }

private:
    bool stop;
    std::vector<std::thread> workers;
    std::queue<std::function<void(Event)>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
};

int main() {
    EventProcessor processor(4);
    for (int i = 0; i < 10; ++i) {
        processor.addEvent(Event(i));
    }
    return 0;
}
