#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <future>
#include <chrono>

class SemaphoreManager {
public:
    SemaphoreManager(int maxSemaphores) : maxSemaphores(maxSemaphores), semCount(0) {}

    bool acquire() {
        std::unique_lock<std::mutex> lock(mutex);
        while (semCount >= maxSemaphores) {
            cond.wait(lock);
        }
        ++semCount;
        return true;
    }

    void release() {
        std::unique_lock<std::mutex> lock(mutex);
        --semCount;
        cond.notify_one();
    }

private:
    int maxSemaphores;
    int semCount;
    std::mutex mutex;
    std::condition_variable cond;
};

int main() {
    SemaphoreManager manager(50000);

    auto acquireSemaphore = [&manager]() {
        if (manager.acquire()) {
            // Perform semaphore acquisition logic
            std::cout << "Semaphore acquired" << std::endl;
        } else {
            // Handle semaphore acquisition failure
            std::cout << "Failed to acquire semaphore" << std::endl;
        }
    };

    auto releaseSemaphore = [&manager]() {
        manager.release();
        std::cout << "Semaphore released" << std::endl;
    };

    std::vector<std::future<void>> threads;
    for (int i = 0; i < 100; ++i) {
        threads.emplace_back(acquireSemaphore);
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
        threads.emplace_back(releaseSemaphore);
    }

    for (auto& future : threads) {
        future.get();
    }

    return 0;
}
```

