#include <thread>
#include <mutex>
#include <atomic>
#include <condition_variable>
#include <system_error>

std::mutex logMutex;

void logError(const std::string& entry, const std::error_code& ec) {
    std::lock_guard<std::mutex> lock(logMutex);
    auto now = std::chrono::system_clock::now();
    std::time_t now_c = std::chrono::system_clock::to_time_t(now);
    std::cout << "[" << std::put_time(std::localtime(&now_c), "%Y-%m-%d %H:%M:%S") 
              << "] Error processing entry '" << entry << "': " << ec.message() << std::endl;
}

bool isServiceAvailable() {
    // Simulate service availability check
    return true; // In a real scenario, this would involve network requests and error handling
}

void insertWithRetry(std::forward_list<std::string>& list, const std::string& target, const std::string& insert) {
    for (int attempt = 0; attempt < 3; ++attempt) {
        if (isServiceAvailable()) {
            auto it = list.begin();
            while (it != list.end() && *it != target) {
                ++it;
            }
            if (it != list.end()) {
                list.insert_after(it, insert);
                return;
            } else {
                list.push_back(insert);
                return;
            }
        } else {
            std::this_thread::sleep_for(std::chrono::milliseconds(std::pow(2, attempt) * 100));
        }
    }
    logError(target, std::make_error_code(std::errc::timed_out));
}

void insertAfterOrLog(std::forward_list<std::string>& list, const std::string& target, const std::string& insert) {
    try {
        insertWithRetry(list, target, insert);
    } catch (const std::system_error& e) {
        logError(target, e.code());
    } catch (...) {
        logError(target, std::make_error_code(std::errc::unknown_error));
    }
}

int main() {
    std::forward_list<std::string> entries = {"entry1", "entry2", "entry3"};
    insertAfterOrLog(entries, "entry2", "newEntry");
    for (const auto& entry : entries) {
        std::cout << entry << std::endl;
    }
    return 0;
}
