	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
	"google.golang.org/grpc/codes"
)

var jwtAuth = jwtauth.New("HS256", []byte("secret"), nil)
var tracer = otel.Tracer("web-api")

func main() {
	r := chi.NewRouter()

	r.Use(middleware.Authenticate(jwtAuth))
	r.Use(middleware.Logging(tracer))

	r.Put("/resource/{id}", updateResource)
	r.Delete("/resource/{id}", deleteResource)

	http.ListenAndServe(":8080", r)
}

type Resource struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

func updateResource(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	id := chi.URLParam(r, "id")

	var payload Resource
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if _, err := db.UpdateResource(ctx, id, payload.Name); err != nil {
		http.Error(w, "Failed to update resource", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Resource updated successfully")
}

func deleteResource(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	id := chi.URLParam(r, "id")

	if err := db.DeleteResource(ctx, id); err != nil {
		http.Error(w, "Failed to delete resource", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Resource deleted successfully")
}
