        // Log request details for monitoring
        $this->logger->info('Create User Request', ['user_data' => $data]);

        // Handle concurrent requests using distributed locks (e.g., Redis)
        if ($this->cache->add('lock:create_user:' . $data['email'], true, 60)) {
            try {
                // Call external authentication service to create user
                $authResponse = $this->authClient->request('POST', '/users', [
                    'json' => $data,
                ]);

                if ($authResponse->getStatusCode() == 201) {
                    // Insert user data into the database
                    $stmt = $this->dbConnection->prepare("INSERT INTO users (email, password) VALUES (:email, :password)");
                    $stmt->execute(['email' => $data['email'], 'password' => $data['password']]);

                    // Publish success message to the message queue
                    $this->messageQueue->publish('user_created', json_encode($data));

                    return ['status' => 'success', 'message' => 'User created successfully'];
                } else {
                    return ['status' => 'error', 'message' => 'Failed to create user in auth service'];
                }
            } catch (Exception $e) {
                // Handle exceptions and retry logic
                // ...

                return ['status' => 'error', 'message' => 'Internal server error'];
            } finally {
                // Release lock after processing request
                $this->cache->delete('lock:create_user:' . $data['email']);
            }
        } else {
            return ['status' => 'error', 'message' => 'Too many requests, please try again later'];
        }
    }

