using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public interface ICmsService
{
    Task<string> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent);
}

public class CmsService : ICmsService
{
    private readonly HttpClient _httpClient;
    private const string ApiUrl = "https://cms.example.com/api";

    public CmsService(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<string> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        var requestUri = $"{ApiUrl}/elements/{pageSectionId}/{elementId}";
        var content = new StringContent(JsonSerializer.Serialize(new { HtmlContent = htmlContent }), System.Text.Encoding.UTF8, "application/json");

        // Apply Content Security Policy (CSP) headers
        content.Headers.Add("Content-Security-Policy", "default-src 'self'");

        // Enforce rate limiting
        await Task.Delay(10); // Simulate delay for rate limiting

        var response = await _httpClient.PutAsync(requestUri, content);
        if (!response.IsSuccessStatusCode)
            throw new Exception($"Failed to update element: {response.ReasonPhrase}");

        return await response.Content.ReadAsStringAsync();
    }
}

public class Microservice
{
    private readonly ICmsService _cmsService;

    public Microservice(ICmsService cmsService)
    {
        _cmsService = cmsService;
    }

    public async Task<string> UpdateElement(string pageSectionId, string elementId, string htmlContent)
    {
        return await _cmsService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddHttpClient<ICmsService, CmsService>();
        services.AddSingleton<Microservice>();
    }

    public void Configure(IApplicationBuilder app)
    {
        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapPost("/update-element", async context =>
            {
                var pageSectionId = context.Request.Query["pageSectionId"];
                var elementId = context.Request.Query["elementId"];
                var htmlContent = await new StreamReader(context.Request.Body).ReadToEndAsync();

                var microservice = context.RequestServices.GetService<Microservice>();
                var result = await microservice.UpdateElement(pageSectionId, elementId, htmlContent);

                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(result);
            });
        });
    }
}
