// app.js
angular.module('dialogApp', [])
  .service('DialogService', DialogService);

function DialogService($http, $q) {
  var cache = {};
  const REFRESH_INTERVAL = 60000; // Default refresh interval in milliseconds

  function fetchMetadata(resourceId, url) {
    return $q((resolve, reject) => {
      if (cache[resourceId]) {
        resolve(cache[resourceId]);
      } else {
        $http.get(url + resourceId)
          .then(response => {
            cache[resourceId] = response.data;
            resolve(response.data);
          })
          .catch(error => {
            console.error('Error fetching metadata:', error);
            reject(error);
          });
      }
    });
  }

  function refreshField(field, resourceId, url) {
    return $q((resolve, reject) => {
      fetchMetadata(resourceId, url).then(metadata => {
        const fieldInfo = metadata.find(f => f.name === field);
        if (fieldInfo && fieldInfo.refreshInterval <= REFRESH_INTERVAL) {
          setTimeout(() => {
            // Simulate field refresh
            console.log(`Refreshing ${field} for resource ${resourceId}`);
            resolve();
          }, fieldInfo.refreshInterval);
        } else {
          resolve();
        }
      }).catch(error => reject(error));
    });
  }

  function prioritizeFields(fields, metadata) {
    return fields.sort((a, b) => {
      const aMeta = metadata.find(f => f.name === a);
      const bMeta = metadata.find(f => f.name === b);
      if (aMeta.priority && bMeta.priority) {
        return bMeta.priority - aMeta.priority;
      }
      return 0;
    });
  }

  function lazyLoadFields(fields, requiredFields) {
    return fields.filter(field => requiredFields.includes(field));
  }

  function throttleRefresh(requestsPerMinute) {
    let requestCount = 0;
    const interval = (60 * 1000) / requestsPerMinute;

    return function(refreshFunction) {
      return function() {
        if (requestCount === 0) {
          refreshFunction();
          requestCount++;
          setTimeout(() => {
            requestCount--;
          }, interval);
        }
      };
    };
  }

  this.refreshDialogFields = throttleRefresh(10)(function(resourceId, url, requiredFields) {
    fetchMetadata(resourceId, url).then(metadata => {
      const fields = metadata.map(f => f.name);
      const prioritizedFields = prioritizeFields(fields, metadata);
      const loadedFields = lazyLoadFields(prioritizedFields, requiredFields);

      loadedFields.forEach(field => refreshField(field, resourceId, url));
    }).catch(error => console.error('Error refreshing dialog fields:', error));
  });
}

// Usage in a controller
angular.module('dialogApp')
  .controller('DialogController', ['$scope', 'DialogService',
    function($scope, DialogService) {
      $scope.refreshFields = function(resourceId, url, requiredFields) {
        DialogService.refreshDialogFields(resourceId, url, requiredFields);
      };
    }
  ]);
