#include <chrono>
#include <mutex>
#include <atomic>

class Session {
public:
    std::string sessionID;
    std::string authInfo;
    std::time_t lastActivity;
    bool status;

    Session(std::string id, std::string info) : sessionID(id), authInfo(info), lastActivity(time(nullptr)), status(true) {}
};

class SessionManager {
private:
    std::unordered_map<std::string, Session> sessions;
    std::mutex mutex;
    std::atomic<int> activeHandlers;

public:
    SessionManager() : activeHandlers(0) {}

    void startSession(const std::string& id, const std::string& authInfo) {
        std::lock_guard<std::mutex> lock(mutex);
        sessions[id] = Session(id, authInfo);
        activeHandlers++;
    }

    void endSession(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sessions.find(id) != sessions.end()) {
            sessions.erase(id);
            activeHandlers--;
        }
    }

    bool isSessionActive(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = sessions.find(id);
        if (it != sessions.end() && it->second.status) {
            return true;
        }
        return false;
    }

    void updateLastActivity(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (sessions.find(id) != sessions.end()) {
            sessions[id].lastActivity = time(nullptr);
        }
    }

    int getActiveHandlers() const {
        return activeHandlers;
    }
};

int main() {
    SessionManager manager;

    // Simulate session start and end
    manager.startSession("session1", "authInfo1");
    std::this_thread::sleep_for(std::chrono::seconds(5));
    manager.updateLastActivity("session1");
    if (manager.isSessionActive("session1")) {
        std::cout << "Session 1 is active." << std::endl;
    }
    manager.endSession("session1");

    std::cout << "Active handlers: " << manager.getActiveHandlers() << std::endl;

    return 0;
}
