        response = requests.post(self.api_url + '/error', json={'message': message}, headers={'Authorization': f'Bearer {self.auth_token}'})
        if response.status_code != 200:
            print(f"Failed to log error: {response.text}")

    def start_processing(self):
        self.log_start()
        with ThreadPoolExecutor(max_workers=10) as executor:
            results = list(executor.map(self.process_file, self.log_files))
        last_sequence_numbers = [res for res in results if res is not None]
        max_sequence_number = max(last_sequence_numbers) if last_sequence_numbers else None
        self.log_completion(max_sequence_number)

