        response = requests.post(self.api_url + '/start', headers={'Authorization': f'Bearer {self.auth_token}'})
        if response.status_code != 200:
            print(f"Failed to log start: {response.text}")

    def log_completion(self, max_sequence_number):
        response = requests.post(self.api_url + '/completion', json={'max_sequence_number': max_sequence_number}, headers={'Authorization': f'Bearer {self.auth_token}'})
