using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private readonly ConcurrentDictionary<string, Random> _randoms = new();
    private readonly object _lockObject = new();
    private long _seedCounter;

    public DynamicRandomValueGenerator()
    {
        _seedCounter = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
    }

    public int GenerateRandomInt(int min, int max)
    {
        return GetRandom(min, max).Next();
    }

    public double GenerateRandomDouble(double min, double max)
    {
        return min + (max - min) * GetRandom(0, 1).NextDouble();
    }

    private Random GetRandom(int seedMin, int seedMax)
    {
        var seed = Interlocked.Increment(ref _seedCounter);
        var key = $"{seed}_{seedMin}_{seedMax}";
        if (!_randoms.TryGetValue(key, out var random))
        {
            lock (_lockObject)
            {
                if (!_randoms.TryGetValue(key, out random))
                {
                    random = new Random(seed);
                    _randoms.TryAdd(key, random);
                }
            }
        }
        return random;
    }

    public void ConfigureSeed(long seed)
    {
        Interlocked.Exchange(ref _seedCounter, seed);
        foreach (var kvp in _randoms.Keys.ToList())
        {
            if (kvp.Contains(seed.ToString()))
            {
                _randoms.TryRemove(kvp, out _);
            }
        }
    }

