    LOG_LEVEL_ERROR
} LogLevel;

typedef struct {
    char *logFile;
    int logLevel;
    sem_t lock;
} Logger;

Logger logger = {NULL, LOG_LEVEL_INFO, SEMAPHORE_INIT};

void logMessage(LogLevel level, const char *message) {
    if (level < logger.logLevel) return;

    sem_wait(&logger.lock);

    if (logger.logFile != NULL) {
        FILE *file = fopen(logger.logFile, "a");
        fprintf(file, "%s\n", message);
        fclose(file);
    }

    printf("%s\n", message);

    sem_post(&logger.lock);
}

void setLogger(const char *logFile, LogLevel level) {
    logger.logFile = strdup(logFile);
    logger.logLevel = level;
    sem_init(&logger.lock, 0, 1);
}

