    void processLog(const std::string& logEntry) {
        // Simulate processing logic
        Json::Value json = parseJson(logEntry);
        if (json.isObject()) {
            std::lock_guard<std::mutex> lock(mutex_);
            data_.push_back(json);
            cv_.notify_one();
        }
    }

private:
    std::vector<Json::Value> data_;
    std::mutex mutex_;
    std::condition_variable cv_;

    Json::Value parseJson(const std::string& logEntry) {
        // Parse JSON logic using the chosen library
        Json::Reader reader;
        Json::Value root;
        reader.parse(logEntry, root);
        return root;
    }
};

class LogProcessorWorker {
public:
    LogProcessorWorker(LogProcessor& processor) : processor_(processor) {}

    void operator()() {
        while (true) {
            std::unique_lock<std::mutex> lock(processor_.mutex_);
            processor_.cv_.wait(lock, [this] { return !processor_.data_.empty(); });
            Json::Value data = processor_.data_.back();
            processor_.data_.pop_back();
            lock.unlock();

            // Process the log entry
            processLogEntry(data);
        }
    }

private:
    LogProcessor& processor_;

    void processLogEntry(const Json::Value& data) {
        // Simulate processing logic for a single log entry
        std::cout << "Processing log entry: " << data.toStyledString() << std::endl;
    }
};

int main() {
    LogProcessor processor;
    std::vector<std::thread> workers;

    // Create worker threads
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workers.emplace_back(LogProcessorWorker(processor));
    }

    // Simulate log processing
    for (int i = 0; i < 100000; ++i) {
        std::string logEntry = "{\"timestamp\":\"2023-04-01T12:00:00Z\",\"user_id\":\"user123\",\"session_id\":\"sess123\",\"response_time\":500,\"error_count\":0,\"geographical_location\":\"US\",\"context_metrics\":{\"api1\":10.5}}";
        processor.processLog(logEntry);
    }

