['```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <functional>

class Task {
public:
    virtual void execute() = 0;
};

class SimpleTask : public Task {
public:
    void execute() override {
        std::cout << "Executing simple task" << std::endl;
    }
};

class TaskManager {
private:
    std::vector<std::thread> workers;
    std::queue<Task*> taskQueue;
    std::mutex queueMutex;
    std::condition_variable taskCondition;
    bool stop;

public:
    TaskManager(size_t numWorkers) : stop(false) {
        for (size_t i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&TaskManager::workerThread, this);
        }
    }

    ~TaskManager() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        taskCondition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addTask(Task* task) {
        std::lock_guard<std::mutex> lock(queueMutex);
        taskQueue.push(task);
        taskCondition.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            taskCondition.wait(lock, [this] { return !taskQueue.empty() || stop; });
            if (stop && taskQueue.empty()) {
                break;
            }
            Task* task = taskQueue.front();
            taskQueue.pop();
            lock.unlock();

            try {
                task->execute();
            } catch (...) {
                std::cerr << "Task execution failed" << std::endl;
            }

            delete task;
        }
    }
};

int main() {
    TaskManager manager(5);
    manager.addTask(new SimpleTask());
    manager.addTask(new SimpleTask());

    return 0;
}
```']

