using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class DynamicFileProcessor
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _initializationVector;
    private readonly HttpClient _metadataServiceClient;
    private readonly ConcurrentDictionary<string, string> _fileCache = new ConcurrentDictionary<string, string>();
    private readonly LruCache<string, string> _metadataCache;

    public DynamicFileProcessor(string encryptionKeyBase64, string ivBase64)
    {
        _encryptionKey = Convert.FromBase64String(encryptionKeyBase64);
        _initializationVector = Convert.FromBase64String(ivBase64);
        _metadataServiceClient = new HttpClient();
        _metadataCache = new LruCache<string, string>(TimeSpan.FromDays(7));
    }

    public async Task<string> ProcessFileAsync(string base64EncodedData, string user)
    {
        string decryptedContent = await DecryptStringAsync(base64EncodedData);
        string metadata = GetMetadataFromService(user);

        return $"{metadata}_{DateTime.Now:yyyy-MM-dd_HH-mm-ss}_{Guid.NewGuid()}.txt";
    }

    private async Task<string> DecryptStringAsync(string base64EncodedData)
    {
        try
        {
            using (TripleDES td3des = TripleDES.Create())
            {
                td3des.Key = _encryptionKey;
                td3des.IV = _initializationVector;

                ICryptoTransform decryptor = td3des.CreateDecryptor(td3des.Key, td3des.IV);
                byte[] encryptedData = Convert.FromBase64String(base64EncodedData);

                using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            return await srDecrypt.ReadToEndAsync();
                        }
                    }
                }
            }
        }
        catch (Exception)
        {
            // Fallback to external decryption service
            return await ExternalDecryptionService.DecryptAsync(base64EncodedData);
        }
    }

    private string GetMetadataFromService(string user)
    {
        string cacheKey = $"{user}_metadata";
        if (!_fileCache.TryGetValue(cacheKey, out _))
        {
            for (int i = 0; i < 10; i++)
            {
                try
                {
                    var response = await _metadataServiceClient.GetAsync($"https://metadataapi.com/user/{user}/data");
                    response.EnsureSuccessStatusCode();
                    string metadata = await response.Content.ReadAsStringAsync();
                    _fileCache.TryAdd(cacheKey, metadata);
                    return metadata;
                }
                catch (HttpRequestException)
                {
                    if (i == 9) throw; // Rethrow after 10 attempts
                    await Task.Delay((int)Math.Pow(2, i) * 100); // Exponential backoff
                }
            }
        }

        return _fileCache[cacheKey];
    }

    private class LruCache<TKey, TValue>
    {
        private readonly ConcurrentDictionary<TKey, TValue> _store = new ConcurrentDictionary<TKey, TValue>();
        private readonly ConcurrentQueue<TKey> _queue = new ConcurrentQueue<TKey>();
        private readonly TimeSpan _expiration;
        private readonly object _lock = new object();

        public LruCache(TimeSpan expiration)
        {
            _expiration = expiration;
        }

        public bool TryGetValue(TKey key, out TValue value)
        {
            lock (_lock)
            {
                if (!_store.TryGetValue(key, out value)) return false;

                if (DateTime.Now - _queue.Dequeue() < _expiration) return true;

                _store.TryRemove(key, out _);
                return false;
            }
        }

        public void AddOrUpdate(TKey key, TValue value)
        {
            lock (_lock)
            {
                if (!_store.ContainsKey(key)) _queue.Enqueue(key);

                _store[key] = value;
            }
        }
    }
}

public static class ExternalDecryptionService
{
    private static readonly HttpClient _client = new HttpClient();

    public static async Task<string> DecryptAsync(string base64EncodedData)
    {
        var content = new StringContent(base64EncodedData, Encoding.UTF8);
        var response = await _client.PostAsync("https://decryptionapi.com/decrypt", content);
        return await response.Content.ReadAsStringAsync();
    }
}
```

