using System;
using System.Collections.Concurrent;
using System.Net.WebSockets;
using System.Threading;
using System.Threading.Tasks;

public class StreamingDataProcessor : IDisposable
{
    private readonly WebSocketListener _listener;
    private readonly ConcurrentQueue<WebSocket> _activeConnections = new();
    private bool _isRunning;

    public StreamingDataProcessor(int port)
    {
        _listener = new WebSocketListener(port);
    }

    public void Start()
    {
        _isRunning = true;
        _listener.Start();
        Task.Run(ListenForClients);
    }

    private async Task ListenForClients()
    {
        while (_isRunning)
        {
            var socket = await _listener.AcceptWebSocketAsync(null, CancellationToken.None);
            _activeConnections.Enqueue(socket);
            Task.Run(() => HandleClient(socket));
        }
    }

    private async Task HandleClient(WebSocket socket)
    {
        try
        {
            var buffer = new byte[1024 * 4];
            while (socket.State == WebSocketState.Open)
            {
                var result = await socket.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);
                if (result.MessageType == WebSocketMessageType.Close)
                    break;

                // Process the received data
                await ProcessData(buffer, result.Count);
            }
        }
        finally
        {
            _activeConnections.TryRemove(socket);
            socket.Dispose();
        }
    }

    private async Task ProcessData(byte[] buffer, int count)
    {
        // Implement data processing logic here
        Console.WriteLine($"Received {count} bytes of data");
        await Task.Delay(10); // Simulate processing time
    }

    public void Stop()
    {
        _isRunning = false;
        foreach (var socket in _activeConnections)
            socket.Dispose();
        _listener.Stop();
    }

    public void Dispose()
    {
        Stop();
        _listener.Dispose();
    }
}
```

