const AWS = require('aws-sdk');
const { promisify } = require('util');
const fs = require('fs');
const path = require('path');

class BatchUploadManager {
  constructor(tenantId, config) {
    this.tenantId = tenantId;
    this.config = config;
    this.s3 = new AWS.S3({ region: config.region });
    this.uploadQueue = [];
    this.activeUploads = new Set();
  }

  async uploadFile(filePath) {
    const fileKey = path.join(this.tenantId, path.basename(filePath));
    try {
      await promisify(fs.stat)(filePath);
    } catch (err) {
      throw new Error(`File not found: ${filePath}`);
    }

    if (!this.config.allowedFileTypes.includes(path.extname(fileKey))) {
      throw new Error('File type not allowed');
    }

    if (fs.statSync(filePath).size > this.config.maxFileSize) {
      throw new Error('File size exceeds limit');
    }

    if (this.activeUploads.size >= this.config.maxConcurrentUploads) {
      await this.waitForSpot();
    }

    const upload = this.s3.upload({
      Bucket: this.config.bucketName,
      Key: fileKey,
      Body: fs.createReadStream(filePath),
    });

    this.activeUploads.add(upload);

    return new Promise((resolve, reject) => {
      upload.on('success', (response) => {
        this.activeUploads.delete(upload);
        resolve(response.Location);
      }).on('error', (err) => {
        this.activeUploads.delete(upload);
        reject(err);
      });
    });
  }

  async waitForSpot() {
    return new Promise((resolve, reject) => {
      const interval = setInterval(async () => {
        if (this.activeUploads.size < this.config.maxConcurrentUploads) {
          clearInterval(interval);
          resolve();
        }
      }, 1000);
    });
  }

  static async createInstance(tenantId, config) {
    const instance = new BatchUploadManager(tenantId, config);
    await instance.setupBucket();
    return instance;
  }

  async setupBucket() {
    try {
      await this.s3.headBucket({ Bucket: this.config.bucketName }).promise();
    } catch (err) {
      if (err.statusCode === 404) {
        await this.s3.createBucket({ Bucket: this.config.bucketName }).promise();
        console.log(`Bucket ${this.config.bucketName} created`);
      } else {
        throw err;
      }
    }
  }

  static async initialize(tenantId, config) {
    const instance = new BatchUploadManager(tenantId, config);
    await instance.setupBucket();
    return instance;
  }
}

module.exports = BatchUploadManager;
