import logging
from abc import ABC, abstractmethod
import asyncio
import backoff
import requests

class Logger:
    def __init__(self, name):
        self.logger = logging.getLogger(name)
        self.logger.setLevel(logging.DEBUG)

    def debug(self, message):
        self.logger.debug(message)

    def info(self, message):
        self.logger.info(message)

    def warning(self, message):
        self.logger.warning(message)

    def error(self, message):
        self.logger.error(message)

    def critical(self, message):
        self.logger.critical(message)

class LogHandler(ABC):
    @abstractmethod
    async def handle_log(self, log_message):
        pass

class ELKLogHandler(LogHandler):
    def __init__(self, url):
        self.url = url

    @backoff.on_exception(backoff.expo, requests.exceptions.RequestException, max_tries=5)
    async def handle_log(self, log_message):
        response = await asyncio.to_thread(requests.post, self.url, json=log_message)
        response.raise_for_status()

class LogContextManager:
    def __init__(self, logger):
        self.logger = logger

    def __enter__(self):
        return self.logger

    def __exit__(self, exc_type, exc_value, traceback):
        pass

# Example usage
logger = Logger('example_logger')
elk_handler = ELKLogHandler('http://elasticsearch:9200/logs/_doc')

async def log_with_elk():
    async with LogContextManager(logger) as log:
        log.info('This is an info message')

asyncio.run(log_with_elk())
```

