    void addServer(const std::string& url, const std::string& headers) {
        std::lock_guard<std::mutex> lock(mutex_);
        servers_.push_back({url, headers});
    }

    void removeServer(const std::string& url) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = std::find_if(servers_.begin(), servers_.end(),
                               [&url](const ServerInfo& info) { return info.url == url; });
        if (it != servers_.end()) {
            servers_.erase(it);
        }
    }

    void updateServerHeaders(const std::string& url, const std::string& headers) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& server : servers_) {
            if (server.url == url) {
                server.headers = headers;
                break;
            }
        }
    }

    void connect() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& server : servers_) {
            // Simulate connection
            std::cout << "Connecting to " << server.url << std::endl;
        }
    }

private:
    struct ServerInfo {
        std::string url;
        std::string headers;
    };

    std::vector<ServerInfo> servers_;
    std::mutex mutex_;
};
