#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>

#define KEY_SIZE 32
#define IV_SIZE 16

void generate_key(char *key, int key_len) {
    if (!RAND_bytes((unsigned char*)key, key_len)) {
        fprintf(stderr, "Failed to generate key\n");
        exit(EXIT_FAILURE);
    }
}

void generate_iv(char *iv, int iv_len) {
    if (!RAND_bytes((unsigned char*)iv, iv_len)) {
        fprintf(stderr, "Failed to generate IV\n");
        exit(EXIT_FAILURE);
    }
}

int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        handleErrors();

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        handleErrors();
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) handleErrors();
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 const unsigned char *key, const unsigned char *iv,
                 unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv))
        handleErrors();

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        handleErrors();
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) handleErrors();
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}

void handleErrors() {
    ERR_print_errors_fp(stderr);
    abort();
}

int main() {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[sizeof(plaintext)];
    int ciphertext_len;

    generate_key(key, KEY_SIZE);
    generate_iv(iv, IV_SIZE);

    if ((ciphertext_len = encrypt_data(plaintext, strlen((char *)plaintext), key, iv, ciphertext)) == -1) {
        fprintf(stderr, "Encryption failed\n");
        return 1;
    }

    printf("Ciphertext is:\n");
    BIO_dump_fp(stdout, (const char *)ciphertext, ciphertext_len);

    unsigned char decryptedtext[ciphertext_len];

    if ((ciphertext_len = decrypt_data(ciphertext, ciphertext_len, key, iv, decryptedtext)) == -1) {
        fprintf(stderr, "Decryption failed\n");
        return 1;
    }

    decryptedtext[ciphertext_len] = '\0';

    printf("Decrypted text is:\n");
    printf("%s\n", decryptedtext);

    return 0;
}
```

This code demonstrates basic encryption and decryption using AES-256-CBC mode with OpenSSL. It includes functions to generate a key, IV, encrypt data, and decrypt data. Error handling is included using the `ERR_print_errors_fp` function from OpenSSL. The `main` function demonstrates encrypting and then decrypting a simple string.']

