#include <iostream>
#include <thread>
#include <atomic>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>

// Define a simple event struct
struct Event {
    std::string data;
};

// Thread-safe queue for asynchronous processing
class AsyncQueue {
public:
    void push(Event event) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(event);
        condition_.notify_one();
    }

    Event pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !queue_.empty(); });
        Event event = queue_.front();
        queue_.pop();
        return event;
    }

private:
    std::queue<Event> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

// Worker thread for processing events
void worker(AsyncQueue& queue, int id) {
    while (true) {
        Event event = queue.pop();
        // Process the event (simulated with a simple task)
        std::cout << "Worker " << id << " processed: " << event.data << std::endl;
    }
}

// Function to simulate logging
void log(const std::string& message) {
    std::cout << "Log: " << message << std::endl;
}

int main() {
    const int num_workers = 4;
    AsyncQueue queue;

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < num_workers; ++i) {
        workers.emplace_back(worker, std::ref(queue), i);
    }

    // Simulate event generation and logging
    for (int i = 0; i < 100; ++i) {
        Event event{"Event " + std::to_string(i)};
        queue.push(event);
        log("Generated: " + event.data);
    }

    // Join worker threads
    for (auto& thread : workers) {
        thread.join();
    }

    return 0;
}
```

