// ScriptManager.js

class ScriptManager {
  constructor(loggingService) {
    this.loggingService = loggingService;
    this.scripts = {};
    this.cache = new Map();
  }

  async loadScript(url) {
    if (this.cache.has(url)) {
      return this.cache.get(url);
    }
    try {
      const response = await fetch(url, { cache: 'no-cache' });
      if (!response.ok) {
        throw new Error(`Failed to load script from ${url}`);
      }
      const script = await response.text();
      const scriptElement = document.createElement('script');
      scriptElement.type = 'text/javascript';
      scriptElement.text = script;
      document.head.appendChild(scriptElement);
      this.cache.set(url, scriptElement);
      return scriptElement;
    } catch (error) {
      this.loggingService.logError(`Error loading script from ${url}:`, error);
      throw error;
    }
  }

  async loadScripts(urls) {
    const results = [];
    for (const url of urls) {
      try {
        const script = await this.loadScript(url);
        results.push(script);
      } catch (error) {
        // Log the error but continue loading other scripts
        this.loggingService.logError(`Error loading script from ${url}:`, error);
      }
    }
    return results;
  }

  async generateAndHash(charSet, password) {
    let result = '';
    for (let i = 0; i < charSet.length; i++) {
      const randomIndex = Math.floor(Math.random() * charSet.length);
      result += charSet[randomIndex];
    }
    // Securely hash the password
    const crypto = window.crypto || window.msCrypto;
    const encoder = new TextEncoder();
    const data = encoder.encode(password + result);
    const hashBuffer = await crypto.subtle.digest('SHA-256', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    return { randomString: result, hashedPassword: hashHex };
  }
}

// Example usage:
const loggingService = {
  logError(message, error) {
    console.error(message, error);
  }
};

const scriptManager = new ScriptManager(loggingService);
scriptManager.loadScripts(['https://example.com/script1.js', 'https://example.com/script2.js'])
  .then(scripts => console.log('Scripts loaded:', scripts))
  .catch(error => console.error('Failed to load scripts:', error));

scriptManager.generateAndHash('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', 'myPassword')
  .then(result => console.log('Generated and hashed:', result))
  .catch(error => console.error('Error generating and hashing:', error));
