#include <iostream>
#include <forward_list>

void insertAfter(std::forward_list<std::string>& fl, const std::string& target, const std::string& value) {
    auto it = fl.begin();
    while (it != fl.end()) {
        if (*it == target) {
            it++;
            fl.insert_after(it, value);
            return;
        }
        it++;
    }
}

int main() {
    std::forward_list<std::string> fl = {"apple", "banana", "cherry"};
    insertAfter(fl, "banana", "grape");

    for (const auto& elem : fl) {
        std::cout << elem << " ";
    }
    return 0;
}
```

This C++ function `insertAfter` takes a forward list of strings and two string arguments. It inserts the second string argument after the first occurrence of the first string argument in the forward list. If the target string is not found, no insertion occurs.']

