class IoTDataProcessor {
public:
    void startProcessing() {
        for (size_t i = 0; i < numThreads; ++i) {
            worker_threads.emplace_back(&IoTDataProcessor::process, this);
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stopFlag = true;
        }
        cv.notify_all();
        for (auto& thread : worker_threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void enqueueData(const SensorData& data) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(data);
        cv.notify_one();
    }

private:
    void process() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !queue.empty() || stopFlag; });
            if (stopFlag && queue.empty()) break;
            SensorData data = queue.front();
            queue.pop();
            lock.unlock();

            // Process the data
            processData(data);
        }
    }

    void processData(const SensorData& data) {
        // Implement data processing logic here
        std::cout << "Processing data: " << data.value << std::endl;
    }

    std::vector<std::thread> worker_threads;
    std::queue<SensorData> queue;
    std::mutex mutex;
    std::condition_variable cv;
    bool stopFlag = false;
    size_t numThreads = std::thread::hardware_concurrency();
};

struct SensorData {
