    "github.com/go-kit/kit/metrics"
    "github.com/google/wire"
)

type Service struct{}

func (s *Service) HandleRequest(ctx context.Context, req *http.Request) (string, error) {
    // Handle request logic here
    return "Response", nil
}

type Server struct {
    Router *gin.Engine
    Service *Service
}

func NewServer(s *Service) (*Server, error) {
    r := gin.Default()
    server := &Server{
        Router:  r,
        Service: s,
    }
    setupRoutes(server)
    return server, nil
}

func setupRoutes(s *Server) {
    s.Router.GET("/endpoint", func(c *gin.Context) {
        resp, err := s.Service.HandleRequest(c.Request.Context(), c.Request)
        if err != nil {
            c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
            return
        }
        c.JSON(http.StatusOK, gin.H{"message": resp})
    })
}

func main() {
    service := &Service{}
    server, err := NewServer(service)
    if err != nil {
        panic(err)
    }

    server.Router.Run(":8080")
}
