#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for JWT claims
typedef struct {
    char *iss;
    char *sub;
    char *aud;
    long exp;
    long iat;
    char *role;
    char *scope;
    int mfa_status;
} JwtClaims;

// Function to parse and validate JWT token
JwtClaims* validate_jwt(const char *token, const char *config_iss, const char *config_sub, const char *config_aud) {
    JwtClaims *claims = (JwtClaims *)malloc(sizeof(JwtClaims));
    if (claims == NULL) {
        return NULL;
    }

    // Simulate JWT parsing and validation
    claims->iss = strdup(config_iss);
    claims->sub = strdup(config_sub);
    claims->aud = strdup(config_aud);
    claims->exp = time(NULL) + 3600; // Set exp to one hour in the future
    claims->iat = time(NULL); // Set iat to current time

    if (strcmp(claims->iss, config_iss) != 0 ||
        strcmp(claims->sub, config_sub) != 0 ||
        strcmp(claims->aud, config_aud) != 0) {
        free(claims->iss);
        free(claims->sub);
        free(claims->aud);
        free(claims);
        return NULL;
    }

    // Simulate role-based access control
    claims->role = strdup("admin");
    if (strcmp(claims->role, "admin") != 0) {
        free(claims->iss);
        free(claims->sub);
        free(claims->aud);
        free(claims->role);
        free(claims);
        return NULL;
    }

    return claims;
}

// Function to handle authentication requests
void handle_authentication_request(const char *token, const char *config_iss, const char *config_sub, const char *config_aud) {
    JwtClaims *claims = validate_jwt(token, config_iss, config_sub, config_aud);
    if (claims == NULL) {
        printf("Authentication failed.\n");
        return;
    }

    printf("Authentication successful. User: %s, Role: %s\n", claims->sub, claims->role);

    // Free allocated memory
    free(claims->iss);
    free(claims->sub);
    free(claims->aud);
    free(claims->role);
}

int main() {
    const char *token = "example.jwt.token";
    const char *config_iss = "https://example.com/issuer";
    const char *config_sub = "user123";
    const char *config_aud = "app1";

    handle_authentication_request(token, config_iss, config_sub, config_aud);

    return 0;
}
```

