#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to encrypt data using AES-256-CBC
int aes_encrypt(const unsigned char *key, const unsigned char *iv,
                const unsigned char *plaintext, int plaintext_len,
                unsigned char **ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    *ciphertext = realloc(*ciphertext, ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to decrypt data using AES-256-CBC
int aes_decrypt(const unsigned char *key, const unsigned char *iv,
                const unsigned char *ciphertext, int ciphertext_len,
                unsigned char **plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    *plaintext = realloc(*plaintext, plaintext_len);
    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}

// Function to generate a random initialization vector (IV)
void generate_iv(unsigned char *iv) {
    if (!RAND_bytes(iv, EVP_CIPHER_block_size(EVP_aes_256_cbc()))) {
        fprintf(stderr, "Error generating IV\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    unsigned char key[32]; // 256-bit AES key
    unsigned char iv[EVP_CIPHER_BLOCK_SIZE]; // Initialization vector
    unsigned char plaintext[] = "Hello, world!";
    unsigned char *ciphertext = NULL;
    int ciphertext_len;

    // Generate a random key and IV
    if (!RAND_bytes(key, sizeof(key))) {
        fprintf(stderr, "Error generating key\n");
        return 1;
    }
    generate_iv(iv);

    // Encrypt the plaintext
    ciphertext_len = aes_encrypt(key, iv, plaintext, strlen((char *)plaintext), &ciphertext);
    if (ciphertext_len < 0) {
        fprintf(stderr, "Encryption failed\n");
        return 1;
    }

    // Decrypt the ciphertext
    unsigned char *decryptedtext = NULL;
    int decryptedtext_len = aes_decrypt(key, iv, ciphertext, ciphertext_len, &decryptedtext);
    if (decryptedtext_len < 0) {
        fprintf(stderr, "Decryption failed\n");
        return 1;
    }

    // Print the original and decrypted text
    printf("Original Text: %s\n", plaintext);
    printf("Decrypted Text: %s\n", decryptedtext);

    // Free allocated memory
    free(ciphertext);
    free(decryptedtext);

    return 0;
}
