#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <cstring>

// Define event structure
struct Event {
    std::chrono::system_clock::time_point timestamp;
    std::string type;
    std::map<std::string, std::string> metadata;
    std::string location;
};

// Logger interface (placeholder)
class ILogger {
public:
    virtual void Log(const Event& event) = 0;
    virtual ~ILogger() {}
};

// Simple logger implementation
class SimpleLogger : public ILogger {
public:
    void Log(const Event& event) override {
        // Simulate logging to an external service
        std::cout << "Logged at: " << event.timestamp.time_since_epoch().count()
                  << ", Type: " << event.type
                  << ", Location: " << event.location << std::endl;
    }
};

// Event processor class
class EventProcessor {
private:
    ILogger& logger;
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    std::atomic<bool> running{true};
    std::vector<std::thread> workerThreads;

public:
    EventProcessor(ILogger& logger, size_t numWorkers)
        : logger(logger) {
        for (size_t i = 0; i < numWorkers; ++i) {
            workerThreads.emplace_back([this] { processEvents(); });
        }
    }

    ~EventProcessor() {
        running.store(false);
        cv.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void AddEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        cv.notify_one();
    }

private:
    void processEvents() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !eventQueue.empty() || !running.load(); });
            if (!eventQueue.empty()) {
                Event event = eventQueue.front();
                eventQueue.pop();
                lock.unlock();

                // Process and log the event
                logger.Log(event);
            }
        }
    }
};

// Example usage
int main() {
    SimpleLogger logger;
    EventProcessor processor(logger, 4);

    // Simulate adding events
    for (int i = 0; i < 10; ++i) {
        Event event;
        event.timestamp = std::chrono::system_clock::now();
        event.type = "Type" + std::to_string(i);
        event.location = "Location" + std::to_string(i % 2);

        processor.AddEvent(event);
    }

    return 0;
}
```

