// Function to perform DES encryption in ECB mode
void des_encrypt_ecb(unsigned char *key, unsigned char *plaintext, unsigned char *ciphertext) {
    des_key_schedule ks;
    des_set_key((C_Block *)key, &ks);
    for (int i = 0; i < strlen((char *)plaintext); i += DES_BLOCK_SIZE) {
        des_encrypt((C_Block *)(plaintext + i), (C_Block *)(ciphertext + i), &ks);
    }
}

// Function to perform DES decryption in ECB mode
void des_decrypt_ecb(unsigned char *key, unsigned char *ciphertext, unsigned char *decryptedtext) {
    des_key_schedule ks;
    des_set_key((C_Block *)key, &ks);
    for (int i = 0; i < strlen((char *)ciphertext); i += DES_BLOCK_SIZE) {
        des_decrypt((C_Block *)(ciphertext + i), (C_Block *)(decryptedtext + i), &ks);
    }
}

// Function to perform DES encryption in EDE mode
void des_encrypt_ede(unsigned char *key1, unsigned char *key2, unsigned char *plaintext, unsigned char *ciphertext) {
    des_key_schedule ks1, ks2;
    des_set_key((C_Block *)key1, &ks1);
    des_set_key((C_Block *)key2, &ks2);
    for (int i = 0; i < strlen((char *)plaintext); i += DES_BLOCK_SIZE) {
        des_encrypt((C_Block *)(plaintext + i), (C_Block *)(ciphertext + i), &ks1);
        des_decrypt((C_Block *)(ciphertext + i), (C_Block *)(ciphertext + i), &ks2);
    }
}

// Function to perform DES decryption in EDE mode
void des_decrypt_ede(unsigned char *key1, unsigned char *key2, unsigned char *ciphertext, unsigned char *decryptedtext) {
    des_key_schedule ks1, ks2;
    des_set_key((C_Block *)key1, &ks1);
    des_set_key((C_Block *)key2, &ks2);
    for (int i = 0; i < strlen((char *)ciphertext); i += DES_BLOCK_SIZE) {
        des_decrypt((C_Block *)(ciphertext + i), (C_Block *)(decryptedtext + i), &ks1);
        des_encrypt((C_Block *)(decryptedtext + i), (C_Block *)(decryptedtext + i), &ks2);
    }
}

// Function to perform DES encryption in EDE3 mode
void des_encrypt_ede3(unsigned char *key1, unsigned char *key2, unsigned char *key3, unsigned char *plaintext, unsigned char *ciphertext) {
    des_key_schedule ks1, ks2, ks3;
    des_set_key((C_Block *)key1, &ks1);
    des_set_key((C_Block *)key2, &ks2);
    des_set_key((C_Block *)key3, &ks3);
    for (int i = 0; i < strlen((char *)plaintext); i += DES_BLOCK_SIZE) {
        des_encrypt((C_Block *)(plaintext + i), (C_Block *)(ciphertext + i), &ks1);
        des_decrypt((C_Block *)(ciphertext + i), (C_Block *)(ciphertext + i), &ks2);
        des_encrypt((C_Block *)(ciphertext + i), (C_Block *)(ciphertext + i), &ks3);
    }
}

// Function to perform DES decryption in EDE3 mode
void des_decrypt_ede3(unsigned char *key1, unsigned char *key2, unsigned char *key3, unsigned char *ciphertext, unsigned char *decryptedtext) {
    des_key_schedule ks1, ks2, ks3;
    des_set_key((C_Block *)key1, &ks1);
    des_set_key((C_Block *)key2, &ks2);
    des_set_key((C_Block *)key3, &ks3);
    for (int i = 0; i < strlen((char *)ciphertext); i += DES_BLOCK_SIZE) {
        des_decrypt((C_Block *)(ciphertext + i), (C_Block *)(decryptedtext + i), &ks1);
        des_encrypt((C_Block *)(decryptedtext + i), (C_Block *)(decryptedtext + i), &ks2);
        des_decrypt((C_Block *)(decryptedtext + i), (C_Block *)(decryptedtext + i), &ks3);
    }
}

