#include <iostream>
#include <vector>
#include <memory>
#include <mutex>
#include <condition_variable>

class NetworkAdapter {
public:
    void connect() { std::cout << "Connecting network adapter...\n"; }
    void disconnect() { std::cout << "Disconnecting network adapter...\n"; }
};

class DynamicNetworkAdapterManager {
private:
    std::vector<std::shared_ptr<NetworkAdapter>> pool;
    std::mutex mtx;
    std::condition_variable cv;
    size_t activeConnections;

public:
    DynamicNetworkAdapterManager(size_t initialSize) : activeConnections(0) {
        for (size_t i = 0; i < initialSize; ++i) {
            pool.push_back(std::make_shared<NetworkAdapter>());
        }
    }

    std::shared_ptr<NetworkAdapter> acquire() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !pool.empty(); });
        auto adapter = pool.back();
        pool.pop_back();
        ++activeConnections;
        return adapter;
    }

    void release(std::shared_ptr<NetworkAdapter> adapter) {
        std::unique_lock<std::mutex> lock(mtx);
        pool.push_back(adapter);
        --activeConnections;
        cv.notify_one();
    }

    void addAdapter() {
        std::lock_guard<std::mutex> lock(mtx);
        pool.push_back(std::make_shared<NetworkAdapter>());
    }

    void removeAdapters(size_t count) {
        std::unique_lock<std::mutex> lock(mtx);
        size_t newSize = pool.size() - count;
        if (newSize > 0) {
            pool.resize(newSize);
        }
        cv.notify_all();
    }

    size_t getActiveConnections() const { return activeConnections; }
};

int main() {
    DynamicNetworkAdapterManager manager(5);

    auto adapter1 = manager.acquire();
    std::cout << "Active connections: " << manager.getActiveConnections() << "\n";

    manager.release(adapter1);
    std::cout << "Active connections: " << manager.getActiveConnections() << "\n";

    manager.addAdapter();
    std::cout << "Active connections: " << manager.getActiveConnections() << "\n";

    manager.removeAdapters(2);
    std::cout << "Active connections: " << manager.getActiveConnections() << "\n";

    return 0;
}
```']

