public:
    virtual ~ICryptographicAlgorithm() {}
    virtual std::string encrypt(const std::string& data) = 0;
    virtual std::string decrypt(const std::string& data) = 0;
};

// Example of a simple AES encryption algorithm
class AES : public ICryptographicAlgorithm {
public:
    std::string encrypt(const std::string& data) override {
        // Dummy implementation
        return "encrypted_" + data;
    }

    std::string decrypt(const std::string& data) override {
        // Dummy implementation
        return "decrypted_" + data.substr(10);
    }
};

// Cryptographic library class
class CryptoLibrary {
public:
    void addAlgorithm(std::shared_ptr<ICryptographicAlgorithm> algorithm, const std::string& name) {
        std::lock_guard<std::mutex> lock(mutex_);
        algorithms_[name] = algorithm;
    }

    std::string encrypt(const std::string& data, const std::string& algorithmName) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (algorithms_.find(algorithmName) != algorithms_.end()) {
            return algorithms_[algorithmName]->encrypt(data);
        }
        throw std::runtime_error("Algorithm not found");
    }

    std::string decrypt(const std::string& data, const std::string& algorithmName) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (algorithms_.find(algorithmName) != algorithms_.end()) {
            return algorithms_[algorithmName]->decrypt(data);
        }
        throw std::runtime_error("Algorithm not found");
    }

private:
    std::mutex mutex_;
    std::unordered_map<std::string, std::shared_ptr<ICryptographicAlgorithm>> algorithms_;
};

int main() {
    CryptoLibrary library;
    auto aes = std::make_shared<AES>();
    library.addAlgorithm(aes, "AES");

    try {
        std::string encrypted = library.encrypt("Hello, World!", "AES");
        std::string decrypted = library.decrypt(encrypted, "AES");
        std::cout << "Decrypted: " << decrypted << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
