        private readonly ILogger<ConfigurationUpdateService> _logger;
        private Timer _timer;

        public ConfigurationUpdateService(IConfiguration configuration, ILogger<ConfigurationUpdateService> logger)
        {
            _configuration = configuration;
            _logger = logger;
        }

        public Task StartAsync(CancellationToken cancellationToken)
        {
            _timer = new Timer(UpdateConfigurations, null, TimeSpan.Zero, TimeSpan.FromHours(1));
            return Task.CompletedTask;
        }

        private async void UpdateConfigurations(object state)
        {
            try
            {
                var updatedSettings = await FetchUpdatedSettingsFromApi();
                _configuration.GetSection("GameWorld").Reload();
                foreach (var key in updatedSettings.Keys)
                {
                    _configuration[key] = updatedSettings[key];
                }
                _logger.LogInformation("Configuration updated successfully.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to update configuration.");
            }
        }

        private async Task<IConfigurationSection> FetchUpdatedSettingsFromApi()
        {
            // Simulate API call with retry mechanism
            int retries = 3;
            for (int i = 0; i < retries; i++)
            {
                try
                {
                    // Replace with actual API call
                    var response = await Task.Delay(1000);
                    return _configuration.GetSection("GameWorld");
                }
                catch (Exception)
                {
                    if (i == retries - 1) throw;
                    await Task.Delay(1000); // Wait before retrying
                }
            }

            throw new InvalidOperationException("Failed to fetch configuration from API after multiple attempts.");
        }

        public Task StopAsync(CancellationToken cancellationToken)
        {
            _timer?.Change(Timeout.Infinite, 0);
            return Task.CompletedTask;
        }
    }

    public class SessionManager
    {
        private readonly ILogger<SessionManager> _logger;

        public SessionManager(ILogger<SessionManager> logger)
        {
            _logger = logger;
        }

        public string CreateSessionDirectory()
        {
            var sessionId = Guid.NewGuid().ToString("N");
            var sessionPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "GameSessions", sessionId);
            Directory.CreateDirectory(sessionPath);
            _logger.LogInformation($"Created session directory: {sessionPath}");
            return sessionPath;
        }
    }
