[Route("[controller]")]
public class WebPageController : ControllerBase
{
    private readonly ICmsService _cmsService;
    private readonly ILogger<WebPageController> _logger;

    public WebPageController(ICmsService cmsService, ILogger<WebPageController> logger)
    {
        _cmsService = cmsService;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateWebPage([FromBody] PageUpdateRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        try
        {
            await _cmsService.UpdatePageAsync(request.PageId, request.Content, request.Version);
            return Ok();
        }
        catch (CmsApiDownException ex)
        {
            _logger.LogError(ex, "CMS API is down. Providing fallback mechanism.");
            // Fallback mechanism for when CMS API is down
            return StatusCode(503, "Service unavailable");
        }
        catch (RateLimitExceededException ex)
        {
            _logger.LogWarning(ex, "Rate limit exceeded. Please try again later.");
            return TooManyRequests();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating the web page.");
            return StatusCode(500, "Internal server error");
        }
    }
}

public class PageUpdateRequest
{
    public string PageId { get; set; }
    public string Content { get; set; }
    public int Version { get; set; }
}

public interface ICmsService
{
    Task UpdatePageAsync(string pageId, string content, int version);
}

public class CmsService : ICmsService
{
    private readonly IHttpClientFactory _httpClientFactory;

    public CmsService(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    public async Task UpdatePageAsync(string pageId, string content, int version)
    {
        var client = _httpClientFactory.CreateClient("cms");
        var requestContent = new StringContent(JsonConvert.SerializeObject(new { PageId, Content, Version }), Encoding.UTF8, "application/json");
        var response = await client.PostAsync("/api/pages", requestContent);

        if (!response.IsSuccessStatusCode)
        {
            throw new CmsApiDownException("CMS API is down.");
        }

        // Handle other potential errors
    }
}

public class CmsApiDownException : Exception
{
    public CmsApiDownException(string message) : base(message)
    {
    }
}

public class RateLimitExceededException : Exception
{
    public RateLimitExceededException(string message) : base(message)
    {
    }
}
