using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Polly;
using Polly.Retry;

public class ContentService : IContentService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, DateTime> _rateLimiters = new();
    private readonly RetryPolicy _retryPolicy;

    public ContentService(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _retryPolicy = Policy.Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    public async Task UpdateElementAsync(string sectionId, string elementId, string htmlContent)
    {
        var rateLimitKey = $"{sectionId}_{elementId}";
        if (_rateLimiters.TryGetValue(rateLimitKey, out var lastUpdated) && DateTime.UtcNow - lastUpdated < TimeSpan.FromSeconds(1))
        {
            throw new InvalidOperationException("Rate limit exceeded.");
        }

        _rateLimiters[rateLimitKey] = DateTime.UtcNow;

        await _retryPolicy.ExecuteAsync(async () =>
        {
