class EventPipeline {
private:
    std::queue<Event> incomingEvents;
    std::mutex incomingQueueMutex;
    std::condition_variable incomingQueueCondVar;
    std::atomic<bool> running{true};
    EventProcessor processor;
    EventFilter filter;
    DistributedCache cache;
    ExternalAPIClient client;

public:
    void start() {
        while (running) {
            std::unique_lock<std::mutex> lock(incomingQueueMutex);
            incomingQueueCondVar.wait(lock, [this] { return !incomingEvents.empty(); });
            Event event = incomingEvents.front();
            incomingEvents.pop();
            lock.unlock();

            if (filter.filter(event)) {
                processor.process(event);
                cache.put("event_key", "event_data");
                client.sendRequest(event);
            }
        }
    }

    void stop() {
        running = false;
        incomingQueueCondVar.notify_all();
    }

    void enqueueEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(incomingQueueMutex);
        incomingEvents.push(event);
        incomingQueueCondVar.notify_one();
    }
};

int main() {
    EventPipeline pipeline;
    std::thread worker([&pipeline] { pipeline.start(); });

    // Simulate event ingestion
    for (int i = 0; i < 1000; ++i) {
        Event event;
        pipeline.enqueueEvent(event);
    }

    pipeline.stop();
    worker.join();

    return 0;
}
