namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = net::ip::tcp;               // from <boost/asio/ip/tcp.hpp>

// Asynchronous HTTP client
class HttpClient {
public:
    HttpClient(net::io_context& ioc)
        : resolver_(ioc), stream_(ioc) {}

    void start(const std::string& host, const std::string& port) {
        resolver_.async_resolve(host, port,
            beast::bind_front_handler(&HttpClient::onResolve, this, std::placeholders::_1, std::placeholders::_2));
    }

private:
    void onResolve(beast::error_code ec, tcp::resolver::results_type results) {
        if (!ec) {
            beast::get_lowest_layer(stream_).async_connect(results,
                beast::bind_front_handler(&HttpClient::onConnect, this, std::placeholders::_1));
        }
    }

    void onConnect(beast::error_code ec, tcp::resolver::endpoint_type endpoint) {
        if (!ec) {
            http::async_read_until(stream_, buffer_, "\r\n\r\n",
                beast::bind_front_handler(&HttpClient::onRead, this, std::placeholders::_1));
        }
    }

    void onRead(beast::error_code ec, std::size_t bytes_transferred) {
        if (!ec) {
            // Handle the response here
        }
    }

    tcp::resolver resolver_;
    beast::tcp_stream stream_;
    beast::flat_buffer buffer_;
};

int main() {
    try {
        net::io_context ioc;
        HttpClient client(ioc);
        client.start("example.com", "80");
        ioc.run();
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
    }
    return 0;
}
