                let data = vec![1u8; 1024];
                self.memory_chunks.insert(data_id.to_string(), data.clone());
                self.cache.insert(data_id.to_string(), data);
                self.cache.get(data_id).cloned()
            }
        }

        pub fn free_resource(&mut self, data_id: &str) {
            if let Some(_) = self.memory_chunks.remove(data_id) {
                self.cache.remove(data_id);
            }
        }
    }
}

