fn create_directory_and_set_env_var(directory_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    // Check if the environment variable is already set
    if let Ok(path) = env::var("PAYMENT_DIR") {
        println!("Using existing directory from environment variable: {}", path);
        return Ok(());
    }

    // Create a new directory
    let path = Path::new(directory_name);
    fs::create_dir_all(&path)?;

    // Set the environment variable to the path of the directory
    env::set_var("PAYMENT_DIR", &path);

    println!("Created and set directory: {}", path.display());
    Ok(())
}
