import boto3
from botocore.exceptions import NoCredentialsError
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
from PIL import Image
import io

app = Flask(__name__)

# Initialize AWS S3 client
s3_client = boto3.client(
    's3',
    aws_access_key_id='YOUR_ACCESS_KEY',
    aws_secret_access_key='YOUR_SECRET_KEY'
)

# Configuration for S3 bucket and region
BUCKET_NAME = 'your-bucket-name'
REGION = 'your-region'

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        try:
            s3_client.upload_fileobj(io.BytesIO(file.read()), BUCKET_NAME, filename, ExtraArgs={'ACL': 'public-read'})
            return jsonify({'message': f'File {filename} uploaded successfully', 'url': f'https://{BUCKET_NAME}.s3-{REGION}.amazonaws.com/{filename}'})
        except FileNotFoundError:
            return jsonify({'error': 'The file was not found'}), 404
        except NoCredentialsError:
            return jsonify({'error': 'Credentials not available'}), 401

def allowed_file(filename):
    # Check if the file is one of the allowed types
    ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=80)
```

