['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define INITIAL_CAPACITY 10
#define RESIZE_FACTOR 2
#define GARBAGE_COLLECTION_INTERVAL 60

typedef struct Session {
    char* id;
    time_t expiration_time;
} Session;

typedef struct SessionList {
    Session** sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t resize_cond;
} SessionList;

SessionList* create_session_list() {
    SessionList* list = malloc(sizeof(SessionList));
    if (list == NULL) return NULL;
    list->sessions = calloc(INITIAL_CAPACITY, sizeof(Session*));
    if (list->sessions == NULL) {
        free(list);
        return NULL;
    }
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->resize_cond, NULL);
    return list;
}

void destroy_session_list(SessionList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->sessions[i]->id);
        free(list->sessions[i]);
    }
    free(list->sessions);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->resize_cond);
    free(list);
}

void add_session(SessionList* list, char* id, time_t expiration_time) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * RESIZE_FACTOR;
        Session** new_sessions = realloc(list->sessions, new_capacity * sizeof(Session*));
        if (new_sessions == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&list->lock);
            return;
        }
        list->sessions = new_sessions;
        list->capacity = new_capacity;
        pthread_cond_signal(&list->resize_cond); // Notify waiting threads of resize completion
    }
    Session* session = malloc(sizeof(Session));
    if (session == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle memory allocation failure
    }
    session->id = strdup(id);
    session->expiration_time = expiration_time;
    list->sessions[list->size++] = session;
    pthread_mutex_unlock(&list->lock);
}

void remove_session(SessionList* list, char* id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (strcmp(list->sessions[i]->id, id) == 0) {
            free(list->sessions[i]->id);
            free(list->sessions[i]);
            while (i + 1 < list->size) {
                list->sessions[i] = list->sessions[i + 1];
                i++;
            }
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void garbage_collection(SessionList* list) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&list->lock);
    for (size_t i = list->size - 1; i >= 0; --i) {
        if (list->sessions[i]->expiration_time <= current_time) {
            free(list->sessions[i]->id);
            free(list->sessions[i]);
            while (i + 1 < list->size) {
                list->sessions[i] = list->sessions[i + 1];
                i++;
            }
            list->size--;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void* gc_thread(void* arg) {
    SessionList* list = (SessionList*)arg;
    while (1) {
        sleep(GARBAGE_COLLECTION_INTERVAL);
        garbage_collection(list);
    }
    return NULL;
}

int main() {
    SessionList* session_list = create_session_list();
    if (session_list == NULL) return 1;

    pthread_t gc_tid;
    pthread_create(&gc_tid, NULL, gc_thread, session_list);

    // Simulate adding and removing sessions
    add_session(session_list, "user123", time(NULL) + 3600);
    remove_session(session_list, "user123");

    destroy_session_list(session_list);
    pthread_join(gc_tid, NULL);
    return 0;
}
```

This code provides a basic implementation of a session management module in C. It includes creating and destroying the session list, adding and removing sessions, and performing garbage collection. The garbage collection runs on a separate thread to handle periodic cleanup without blocking the main service flow.

Please note that this is a simplified example for demonstration purposes. In a production environment, you would need to add more robust error handling, logging, and consider other factors such as session compression or encryption as specified in the task requirements.']

