// Define the TextureLoader class
class TextureLoader {
public:
    TextureLoader(const std::string& address)
        : channel(grpc::CreateChannel(address, grpc::InsecureChannelCredentials())) {}

    // Function to load textures asynchronously
    void LoadTextureAsync(const std::string& textureId, std::promise<void> future) {
        std::thread([this, textureId, &future]() mutable {
            // Simulate network delay
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            // Perform texture loading logic here
            std::cout << "Loading texture: " << textureId << std::endl;
            future.set_value();
        }).detach();
    }

    // Function to fetch texture metadata from the asset management service
    void FetchMetadataAsync(const std::string& textureId, std::promise<void> future) {
        grpc::ClientContext context;
        AssetManagementService::Stub stub(channel);
        AssetRequest request;
        request.set_texture_id(textureId);
        AssetResponse response;

        if (stub.GetMetadata(&context, request, &response)) {
            std::cout << "Fetched metadata for texture: " << textureId << std::endl;
            future.set_value();
        } else {
            future.set_exception(std::make_exception_ptr(std::runtime_error("Failed to fetch metadata")));
        }
    }

private:
    std::shared_ptr<grpc::Channel> channel;
};

int main() {
    TextureLoader loader("localhost:50051");

    // Example usage of the TextureLoader
    auto future1 = std::async(std::launch::async, &TextureLoader::LoadTextureAsync, &loader, "texture123", std::promise<void>());
    auto future2 = std::async(std::launch::async, &TextureLoader::FetchMetadataAsync, &loader, "texture456", std::promise<void>());

    // Wait for tasks to complete
    future1.get();
    future2.get();

    return 0;
}
