        if (typeof(T) == typeof(int))
        {
            return await GenerateIntAsync((int)random.Next(), cancellationToken).ConfigureAwait(false);
        }
        else if (typeof(T) == typeof(double))
        {
            return await GenerateDoubleAsync(random.NextDouble(), cancellationToken).ConfigureAwait(false);
