#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PATH_LENGTH 4096

typedef struct {
    char path[MAX_PATH_LENGTH];
    pthread_mutex_t mutex;
} FilePath;

void init_file_path(FilePath *fp, const char *path) {
    strncpy(fp->path, path, sizeof(fp->path));
    fp->path[sizeof(fp->path) - 1] = '\0';
    pthread_mutex_init(&fp->mutex, NULL);
}

void free_file_path(FilePath *fp) {
    pthread_mutex_destroy(&fp->mutex);
}

int set_file_path(FilePath *fp, const char *new_path) {
    pthread_mutex_lock(&fp->mutex);
    strncpy(fp->path, new_path, sizeof(fp->path));
    fp->path[sizeof(fp->path) - 1] = '\0';
    pthread_mutex_unlock(&fp->mutex);
    return 0;
}

char* get_file_path(FilePath *fp) {
    char *result = malloc(sizeof(char) * (MAX_PATH_LENGTH + 1));
    if (!result) return NULL;

    pthread_mutex_lock(&fp->mutex);
    strncpy(result, fp->path, sizeof(fp->path));
    result[sizeof(fp->path) - 1] = '\0';
    pthread_mutex_unlock(&fp->mutex);

    return result;
}

