// File: concurrent_operations.c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONCURRENT_THREADS 10

typedef struct {
    int thread_count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ConcurrencyControl;

void init_concurrency_control(ConcurrencyControl *cc, int max_threads) {
    cc->thread_count = 0;
    cc->max_threads = max_threads;
    pthread_mutex_init(&cc->mutex, NULL);
    pthread_cond_init(&cc->cond, NULL);
}

void free_concurrency_control(ConcurrencyControl *cc) {
    pthread_mutex_destroy(&cc->mutex);
    pthread_cond_destroy(&cc->cond);
}

int acquire_concurrency_control(ConcurrencyControl *cc) {
    pthread_mutex_lock(&cc->mutex);
    while (cc->thread_count >= cc->max_threads) {
        pthread_cond_wait(&cc->cond, &cc->mutex);
    }
    cc->thread_count++;
    pthread_mutex_unlock(&cc->mutex);
    return 0;
}

void release_concurrency_control(ConcurrencyControl *cc) {
    pthread_mutex_lock(&cc->mutex);
    cc->thread_count--;
    pthread_cond_signal(&cc->cond);
    pthread_mutex_unlock(&cc->mutex);
}
