#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <fstream>
#include <string>

// Define a simple event structure
struct Event {
    std::string type;
    std::time_t timestamp;
    std::unordered_map<std::string, std::string> metadata;

    Event(std::string t, std::time_t ts, std::unordered_map<std::string, std::string> md)
        : type(t), timestamp(ts), metadata(md) {}
};

// Define a worker thread to process events
void Worker(const std::queue<Event>& event_queue, std::mutex& queue_mutex,
             std::condition_variable& cond_var, bool& stop) {
    while (true) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        cond_var.wait(lock, [&stop] { return !stop || !event_queue.empty(); });

        if (stop && event_queue.empty()) break;

        Event event = event_queue.front();
        event_queue.pop();

        // Simulate processing the event
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed event: " << event.type << ", Timestamp: " << event.timestamp << std::endl;
    }
}

// Define a function to start the pipeline
void StartPipeline(const std::vector<std::string>& service_urls, int num_workers) {
    std::queue<Event> event_queue;
    std::mutex queue_mutex;
    std::condition_variable cond_var;
    bool stop = false;

    // Create worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < num_workers; ++i) {
        workers.emplace_back(Worker, std::ref(event_queue), std::ref(queue_mutex),
                             std::ref(cond_var), std::ref(stop));
    }

    // Simulate receiving events
    for (int i = 0; i < 100; ++i) {
        Event event("Type" + std::to_string(i % 10), time(nullptr), {});
        std::lock_guard<std::mutex> lock(queue_mutex);
        event_queue.push(event);
        cond_var.notify_one();
    }

    // Stop the workers
    stop = true;
    for (auto& worker : workers) {
        worker.join();
    }
}

int main() {
    std::vector<std::string> service_urls = {"http://service1", "http://service2"};
    StartPipeline(service_urls, 5);
    return 0;
}
```

