#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char event_type[32];
    void* metadata;
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} EventQueue;

void init_event_queue(EventQueue* queue, size_t initial_capacity) {
    queue->events = malloc(initial_capacity * sizeof(NetworkEvent));
    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

void enqueue_event(EventQueue* queue, NetworkEvent event) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    queue->events[queue->size++] = event;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

NetworkEvent dequeue_event(EventQueue* queue) {
    NetworkEvent event;
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    event = queue->events[--queue->size];
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return event;
}

void resize_event_queue(EventQueue* queue, size_t new_capacity) {
    pthread_mutex_lock(&queue->lock);
    NetworkEvent* new_events = realloc(queue->events, new_capacity * sizeof(NetworkEvent));
    if (new_events == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    queue->events = new_events;
    queue->capacity = new_capacity;
    pthread_mutex_unlock(&queue->lock);
}

void destroy_event_queue(EventQueue* queue) {
    free(queue->events);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->cond);
}
```

