#define MAX_EVENTS 1024
#define MAX_THREADS 100

typedef struct {
    time_t timestamp;
    char type[50];
    void* metadata;
} NetworkEvent;

NetworkEvent event_buffer[MAX_EVENTS];
sem_t buffer_lock;
int buffer_size = 0;

void* event_processor(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        sem_wait(&buffer_lock);
        if (buffer_size > 0) {
            NetworkEvent event = event_buffer[--buffer_size];
            // Process the event
            printf("Thread %d processing event: Type=%s, Timestamp=%ld\n", thread_id, event.type, event.timestamp);
            free(event.metadata); // Free any allocated metadata
        }
        sem_post(&buffer_lock);
    }
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, event_processor, &thread_ids[i]);
    }

    // Simulate event ingestion
    for (int i = 0; i < MAX_EVENTS; i++) {
        sem_wait(&buffer_lock);
        if (buffer_size < MAX_EVENTS) {
            NetworkEvent event;
            event.timestamp = time(NULL);
            snprintf(event.type, sizeof(event.type), "Type%d", i % 10);
            event.metadata = malloc(128); // Allocate metadata
            snprintf((char*)event.metadata, 128, "Metadata%d", i);
            event_buffer[buffer_size++] = event;
        }
        sem_post(&buffer_lock);
        sleep(1); // Simulate variable processing time
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
