using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class SecureDataProcessor
{
    private readonly HttpClient _httpClient;
    private readonly IConfigService _configService;
    private readonly IDistributedCache _cache;

    public SecureDataProcessor(HttpClient httpClient, IConfigService configService, IDistributedCache cache)
    {
        _httpClient = httpClient;
        _configService = configService;
        _cache = cache;
    }

    public async Task<T> GetSecureDataAsync<T>(string userId)
    {
        var endpoint = await GetOptimalEndpointAsync();
        var key = $"secureData:{userId}";

        if (await _cache.TryGetValueAsync(key, out byte[] cachedData))
        {
            return JsonConvert.DeserializeObject<T>(System.Text.Encoding.UTF8.GetString(cachedData));
        }

        try
        {
            var response = await _httpClient.GetAsync($"{endpoint}/data/{userId}");
            response.EnsureSuccessStatusCode();
            var data = await response.Content.ReadAsStringAsync();

            var deserializedData = JsonConvert.DeserializeObject<T>(data);
            var serializedData = System.Text.Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(deserializedData));
            await _cache.SetAsync(key, serializedData);

            return deserializedData;
        }
        catch (Exception ex)
        {
            // Log exception details
            throw;
        }
    }

    private async Task<string> GetOptimalEndpointAsync()
    {
        var endpoints = await _configService.GetEndpointsAsync();
        var availableEndpoints = endpoints.Where(e => e.IsAvailable).ToList();

        if (!availableEndpoints.Any())
        {
            throw new InvalidOperationException("No available endpoints.");
        }

        // Implement load balancing strategy (e.g., round-robin)
        return availableEndpoints[0].Url;
    }
}

public interface IConfigService
{
    Task<List<EndpointMetadata>> GetEndpointsAsync();
}

public class EndpointMetadata
{
    public string Url { get; set; }
    public bool IsAvailable { get; set; }
}

public interface IDistributedCache
{
    Task<byte[]> TryGetValueAsync(string key, out byte[] value);
    Task SetAsync(string key, byte[] value);
}
