using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.WebSockets;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using RabbitMQ.Client;

public interface IEventProcessor { }

public class EventProcessor : IEventProcessor {
    private readonly List<WebSocket> _webSockets;
    private readonly IModel _channel;
    private readonly ConnectionFactory _factory;

    public EventProcessor() {
        _webSockets = new List<WebSocket>();
        var factory = new ConnectionFactory { HostName = "localhost" };
        _factory = factory;
        _channel = factory.CreateConnection().CreateModel();
    }

    public async Task StartProcessingAsync(List<string> endpoints) {
        foreach (var endpoint in endpoints) {
            using (var client = new ClientWebSocket()) {
                await client.ConnectAsync(new Uri(endpoint), CancellationToken.None);
                _webSockets.Add(client);
                _channel.QueueDeclare(queue: "events", durable: false, exclusive: false, autoDelete: false, arguments: null);
                // Start listening for messages
            }
        }

        while (true) {
            foreach (var webSocket in _webSockets) {
                if(webSocket.State == WebSocketState.Open){
                    var buffer = new byte[1024 * 4];
                    await webSocket.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);
                    // Process message
                    _channel.BasicPublish(exchange: "",
                                         routingKey: "events",
                                         basicProperties: null,
                                         body: buffer);
                }
            }

            await Task.Delay(100); 
        }
    }

    public void StopProcessing() {
        foreach (var webSocket in _webSockets) {
            if(webSocket.State == WebSocketState.Open){
                webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, "Closing", CancellationToken.None);
            }
        }

        _channel.Close();
        _factory.Dispose();
    }
}
```
