public class DataProcessorService {

    private static final Logger logger = LoggerFactory.getLogger(DataProcessorService.class);
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void startProcessing(String apiEndpoint, Class<?> targetClass) {
        scheduler.scheduleAtFixedRate(() -> processApiData(apiEndpoint, targetClass), 0, 1, TimeUnit.MINUTES);
    }

    private <T> void processApiData(String apiEndpoint, Class<T> targetClass) {
        try {
            T data = fetchAndDeserializeData(apiEndpoint, targetClass);
            processData(data);
        } catch (IOException | InterruptedException e) {
            handleFailure(e);
        }
    }

    @SuppressWarnings("unchecked")
    private <T> T fetchAndDeserializeData(String apiEndpoint, Class<T> targetClass) throws IOException, InterruptedException {
        // Simulate fetching data from an external API
        Thread.sleep(100); // Network latency simulation

        URI uri = new URI(apiEndpoint);
        String jsonData = fetchDataFromUri(uri); // Fetch JSON data from the given URI

        return (T) objectMapper.readValue(jsonData, targetClass);
    }

    private void processData(Object data) {
        logger.info("Processing data: {}", data);
        // Perform processing logic here
    }

    private void handleFailure(Exception e) {
        if (e instanceof IOException || e instanceof InterruptedException) {
            logger.warn("Failed to process data due to transient error", e);
            retryOperation();
        } else {
            logger.error("Unexpected failure while processing data", e);
        }
    }

    private void retryOperation() {
        int delay = 1; // Initial delay
        for (int attempt = 1; attempt <= 5; attempt++) { // Max attempts with exponential backoff
            try {
                Thread.sleep(delay * 1000); // Wait before retrying
                logger.info("Retrying operation (attempt {})", attempt);
                break;
            } catch (InterruptedException ie) {
                logger.error("Interrupted while retrying operation", ie);
                Thread.currentThread().interrupt();
            }
            delay *= 2; // Exponential backoff
        }
    }

    private String fetchDataFromUri(URI uri) throws IOException {
        // Simulate fetching data from a URI
        return "{\"key\":\"value\"}"; // Replace with actual API call to fetch JSON data
    }

    public void stopProcessing() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            logger.error("Error shutting down scheduler", e);
        }
    }
}
