const express = require('express');
const axios = require('axios');
const { exec } = require('child_process');
const redis = require('redis');
const bluebird = require('bluebird');

// Initialize Redis client with bluebird promises
bluebird.promisifyAll(redis.RedisClient.prototype);
bluebird.promisifyAll(redis.Multi.prototype);

const app = express();
const port = process.env.PORT || 3000;
const redisClient = redis.createClient();

app.use(express.json());

// Function to safely execute system commands
async function executeCommand(command) {
  return new Promise((resolve, reject) => {
    exec(command, (error, stdout, stderr) => {
      if (error) {
        console.error(`Error executing command: ${command}`);
        reject(error);
      } else {
        resolve(stdout);
      }
    });
  });
}

// Function to fetch data from external API
async function fetchDataFromAPI(url) {
  try {
    const response = await axios.get(url);
    return response.data;
  } catch (error) {
    console.error(`Error fetching data from ${url}`);
    throw error;
  }
}

// Route to handle batch job processing
app.post('/process-job', async (req, res) => {
  try {
    const { command, apiUrls } = req.body;

    // Execute system command
    const commandOutput = await executeCommand(command);

    // Fetch data from multiple external APIs
    const results = await Promise.all(apiUrls.map(fetchDataFromAPI));

    // Store results in Redis for aggregation later
    redisClient.set('job_results', JSON.stringify({ commandOutput, apiResults }));

    res.status(200).send('Job processed successfully');
  } catch (error) {
    console.error('Error processing job:', error);
    res.status(500).send('Internal Server Error');
  }
});

// Route to fetch aggregated results
app.get('/get-results', async (req, res) => {
  try {
    const results = await redisClient.getAsync('job_results');
    res.json(JSON.parse(results));
  } catch (error) {
    console.error('Error fetching job results:', error);
    res.status(500).send('Internal Server Error');
  }
});

app.listen(port, () => {
  console.log(`Microservice listening at http://localhost:${port}`);
});
