use actix_web::{web, App, HttpResponse, HttpServer};
use tokio::sync::Mutex;
use reqwest::Client;
use std::collections::HashMap;
use serde_json::{json, Value};

struct ApiConfig {
    endpoint: String,
    auth_method: AuthMethod,
}

enum AuthMethod {
    BearerToken(String),
    OAuth2(OAuth2Config),
}

struct OAuth2Config {
    client_id: String,
    client_secret: String,
    token_url: String,
    refresh_token_url: String,
    expiration_interval: u64,
}

struct AppState {
    clients: HashMap<String, Client>,
    oauth2_tokens: Mutex<HashMap<String, (String, std::time::Instant)>>,
}

async fn fetch_data(state: web::Data<AppState>, api_config: web::Path<String>) -> HttpResponse {
    let client = state.clients.get(api_config.as_str()).unwrap();
    match &api_config.auth_method {
        AuthMethod::BearerToken(token) => {
            client
                .get(&api_config.endpoint)
                .header("Authorization", format!("Bearer {}", token))
                .send()
                .await
                .map_err(|e| HttpResponse::InternalServerError().body(format!("Request failed: {}", e)))
        }
        AuthMethod::OAuth2(oauth2_config) => {
            let mut oauth2_tokens = state.oauth2_tokens.lock().await;
            if !oauth2_tokens.contains_key(api_config.as_str()) || oauth2_tokens[api_config.as_str()].1.elapsed() > std::time::Duration::from_secs(oauth2_config.expiration_interval) {
                // Refresh token logic here
                let response: Value = client
                    .post(&oauth2_config.refresh_token_url)
                    .form(&[
                        ("grant_type", "refresh_token"),
                        ("client_id", &oauth2_config.client_id),
                        ("client_secret", &oauth2_config.client_secret),
                    ])
                    .send()
                    .await?
                    .json()
                    .await?;
                let new_token = response["access_token"].as_str().unwrap().to_string();
                oauth2_tokens.insert(api_config.as_str().to_string(), (new_token.clone(), std::time::Instant::now()));
            }
            client
                .get(&api_config.endpoint)
                .header("Authorization", format!("Bearer {}", oauth2_tokens[api_config.as_str()].0))
                .send()
                .await
        }
    }
    .map(|response| response.json::<Value>().map_err(|e| HttpResponse::InternalServerError().body(format!("Failed to parse response: {}", e))))
    .and_then(|result| result.map_err(|e| HttpResponse::InternalServerError().body(format!("Request failed: {}", e))))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let api_configs = HashMap::from([
        ("api1".to_string(), ApiConfig {
            endpoint: "https://api1.example.com/data".to_string(),
            auth_method: AuthMethod::BearerToken("initial_token".to_string()),
        }),
        // Add more API configurations here
    ]);

    let clients = api_configs.iter().map(|(name, config)| {
        (name.clone(), Client::new())
    }).collect();

    let oauth2_tokens = Mutex::new(HashMap::new());

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(AppState { clients, oauth2_tokens }))
            .route("/{api}", web::get().to(fetch_data))
            // Add routes for other CRUD operations and API endpoints
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
