class BufferManager {
public:
    // Constructor
    BufferManager(size_t capacity) : capacity_(capacity), size_(0) {}

    // Function to add data to buffer
    void addData(const std::string& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return size_ < capacity_; });
        buffer_.push(data);
        ++size_;
        lock.unlock();
        condition_.notify_one();
    }

    // Function to remove data from buffer
    void removeData(std::string& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !buffer_.empty(); });
        data = buffer_.front();
        buffer_.pop();
        --size_;
        lock.unlock();
        condition_.notify_one();
    }

private:
    size_t capacity_;
    size_t size_;
    std::queue<std::string> buffer_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

