import time
import requests

class CustomerProfileService:
    def __init__(self):
        self.api_queue = Queue()
        self.lock = threading.Lock()
        self.api_rate_limit = 500
        self.api_calls_per_minute = 0
        self.start_time = time.time()

    def add_update_to_queue(self, update_task):
        with self.lock:
            if (time.time() - self.start_time) > 60:
                self.api_calls_per_minute = 0
                self.start_time = time.time()
            if self.api_calls_per_minute < self.api_rate_limit:
                self.api_calls_per_minute += 1
                self.api_queue.put(update_task)
            else:
                self.handle_throttle()

    def handle_throttle(self):
        time.sleep(60 - (time.time() - self.start_time))
        self.api_calls_per_minute = 0
        self.start_time = time.time()

    def process_updates(self):
        while True:
            task = self.api_queue.get()
            if task is None:
                break
            self.call_api(task)
            self.api_queue.task_done()

    def call_api(self, update_task):
        try:
            response = requests.post(update_task['url'], json=update_task['data'])
            response.raise_for_status()
        except requests.RequestException as e:
            print(f"API Error: {e}")
        finally:
            with self.lock:
                if (time.time() - self.start_time) > 60:
                    self.api_calls_per_minute = 0
                    self.start_time = time.time()

    def start(self):
        threads = []
        for i in range(5):  # Create multiple worker threads
            thread = threading.Thread(target=self.process_updates)
            thread.start()
            threads.append(thread)

        while True:
            update_task = self.get_update_from_source()  # Implement your logic to get updates from source
            if update_task is None:
                break
            self.add_update_to_queue(update_task)

        for _ in range(5):
            self.api_queue.put(None)  # Send stop signals to workers
        for thread in threads:
            thread.join()

    def get_update_from_source(self):
        # Implement your logic to fetch updates from the source (e.g., database, API)
        pass

if __name__ == "__main__":
    service = CustomerProfileService()
    service.start()
