class EventProcessor {
public:
    void submitEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(mutex);
        eventQueue.push(event);
        cv.notify_one();
    }

private:
    std::queue<Event> eventQueue;
    std::mutex mutex;
    std::condition_variable cv;
};

class LoggingService {
public:
    void logEvent(const Event& event) {
        // Implement logging logic here
        // This could involve sending the event to an external service asynchronously
    }
};

class RealTimeEventProcessingFramework {
public:
    RealTimeEventProcessingFramework() : stop(false), numThreads(4) {
        for (int i = 0; i < numThreads; ++i) {
            workers.emplace_back(&RealTimeEventProcessingFramework::workerThread, this);
        }
    }

    ~RealTimeEventProcessingFramework() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        for (auto& thread : workers) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void submitEvent(const Event& event) {
        processor.submitEvent(event);
    }

private:
    EventProcessor processor;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable cv;
    bool stop;
    int numThreads;

    void workerThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return stop || !processor.eventQueue.empty(); });
            if (stop && processor.eventQueue.empty()) {
                break;
            }
            Event event = processor.eventQueue.front();
            processor.eventQueue.pop();
            lock.unlock();

            LoggingService service;
            service.logEvent(event);
        }
    }
};

int main() {
    RealTimeEventProcessingFramework framework;

    // Simulate submitting events
    for (int i = 0; i < 10; ++i) {
        Event event(i, "Type" + std::to_string(i), {{"key", "value"}}, "Location" + std::to_string(i), i % 3, {});
        framework.submitEvent(event);
    }

    return 0;
}
