#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <string.h>
#include <pthread.h>

#define KEY_SIZE 32
#define IV_SIZE 12
#define PBKDF2_ITERATIONS 30000

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} EncryptionKey;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static EVP_CIPHER_CTX *ctx = NULL;

void init_aes_context() {
    if (ctx == NULL) {
        ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            ERR_print_errors_fp(stderr);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_aes_context() {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx);
        ctx = NULL;
    }
}

int derive_key(const char *password, size_t password_len, unsigned char *key, unsigned char *iv) {
    if (!PKCS5_PBKDF2_HMAC_SHA256(password, password_len, (unsigned char *)"salt", 4, PBKDF2_ITERATIONS, key, KEY_SIZE)) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    if (RAND_bytes(iv, IV_SIZE) != 1) {
        ERR_print_errors_fp(stderr);
        return -1;
    }

    return 0;
}

int encrypt_data(const unsigned char *data, size_t data_len, const EncryptionKey *key, unsigned char *encrypted_data, unsigned char *tag) {
    if (pthread_mutex_lock(&mutex) != 0) {
        return -1;
    }

    int len = 0;
    if (!EVP_EncryptInit_ex2(ctx, EVP_aes_256_gcm(), NULL, key->key, key->iv)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    if (!EVP_EncryptUpdate(ctx, encrypted_data + len, &len, data, data_len)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    int ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    ciphertext_len += len;

    if (tag == NULL) {
        pthread_mutex_unlock(&mutex);
        return ciphertext_len;
    }

    int tag_len = 0;
    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, GCM_TAG_LENGTH, tag, &tag_len)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    pthread_mutex_unlock(&mutex);
    return ciphertext_len + tag_len;
}

int decrypt_data(const unsigned char *encrypted_data, size_t encrypted_data_len, const EncryptionKey *key, unsigned char *decrypted_data) {
    if (pthread_mutex_lock(&mutex) != 0) {
        return -1;
    }

    int len = 0;
    if (!EVP_DecryptInit_ex2(ctx, EVP_aes_256_gcm(), NULL, key->key, key->iv)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    if (!EVP_DecryptUpdate(ctx, decrypted_data + len, &len, encrypted_data, encrypted_data_len)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    int plaintext_len = len;

    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, GCM_TAG_LENGTH, (unsigned char *)encrypted_data + encrypted_data_len, 0)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    if (!EVP_DecryptFinal_ex(ctx, decrypted_data + len, &len)) {
        ERR_print_errors_fp(stderr);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    plaintext_len += len;

    pthread_mutex_unlock(&mutex);
    return plaintext_len;
}

void erase_sensitive_data(unsigned char *data, size_t data_len) {
    memset(data, 0, data_len);
}
