    int poolSize;
    NFAPI_CRC_INDICATION_PDU_T** pool;
    CallbackFunction* callbacks;
} WirelessNetworkManager;

// Initialize the WirelessNetworkManager
WirelessNetworkManager* initWirelessNetworkManager(int poolSize) {
    WirelessNetworkManager* manager = (WirelessNetworkManager*)malloc(sizeof(WirelessNetworkManager));
    manager->poolSize = poolSize;
    manager->pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(poolSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    manager->callbacks = (CallbackFunction*)malloc(poolSize * sizeof(CallbackFunction));

    for(int i = 0; i < poolSize; i++) {
        manager->pool[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->callbacks[i] = NULL;
    }

    return manager;
}

// Add a callback to the manager
void addCallback(WirelessNetworkManager* manager, int index, CallbackFunction callback) {
    if(index >= 0 && index < manager->poolSize) {
        manager->callbacks[index] = callback;
    }
}

// Process an NFAPI_CRC_INDICATION_PDU_T structure and call the associated callback
void processPDU(WirelessNetworkManager* manager, int index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if(index >= 0 && index < manager->poolSize && manager->callbacks[index] != NULL) {
        manager->callbacks[index](pdu);
    }
}

// Clean up the WirelessNetworkManager
void cleanupWirelessNetworkManager(WirelessNetworkManager* manager) {
    for(int i = 0; i < manager->poolSize; i++) {
        free(manager->pool[i]);
    }

