class EventProcessor {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable condition;
    std::atomic<bool> stopProcessing;

public:
    void addEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        condition.notify_one();
    }

    void startProcessing() {
        stopProcessing = false;
        while (!stopProcessing.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this] { return !eventQueue.empty() || stopProcessing.load(); });
            if (stopProcessing.load())
                break;

            Event event = eventQueue.front();
            eventQueue.pop();
            lock.unlock();

            processEvent(event);
        }
    }

    void stop() {
        stopProcessing.store(true);
        condition.notify_all();
    }

private:
    void processEvent(const Event& event) {
        // Implement event processing logic here
        std::cout << "Processing event: " << event.type << " at " << event.timestamp << std::endl;
    }
};

