class DistributedSystem {
private:
    std::vector<EventProcessor> processors;
    LoggingServiceClient logger;

public:
    void addEvent(const Event& event) {
        for (auto& processor : processors)
            processor.addEvent(event);
    }

    void startProcessing() {
        for (auto& processor : processors)
            std::thread(&EventProcessor::startProcessing, &processor).detach();
    }

    void stopProcessing() {
        for (auto& processor : processors)
            processor.stop();
    }
};

int main() {
