// Define a class for the event processing pipeline
class EventPipeline {
private:
    std::queue<Event> events;
    std::mutex mtx;
    std::condition_variable cv;
    bool stop;

public:
    EventPipeline() : stop(false) {}

    void startProcessing() {
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !events.empty() || stop; });
                if (stop && events.empty()) break;
                Event event = events.front();
                events.pop();
                lock.unlock();

                // Process the event
                processEvent(event);
            }
        }).detach();
    }

    void addEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(mtx);
        events.push(event);
        cv.notify_one();
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mtx);
            stop = true;
        }
        cv.notify_all();
    }

private:
    void processEvent(const Event& event) {
        // Process the event logic here
        // Example: Log, store in database, or forward to external service
    }
};

// Define a class for S3 file upload
