using Microsoft.Extensions.DependencyInjection;

public class HtmlElementUpdaterService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly IAuthorizationService _authorizationService;

    public HtmlElementUpdaterService(HttpClient httpClient, IDistributedCache cache, IAuthorizationService authorizationService)
    {
        _httpClient = httpClient;
        _cache = cache;
        _authorizationService = authorizationService;
    }

    [Authorize(AuthenticationSchemes = JwtBearerDefaults.AuthenticationScheme)]
    public async Task UpdateElementAsync(string userId, string pageId, string elementId, string newHtmlContent)
    {
        var userRoles = await GetRolesForUserAsync(userId);
        if (!userRoles.Contains("Editor"))
        {
            throw new UnauthorizedAccessException("You are not authorized to update elements.");
        }

        var currentHtmlContent = await _cache.GetStringAsync($"page-{pageId}");
        if (currentHtmlContent == null)
        {
            currentHtmlContent = await FetchPageContentFromDatabaseAsync(pageId);
        }

        var updatedHtmlContent = UpdateElementInHtml(currentHtmlContent, elementId, newHtmlContent);

        // Implement optimistic locking here

        await _cache.SetStringAsync($"page-{pageId}", updatedHtmlContent);
    }

    private async Task<string> GetRolesForUserAsync(string userId)
    {
        // Fetch user roles from the identity provider
        return await _httpClient.GetStringAsync($"https://idp.example.com/api/users/{userId}/roles");
    }

    private async Task<string> FetchPageContentFromDatabaseAsync(string pageId)
    {
        // Fetch page content from the database
        return await _httpClient.GetStringAsync($"https://database.example.com/api/pages/{pageId}");
    }

    private string UpdateElementInHtml(string htmlContent, string elementId, string newHtmlContent)
    {
        // Implement HTML parsing and updating logic here
        return htmlContent.Replace(elementId, newHtmlContent);
    }
}

public static class ServiceCollectionExtensions
{
    public static IServiceCollection AddHtmlElementUpdaterService(this IServiceCollection services)
    {
        services.AddHttpClient();
        services.AddDistributedMemoryCache();
        services.AddScoped<IAuthorizationService, AuthorizationService>();
        services.AddTransient<HtmlElementUpdaterService>();
        return services;
    }
}
