      if (currentChunk.length >= 1024 * 1024) { // 1MB
        const valid = await validateChunk(currentChunk);
        if (!valid) {
          reject(new Error(`Validation failed for chunk ${chunkIndex}`));
        }
        currentChunk = '';
        chunkIndex++;
      }
    });

    fileStream.on('end', async () => {
      if (currentChunk.length > 0) {
        const valid = await validateChunk(currentChunk);
        if (!valid) {
          reject(new Error(`Validation failed for final chunk`));
        }
      }
      resolve();
    });

