public class LinkedListNode {
    int data;
    LinkedListNode next;

    public LinkedListNode(int data) {
        this.data = data;
        this.next = null;
    }
}

public class LinkedList {

    private LinkedListNode head;

    public void insertAfterFirstOccurrence(int target, int valueToInsert) {
        if (head == null) return;

        LinkedListNode current = head;
        while (current != null && current.data != target) {
            current = current.next;
        }

        if (current != null) {
            LinkedListNode newNode = new LinkedListNode(valueToInsert);
            newNode.next = current.next;
            current.next = newNode;
        }
    }

    // Additional methods for linked list operations
}
