#define MAX_EVENTS 1000
#define RETRY_COUNT 3

typedef enum {
    OK,
    ERROR
} EventStatus;

typedef struct {
    int eventID;
    time_t timestamp;
    EventStatus status;
} NetworkEvent;

NetworkEvent* events[MAX_EVENTS];
int event_count = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void* simulate_network_latency(void* arg) {
    // Simulate network latency
    usleep(rand() % 100000); // Sleep for up to 100ms
    return NULL;
}

EventStatus generate_event(int eventID, double success_prob) {
    if (rand() < success_prob * RAND_MAX) {
        return OK;
    } else {
        return ERROR;
    }
}

void submit_event(NetworkEvent* event) {
    // Simulate external event processing service submission
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, simulate_network_latency, NULL);
    pthread_join(thread_id, NULL);

    if (rand() % 2 == 0) { // Simulate occasional failure
        printf("Failed to submit event %d\n", event->eventID);
        free(event);
    } else {
        events[event_count++] = event;
    }
}

void* generate_events(void* arg) {
    double success_prob = *(double*)arg;
    int rate = 10; // Events per second
    struct timespec ts, ts_old;

    clock_gettime(CLOCK_MONOTONIC, &ts_old);
    while (1) {
        for (int i = 0; i < rate; i++) {
            NetworkEvent* event = malloc(sizeof(NetworkEvent));
            event->eventID = event_count + 1;
            event->timestamp = time(NULL);
            event->status = generate_event(event_count + 1, success_prob);
            submit_event(event);

            pthread_mutex_lock(&log_mutex);
            printf("Event %d generated with status %s\n", event_count + 1, event->status == OK ? "OK" : "ERROR");
            pthread_mutex_unlock(&log_mutex);

            nanosleep((struct timespec){0, 1e9 / rate}, NULL); // Sleep for 1/rate seconds
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (timespec_subtract(&ts, &ts_old) >= 1) {
            ts_old = ts;
        }
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    double success_prob = 0.9; // Probability of successful event
    pthread_t generate_thread;

    if (pthread_create(&generate_thread, NULL, generate_events, &success_prob) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(generate_thread, NULL);

    return 0;
}
