['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_EVENTS 1000
#define MAX_SERVICES 5

typedef struct {
    int id;
    char* event_data;
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    int front, rear;
    sem_t empty, full;
    pthread_mutex_t mutex;
} EventQueue;

EventQueue event_queue;

void init_event_queue() {
    memset(&event_queue, 0, sizeof(EventQueue));
    sem_init(&event_queue.empty, 0, MAX_EVENTS);
    sem_init(&event_queue.full, 0, 0);
    pthread_mutex_init(&event_queue.mutex, NULL);
}

void enqueue(Event event) {
    sem_wait(&event_queue.empty);
    pthread_mutex_lock(&event_queue.mutex);
    event_queue.events[event_queue.rear] = event;
    event_queue.rear = (event_queue.rear + 1) % MAX_EVENTS;
    pthread_mutex_unlock(&event_queue.mutex);
    sem_post(&event_queue.full);
}

Event dequeue() {
    Event event;
    sem_wait(&event_queue.full);
    pthread_mutex_lock(&event_queue.mutex);
    event = event_queue.events[event_queue.front];
    event_queue.front = (event_queue.front + 1) % MAX_EVENTS;
    pthread_mutex_unlock(&event_queue.mutex);
    sem_post(&event_queue.empty);
    return event;
}

void* worker_thread(void* arg) {
    int service_id = *(int*)arg;
    while (1) {
        Event event = dequeue();
        // Simulate submission to external service
        printf("Service %d: Processing event %s\n", service_id, event.event_data);
        sleep(1);  // Simulate processing time
    }
}

void* producer_thread(void* arg) {
    while (1) {
        Event event;
        // Simulate event generation
        event.id = rand() % 1000;
        sprintf(event.event_data, "Event_%d", event.id);
        enqueue(event);
        sleep(1);  // Simulate time between events
    }
}

int main() {
    init_event_queue();
    pthread_t producer, workers[MAX_SERVICES];
    int service_ids[MAX_SERVICES];

    for (int i = 0; i < MAX_SERVICES; ++i) {
        service_ids[i] = i;
        pthread_create(&workers[i], NULL, worker_thread, &service_ids[i]);
    }
    pthread_create(&producer, NULL, producer_thread, NULL);

    pthread_join(producer, NULL);
    for (int i = 0; i < MAX_SERVICES; ++i) {
        pthread_join(workers[i], NULL);
    }

    return 0;
}
