import org.eclipse.paho.client.mqttv3.MqttClient;
import org.eclipse.paho.client.mqttv3.MqttConnectOptions;
import org.eclipse.paho.client.mqttv3.MqttMessage;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DataIngestionPipeline {

    private static final String KAFKA_BROKER = "kafka://localhost:9092";
    private static final String MQTT_BROKER = "tcp://mqtt.eclipse.org:1883";
    private static final String HTTP_API_URL = "https://api.example.com/data";

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(5);

        // Kafka consumer
        Properties kafkaProps = new Properties();
        kafkaProps.put("bootstrap.servers", KAFKA_BROKER);
        kafkaProps.put("group.id", "data-ingestion-group");
        KafkaConsumer<String, String> kafkaConsumer = new KafkaConsumer<>(kafkaProps);
        kafkaConsumer.subscribe(java.util.Collections.singletonList("input-topic"));

        // MQTT client
        MqttClient mqttClient;
        try {
            mqttClient = MqttClient.createMqttv3Client(MQTT_BROKER, "data-ingestion-client");
            MqttConnectOptions connOpts = new MqttConnectOptions();
            connOpts.setCleanSession(true);
            connOpts.setSSLConnectionSocketFactory(createSSLSocketFactory());
            mqttClient.connect(connOpts);
            mqttClient.subscribe("mqtt/topic", new MqttCallback() {
                @Override
                public void connectionLost(Throwable cause) {}

                @Override
                public void messageArrived(String topic, MqttMessage message) throws Exception {
                    executor.submit(() -> processMessage(topic, message));
                }

                @Override
                public void deliveryComplete(IMqttDeliveryToken token) {}
            });
        } catch (Exception e) {
            e.printStackTrace();
        }

        // HTTP client
        try {
            URL url = new URL(HTTP_API_URL);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder content = new StringBuilder();
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();
            executor.submit(() -> processHttpData(content.toString()));
        } catch (Exception e) {
            e.printStackTrace();
        }

        // Kafka consumer loop
        while (true) {
            ConsumerRecords<String, String> records = kafkaConsumer.poll(100);
            for (ConsumerRecord<String, String> record : records) {
                executor.submit(() -> processMessage(record.topic(), new MqttMessage(record.value().getBytes())));
            }
        }
    }

    private static void processMessage(String topic, MqttMessage message) {
        // Process the message
        System.out.println("Received message from " + topic + ": " + new String(message.getPayload()));
    }

    private static void processHttpData(String data) {
        // Process the HTTP data
