    unsigned char key[8];
} DesKey;

typedef struct {
    unsigned char iv[8];
} DesIv;

int des_encrypt(unsigned char *plaintext, size_t plaintext_len, const DesKey *key, const DesIv *iv, EncryptionMode mode, unsigned char *ciphertext);
int des_decrypt(unsigned char *ciphertext, size_t ciphertext_len, const DesKey *key, const DesIv *iv, EncryptionMode mode, unsigned char *plaintext);

