// des.c
#include "des.h"
#include <string.h>
#include <openssl/evp.h>

int des_encrypt(unsigned char *plaintext, size_t plaintext_len, const DesKey *key, const DesIv *iv, EncryptionMode mode, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len, ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    switch (mode) {
        case ECB:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_des_cbc(), NULL, key->key, iv->iv))
                goto error;
            break;
        // Add cases for EDE, EDE3, and CFB modes
        default:
            EVP_CIPHER_CTX_free(ctx);
            return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        goto error;

    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        goto error;

    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;

error:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

