    req->data = (void *)ciphertext_len;
}

void encrypt_after(uv_work_t *req, int status) {
    void (*callback)(unsigned char *, size_t) = (void (*)(unsigned char *, size_t))req->data;
    free(req);

    // Call callback with ciphertext and length
}

