public class ParallelDataProcessor extends RecursiveTask<List<Object>> {
    private List<Map<String, Object>> dataChunks;

    public ParallelDataProcessor(List<Map<String, Object>> dataChunks) {
        this.dataChunks = dataChunks;
    }

    @Override
    protected List<Object> compute() {
        if (dataChunks.size() <= 1000) {
            return processData(dataChunks);
        } else {
            int mid = dataChunks.size() / 2;
            ParallelDataProcessor leftTask = new ParallelDataProcessor(dataChunks.subList(0, mid));
            ParallelDataProcessor rightTask = new ParallelDataProcessor(dataChunks.subList(mid, dataChunks.size()));
            invokeAll(leftTask, rightTask);
            List<Object> results = new ArrayList<>();
            results.addAll(leftTask.join());
            results.addAll(rightTask.join());
            return results;
        }
    }

