import os
import logging
import json
from concurrent.futures import ThreadPoolExecutor
from docx2txt import process as docx_to_txt
from pdfminer.high_level import extract_text as pdf_to_txt
from xlsx2csv import XLSXConverter

class DocumentConverter:
    def __init__(self, config):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self.executor = ThreadPoolExecutor(max_workers=config.get('max_workers', 5))

    def convert_document(self, file_path):
        _, ext = os.path.splitext(file_path)
        if ext == '.pdf':
            return pdf_to_txt(file_path)
        elif ext == '.docx':
            return docx_to_txt(file_path)
        elif ext == '.xlsx':
            converter = XLSXConverter(file_path, output_dir=self.config['output_directory'])
            converter.convert()
            with open(converter.output_files[0], 'r', encoding='utf-8') as f:
                return f.read()
        else:
            raise ValueError(f"Unsupported document format: {ext}")

    def process_documents(self, file_paths):
        results = []
        for file_path in file_paths:
            future = self.executor.submit(self.convert_document, file_path)
            results.append(future)
        for result in results:
            try:
                text = result.result()
                output_path = os.path.join(self.config['output_directory'], f"{os.path.basename(file_path)}.txt")
                with open(output_path, 'w', encoding='utf-8') as f:
                    f.write(text)
                self.logger.info(f"Converted {file_path} to {output_path}")
            except Exception as e:
                self.logger.error(f"Failed to convert {file_path}: {e}", exc_info=True)

if __name__ == "__main__":
    config = {
        'max_workers': 5,
        'output_directory': './converted_docs',
        # Add other configurable settings here
    }

    converter = DocumentConverter(config)
    file_paths = ['document1.pdf', 'document2.docx', 'document3.xlsx']  # Replace with actual file paths
    converter.process_documents(file_paths)
