#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <openssl/aes.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

#define KEY_SIZE 32
#define IV_SIZE 12
#define SALT_SIZE 16
#define PBKDF2_ITERATIONS 30000
#define MAX_ERROR_LEN 256

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} EncryptionKey;

int derive_key(const char *password, size_t password_len, const unsigned char *salt, size_t salt_len, unsigned char *key) {
    return PKCS5_PBKDF2_HMAC_SHA256(password, password_len, salt, salt_len, PBKDF2_ITERATIONS, KEY_SIZE, key);
}

int encrypt(const unsigned char *plaintext, int plaintext_len, const EncryptionKey *encryption_key, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, encryption_key->key, encryption_key->iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len = len;

    unsigned char tag[16];
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;
    memcpy(ciphertext + plaintext_len, tag, 16);

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

int decrypt(const unsigned char *ciphertext, int ciphertext_len, const EncryptionKey *encryption_key, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;

    if (!(ctx = EVP_CIPHER_CTX_new()))
        return -1;

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, encryption_key->key, encryption_key->iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len - 16)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len = len;

    unsigned char tag[16];
    memcpy(tag, ciphertext + ciphertext_len - 16, 16);

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, tag)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

void cleanup_encryption_key(EncryptionKey *encryption_key) {
    memset(encryption_key->key, 0, KEY_SIZE);
    memset(encryption_key->iv, 0, IV_SIZE);
}

int main() {
    unsigned char password[] = "password";
    unsigned char salt[SALT_SIZE];
    if (!RAND_bytes(salt, SALT_SIZE)) {
        fprintf(stderr, "Failed to generate random salt\n");
        return -1;
    }

    EncryptionKey encryption_key;
    if (derive_key(password, strlen((char *)password), salt, SALT_SIZE, encryption_key.key) != 0) {
        fprintf(stderr, "Failed to derive key\n");
        return -1;
    }
    if (!RAND_bytes(encryption_key.iv, IV_SIZE)) {
        fprintf(stderr, "Failed to generate random IV\n");
        cleanup_encryption_key(&encryption_key);
        return -1;
    }

    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_gcm())];
    int encrypted_len = encrypt(plaintext, strlen((char *)plaintext), &encryption_key, ciphertext);

    if (encrypted_len < 0) {
        fprintf(stderr, "Encryption failed\n");
        cleanup_encryption_key(&encryption_key);
        return -1;
    }

    unsigned char decrypted_text[encrypted_len];
    int decrypted_len = decrypt(ciphertext, encrypted_len, &encryption_key, decrypted_text);

    if (decrypted_len < 0) {
        fprintf(stderr, "Decryption failed\n");
        cleanup_encryption_key(&encryption_key);
        return -1;
    }

    decrypted_text[decrypted_len] = '\0';
    printf("Decrypted text: %s\n", decrypted_text);

    cleanup_encryption_key(&encryption_key);
    return 0;
}
