import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DistributedCache {
    private ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private ScheduledExecutorService cleaner = Executors.newScheduledThreadPool(1);

    public DistributedCache(long ttlMillis) {
        cleaner.scheduleAtFixedRate(this::cleanupExpiredEntries, ttlMillis, ttlMillis, TimeUnit.MILLISECONDS);
    }

    public void put(String key, Object value, long ttlMillis) {
        cache.put(key, new CacheEntry(value, System.currentTimeMillis() + ttlMillis));
    }

    public Object get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && entry.isExpired()) {
            cache.remove(key);
            return null;
        }
        return entry.getValue();
    }

    private void cleanupExpiredEntries() {
        for (String key : cache.keySet()) {
            if (cache.get(key).isExpired()) {
                cache.remove(key);
            }
        }
    }

    private static class CacheEntry {
        private final Object value;
        private final long expiryTime;

        public CacheEntry(Object value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }

        public Object getValue() {
            return value;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expiryTime;
        }
    }
}
