#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define KEY_SIZE 32
#define IV_SIZE 12
#define PBKDF2_ITERATIONS 30000
#define ENCRYPTION_ALGORITHM EVP_aes_256_gcm

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
} EncryptionKey;

EncryptionKey derive_key(const char *password, size_t password_len) {
    EncryptionKey key;
    if (!PKCS5_PBKDF2_HMAC(password, password_len, NULL, 0, PBKDF2_ITERATIONS,
                            EVP_sha256(), KEY_SIZE, key.key)) {
        fprintf(stderr, "Failed to derive key.\n");
        exit(EXIT_FAILURE);
    }
    // Derive IV using a secure random method
    if (!RAND_bytes(key.iv, IV_SIZE)) {
        fprintf(stderr, "Failed to generate IV.\n");
        exit(EXIT_FAILURE);
    }
    return key;
}

int encrypt(const unsigned char *plaintext, size_t plaintext_len,
            const EncryptionKey *key, unsigned char **ciphertext,
            unsigned long long *ciphertext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context.\n");
        return 0;
    }
    if (1 != EVP_EncryptInit_ex(ctx, ENCRYPTION_ALGORITHM, NULL, key->key, key->iv)) {
        fprintf(stderr, "Failed to initialize encryption.\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    *ciphertext_len = plaintext_len + EVP_CIPHER_get_iv_length(ENCRYPTION_ALGORITHM) +
                      EVP_CIPHER_get_block_size(ENCRYPTION_ALGORITHM);
    *ciphertext = (unsigned char *)OPENSSL_malloc(*ciphertext_len);
    if (!*ciphertext) {
        fprintf(stderr, "Failed to allocate memory for ciphertext.\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    size_t len;
    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption update failed.\n");
        OPENSSL_free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    size_t ciphertext_padding = *ciphertext_len - (len + EVP_CIPHER_get_iv_length(ENCRYPTION_ALGORITHM));
    unsigned char tag[EVP_CIPHER_get_tag_length(ENCRYPTION_ALGORITHM)];
    if (!EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) {
        fprintf(stderr, "Encryption final failed.\n");
        OPENSSL_free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }
    memcpy((*ciphertext) + len + ciphertext_padding, tag, EVP_CIPHER_get_tag_length(ENCRYPTION_ALGORITHM));
    *ciphertext_len = len + len + ciphertext_padding + EVP_CIPHER_get_tag_length(ENCRYPTION_ALGORITHM);
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

void cleanup(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
