#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int key;
    long offset;
    char* metadata;
} Record;

typedef struct record_collection {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

Record* create_record(int key, long offset, const char* metadata) {
    Record* rec = (Record*)malloc(sizeof(Record));
    rec->key = key;
    rec->offset = offset;
    rec->metadata = strdup(metadata);
    return rec;
}

void destroy_record(Record* rec) {
    free(rec->metadata);
    free(rec);
}

RecordCollection* create_collection(size_t initial_capacity) {
    RecordCollection* col = (RecordCollection*)malloc(sizeof(RecordCollection));
    col->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    col->capacity = initial_capacity;
    col->size = 0;
    pthread_mutex_init(&col->lock, NULL);
    return col;
}

void destroy_collection(RecordCollection* col) {
    for (size_t i = 0; i < col->size; ++i) {
        destroy_record(col->records[i]);
    }
    free(col->records);
    pthread_mutex_destroy(&col->lock);
    free(col);
}

int add_record(RecordCollection* col, int key, long offset, const char* metadata) {
    pthread_mutex_lock(&col->lock);
    if (col->size >= col->capacity) {
        Record** new_records = (Record**)realloc(col->records, 2 * col->capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&col->lock);
            return -1; // Memory allocation failed
        }
        col->records = new_records;
        col->capacity *= 2;
    }
    col->records[col->size++] = create_record(key, offset, metadata);
    pthread_mutex_unlock(&col->lock);
    return 0;
}

// Implement other functions for updating and querying the collection as needed

int main() {
    RecordCollection* col = create_collection(10);
    add_record(col, 1, 12345, "Initial data");
    // Continue with other operations...

    destroy_collection(col);
    return 0;
}
