class MyKafkaProducer {
public:
    MyKafkaProducer(const std::string& brokers, const std::string& topic) {
        producer_ = RdKafka::Producer::create(RdKafka::Conf::Create(&conf_));
        if (!producer_) {
            throw std::runtime_error("Failed to create Kafka producer");
        }
        std::unique_ptr<RdKafka::Topic> topic_obj(RdKafka::Topic::create(producer_, topic.c_str(), &topic_conf_, errstr_.c_str()));
        if (!topic_obj) {
            throw std::runtime_error("Failed to create Kafka topic: " + errstr_);
        }
        topic_ = std::move(topic_obj);
    }

    void produce(const std::string& message, const std::string& key = "") {
        RdKafka::ErrorCode resp = producer_->produce(
            topic_.get(), RdKafka::Topic::PARTITION_UA,
            RdKafka::Producer::RK_MSG_COPY, const_cast<char*>(message.c_str()), message.size(),
            key.empty() ? nullptr : key.c_str(), key.size(),
            0, 0, 0, nullptr);
        if (resp != RdKafka::ERR_NO_ERROR) {
            throw std::runtime_error("Produce failed: " + RdKafka::err2str(resp));
        }
    }

private:
    RdKafka::Conf conf_;
    RdKafka::TopicConf topic_conf_;
    std::string errstr_;
    RdKafka::Producer* producer_;
    std::unique_ptr<RdKafka::Topic> topic_;
};

int main() {
    MyKafkaProducer producer("localhost:9092", "my_topic");
    producer.produce("Hello, Kafka!");
    return 0;
}
