#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define event types
typedef enum {
    EVENT_TYPE_ERROR,
    EVENT_TYPE_WARNING,
    EVENT_TYPE_INFO
} EventType;

// Define metadata structure (example)
typedef struct {
    int data;
} Metadata;

// Event structure
typedef struct Event {
    time_t timestamp;
    EventType type;
    Metadata* metadata;
} Event;

// Custom event queue structure
typedef struct {
    Event** events;
    size_t front;
    size_t rear;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} EventQueue;

// Initialize the event queue
void init_event_queue(EventQueue* queue, size_t initial_capacity) {
    queue->events = (Event**)malloc(initial_capacity * sizeof(Event*));
    queue->front = 0;
    queue->rear = -1;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
}

// Enqueue an event
void enqueue_event(EventQueue* queue, Event* event) {
    pthread_mutex_lock(&queue->mutex);
    while ((queue->rear + 1) % queue->capacity == queue->front) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->events[queue->rear] = event;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

// Dequeue an event
Event* dequeue_event(EventQueue* queue) {
    Event* event = NULL;
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == (queue->rear + 1) % queue->capacity) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    if (queue->front != (queue->rear + 1) % queue->capacity) {
        event = queue->events[queue->front];
        queue->front = (queue->front + 1) % queue->capacity;
        pthread_cond_signal(&queue->not_full);
    }
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

// Example usage
int main() {
    EventQueue event_queue;
    init_event_queue(&event_queue, 100);

    // Simulate adding events
    for (int i = 0; i < 150; ++i) {
        Event* new_event = (Event*)malloc(sizeof(Event));
        new_event->timestamp = time(NULL);
        new_event->type = EVENT_TYPE_INFO;
        new_event->metadata = NULL;

        enqueue_event(&event_queue, new_event);
    }

    // Simulate processing events
    while (!is_empty(&event_queue)) {
        Event* event = dequeue_event(&event_queue);
        if (event != NULL) {
            process_event(event);
            free(event);
        }
    }

    destroy_event_queue(&event_queue);
    return 0;
}
