#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_QUEUE_SIZE 1024
#define MAX_MESSAGE_SIZE 1024

typedef struct {
    char data[MAX_MESSAGE_SIZE];
    int size;
} Message;

typedef struct {
    Message messages[MAX_QUEUE_SIZE];
    int head;
    int tail;
    int count;
} Queue;

Queue event_queue;

void init_queue(Queue *queue) {
    queue->head = 0;
    queue->tail = 0;
    queue->count = 0;
}

int enqueue(Queue *queue, Message message) {
    if (queue->count >= MAX_QUEUE_SIZE) {
        return -1; // Queue is full
    }
    memcpy(queue->messages[queue->tail].data, message.data, message.size);
    queue->messages[queue->tail].size = message.size;
    queue->tail = (queue->tail + 1) % MAX_QUEUE_SIZE;
    queue->count++;
    return 0;
}

int dequeue(Queue *queue, Message *message) {
    if (queue->count == 0) {
        return -1; // Queue is empty
    }
    memcpy(message->data, queue->messages[queue->head].data, queue->messages[queue->head].size);
    message->size = queue->messages[queue->head].size;
    queue->head = (queue->head + 1) % MAX_QUEUE_SIZE;
    queue->count--;
    return 0;
}

int main() {
    init_queue(&event_queue);

    Message event1;
    strcpy(event1.data, "{\"type\":\"click\", \"user_id\":123}");
    event1.size = strlen(event1.data);

