// Define a simple memory pool allocator structure
typedef struct {
    void *pool;
    size_t block_size;
    int free_count;
} MemoryPool;

// Initialize the memory pool
MemoryPool *init_memory_pool(size_t block_size, int num_blocks) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->free_count = num_blocks;
    mp->pool = malloc(block_size * num_blocks);
    return mp;
}

// Allocate memory from the pool
void *allocate_from_pool(MemoryPool *mp) {
    if (mp->free_count <= 0) {
        printf("Memory pool is full\n");
        return NULL;
    }
    void *block = (char *)mp->pool + (mp->free_count - 1) * mp->block_size;
    mp->free_count--;
    return block;
}

// Free memory back to the pool
void free_to_pool(MemoryPool *mp, void *block) {
    int index = ((char *)block - (char *)mp->pool) / mp->block_size;
    if (index >= mp->free_count || index < 0) {
        printf("Invalid block\n");
        return;
    }
    mp->free_count++;
}

