#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>

// Define a basic message structure
struct Message {
    std::string content;
};

// Thread-safe queue implementation
class ThreadSafeQueue {
private:
    mutable std::mutex mtx;
    std::condition_variable cv;
    std::queue<Message> q;

public:
    void push(Message msg) {
        std::lock_guard<std::mutex> lock(mtx);
        q.push(msg);
        cv.notify_one();
    }

    Message pop() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]{ return !q.empty(); });
        Message msg = q.front();
        q.pop();
        return msg;
    }
};

// Worker thread function
void worker(ThreadSafeQueue& queue) {
    while (true) {
        auto msg = queue.pop();
        // Process the message
        std::cout << "Processing: " << msg.content << std::endl;
    }
}

int main() {
    const int num_workers = 5;
    ThreadSafeQueue queue;

    // Create worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < num_workers; ++i) {
        workers.emplace_back(worker, std::ref(queue));
    }

    // Simulate message production
    for (int i = 0; i < 10; ++i) {
        Message msg = {"Message " + std::to_string(i)};
        queue.push(msg);
    }

    // Join worker threads
    for (auto& w : workers) {
        w.join();
    }

    return 0;
}
