// Define message structure for RabbitMQ
typedef struct {
    char* data;
    int criticality;
} Message;

// Define worker function prototype
void* worker_function(void* arg);

// Global variables
Message** queue; // Message queue
int front, rear, size; // Queue pointers and size
pthread_mutex_t queue_lock; // Mutex for thread-safe operations on the queue
int worker_count; // Number of worker threads

// Initialize message queue
void init_queue(int max_size) {
    size = max_size;
    queue = (Message**)malloc(size * sizeof(Message*));
    front = rear = -1;
    pthread_mutex_init(&queue_lock, NULL);
}

// Add a message to the queue
void enqueue(Message* msg) {
    pthread_mutex_lock(&queue_lock);
    if ((rear + 1) % size == front)
        printf("Queue is full\n");
    else {
        if (front == -1)
            front = rear = 0;
        else
            rear = (rear + 1) % size;
        queue[rear] = msg;
    }
    pthread_mutex_unlock(&queue_lock);
}

// Remove a message from the queue
Message* dequeue() {
    Message* msg = NULL;
    pthread_mutex_lock(&queue_lock);
    if (front == -1)
        printf("Queue is empty\n");
    else {
        msg = queue[front];
        if (front == rear) {
            front = rear = -1;
        } else
            front = (front + 1) % size;
    }
    pthread_mutex_unlock(&queue_lock);
    return msg;
}

// Worker thread function
void* worker_function(void* arg) {
    while (1) {
        Message* msg = dequeue();
        if (msg != NULL) {
            // Process message
            printf("Processing message with criticality %d\n", msg->criticality);
            free(msg); // Free allocated memory for the message
        }
        usleep(1000); // Simulate processing time
    }
}

// Initialize worker threads
void init_workers(int num_threads) {
    worker_count = num_threads;
    pthread_t* workers = (pthread_t*)malloc(worker_count * sizeof(pthread_t));
    for (int i = 0; i < worker_count; i++) {
        pthread_create(&workers[i], NULL, worker_function, NULL);
    }
}

// Clean up resources
void cleanup() {
    free(queue);
    pthread_mutex_destroy(&queue_lock);
}

int main(int argc, char* argv[]) {
    int queue_size = 100;
    int num_workers = 4;

    init_queue(queue_size);
    init_workers(num_workers);

    // Simulate message production
    for (int i = 0; i < 200; i++) {
        Message* msg = (Message*)malloc(sizeof(Message));
        msg->data = (char*)malloc(100 * sizeof(char));
        sprintf(msg->data, "Message %d", i);
        msg->criticality = rand() % 3 + 1;
        enqueue(msg);
    }

    // Wait for workers to finish
    pthread_exit(NULL);

    cleanup();
    return 0;
}
