    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray *array) {
    free(array->reports);
    free(array);
}

void dynamic_array_add_report(DynamicArray *array, CellMeasurementReport report) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        array->reports = (CellMeasurementReport*)realloc(array->reports, new_capacity * sizeof(CellMeasurementReport));
        array->capacity = new_capacity;
    }
    array->reports[array->size++] = report;
    pthread_mutex_unlock(&array->lock);
}

void dynamic_array_update_report(DynamicArray *array, size_t index, CellMeasurementReport report) {
    if (index < array->size) {
        pthread_mutex_lock(&array->lock);
        array->reports[index] = report;
        pthread_mutex_unlock(&array->lock);
    } else {
        fprintf(stderr, "Index out of bounds\n");
    }
}

CellMeasurementReport* dynamic_array_get_report(DynamicArray *array, size_t index) {
    if (index < array->size) {
        return &array->reports[index];
    } else {
        fprintf(stderr, "Index out of bounds\n");
        return NULL;
    }
}

void dynamic_array_log(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        printf("Report %zu: Signal Strength=%d, Frequency=%d, Timing Advance=%d\n",
               i, array->reports[i].cells[0].signal_strength,
               array->reports[i].cells[0].frequency,
               array->reports[i].cells[0].timing_advance);
    }
    pthread_mutex_unlock(&array->lock);
}
