    void fetchData(const std::string& region, std::promise<std::vector<double>>& result) {
        // Simulate data fetching with a delay
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        result.set_value({45.2, 60.3, 5.1}); // Temperature, Humidity, Pollution levels
    }
};

class CloudStorageClient {
public:
    void storeData(const std::string& region, const std::vector<double>& data) {
        // Simulate data storage with a delay
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
};

// Worker thread function to process data
void workerThread(int id, ExternalAPIClient& apiClient, CloudStorageClient& storageClient, std::queue<std::string>& regionsQueue, std::mutex& queueMutex, std::condition_variable& condVar, std::atomic<bool>& running) {
    while (running || !regionsQueue.empty()) {
        std::unique_lock<std::mutex> lock(queueMutex);
        condVar.wait(lock, [&]{ return !running && !regionsQueue.empty() || regionsQueue.empty(); });

        if (!regionsQueue.empty()) {
            std::string region = regionsQueue.front();
            regionsQueue.pop();

            lock.unlock();

            std::promise<std::vector<double>> resultPromise;
            std::future<std::vector<double>> resultFuture = resultPromise.get_future();

            // Fetch data from external API
            apiClient.fetchData(region, resultPromise);

            std::vector<double> data = resultFuture.get();
            storageClient.storeData(region, data);
        }
    }
}

int main() {
    ExternalAPIClient apiClient;
    CloudStorageClient storageClient;

    const int numWorkers = 5;
    std::queue<std::string> regionsQueue;
    std::mutex queueMutex;
    std::condition_variable condVar;
    std::atomic<bool> running(true);

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < numWorkers; ++i) {
        workers.emplace_back(workerThread, i, std::ref(apiClient), std::ref(storageClient), std::ref(regionsQueue), std::ref(queueMutex), std::ref(condVar), std::ref(running));
    }

    // Simulate adding regions to the queue
    for (int i = 0; i < 10; ++i) {
        regionsQueue.push("Region" + std::to_string(i));
        condVar.notify_one();
    }

    // Stop worker threads
    running.store(false);
    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
