class DataProcessor {
public:
    void processData(const std::string& data) {
        // Process geospatial data here
        std::cout << "Processing data: " << data << std::endl;
    }
};

class DistributedSystem {
private:
    DataProcessor processor;
    std::vector<std::thread> workers;
    std::queue<std::string> dataQueue;
    std::mutex queueMutex;
    std::condition_variable dataCondition;
    std::atomic<bool> running{true};
    int workerCount;

public:
    DistributedSystem(int numWorkers) : workerCount(numWorkers) {
        for (int i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&DistributedSystem::workerThread, this);
        }
    }

    ~DistributedSystem() {
        running.store(false);
        dataCondition.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void enqueueData(const std::string& data) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(data);
        dataCondition.notify_one();
    }

private:
    void workerThread() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            dataCondition.wait(lock, [this] { return !dataQueue.empty() || !running.load(); });

            if (!dataQueue.empty()) {
                std::string data = dataQueue.front();
                dataQueue.pop();
                lock.unlock();

                processor.processData(data);
            }
        }
    }
};

int main() {
    DistributedSystem system(4);

    // Simulate incoming data
    for (int i = 0; i < 100; ++i) {
        std::string data = "DataPoint" + std::to_string(i);
        system.enqueueData(data);
    }

    return 0;
}
