['```rust
use std::process::{Command, Stdio};
use std::time::Instant;
use libc::{getrusage, RUSAGE_SELF, struct_rusage, RLIMIT_AS};
use rustc_driver::{catch_with_exit_code, early_error};
use rustc_interface::{interface, Compiler};

fn get_resident_set_size() -> u64 {
    let mut usage = std::mem::zeroed();
    if unsafe { getrusage(RUSAGE_SELF, &mut usage) } == 0 {
        usage.ru_maxrss as u64
    } else {
        0
    }
}

fn run_rustc_with_logging() -> i32 {
    let start_time = Instant::now();
    let initial_memory = get_resident_set_size();

    let mut child = Command::new("rustc")
        .args(&["src/main.rs"])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to spawn rustc");

    let status = catch_with_exit_code(|| {
        interface::run_compiler(
            &interface::default_config(),
            |compiler| compiler.parse_input(interface::Input::File),
            |queries| queries.compile(),
        );
    });

    if !child.wait().unwrap().success() {
        early_error(early_diagnostic::ErrorLevel::Fatal, "Compilation failed");
    }

    let end_time = Instant::now();
    let final_memory = get_resident_set_size();

    println!("Compilation took: {:?}", end_time.duration_since(start_time));
    println!("Initial memory usage: {} KB", initial_memory);
    println!("Final memory usage: {} KB", final_memory);

    status
}
