```cpp
#include <iostream>
#include <unordered_map>
#include <list>
#include <future>
#include <mutex>

template<typename K, typename V>
class Cache {
public:
    struct CacheItem {
        K key;
        V value;
        std::chrono::time_point<std::chrono::system_clock> expireTime;
        int priority;

        CacheItem(K k, V v, std::chrono::time_point<std::chrono::system_clock> exp, int p) : 
            key(k), value(v), expireTime(exp), priority(p) {}
    };

    void set(const K& key, const V& value, std::chrono::time_point<std::chrono::system_clock> expire, int priority) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = CacheItem(key, value, expire, priority);
        updateLRU(key);
    }

    std::optional<V> get(const K& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (cache_.find(key) != cache_.end()) {
            CacheItem& item = cache_[key];
            if (std::chrono::system_clock::now() < item.expireTime) {
                updateLRU(key);
                return item.value;
            } else {
                cache_.erase(key);
            }
        }
        return std::nullopt;
    }

private:
    void updateLRU(const K& key) {
        auto it = lruList_.find(key);
        if (it != lruList_.end()) {
            lruList_.erase(it);
        }
        lruList_.push_back(key);
    }

    std::unordered_map<K, CacheItem> cache_;
    std::list<K> lruList_;
    mutable std::mutex mutex_;
};

int main() {
    Cache<int, std::string> myCache;
    auto now = std::chrono::system_clock::now();
    auto expireTime = now + std::chrono::seconds(10);

    myCache.set(1, "Value1", expireTime, 1);
    std::optional<std::string> result = myCache.get(1);
    if (result) {
        std::cout << "Retrieved: " << *result << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    return 0;
}
