### PHP Function for User Account Management

```php
<?php

class UserManager {
    private $db;
    private $logger;

    public function __construct($db, $logger) {
        $this->db = $db;
        $this->logger = $logger;
    }

    public function createUser($user) {
        try {
            $stmt = $this->db->prepare("INSERT INTO users (username, email, password) VALUES (:username, :email, :password)");
            $stmt->execute([
                'username' => $user['username'],
                'email' => $user['email'],
                'password' => password_hash($user['password'], PASSWORD_DEFAULT)
            ]);
            return $this->db->lastInsertId();
        } catch (PDOException $e) {
            $this->logger->error("Error creating user: " . $e->getMessage());
            throw new Exception("Failed to create user");
        }
    }

    public function updateUser($userId, $user) {
        try {
            $stmt = $this->db->prepare("UPDATE users SET username=:username, email=:email WHERE id=:id");
            $stmt->execute([
                'id' => $userId,
                'username' => $user['username'],
                'email' => $user['email']
            ]);
        } catch (PDOException $e) {
            $this->logger->error("Error updating user: " . $e->getMessage());
            throw new Exception("Failed to update user");
        }
    }

    public function deleteUser($userId) {
        try {
            $stmt = $this->db->prepare("DELETE FROM users WHERE id=:id");
            $stmt->execute(['id' => $userId]);
        } catch (PDOException $e) {
            $this->logger->error("Error deleting user: " . $e->getMessage());
            throw new Exception("Failed to delete user");
        }
    }

    public function getUser($userId) {
        try {
            $stmt = $this->db->prepare("SELECT * FROM users WHERE id=:id");
            $stmt->execute(['id' => $userId]);
            return $stmt->fetch(PDO::FETCH_ASSOC);
        } catch (PDOException $e) {
            $this->logger->error("Error getting user: " . $e->getMessage());
            throw new Exception("Failed to get user");
        }
    }
}

?>
```

