['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_CONNECTIONS 1000
#define TIMEOUT_SECONDS 30

typedef struct {
    int id;
    char remote_ip[16];
    char local_ip[16];
    int remote_port;
    int local_port;
    time_t last_activity;
} TCPConnection;

TCPConnection connections[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t connection_lock;
struct timeval activity_timeout;

void initialize_service() {
    pthread_mutex_init(&connection_lock, NULL);
    gettimeofday(&activity_timeout, NULL);
    activity_timeout.tv_sec += TIMEOUT_SECONDS;
}

int add_connection(int id, char* remote_ip, char* local_ip, int remote_port, int local_port) {
    pthread_mutex_lock(&connection_lock);
    if (connection_count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&connection_lock);
        return -1; // Connection pool full
    }
    connections[connection_count].id = id;
    strcpy(connections[connection_count].remote_ip, remote_ip);
    strcpy(connections[connection_count].local_ip, local_ip);
    connections[connection_count].remote_port = remote_port;
    connections[connection_count].local_port = local_port;
    gettimeofday(&connections[connection_count].last_activity, NULL);
    connection_count++;
    pthread_mutex_unlock(&connection_lock);
    return 0;
}

int update_connection(int id, char* remote_ip, char* local_ip, int remote_port, int local_port) {
    pthread_mutex_lock(&connection_lock);
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].id == id) {
            strcpy(connections[i].remote_ip, remote_ip);
            strcpy(connections[i].local_ip, local_ip);
            connections[i].remote_port = remote_port;
            connections[i].local_port = local_port;
            gettimeofday(&connections[i].last_activity, NULL);
            pthread_mutex_unlock(&connection_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&connection_lock);
    return -1; // Connection not found
}

TCPConnection* get_connection(int id) {
    pthread_mutex_lock(&connection_lock);
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].id == id) {
            TCPConnection* conn = &connections[i];
            gettimeofday(&conn->last_activity, NULL); // Refresh activity time
            pthread_mutex_unlock(&connection_lock);
            return conn;
        }
    }
    pthread_mutex_unlock(&connection_lock);
    return NULL; // Connection not found
}

void cleanup_connections() {
    struct timeval current_time;
    pthread_mutex_lock(&connection_lock);
    gettimeofday(&current_time, NULL);
    for (int i = connection_count - 1; i >= 0; i--) {
        if (timercmp(&current_time, &connections[i].last_activity, >)) {
            memmove(&connections[i], &connections[i + 1], sizeof(TCPConnection) * (connection_count - i - 1));
            connection_count--;
            i--; // Adjust index after removal
        }
    }
    pthread_mutex_unlock(&connection_lock);
}

void* monitor_connections(void* arg) {
    while (1) {
        cleanup_connections();
        sleep(1); // Check every second
    }
    return NULL;
}

int main() {
    initialize_service();
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_connections, NULL);

    add_connection(1, "192.168.1.1", "10.0.0.1", 12345, 54321);
    TCPConnection* conn = get_connection(1);
    if (conn != NULL) {
        printf("Connection found: ID=%d, Remote IP=%s\n", conn->id, conn->remote_ip);
    }

    pthread_join(monitor_thread, NULL);
    return 0;
}
