// Thread-safe queue for log entries
template <typename T>
class ThreadSafeQueue {
private:
    std::queue<T> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_;

public:
    void push(const T& item) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(item);
        cond_.notify_one();
    }

    bool try_pop(T& item, std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cond_.wait_for(lock, timeout, [this]{ return !queue_.empty(); })) {
            item = queue_.front();
            queue_.pop();
            return true;
        }
        return false;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }
};

class LogProcessor {
private:
    std::vector<std::unique_ptr<LogFormat>> formats_;
    std::vector<std::unique_ptr<ExternalSystemAdapter>> externalSystems_;
    ThreadSafeQueue<LogEntry> logQueue_;
    std::atomic<bool> running_;

