// Define the Event interface
public interface Event {
    String getType();
    Object getData();
}

// Implement a concrete event class
public class UserRegistrationEvent implements Event {
    private String userId;
    private String email;

    public UserRegistrationEvent(String userId, String email) {
        this.userId = userId;
        this.email = email;
    }

    @Override
    public String getType() {
        return "USER_REGISTRATION";
    }

    @Override
    public Object getData() {
        return new HashMap<String, String>() {{
            put("userId", userId);
            put("email", email);
        }};
    }
}

// Define the EventListener interface
public interface EventListener {
    void onEvent(Event event);
}

// Implement a concrete event listener
public class UserNotificationListener implements EventListener {
    @Override
    public void onEvent(Event event) {
        if (event.getType().equals("USER_REGISTRATION")) {
            System.out.println("Sending welcome email to: " + ((Map<String, String>) event.getData()).get("email"));
        }
    }
}

// Define the EventBus class
public class EventBus {
    private Map<Class<? extends Event>, List<EventListener>> listeners = new ConcurrentHashMap<>();

    public void subscribe(Class<? extends Event> eventType, EventListener listener) {
        listeners.computeIfAbsent(eventType, k -> new CopyOnWriteArrayList<>()).add(listener);
    }

    public void publish(Event event) {
        Class<? extends Event> eventType = event.getClass();
        List<EventListener> eventListeners = listeners.get(eventType);
        if (eventListeners != null) {
            for (EventListener listener : eventListeners) {
                listener.onEvent(event);
            }
        }
    }
}

// Implement a simple messaging broker using RabbitMQ
public class RabbitMqBroker {
    private ConnectionFactory factory;

    public RabbitMqBroker(String host, int port, String username, String password) {
        factory = new ConnectionFactory();
        factory.setHost(host);
        factory.setPort(port);
        factory.setUsername(username);
        factory.setPassword(password);
    }

    public void publishMessage(String exchange, String routingKey, Event message) throws IOException, TimeoutException {
        try (Connection connection = factory.newConnection()) {
            Channel channel = connection.createChannel();
            channel.exchangeDeclare(exchange, "direct");
            channel.basicPublish(exchange, routingKey, null, serialize(message));
        }
    }

    public void consumeMessages(String exchange, String routingKey, EventListener listener) throws IOException, TimeoutException {
        try (Connection connection = factory.newConnection()) {
            Channel channel = connection.createChannel();
            channel.exchangeDeclare(exchange, "direct");
            Queue queue = channel.queueDeclare().getQueue();
            channel.queueBind(queue.getName(), exchange, routingKey);

            DeliverCallback deliverCallback = (consumerTag, delivery) -> {
                Event event = deserialize(delivery.getBody());
                listener.onEvent(event);
            };
            channel.basicConsume(queue.getName(), true, deliverCallback, consumerTag -> { });
        }
    }

    private byte[] serialize(Event message) throws IOException {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject(message);
            return bos.toByteArray();
        }
    }

    private Event deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return (Event) ois.readObject();
        }
    }
}

// Main class to demonstrate the system
public class MessagingSystemDemo {
    public static void main(String[] args) throws Exception {
        EventBus eventBus = new EventBus();
        RabbitMqBroker rabbitMqBroker = new RabbitMqBroker("localhost", 5672, "guest", "guest");

        // Subscribe to user registration events
        UserNotificationListener listener = new UserNotificationListener();
        eventBus.subscribe(UserRegistrationEvent.class, listener);

        // Consume user registration events from RabbitMQ
        rabbitMqBroker.consumeMessages("user_exchange", "registration_routing_key", listener);

        // Publish a user registration event
        Event userRegistrationEvent = new UserRegistrationEvent("12345", "john.doe@example.com");
        rabbitMqBroker.publishMessage("user_exchange", "registration_routing_key", userRegistrationEvent);
    }
}
```

This code provides a basic structure for an event-driven messaging system in Java. It includes interfaces for events and listeners, an EventBus to manage subscriptions and publishing of events, and a RabbitMQ broker for message transport and storage. The system demonstrates how to serialize and deserialize events, subscribe to events, and publish messages asynchronously using a messaging broker.

Note that this is a simplified example and does not cover all aspects of the requirements, such as acknowledgment mechanisms, retry policies, dead-letter queues, dynamic scaling, resilience against failures, monitoring, or handling varying message formats. You will need to expand upon this foundation to create a fully functional and resilient system.']

