async fn load_config(url: &str) -> Result<Config, Box<dyn std::error::Error>> {
    // Implement logic to fetch and parse JSON configuration from the URL
    let config_string = reqwest::get(url).await?.text().await?;
    serde_json::from_str(&config_string)
