async fn run_server(config: Config, shutdown_tx: mpsc::Sender<()>) -> Result<(), Box<dyn std::error::Error>> {
    let addr = SocketAddr::from(([0, 0, 0, 0], config.port));
    let listener = TcpListener::bind(&addr).await?;
    info!("Server listening on {}", addr);

    let (tx, mut rx) = mpsc::channel(32);
    tokio::spawn(async move {
        while let Some(request) = rx.recv().await {
            // Handle request
        }
    });

    loop {
        tokio::select! {
            result = listener.accept() => {
                if let Ok((socket, _)) = result {
                    tx.send(socket).await.expect("Failed to send socket");
                }
            },
            shutdown = rx.recv() => {
                info!("Server shutting down");
                break;
            },
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config_url = "http://example.com/config.json";
