// Function to simulate external service call
bool validateMetadata(const std::string& entry, const std::string& key) {
    // Simulate a network delay
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    return true; // Always succeed for demonstration purposes
}

void secureInsertOrLog(std::forward_list<std::string>& metadata, 
                        const std::string& target, 
                        const std::string& insert) {
    auto pred = [&target](const std::string& entry) { return entry == target; };
    if (metadata.empty() || !std::find_if(metadata.begin(), metadata.end(), pred)) {
        // Target not found, append to the end
        metadata.push_front(insert);
        return;
    }

    auto pos = std::find_if(metadata.begin(), metadata.end(), pred);
    if (pos == metadata.end()) {
        // Target not found, append to the end
        metadata.push_front(insert);
        return;
    }

    try {
        for (int i = 0; i < 3; ++i) {
            std::string key = "salted_key"; // Generate a salted key
            if (validateMetadata(*pos, key)) {
                pos = metadata.insert_after(pos, insert);
                return;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * i));
        }
    } catch (...) {
        std::cerr << "Error: Failed to insert entry due to unexpected error at "
                  << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now())
                  << ". Entry: " << target
                  << ", Error: " << std::current_exception() << std::endl;
    }
}

int main() {
    std::forward_list<std::string> metadata = {"entry1", "entry2", "target"};
    secureInsertOrLog(metadata, "target", "new_entry");
    for (const auto& entry : metadata) {
        std::cout << entry << std::endl;
    }
    return 0;
}
