import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;
import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;
import io.github.resilience4j.reactor.bulkhead.operator.BulkheadOperator;
import io.github.resilience4j.ratelimiter.RateLimiter;
import io.github.resilience4j.ratelimiter.RateLimiterConfig;
import io.github.resilience4j.ratelimiter.RateLimiterRegistry;
import io.github.resilience4j.retry.Retry;
import io.github.resilience4j.retry.RetryConfig;
import io.github.resilience4j.retry.RetryRegistry;
import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.gateway.route.builder.RouteLocatorBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import reactor.core.publisher.Mono;

@Configuration
public class ApiGatewayConfig {

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
            .route("serviceA", r -> r.path("/api/**")
                .filters(f -> f.rewritePath("^/api/(?<segment>.*$)", "/${segment}")
                    .circuitBreaker(c -> c.setName("serviceACircuitBreaker"))
                    .bulkhead(b -> b.setName("serviceABulkhead"))
                    .ratelimiter(r -> r.setName("serviceARateLimiter")))
                .uri("lb://serviceA"))
            .route("serviceB", r -> r.path("/api/**")
                .filters(f -> f.rewritePath("^/api/(?<segment>.*$)", "/${segment}")
                    .circuitBreaker(c -> c.setName("serviceBCircuitBreaker"))
                    .bulkhead(b -> b.setName("serviceBBulkhead"))
                    .ratelimiter(r -> r.setName("serviceBRateLimiter")))
                .uri("lb://serviceB"))
            .build();
    }

    @Bean
    public CircuitBreakerRegistry circuitBreakerRegistry() {
        CircuitBreakerConfig config = CircuitBreakerConfig.custom()
            .failureRateThreshold(50)
            .waitDurationInOpenState(Duration.ofSeconds(10))
            .permittedNumberOfCallsInHalfOpenState(3)
            .build();
        return CircuitBreakerRegistry.of(config);
    }

    @Bean
    public BulkheadRegistry bulkheadRegistry() {
        BulkheadConfig config = BulkheadConfig.custom()
            .maxConcurrentCalls(100)
            .maxWaitDuration(Duration.ofMillis(500))
            .build();
        return BulkheadRegistry.of(config);
    }

    @Bean
    public RateLimiterRegistry rateLimiterRegistry() {
        RateLimiterConfig config = RateLimiterConfig.custom()
            .limitForPeriod(100)
            .limitRefreshPeriod(Duration.ofSeconds(1))
            .timeoutDuration(Duration.ofMillis(500))
            .build();
        return RateLimiterRegistry.of(config);
    }

    @Bean
    public RetryRegistry retryRegistry() {
        RetryConfig config = RetryConfig.custom()
            .maxAttempts(3)
            .waitDuration(Duration.ofSeconds(1))
            .build();
        return RetryRegistry.of(config);
    }
}
```

This code snippet demonstrates how to configure a basic API gateway using Spring Cloud Gateway, incorporating resilience patterns such as Circuit Breaker, Bulkhead, Rate Limiter, and Retry. Each service route is configured with its respective circuit breaker, bulkhead, rate limiter, and retry policies.']

