// C# ASP.NET Core Application

using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Configuration;
using System.Threading.Tasks;

public class IdentityService : IIdentityService
{
    private readonly UserManager<IdentityUser> _userManager;
    private readonly SignInManager<IdentityUser> _signInManager;
    private readonly IConfiguration _configuration;

    public IdentityService(UserManager<IdentityUser> userManager, SignInManager<IdentityUser> signInManager, IConfiguration configuration)
    {
        _userManager = userManager;
        _signInManager = signInManager;
        _configuration = configuration;
    }

    public async Task RegisterAsync(string username, string password)
    {
        var user = new IdentityUser { UserName = username };
        var result = await _userManager.CreateAsync(user, password);
        if (!result.Succeeded)
        {
            throw new Exception("Registration failed.");
        }
    }

    public async Task<SignInResult> LoginAsync(string username, string password)
    {
        return await _signInManager.PasswordSignInAsync(username, password, isPersistent: false, lockoutOnFailure: true);
    }

    public async Task LockoutUserAsync(string userId)
    {
        await _userManager.SetLockoutEnabledAsync(userId, true);
        await _userManager.AccessFailedAsync(await _userManager.FindByIdAsync(userId));
    }
}
