// Rust HTTP Client

use reqwest::{Client, Error};
use tokio::net::TcpStream;

pub struct HttpClient {
    client: Client,
}

impl HttpClient {
    pub fn new() -> Self {
        HttpClient {
            client: Client::new(),
        }
    }

    pub async fn make_request(&self, url: &str) -> Result<String, Error> {
        let response = self.client.get(url).send().await?;
        if response.status().is_success() {
            response.text().await
        } else {
            Err(Error::new(std::io::ErrorKind::Other, "Failed to make request"))
        }
    }

    pub fn with_tls(&self, host: &str) -> Result<Client, Error> {
        let connector = hyper_rustls::HttpsConnectorBuilder::new()
            .with_native_certs()
            .build();
        Ok(Client::builder().build(connector)?)
    }
}
