# microservice.py
from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

@app.route('/process_document', methods=['POST'])
def process_document():
    data = request.json
    text = data.get('text')

    entities = extract_entities(text)
    geolocated_entities = geolocate_entities(entities)

    return jsonify(geolocated_entities)

def extract_entities(text):
    # Placeholder for entity extraction logic
    import re
    numeric_entities = re.findall(r'\d+', text)
    location_entities = re.findall(r'[A-Z][a-z]+, [A-Z]{2}', text)
    return numeric_entities + location_entities

def geolocate_entities(entities):
    geolocated = []
    for entity in entities:
        response = requests.get(f'https://api.geolocation.com/locate?query={entity}')
        if response.status_code == 200:
            geolocated.append(response.json())
        else:
            # Fallback mechanism
            geolocated.append({'entity': entity, 'location': 'Unknown'})
    return geolocated

if __name__ == '__main__':
    app.run(debug=True)
