// random_number_generator.cpp
#include <iostream>
#include <random>

namespace RandomGenerator {
    class MersenneTwisterGenerator {
    public:
        MersenneTwisterGenerator() : generator(std::random_device{}()) {}

        ~MersenneTwisterGenerator() = default;

        static std::mt19937& instance() {
            static MersenneTwisterGenerator instance;
            return instance.generator;
        }

        template<typename T>
        T generate(T min, T max) {
            std::uniform_int_distribution<T> distribution(min, max);
            return distribution(instance());
        }

    private:
        std::mt19937 generator;
    };
}

int main() {
    auto random_number = RandomGenerator::MersenneTwisterGenerator::instance().generate(0, 100);
    std::cout << "Random number: " << random_number << std::endl;
    return 0;
}
```

