angular.module('userDialogService', [])
.service('dialogService', ['$http', '$q', '$timeout', 'cryptoService', 'cacheService', function($http, $q, $timeout, cryptoService, cacheService) {
  var service = this;

  // Function to refresh dialog fields based on resource ID and URL
  service.refreshDialogFields = function(resourceId, url) {
    return cacheService.getFromCache(resourceId)
      .then(function(cachedData) {
        if (cachedData && isFresh(cachedData)) {
          return cachedData;
        } else {
          return $http.get(url)
            .then(function(response) {
              var data = response.data;
              cacheService.saveToCache(resourceId, data);
              return data;
            })
            .catch(function(error) {
              console.error('Failed to refresh dialog fields:', error);
              throw error;
            });
        }
      });
  };

  // Function to check if cached data is fresh
  function isFresh(cachedData) {
    var now = Date.now();
    return cachedData.timestamp + (10 * 60 * 1000) > now; // Fresh for 10 minutes
  }

  // Function to analyze updated field content for mentions of Old Testament books
  service.analyzeUpdatedField = function(fieldContent) {
    var regex = /(?:\b(?:genesis|exodus|leviticus|numbers|deuteronomy)\b)/i;
    return regex.test(fieldContent);
  };

  return service;
}]);

// Define the cryptoService for encryption and decryption
angular.module('cryptoModule', [])
.service('cryptoService', ['$q', function($q) {
  var service = this;

  // Function to encrypt data using AES-256-CBC
  service.encryptData = function(data, key, iv) {
    return $q.resolve(crypto.AES.encrypt(JSON.stringify(data), key, { iv: iv }).toString());
  };

  // Function to decrypt data using AES-256-CBC
  service.decryptData = function(encryptedData, key, iv) {
    var decrypted = crypto.AES.decrypt(encryptedData, key, { iv: iv });
    return $q.resolve(JSON.parse(decrypted.toString(crypto.enc.Utf8)));
  };

  return service;
}]);

// Define the cacheService for caching data
angular.module('cacheModule', [])
.service('cacheService', ['$q', function($q) {
  var service = this;

  // In-memory cache storage
  var cache = {};

  // Function to get data from cache
  service.getFromCache = function(resourceId) {
    return $q.resolve(cache[resourceId]);
  };

  // Function to save data to cache
  service.saveToCache = function(resourceId, data) {
    cache[resourceId] = {
      data: data,
      timestamp: Date.now()
    };
    return $q.resolve();
  };

  return service;
}]);

