class EncryptionService {
public:
    void encryptData(const std::string& data, const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        // Simulate encryption process
        encryptedData_.push_back(data + " encrypted with key: " + key);
    }

    std::vector<std::string> getEncryptedData() const {
        return encryptedData_;
    }

private:
    mutable std::mutex mutex_;
    std::vector<std::string> encryptedData_;
};

int main() {
    EncryptionService service;
    std::vector<std::thread> threads;

    // Simulate multiple encryption operations
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back([&service, i]() {
            service.encryptData("User Data " + std::to_string(i), "Key " + std::to_string(i));
        });
    }

    // Join all threads
    for (auto& thread : threads) {
        thread.join();
    }

    // Output encrypted data
    const auto& data = service.getEncryptedData();
    for (const auto& item : data) {
        std::cout << item << std::endl;
    }

    return 0;
}
