import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ServiceOrchestrator {

    private static final int MAX_INSTANCES = 10;
    private ExecutorService executorService;

    public void initialize() {
        executorService = Executors.newFixedThreadPool(MAX_INSTANCES);
    }

    public void startInstance(int instanceId) {
        executorService.submit(new InstanceRunner(instanceId));
    }

    public void shutdown() {
        if (!executorService.isShutdown()) {
            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                    executorService.shutdownNow();
                }
            } catch (InterruptedException e) {
                executorService.shutdownNow();
            }
        }
    }

    private class InstanceRunner implements Runnable {
        private final int instanceId;

        public InstanceRunner(int instanceId) {
            this.instanceId = instanceId;
        }

        @Override
        public void run() {
            connectToMonitoringSystem(instanceId);
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    sendHeartbeatMessage(instanceId);
                    Thread.sleep(getAdjustedHeartbeatInterval());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
            sendFinalStatusReport(instanceId);
            disconnectFromMonitoringSystem(instanceId);
        }

        private void connectToMonitoringSystem(int instanceId) {
            // Establish secure, persistent connection to monitoring system
        }

        private void sendHeartbeatMessage(int instanceId) {
            // Send heartbeat message with current system load and instance status
        }

        private long getAdjustedHeartbeatInterval() {
            // Dynamically adjust heartbeat interval based on system load
            return 5000; // Example: 5 seconds
        }

        private void sendFinalStatusReport(int instanceId) {
            // Send final status report upon shutdown
        }

        private void disconnectFromMonitoringSystem(int instanceId) {
            // Confirm disconnection from monitoring system
        }
    }

    public static void main(String[] args) {
        ServiceOrchestrator orchestrator = new ServiceOrchestrator();
        orchestrator.initialize();

        for (int i = 0; i < MAX_INSTANCES; i++) {
            orchestrator.startInstance(i);
        }

        // Simulate system shutdown
        try {
            Thread.sleep(60000); // Run for 1 minute
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        orchestrator.shutdown();
    }
}
