use actix_web::{web, App, HttpResponse, HttpServer};
use futures::future;
use log::{error, info};
use std::env;
use std::fs::File;
use std::io::Write;

async fn check_environment_variable(variable_name: &str) -> Result<(), String> {
    if env::var(variable_name).is_err() {
        let path = format!("/tmp/{}", variable_name);
        let mut file = File::create(&path)?;
        write!(file, "{}", path)?;
        env::set_var(variable_name, &path)?;
        info!("Created and set environment variable {}", variable_name);
    }
    Ok(())
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    check_environment_variable("PAYMENT_PROCESSOR_DIR")?;

    HttpServer::new(|| {
        App::new()
            .route("/", web::get().to(|| async { HttpResponse::Ok().body("Hello world") }))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
