import hashlib
import time

class CDN:
    def __init__(self, storage_capacity):
        self.storage = {}
        self.capacity = storage_capacity
        self.cache_policy = {}

    def store_content(self, user_location, device_type, content_id, content):
        # Hash the content to create a unique key
        content_key = hashlib.sha256(content.encode()).hexdigest()

        # Check if we can store the content
        if len(self.storage) + len(content) > self.capacity:
            self.evict_content()

        # Store the content in the cache with metadata
        self.storage[content_key] = {
            'user_location': user_location,
            'device_type': device_type,
            'last_accessed': time.time(),
            'content': content
        }

    def evict_content(self):
        # Evict least recently accessed content
        least_recently_used = min(self.storage.values(), key=lambda x: x['last_accessed'])
        del self.storage[least_recently_used]

    def retrieve_content(self, user_location, device_type, content_id):
        # Hash the content to create a unique key
        content_key = hashlib.sha256(content_id.encode()).hexdigest()

        if content_key in self.storage:
            # Update the last accessed time for cache hit
            self.storage[content_key]['last_accessed'] = time.time()
            return self.storage[content_key]['content']
        else:
            return None

