        // Validate the input using the policy engine
        if (!$this->policyEngine->isValidStatusChange($newStatus)) {
            throw new Exception("Invalid status change");
        }

        // Acquire a distributed lock to prevent race conditions
        $lock = new DistributedLock($clinicId);
        if ($lock->acquire()) {
            try {
                // Retrieve clinic information from external identity providers and APIs
                $clinicInfo = $this->fetchClinicInfo($clinicId);

                // Update the clinic status in the database
                $this->database->updateStatus($clinicId, $newStatus);

                // Cache the updated clinic information
                $this->cache->set('clinic:' . $clinicId, $clinicInfo);

                // Enqueue a background job for sensitive operations
                $job = new BackgroundJob($clinicId, $newStatus);
                $this->messageBroker->enqueue($job);

                return true;
            } finally {
                $lock->release();
            }
        }

        throw new Exception("Failed to acquire lock");
    }

