class DistributedLock {
    private $lockKey;
    private $redis;

    public function __construct($resource) {
        $this->lockKey = "lock:" . md5($resource);
        $this->redis = new Redis();
        $this->redis->connect('localhost', 6379);
    }

    public function acquire() {
        return $this->redis->setnx($this->lockKey, time() + 10); // Acquire lock for 10 seconds
    }

    public function release() {
        if ($this->redis->get($this->lockKey) == time()) {
            $this->redis->del($this->lockKey);
        }
    }
}

class BackgroundJob {
    private $clinicId;
    private $newStatus;

    public function __construct($clinicId, $newStatus) {
