class StateTransitionManager {
public:
    StateTransitionManager(std::shared_ptr<ExternalDB> db, std::shared_ptr<DataStream> stream)
        : db_(db), stream_(stream) {}

    void run() {
        while (stream_->hasNext()) {
            auto data = stream_->next();
            if (!data.index()) {
                continue;
            }

            int key = extractKey(*data);
            long offset = extractOffset(*data);
            std::string metadata = extractMetadata(*data);

            updateState(key, offset, metadata);
        }
    }

private:
    void updateState(int key, long offset, const std::string& metadata) {
        if (!db_->isAvailable()) {
            retryUpdateState(key, offset, metadata);
            return;
        }

        if (!db_->validateSchema(getCurrentSchema())) {
            handleSchemaChange();
            return;
        }

        if (!db_->updateRecord(key, offset, metadata)) {
            handleTransientFailure();
        }
    }

    void retryUpdateState(int key, long offset, const std::string& metadata) {
        // Implement retry logic with exponential backoff and circuit breaker
