// textureLoader.js

const grpc = require('grpc');
const WebSocket = require('ws');
const fs = require('fs');

class TextureLoader {
  constructor(assetManagementServiceUrl) {
    this.assetManagementServiceUrl = assetManagementServiceUrl;
    this.client = null;
    this.wsClient = null;
    this.cache = new Map();
    this.texturePreloadQueue = [];
  }

  async connectToAssetService() {
    if (this.assetManagementServiceUrl.startsWith('grpc')) {
      const protoLoader = require('@grpc/proto-loader');
      const packageDefinition = await protoLoader.load(this.assetManagementServiceUrl, {keepCase: true, longs: String, enums: String, defaults: true, oneofs: true});
      this.client = new grpc.Client(this.assetManagementServiceUrl, grpc.credentials.createInsecure(), packageDefinition);
    } else if (this.assetManagementServiceUrl.startsWith('ws')) {
      this.wsClient = new WebSocket(this.assetManagementServiceUrl);
    }
  }

  async loadTexture(textureId) {
    if (this.cache.has(textureId)) {
      return this.cache.get(textureId);
    }

    let textureData;
    try {
      if (this.client) {
        const request = {textureId: textureId};
        textureData = await new Promise((resolve, reject) => {
          this.client.loadTexture(request, (err, response) => {
            if (err) return reject(err);
            resolve(response.textureData);
          });
        });
      } else if (this.wsClient) {
        const request = {textureId: textureId};
        await new Promise((resolve, reject) => {
          this.wsClient.on('message', (data) => {
            const response = JSON.parse(data);
            if (response.error) return reject(new Error(response.error));
            resolve(response.textureData);
          });
          this.wsClient.send(JSON.stringify(request));
        });
      }

      textureData = await this.compressTexture(textureData);
      this.cache.set(textureId, textureData);
    } catch (error) {
      console.error(`Failed to load texture ${textureId}:`, error);
      throw error;
    }

    return textureData;
  }

  async compressTexture(data) {
    // Implement your texture compression logic here
    // For example, using a library like sharp for image compression
    return data;
  }

  preLoadTextures(preloadList) {
    this.texturePreloadQueue = [...this.texturePreloadQueue, ...preloadList];
    this.processTexturePreloadQueue();
  }

  async processTexturePreloadQueue() {
    while (this.texturePreloadQueue.length > 0 && this.isConnectionAvailable()) {
      const textureId = this.texturePreloadQueue.shift();
      await this.loadTexture(textureId);
    }
  }

  isConnectionAvailable() {
    // Implement your connection availability logic here
    return true;
  }

  async handleRealTimeUpdates() {
    if (this.wsClient) {
      this.wsClient.on('message', (data) => {
        const update = JSON.parse(data);
        if (update.type === 'textureUpdate') {
          this.cache.delete(update.textureId);
          this.preLoadTextures([update.textureId]);
        }
      });
    }
  }

  async handleErrors(error) {
    // Implement your error handling logic here
    console.error('Error occurred:', error);
  }

  async start() {
    await this.connectToAssetService();
    await this.handleRealTimeUpdates();
    setInterval(() => this.processTexturePreloadQueue(), 1000); // Adjust interval based on load and performance
  }
}

module.exports = TextureLoader;
