using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private readonly ConcurrentDictionary<string, Random> _randomGenerators = new ConcurrentDictionary<string, Random>();
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();

    public int GenerateInt(string seed, int min, int max)
    {
        var random = GetRandom(seed);
        return random.Next(min, max + 1);
    }

    public double GenerateDouble(string seed, double min, double max)
    {
        var random = GetRandom(seed);
        return random.NextDouble() * (max - min) + min;
    }

    private Random GetRandom(string seed)
    {
        return _randomGenerators.GetOrAdd(seed, s => new Random(s.GetHashCode()));
    }
}

public class Program
{
    public static async Task Main()
    {
        var generator = new DynamicRandomValueGenerator();

        var tasks = new List<Task>();
        for (int i = 0; i < 100; i++)
        {
            tasks.Add(Task.Run(() =>
            {
                for (int j = 0; j < 1000; j++)
                {
                    int randomValue = generator.GenerateInt("seed1", 1, 100);
                    double randomDouble = generator.GenerateDouble("seed2", 0.5, 2.5);
                }
            }));
        }

        await Task.WhenAll(tasks);

        Console.WriteLine("Random value generation completed.");
    }
}
