        this.executorService = Executors.newFixedThreadPool(10);
        this.cloudTimeSeriesDB = new CloudTimeSeriesDB();
        this.externalAPI = new ExternalAPI();
    }

    public void ingestData(SensorData data) {
        executorService.submit(() -> processData(data));
    }

