        if (data.isCritical()) {
            sendAlert(data);
        }
        cloudTimeSeriesDB.store(data);
        externalAPI.sendAnomalyDetectionRequest(data);
    }

    private void sendAlert(SensorData data) {
        // Implement alert sending logic
    }

    public void shutdown() {
        executorService.shutdown();
    }
}

