// Go Code Snippet for Data Ingestion Pipeline

package main

import (
    "log"
    "net/http"
)

func main() {
    http.HandleFunc("/ingest", handleDataIngest)
    log.Println("Starting data ingestion server on :8080")
    if err := http.ListenAndServe(":8080", nil); err != nil {
        log.Fatal(err)
    }
}

func handleDataIngest(w http.ResponseWriter, r *http.Request) {
    // Parse incoming sensor data
    var sensorData SensorData
    err := json.NewDecoder(r.Body).Decode(&sensorData)
    if err != nil {
        http.Error(w, "Invalid request", http.StatusBadRequest)
        return
    }

    // Process and store the data
    go processData(sensorData)

    w.WriteHeader(http.StatusOK)
}

func processData(sensorData SensorData) {
    if sensorData.IsCritical() {
        sendAlert(sensorData)
    }
    cloudTimeSeriesDB.Store(sensorData)
    externalAPI.SendAnomalyDetectionRequest(sensorData)
}

type SensorData struct {
    Timestamp   string  `json:"timestamp"`
    Location    string  `json:"location"`
