        return False

    def generate_and_send_invoice(self, customer_id: str, services: Dict[str, float]):
        invoice = self.invoice_generator.generate_invoice(customer_id, services)
        # Simulate sending the invoice
        print(f"Invoice sent to {customer_id}: {invoice}")

    def subscribe_customer_with_payment(self, customer_id: str, payment_gateway: str, services: Dict[str, float]):
        if not self.process_payment(customer_id, payment_gateway, sum(services.values())):
            return False
        self.subscription_service.subscribe_customer(customer_id, services)
        self.generate_and_send_invoice(customer_id, services)
