#include <time.h>

typedef struct {
    time_t timestamp;
    char type[50];
    void* metadata;
} NetworkEvent;

typedef struct {
    NetworkEvent** events;
    size_t capacity;
    size_t size;
} EventArray;

void initEventArray(EventArray* array, size_t initialCapacity) {
    array->capacity = initialCapacity;
    array->size = 0;
    array->events = (NetworkEvent**)malloc(initialCapacity * sizeof(NetworkEvent*));
}

void freeEventArray(EventArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->events[i]);
    }
    free(array->events);
}

void addEventToQueue(EventArray* queue, NetworkEvent* event) {
    if (queue->size >= queue->capacity) {
        // Resize the array
        queue->capacity *= 2;
        queue->events = (NetworkEvent**)realloc(queue->events, queue->capacity * sizeof(NetworkEvent*));
    }
    queue->events[queue->size++] = event;
}

int main() {
    EventArray eventQueue;
    initEventArray(&eventQueue, 10);

    // Simulate adding events
    NetworkEvent* newEvent = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    newEvent->timestamp = time(NULL);
    strcpy(newEvent->type, "LOGIN");
    newEvent->metadata = NULL;

    addEventToQueue(&eventQueue, newEvent);

    printf("Event added to queue.\n");

    // Clean up
    freeEventArray(&eventQueue);
    free(newEvent);

    return 0;
}
