#include <pthread.h>
#include <semaphore.h>

#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_ELEMENTS];
    int count;
    sem_t lock;
} NFAPI_PDUCollection_T;

NFAPI_PDUCollection_T pduCollection;

void initPDUCollection() {
    pduCollection.count = 0;
    sem_init(&pduCollection.lock, 0, 1);
}

int addPDU(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (sem_wait(&pduCollection.lock) != 0) return -1; // Handle error
    if (pduCollection.count >= MAX_ELEMENTS) {
        sem_post(&pduCollection.lock);
        return -2; // Collection full
    }
    pduCollection.pdus[pduCollection.count++] = pdu;
    sem_post(&pduCollection.lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* getPDU(int index) {
    if (index < 0 || index >= pduCollection.count) return NULL;
    return pduCollection.pdus[index];
}

void *dataIngestionThread(void *arg) {
    // Simulate data ingestion and PDU updates
    for (int i = 0; i < 1000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            perror("Memory allocation failed");
            continue;
        }
        // Populate pdu fields with real-time data
        addPDU(pdu);
    }
    return NULL;
}

int main() {
    initPDUCollection();

    pthread_t ingestThread;
    if (pthread_create(&ingestThread, NULL, dataIngestionThread, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    // Join thread after completion
    pthread_join(ingestThread, NULL);

    // Cleanup and free resources

    return 0;
}
