// Import necessary libraries
const express = require('express');
const axios = require('axios');
const redis = require('redis');
const { promisify } = require('util');

// Initialize Express app
const app = express();
app.use(express.json());

// Redis setup
const client = redis.createClient();
client.on('error', (err) => {
  console.error('Redis error:', err);
});
const getAsync = promisify(client.get).bind(client);

// Utility function to copy a specified number of bytes from buffered data chunks into a new buffer
function copyBufferedData(bufferChunks, totalBytes) {
  const newBuffer = Buffer.allocUnsafe(totalBytes);
  let offset = 0;

  for (const chunk of bufferChunks) {
    if (offset >= totalBytes) break;
    const bytesToCopy = Math.min(chunk.length, totalBytes - offset);
    chunk.copy(newBuffer, offset, 0, bytesToCopy);
    offset += bytesToCopy;
  }

  return newBuffer.slice(0, totalBytes);
}

// Route to process and cache real-time sensor data
app.post('/processData', async (req, res) => {
  const { deviceID, data } = req.body;

  try {
    // Simulate fetching device metadata from third-party API
    const metadataResponse = await axios.get(`https://api.example.com/devices/${deviceID}`);
    const deviceMetadata = metadataResponse.data;

    // Cache sensor data in Redis
    client.set(deviceID, JSON.stringify(data), (err) => {
      if (err) {
        console.error('Error caching data:', err);
      } else {
        console.log(`Data cached for device ${deviceID}`);
      }
    });

    res.status(200).send({ message: 'Data processed and cached successfully' });
  } catch (error) {
    console.error('Error processing data:', error);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Route to query real-time sensor data
app.get('/queryData/:deviceID', async (req, res) => {
  const { deviceID } = req.params;

  try {
    // Retrieve cached sensor data from Redis
    const cachedData = await getAsync(deviceID);
    if (!cachedData) {
      return res.status(404).send({ message: 'No data found for the specified device' });
    }

    const parsedData = JSON.parse(cachedData);

    // Simulate complex query logic (e.g., filtering, aggregating)
    const queryResults = filterAndAggregateData(parsedData);

    res.status(200).json(queryResults);
  } catch (error) {
    console.error('Error querying data:', error);
    res.status(500).send({ message: 'Internal Server Error' });
  }
});

// Helper function to simulate complex query logic
function filterAndAggregateData(data) {
  // Example filtering and aggregation logic
  return data.filter(item => item.value > 100)
             .reduce((acc, curr) => acc + curr.value, 0);
}

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
