using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.WebSockets;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using StackExchange.Redis;

public class StreamingDataProcessor : IHostedService, IDisposable
{
    private readonly ILogger<StreamingDataProcessor> _logger;
    private readonly IServiceScopeFactory _serviceScopeFactory;
    private CancellationTokenSource _cancellationTokenSource = new();
    private List<WebSocket> _webSockets = new();
    private ConnectionMultiplexer _redis;

    public StreamingDataProcessor(ILogger<StreamingDataProcessor> logger, IServiceScopeFactory serviceScopeFactory)
    {
        _logger = logger;
        _serviceScopeFactory = serviceScopeFactory;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        _cancellationTokenSource = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        await ConnectWebSockets();
        await ConnectRedis();
        await ProcessMessages();
    }

    private async Task ConnectWebSockets()
    {
        // Simulate WebSocket connections
        for (int i = 0; i < 50000; i++)
        {
            var webSocket = new ClientWebSocket();
            await webSocket.ConnectAsync(new Uri("ws://example.com/socket"), _cancellationTokenSource.Token);
            _webSockets.Add(webSocket);
        }
    }

    private async Task ConnectRedis()
    {
        // Connect to Redis
        _redis = ConnectionMultiplexer.Connect("localhost");
        var db = _redis.GetDatabase();
    }

    private async Task ProcessMessages()
    {
        while (!_cancellationTokenSource.Token.IsCancellationRequested)
        {
            foreach (var webSocket in _webSockets.Where(ws => ws.State == WebSocketState.Open))
            {
                try
                {
                    // Simulate message reception and processing
                    var buffer = new byte[1024 * 4];
                    int result = await webSocket.ReceiveAsync(new ArraySegment<byte>(buffer), CancellationToken.None);
                    var message = System.Text.Encoding.UTF8.GetString(buffer, 0, result);
                    _logger.LogInformation($"Received message: {message}");

                    // Process the message using a service
                    using (var scope = _serviceScopeFactory.CreateScope())
                    {
                        var messageProcessor = scope.ServiceProvider.GetRequiredService<IMessageProcessor>();
                        await messageProcessor.ProcessAsync(message);
                    }

                    // Store the message in Redis
                    var db = _redis.GetDatabase();
                    await db.StringSetAsync("messages", message);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing WebSocket message");
                }
            }
            await Task.Delay(100, _cancellationTokenSource.Token);
        }
    }

    public async Task StopAsync(CancellationToken cancellationToken)
    {
        _cancellationTokenSource.Cancel();
        await DisconnectWebSockets();
        await _redis.CloseAsync(true);
    }

    private async Task DisconnectWebSockets()
    {
        foreach (var webSocket in _webSockets.Where(ws => ws.State == WebSocketState.Open))
        {
            await webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, "Closing", CancellationToken.None);
        }
    }

    public void Dispose()
    {
        _cancellationTokenSource.Dispose();
        foreach (var webSocket in _webSockets)
        {
            webSocket.Dispose();
        }
    }
}
