// Dynamic loading of DataProcessor implementations from an external REST API
@Service
public class DataProcessorFactory {

    private final RestTemplate restTemplate;
    private final Map<String, Class<? extends DataProcessor>> processorMap = new ConcurrentHashMap<>();

    @Autowired
    public DataProcessorFactory(RestTemplate restTemplate) {
        this.restTemplate = restTemplate;
        initializeProcessors();
    }

    private void initializeProcessors() {
        // Fetch processor classes from external REST API and cache them
        List<String> processorNames = restTemplate.getForObject("https://api.example.com/data-processors", List.class);
        for (String name : processorNames) {
            try {
                Class<? extends DataProcessor> clazz = Class.forName(name).asSubclass(DataProcessor.class);
                processorMap.put(clazz.getSimpleName(), clazz);
            } catch (ClassNotFoundException e) {
                // Handle class not found, log error
            }
        }
    }

    public DataProcessor getProcessor(String name) {
        return processorMap.getOrDefault(name, XMLDataProcessor.class).getDeclaredConstructor().newInstance();
    }
}

// In-memory caching mechanism with configurable bounds
@Component
public class DataCache {

    private final Cache<String, Object> cache = Caffeine.newBuilder()
            .maximumSize(1000)
            .expireAfterWrite(10, TimeUnit.MINUTES)
            .build();

    public <T> T get(String key, Function<String, T> loader) {
        return cache.get(key, loader);
    }

    public void put(String key, Object value) {
        cache.put(key, value);
    }
}

