package main

import (
	"context"
	"fmt"
	"log"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type Tenant struct {
	ID          string `bson:"_id"`
	Name        string `bson:"name"`
	Config      string `bson:"config"`
	API         string `bson:"api"`
	AuthScheme  string `bson:"auth_scheme"`
	DataIsolation bool   `bson:"data_isolation"`
}

func main() {
	clientOptions := options.Client().ApplyURI("mongodb://localhost:27017")

	client, err := mongo.Connect(context.TODO(), clientOptions)
	if err != nil {
		log.Fatal(err)
	}

	err = client.Ping(context.TODO(), nil)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("Connected to MongoDB!")

	collection := client.Database("multiTenantCloudServiceManager").Collection("tenants")

	tenant := Tenant{
		ID:          "tenant1",
		Name:        "ExampleTenant",
		Config:      "{\"key\": \"value\"}",
		API:         "https://api.example.com",
		AuthScheme:  "BearerToken",
		DataIsolation: true,
	}

	insertResult, err := collection.InsertOne(context.TODO(), tenant)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("Inserted tenant with ID:", insertResult.InsertedID)

	var result Tenant
	err = collection.FindOne(context.TODO(), bson.D{{"_id", "tenant1"}}).Decode(&result)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Found tenant: %+v\n", result)

	err = client.Disconnect(context.TODO())
	if err != nil {
		log.Fatal(err)
	}

	fmt.Println("Connection to MongoDB closed.")
}
