use serde::{Deserialize, Serialize};
use serde_json::Value;
use tokio::sync::Mutex;

#[derive(Debug, Deserialize)]
struct TokenResponse {
    token_type: String,
    expires_in: u64,
    scope: Option<String>,
    iat: Option<u64>,
    nbf: Option<u64>,
}

async fn validate_token(token_json: &str) -> Result<(), &'static str> {
    let token: TokenResponse = serde_json::from_str(token_json).map_err(|_| "Invalid JSON format")?;

    if token.token_type != "Bearer" {
        return Err("Token type must be 'Bearer'");
    }

    if token.expires_in == 0 {
        return Err("Expires in must be a positive integer");
    }

    if let Some(ref scope) = token.scope {
        for s in scope.split_whitespace() {
            if !s.chars().all(|c| c.is_alphanumeric() || c == '-') {
                return Err("Invalid scope format");
            }
        }
    }

    if let Some(iat) = token.iat {
        // Validate issued at claim (Unix timestamp)
        if iat > 0 && iat < chrono::Utc::now().timestamp() as u64 {
            return Err("Token issued in the past");
        }
    }

    if let Some(nbf) = token.nbf {
        // Validate not before claim (Unix timestamp)
        if nbf > 0 && nbf > chrono::Utc::now().timestamp() as u64 {
            return Err("Token not valid yet");
        }
    }

    Ok(())
}

#[tokio::main]
async fn main() {
    let token_json = r#"{
        "token_type": "Bearer",
        "expires_in": 3600,
        "scope": "read write"
    }"#;

    match validate_token(token_json).await {
        Ok(_) => println!("Token is valid"),
        Err(e) => eprintln!("Validation failed: {}", e),
    }
}
```

This Rust program uses the `serde` crate for JSON parsing and validation, and `tokio` for asynchronous operations. The `validate_token` function checks if the token type is 'Bearer', expires in a positive integer, and validates each scope as a valid string of alphanumeric characters and hyphens. It also handles optional claims like `issued_at` (`iat`) and `not_before` (`nbf`). If any validation fails, it returns an error message; otherwise, it returns Ok(). The main function demonstrates how to use this validation function asynchronously.']

