    orchestrator = TaskOrchestrator()
    await orchestrator.submit_task('task1', dependencies=['task0'], data={'data': 'value1'})
    orchestrator.add_worker_node('node1')
    orchestrator.remove_worker_node('node2')

# JavaScript function for AngularJS application
def refreshDialogFields(resourceId, url, fieldNames) {
    var request = new XMLHttpRequest();
    request.open("GET", url, true);
    request.onreadystatechange = function() {
        if (request.readyState === 4 && request.status === 200) {
            var data = JSON.parse(request.responseText);
            for (var fieldName in data) {
                if (fieldNames.includes(fieldName)) {
                    parent.window.updateField(fieldName, data[fieldName]);
                }
            }
        }
    };
    request.send();
}
