NFAPI_CRC_INDICATION_PDU_T pdu_pool[MAX_ELEMENTS];
int pdu_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* process_pdus(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if (pdu_count > 0) {
            NFAPI_CRC_INDICATION_PDU_T pdu = pdu_pool[--pdu_count];
            pthread_mutex_unlock(&lock);

            // Process PDU
            process_pdu_function(pdu);
        } else {
            pthread_mutex_unlock(&lock);
            usleep(1000); // Sleep for 1 ms if no PDUs to process
        }
    }
}

void enqueue_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&lock);
    if (pdu_count < MAX_ELEMENTS) {
        pdu_pool[pdu_count++] = pdu;
    } else {
        // Handle error: PDU pool is full
        log_error("PDU pool is full");
    }
    pthread_mutex_unlock(&lock);
}

void* rate_limiting_thread(void* arg) {
    while (1) {
        usleep(1000); // Sleep for 1 ms to limit rate
    }
}

int main() {
    pthread_t processing_thread, rate_limiting_tid;
    pthread_create(&processing_thread, NULL, process_pdus, NULL);
    pthread_create(&rate_limiting_tid, NULL, rate_limiting_thread, NULL);

