class EventConsumer:
    def __init__(self, bootstrap_servers, topic_name, schema_manager, event_processor, service_resolver, data_service):
        self.bootstrap_servers = bootstrap_servers
        self.topic_name = topic_name
        self.schema_manager = schema_manager
        self.event_processor = event_processor
        self.service_resolver = service_resolver
        self.data_service = data_service
        self.consumer = KafkaConsumer(topic_name, bootstrap_servers=bootstrap_servers)

    def consume_events(self):
        for message in self.consumer:
            event_type = message.key.decode('utf-8')
            event_data = message.value
            try:
                self.schema_manager.validate_event(event_type, event_data)
                processed_data = self.event_processor.process_event(event_type, event_data)
                self.data_service.store_event(event_type, processed_data)
            except Exception as e:
                print(f"Error processing event: {e}")

