#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    char type[32];
    void* metadata;
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t capacity;
    size_t count;
} EventQueue;

void init_event_queue(EventQueue* queue, size_t initial_capacity) {
    queue->events = (NetworkEvent*)malloc(initial_capacity * sizeof(NetworkEvent));
    queue->capacity = initial_capacity;
    queue->count = 0;
}

void enqueue_event(EventQueue* queue, NetworkEvent event) {
    if (queue->count >= queue->capacity) {
        queue->capacity *= 2;
        queue->events = (NetworkEvent*)realloc(queue->events, queue->capacity * sizeof(NetworkEvent));
    }
    queue->events[queue->count++] = event;
}

void process_events(EventQueue* queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        NetworkEvent event = queue->events[i];
        // Process event
        printf("Processing event: Timestamp=%ld, Type=%s\n", event.timestamp, event.type);
        // Log event
        log_event(&event);
        // Forward to analytics service
        forward_to_analytics(event);
        // Free metadata if needed
        free(event.metadata);
    }
    queue->count = 0;
}

void* worker_thread(void* arg) {
    EventQueue* queue = (EventQueue*)arg;
    while (1) {
        process_events(queue);
        sleep(1); // Simulate processing time
    }
    return NULL;
}

int main() {
    EventQueue event_queue;
    init_event_queue(&event_queue, 1024);

    pthread_t thread;
    pthread_create(&thread, NULL, worker_thread, &event_queue);

    NetworkEvent event = {1633075200, "LOGIN", malloc(10)};
    enqueue_event(&event_queue, event);

    pthread_join(thread, NULL);
    free(event.metadata);
    free(event_queue.events);

    return 0;
}
