NFAPI_CRC_INDICATION_PDU_T* allocate_and_process_nfaapi_crc_indications(int N) {
    if (N <= 0) {
        log_message("NFAPI", "Invalid input size");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        log_message("NFAPI", "Failed to allocate memory for NFAPI CRC indications");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        indications[i].RNTI = rand() % 65535;
        indications[i].CRC_INDICATION_REL8_TAG = rand() % 1024;
        indications[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    log_message("NFAPI", "Processed NFAPI CRC indications successfully");
    return indications;
}

void free_nfaapi_crc_indications(NFAPI_CRC_INDICATION_PDU_T *indications, int N) {
    if (indications) {
        free(indications);
        log_message("NFAPI", "Memory freed for NFAPI CRC indications");
    }
}
