{
    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public IConfiguration Configuration { get; }

    // This method gets called by the runtime. Use this method to add services to the container.
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddControllers()
                .AddJsonOptions(options => options.JsonSerializerOptions.PropertyNamingPolicy = null);

        services.AddAuthentication("Bearer")
                .AddJwtBearer("Bearer", options =>
                {
                    options.Authority = Configuration["Auth0:Authority"];
                    options.Audience = Configuration["Auth0:Audience"];
                });

        services.AddAuthorization(options =>
        {
            options.AddPolicy("UpdateElementPolicy", policy => policy.RequireClaim("scope", "update_element"));
        });

        services.AddHttpClient("HtmlRenderingEngine1", client => client.BaseAddress = new Uri(Configuration["HtmlRenderingEngine1:Url"]));
        services.AddHttpClient("HtmlRenderingEngine2", client => client.BaseAddress = new Uri(Configuration["HtmlRenderingEngine2:Url"]));

        services.AddStackExchangeRedisCache(options =>
        {
            options.Configuration = Configuration.GetConnectionString("Redis");
        });

        services.AddSingleton<IBackgroundWorker, BackgroundWorker>();
        services.AddScoped<IHtmlRenderer, HtmlRenderer>();

        services.AddControllers();
