// chunkifyAndValidate.js
const fs = require('fs');
const path = require('path');

function* chunkifyAndValidate(file_path, chunk_size) {
    const buffer = Buffer.alloc(chunk_size);
    let read_bytes = 0;

    while ((read_bytes = fs.readSync(fs.openSync(file_path, 'r'), buffer, 0, chunk_size)) > 0) {
        const chunk = buffer.slice(0, read_bytes);
        yield { chunk, size: read_bytes };
    }
}

module.exports = chunkifyAndValidate;
```

```javascript
// fileProcessor.js
const AWS = require('aws-sdk');
const GoogleCloudStorage = require('@google-cloud/storage');
const AzureBlobStorage = require('@azure/storage-blob');

class FileProcessor {
    constructor(config) {
        this.config = config;
        this.clients = {
            s3: new AWS.S3(),
            gcs: new GoogleCloudStorage.Storage(),
            azure: new AzureBlobStorage.BlobServiceClient(this.config.azure_connection_string)
        };
    }

    async upload(file_path, storage_type, bucket_name) {
        const client = this.clients[storage_type];
        if (!client) throw new Error(`Unsupported storage type: ${storage_type}`);

        const fileStream = fs.createReadStream(file_path);
        return await client.uploadFile({
            Bucket: bucket_name,
            Key: path.basename(file_path),
            Body: fileStream
        });
    }

    async download(bucket_name, key, destination_path) {
        const client = this.clients[this.config.default_storage_type];
        if (!client) throw new Error(`Unsupported storage type: ${this.config.default_storage_type}`);

        const blobClient = client.getBlobClient(`${bucket_name}/${key}`);
        return await blobClient.downloadToFile(destination_path);
    }

    async updateMetadata(bucket_name, key, metadata) {
        const client = this.clients[this.config.default_storage_type];
        if (!client) throw new Error(`Unsupported storage type: ${this.config.default_storage_type}`);

        const blobClient = client.getBlobClient(`${bucket_name}/${key}`);
        return await blobClient.setHTTPHeaders({ ...blobClient.getProperties().then(prop => prop.httpHeaders), ...metadata });
    }
}

module.exports = FileProcessor;
```

