// main.js
const config = {
    default_storage_type: 's3',
    azure_connection_string: 'your-azure-connection-string'
};

const chunkifyAndValidate = require('./chunkifyAndValidate');
const FileProcessor = require('./fileProcessor');

async function processFile(file_path, storage_type, bucket_name) {
    const processor = new FileProcessor(config);
    for await (const { chunk, size } of chunkifyAndValidate(file_path, 1024 * 1024)) {
        await processor.upload(Buffer.from(chunk), storage_type, bucket_name);
    }

    // Update metadata after upload
    await processor.updateMetadata(bucket_name, path.basename(file_path), { contentType: 'application/octet-stream' });
}

// Example usage:
processFile('path/to/large/file', 's3', 'your-bucket-name');
