#include <queue>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <chrono>
#include <cmath>
#include <vector>
#include <memory>
#include <functional>

class NetworkPacket {
public:
    std::string sourceIP;
    size_t packetSize;
    uint8_t TTL;
    int packetID;
};

class LRUQueue {
private:
    struct Node {
        NetworkPacket data;
        std::chrono::time_point<std::chrono::system_clock> lastAccessed;
        Node* prev;
        Node* next;
        Node(const NetworkPacket& p) : data(p), lastAccessed(std::chrono::system_clock::now()), prev(nullptr), next(nullptr) {}
    };

    std::unordered_map<int, Node*> cache;
    Node* head;
    Node* tail;
    size_t capacity;
    std::mutex mtx;

public:
    LRUQueue(size_t cap) : capacity(cap), head(new Node(NetworkPacket())), tail(new Node(NetworkPacket())) {
        head->next = tail;
        tail->prev = head;
    }

    ~LRUQueue() {
        clear();
        delete head;
        delete tail;
    }

    void put(const NetworkPacket& packet, int id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (cache.find(id) != cache.end()) {
            update(packet, id);
        } else {
            evict();
            Node* newNode = new Node(packet);
            newNode->next = head->next;
            newNode->prev = head;
            head->next->prev = newNode;
            head->next = newNode;
            cache[id] = newNode;
            if (cache.size() > capacity) {
                evict();
            }
        }
    }

    NetworkPacket get(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (cache.find(id) == cache.end()) {
            return NetworkPacket();
        } else {
            Node* node = cache[id];
            update(node->data, id);
            return node->data;
        }
    }

    void evict() {
        std::lock_guard<std::mutex> lock(mtx);
        if (tail->prev != head) {
            Node* toRemove = tail->prev;
            toRemove->prev->next = tail;
            tail->prev = toRemove->prev;
            cache.erase(toRemove->data.packetID);
            delete toRemove;
        }
    }

    void update(const NetworkPacket& packet, int id) {
        std::lock_guard<std::mutex> lock(mtx);
        if (cache.find(id) != cache.end()) {
            Node* node = cache[id];
            node->lastAccessed = std::chrono::system_clock::now();
            node->data = packet;
        }
    }

    void clear() {
        std::lock_guard<std::mutex> lock(mtx);
        while (head->next != tail) {
            Node* toRemove = head->next;
            head->next = toRemove->next;
            toRemove->next->prev = head;
            delete toRemove;
        }
        cache.clear();
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mtx);
        return cache.size();
    }
};

class PacketManager {
private:
    LRUQueue queue;
    std::atomic<bool> running;
    std::thread worker;
    std::condition_variable cv;
    std::mutex work_mtx;
    std::queue<NetworkPacket> pendingWork;

public:
    PacketManager(size_t capacity) : queue(capacity), running(false) {}

    ~PacketManager() {
        stop();
    }

    void start() {
        running = true;
        worker = std::thread(&PacketManager::processPackets, this);
    }

    void stop() {
        running = false;
        cv.notify_all();
        if (worker.joinable()) {
            worker.join();
        }
    }

    void enqueue(const NetworkPacket& packet) {
        std::lock_guard<std::mutex> lock(work_mtx);
        pendingWork.push(packet);
        cv.notify_one();
    }

private:
    void processPackets() {
        while (running) {
            NetworkPacket packet;
            {
                std::unique_lock<std::mutex> lock(work_mtx);
                cv.wait(lock, [this] { return !pendingWork.empty() || !running; });
                if (!running) break;
                packet = pendingWork.front();
                pendingWork.pop();
            }
            queue.put(packet, packet.packetID);
        }
    }
};
```']

