        LoggerFramework logger = new CentralizedLogger();
        ResourceAllocator.allocateResources(logger, 10000000);
        KubernetesIntegration.scaleResources(logger, 10000000);

        // Simulate logging a message
        LoggerWithRetry retryLogger = new LoggerWithRetry(logger);
        retryLogger.log("Application started");
    }
