#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <curl/curl.h>

// Define constants for AES-GCM mode
#define GCM_TAG_LENGTH 16

// Function to encrypt data using AES-GCM
int aes_gcm_encrypt(unsigned char *key, unsigned char *iv, unsigned char *plaintext, int plaintext_len, unsigned char **ciphertext, unsigned char **tag) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    // Initialize the context for encryption
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Allocate memory for ciphertext and tag
    *ciphertext = malloc(plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_gcm()));
    if (!*ciphertext) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    *tag = malloc(GCM_TAG_LENGTH);
    if (!*tag) {
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Update the context with plaintext
    int len;
    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        free(*ciphertext);
        free(*tag);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Finalize the encryption and obtain the tag
    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) {
        free(*ciphertext);
        free(*tag);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    memcpy((*ciphertext) + len, *tag, GCM_TAG_LENGTH);

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    return len + GCM_TAG_LENGTH;
}

// Function to decrypt data using AES-GCM
int aes_gcm_decrypt(unsigned char *key, unsigned char *iv, unsigned char *ciphertext_with_tag, int ciphertext_len, unsigned char **plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    // Initialize the context for decryption
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Allocate memory for plaintext
    *plaintext = malloc(ciphertext_len - GCM_TAG_LENGTH);
    if (!*plaintext) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Update the context with ciphertext and tag
    int len;
    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext_with_tag, ciphertext_len - GCM_TAG_LENGTH)) {
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Finalize the decryption
    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) {
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    return len;
}

