    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    // Set up the request for the token endpoint
    curl_easy_setopt(curl, CURLOPT_URL, "https://auth.example.com/oauth/token");
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "grant_type=client_credentials&client_id=" client_id "&client_secret=" client_secret);

    // Perform the request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        curl_easy_cleanup(curl);
        return -1;
    }

    // Parse the token response and validate it
    int status_code;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status_code);
    if (status_code == 200 && validate_access_token((const char *)token)) {
        // Token is valid; store or return it
        curl_easy_cleanup(curl);
        return 0;
    }

    curl_easy_cleanup(curl);
    return -1;
}

