    }

    // Print the decrypted text
    decrypted_text[decrypted_text_len] = '\0';
    printf("Decrypted Text: %s\n", decrypted_text);

    // Clean up
    free(ciphertext_with_tag);
    free(tag);
    free(decrypted_text);

    // Fetch and validate an OAuth2 access token
    unsigned char *access_token;
    if (fetch_access_token("client_id", "client_secret", &access_token) == 0) {
        printf("Access Token: %s\n", access_token);
        free(access_token);
    }

    return 0;
}
