#define AES_BLOCK_SIZE 16

void aes_encrypt_ecb(unsigned char *plaintext, unsigned int plaintext_len, unsigned char *key,
                    unsigned char *iv, unsigned char *ciphertext) {
    AES_KEY enc_key;
    AES_set_encrypt_key(key, 256, &enc_key);
    for (unsigned int i = 0; i < plaintext_len; i += AES_BLOCK_SIZE) {
        AES_ecb_encrypt(plaintext + i, ciphertext + i, &enc_key, AES_ENCRYPT);
    }
}

void aes_decrypt_ecb(unsigned char *ciphertext, unsigned int ciphertext_len, unsigned char *key,
                    unsigned char *iv, unsigned char *plaintext) {
    AES_KEY dec_key;
    AES_set_decrypt_key(key, 256, &dec_key);
    for (unsigned int i = 0; i < ciphertext_len; i += AES_BLOCK_SIZE) {
        AES_ecb_encrypt(ciphertext + i, plaintext + i, &dec_key, AES_DECRYPT);
    }
}

// Add implementations for CBC, GCM, and CCM modes as per requirements
