public class DecryptionService
{
    public string DecryptMessage(string base64EncodedEncryptedMessage, byte[] key, byte[] iv)
    {
        using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
        {
            tripleDES.Key = key;
            tripleDES.IV = iv;
            tripleDES.Mode = CipherMode.CBC;
            tripleDES.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = tripleDES.CreateDecryptor();
            byte[] decryptedBytes = Convert.FromBase64String(base64EncodedEncryptedMessage);
            using (MemoryStream ms = new MemoryStream(decryptedBytes))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    using (StreamReader sr = new StreamReader(cs))
                    {
                        return sr.ReadToEnd();
                    }
                }
            }
        }
    }
}
