from flask import Flask, request, jsonify
import requests
from concurrent.futures import ThreadPoolExecutor
from ratelimiter import RateLimiter
from collections import defaultdict

app = Flask(__name__)

# Third-party payment gateway URLs
PAYMENT_GATEWAYS = {
    "stripe": "https://api.stripe.com/v1/charges",
    "paypal": "https://api.paypal.com/v2/payments/orders",
}

# Regional transaction processing thresholds
TRANSACTION_THRESHOLDS = {
    "US": 50,
    "EU": 30,
}

# Rate limiting configuration
rate_limiter = RateLimiter(max_calls=100, period=60)

# Transaction executor for asynchronous processing
executor = ThreadPoolExecutor(max_workers=10)

# Currency conversion rates (mock data)
CURRENCY_RATES = {
    "USD": {"EUR": 0.85, "GBP": 0.75},
}

@app.route('/process_transaction', methods=['POST'])
@rate_limiter.limit
def process_transaction():
    data = request.get_json()
    amount = data['amount']
    currency = data['currency']
    country_code = data['country_code']

    if currency not in CURRENCY_RATES:
        return jsonify({"error": "Unsupported currency"}), 400

    # Convert to USD for processing
    converted_amount = amount * CURRENCY_RATES[currency]['USD']

    # Select payment gateway based on regional thresholds and availability
    selected_gateway = None
    for gateway, url in PAYMENT_GATEWAYS.items():
        if TRANSACTION_THRESHOLDS[country_code] > 0:
            selected_gateway = gateway
            break

    if not selected_gateway:
        return jsonify({"error": "No available payment gateways"}), 503

    # Asynchronously process transaction
    future = executor.submit(process_payment, url, amount=converted_amount, currency="USD", country_code=country_code)

    return jsonify({"message": "Transaction processing started"}), 202

def process_payment(url, amount, currency, country_code):
    headers = {
        "Authorization": "Bearer API_KEY",
    }
    payload = {
        "amount": int(amount * 100),
        "currency": currency,
        # Add other required parameters for the payment gateway
    }

    try:
        response = requests.post(url, json=payload, headers=headers)
        response.raise_for_status()
        print("Transaction successful:", response.json())
    except requests.RequestException as e:
        print("Transaction failed:", str(e))
        raise

if __name__ == '__main__':
    app.run(debug=True)
```

