void init_sessions() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        sessions[i].status = 0; // Assuming all sessions are initially inactive
    }
}

void add_session(const char *ip, int port) {
    if (session_count >= MAX_SESSIONS) return;
    strcpy(sessions[session_count].ip, ip);
    sessions[session_count].port = port;
    sessions[session_count].last_active = time(NULL);
    sessions[session_count].status = 1; // Active session
    session_count++;
}

void update_session(int index) {
    if (index < 0 || index >= session_count) return;
    sessions[index].last_active = time(NULL);
}

int is_valid_session(int index, int current_time) {
    if (index < 0 || index >= session_count) return 0;
    if ((current_time - sessions[index].last_active) > SESSION_TIMEOUT) {
        sessions[index].status = 0; // Inactive session
        session_count--;
    }
    return sessions[index].status == 1;
}

void purge_old_sessions(int current_time) {
    for (int i = 0; i < session_count; ) {
        if (!is_valid_session(i, current_time)) {
            for (int j = i; j < session_count - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            session_count--;
        } else {
            i++;
        }
    }
}

