#include <curl/curl.h>

// Define a structure to hold user activity logs
struct UserActivityLog {
    // Define fields here, e.g., time, user_id, action
};

// Function to fetch data from the REST API asynchronously
void fetchData(const std::string& apiUrl, std::queue<UserActivityLog>& logQueue) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, apiUrl.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* contents, size_t size, size_t nmemb, void* userp){
            std::string *response = static_cast<std::string*>(userp);
            response->append(static_cast<char*>(contents), size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        // Perform the request
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

// Function to process user activity logs
void processLogs(std::queue<UserActivityLog>& logQueue, std::mutex& queueMutex, std::condition_variable& queueCond) {
    while(true) {
        std::unique_lock<std::mutex> lock(queueMutex);
        queueCond.wait(lock, []{ return !logQueue.empty(); });

        UserActivityLog log = logQueue.front();
        logQueue.pop();

        // Process the log
        // Example: Log to database or perform some analysis

        lock.unlock();
    }
}

int main() {
    std::queue<UserActivityLog> logQueue;
    std::mutex queueMutex;
    std::condition_variable queueCond;

    // Create multiple threads for fetching data asynchronously
    const int numThreads = 4;
    std::vector<std::thread> fetchThreads;
    std::vector<std::string> apiUrls = {"http://api.example.com/logs/1", "http://api.example.com/logs/2"};

    for(int i = 0; i < numThreads; ++i) {
        fetchThreads.emplace_back(fetchData, apiUrls[i % apiUrls.size()], std::ref(logQueue));
    }

    // Create a thread for processing logs
    std::thread processThread(processLogs, std::ref(logQueue), std::ref(queueMutex), std::ref(queueCond));

    // Join the threads
    for(auto& thread : fetchThreads) {
        thread.join();
    }
    processThread.join();

    return 0;
}
```

This code provides a basic structure for a C++ application that integrates with a third-party REST API to fetch, parse, and process user activity logs. It uses asynchronous I/O with libcurl for data retrieval and employs multi-threading to process logs concurrently. The use of a queue and condition variable ensures thread-safe access to the log data.

Please note that this code is a starting point and needs further development to meet the full requirements, including error handling, logging, monitoring, and other features as specified in the task description.']

