    for message in kafka_consumer:
        data = json.loads(message.value)
        if 'iot' in message.topic:
            transformed_data = transform_iot_data(data)
        elif 'social_media' in message.topic:
            transformed_data = transform_social_media_data(data)
        elif 'legacy_system' in message.topic:
            transformed_data = transform_legacy_system_data(data)

        try:
            store_data_in_postgres(transformed_data)
            kafka_producer.send('processed_topic', value=transformed_data.encode())
        except SQLAlchemyError as e:
            log_error(str(e))
            retry_function(store_data_in_redis, max_retries=5)

# Define the Flask app for configuration interface
