#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <memory>
#include <atomic>

struct NetworkEvent {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    std::string eventType;
    std::shared_ptr<void> metadata;
};

class EventProcessor {
public:
    using EventHandler = std::function<void(const NetworkEvent&)>;

    EventProcessor(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(queue_mutex);
                    condition.wait(lock, [this] { return stop || !eventQueue.empty(); });
                    if (stop && eventQueue.empty()) break;
                    NetworkEvent event = std::move(eventQueue.front());
                    eventQueue.pop();
                    lock.unlock();

                    processEvent(std::move(event));
                }
            });
        }
    }

    ~EventProcessor() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addEventHandler(EventHandler handler) {
        eventHandlers.push_back(handler);
    }

    void submitEvent(const NetworkEvent& event) {
        std::unique_lock<std::mutex> lock(queue_mutex);
        eventQueue.push(event);
        condition.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<NetworkEvent> eventQueue;
    std::vector<EventHandler> eventHandlers;
    std::mutex queue_mutex;
    std::condition_variable condition;
    std::atomic<bool> stop;

    void processEvent(NetworkEvent&& event) {
        for (const auto& handler : eventHandlers) {
            handler(event);
        }
    }
};

int main() {
    EventProcessor processor(4);

    processor.addEventHandler([](const NetworkEvent& event) {
        // Process with third-party messaging service
        std::cout << "Processing event with messaging service: " << event.eventType << std::endl;
    });

    processor.addEventHandler([](const NetworkEvent& event) {
        // Process with external analytics platform
        std::cout << "Processing event with analytics platform: " << event.eventType << std::endl;
    });

    processor.addEventHandler([](const NetworkEvent& event) {
        // Process with log aggregation tool
        std::cout << "Processing event with log aggregation: " << event.eventType << std::endl;
    });

    for (int i = 0; i < 100; ++i) {
        processor.submitEvent({std::chrono::system_clock::now(), "Event" + std::to_string(i), nullptr});
    }

    return 0;
}
