namespace NfapiLib {

class NfapiCrcIndicationHandler {
public:
    static NfapiCrcIndicationHandler& getInstance() {
        static NfapiCrcIndicationHandler instance;
        return instance;
    }

    void addUeInformation(const RX_UE_INFORMATION_TAG& ueInfo, RNTI rnti) {
        std::lock_guard<std::mutex> lock(mutex_);
        ueInfo_.push_back(ueInfo);
        rntis_.push_back(rnti);
        cv_.notify_one();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !ueInfo_.empty(); });

            NFAPI_CRC_INDICATION_PDU_T pdu;
            for (size_t i = 0; i < ueInfo_.size(); ++i) {
                pdu.UE_information_tag = ueInfo_[i];
                pdu.RNTI = rntis_[i];
                pdu.CRC_indication_rel8_tag.crcflag = randomGenerator_.rand() % 2;
                // Process PDU
            }

            ueInfo_.clear();
            rntis_.clear();
        }
    }

private:
