class GeoRecommendationLibrary {
public:
    GeoRecommendationLibrary(std::shared_ptr<RecommendationEngineAPI> api,
                              std::shared_ptr<LocationService> locationService,
                              std::shared_ptr<UserPreferenceCache> cache,
                              std::shared_ptr<OAuth2Manager> oauthManager)
        : api(api), locationService(locationService), cache(cache), oauthManager(oauthManager) {}

    void handleRequest(std::future<void>&& future, const LocationData& location, const UserPreferences& preferences) {
        // Handle real-time location updates and user preference caching
        locationService->updateLocation(location);
        cache->cachePreferences(userID, preferences);

        // Fetch recommendations asynchronously
        auto recommendationPromise = std::make_shared<std::promise<std::vector<ContentItem>>>();
        auto recommendationFuture = recommendationPromise->get_future();
        std::thread([=]() {
            try {
                std::lock_guard<std::mutex> lock(cacheMutex);
                auto cachedPreferences = cache->getCachedPreferences(userID);
                if (cachedPreferences) {
                    auto recommendations = api->fetchRecommendations(location, *cachedPreferences);
                    recommendationPromise->set_value(recommendations);
