                    recommendationPromise->set_exception(std::make_exception_ptr<std::runtime_error>("No preferences found"));
                }
            } catch (...) {
                recommendationPromise->set_exception(std::current_exception());
            }
        }).detach();

        // Combine with existing future
        future = std::async(std::launch::deferred, [=]() -> void {
            try {
                auto recommendations = recommendationFuture.get();
                // Process and return recommendations to the client
                processRecommendations(recommendations);
