# Import necessary libraries
import json
from typing import Any, Dict

class CustomDataSerializer:
    """
    A utility to serialize and deserialize custom data structures to JSON format.
    Supports nested objects and arrays, flexible schema validation, and error handling.
    """

    def __init__(self, schema: Dict[str, str] = None):
        self.schema = schema or {}

    def serialize(self, data: Any) -> str:
        """
        Serialize a custom data structure to a JSON string.

        :param data: The custom data structure to serialize
        :return: A JSON-formatted string
        """
        try:
            return json.dumps(data)
        except (TypeError, OverflowError) as e:
            raise ValueError(f"Error serializing data: {e}")

    def deserialize(self, json_str: str) -> Any:
        """
        Deserialize a JSON string to a custom data structure.

        :param json_str: The JSON-formatted string
        :return: The deserialized custom data structure
        """
        try:
            data = json.loads(json_str)
            self.validate_data(data)
            return data
        except (json.JSONDecodeError, ValueError) as e:
            raise ValueError(f"Error deserializing JSON: {e}")

    def validate_data(self, data: Any):
        """
        Validate the data structure against the defined schema.

        :param data: The custom data structure to validate
        """
        for key, value_type in self.schema.items():
            if key not in data:
                raise ValueError(f"Missing required field '{key}'")
            elif not isinstance(data[key], eval(value_type)):
                raise ValueError(f"Incorrect type for '{key}'. Expected {value_type}, got {type(data[key])}")

# Example usage
if __name__ == "__main__":
    schema = {
        "name": "str",
        "age": "int",
        "email": "str"
    }

    serializer = CustomDataSerializer(schema)

    data = {
        "name": "John Doe",
        "age": 30,
        "email": "john.doe@example.com"
    }

    json_str = serializer.serialize(data)
    print("Serialized JSON:", json_str)

    deserialized_data = serializer.deserialize(json_str)
    print("Deserialized Data:", deserialized_data)
