// Event processing function
void processEvent(const Event& event) {
    // Simulate event processing logic
    std::cout << "Processing event: " << event.eventType << " for session: " << event.sessionID << std::endl;
}

// Message queue for decoupling ingestion and processing
class MessageQueue {
private:
    std::queue<Event> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;

public:
    void enqueue(const Event& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(event);
        cv_.notify_one();
    }

    void dequeue(Event& event) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !queue_.empty(); });
        event = queue_.front();
        queue_.pop();
    }
};

// Event processor thread function
void processorThread(MessageQueue& queue) {
    Event event;
    while (true) {
        queue.dequeue(event);
        processEvent(event);
    }
}

int main() {
    const int numThreads = 4;
    MessageQueue queue;

    // Start processor threads
    std::vector<std::thread> processors(numThreads);
    for (auto& t : processors) {
        t = std::thread(processorThread, std::ref(queue));
    }

    // Simulate event ingestion
    for (int i = 0; i < 10; ++i) {
        Event event = {"timestamp" + std::to_string(i), "eventType" + std::to_string(i), "sessionID" + std::to_string(i)};
        queue.enqueue(event);
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
    }

    // Join processor threads
    for (auto& t : processors) {
        t.join();
    }

    return 0;
}
