        {
            _logger = logger;
            _blobServiceClient = blobServiceClient;
            _cacheManager = cacheManager;
        }

        public async Task EncryptFileAsync(string filePath, string containerName, CancellationToken cancellationToken = default)
        {
            try
            {
                var key = GetEncryptionKey();
                var iv = GenerateIV();
                var paddingScheme = GetPaddingScheme();

                using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                {
                    var encryptedFileStream = await EncryptAsync(fileStream, key, iv, paddingScheme, cancellationToken);
                    await UploadToBlobAsync(containerName, filePath, encryptedFileStream, cancellationToken);
                }

                _logger.LogInformation($"Encryption completed for {filePath}");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error encrypting file: {filePath}");
            }
        }

        public async Task DecryptFileAsync(string containerName, string blobName, string outputFilePath, CancellationToken cancellationToken = default)
        {
            try
            {
                using (var encryptedFileStream = await DownloadFromBlobAsync(containerName, blobName, cancellationToken))
                using (var outputStream = new FileStream(outputFilePath, FileMode.Create, FileAccess.Write))
                {
                    var key = GetEncryptionKey();
                    var iv = ReadIVFromMetadata(encryptedFileStream);
                    var paddingScheme = GetPaddingScheme();

                    await DecryptAsync(encryptedFileStream, outputStream, key, iv, paddingScheme, cancellationToken);
                }

                _logger.LogInformation($"Decryption completed for {blobName}");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error decrypting file: {blobName}");
            }
        }

        private byte[] GetEncryptionKey()
        {
            // Retrieve key from environment variable or configuration
            return Convert.FromBase64String(Environment.GetEnvironmentVariable("ENCRYPTION_KEY"));
        }

        private byte[] GenerateIV()
        {
            using (var rng = new RNGCryptoServiceProvider())
            {
                var iv = new byte[16];
                rng.GetBytes(iv);
                return iv;
            }
        }

        private PaddingMode GetPaddingScheme()
        {
            // Retrieve padding scheme from environment variable or configuration
            var paddingModeStr = Environment.GetEnvironmentVariable("PADDING_MODE") ?? "PKCS7";
            return (PaddingMode)Enum.Parse(typeof(PaddingMode), paddingModeStr, true);
        }

        private async Task<MemoryStream> EncryptAsync(Stream input, byte[] key, byte[] iv, PaddingMode paddingScheme, CancellationToken cancellationToken = default)
        {
            var encryptedStream = new MemoryStream();
            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                aes.Padding = paddingScheme;

                using (var encryptor = aes.CreateEncryptor())
                using (var cs = new CryptoStream(encryptedStream, encryptor, CryptoStreamMode.Write))
                {
                    await input.CopyToAsync(cs, cancellationToken);
                }
            }

            return encryptedStream;
        }

        private async Task<MemoryStream> DecryptAsync(Stream input, Stream output, byte[] key, byte[] iv, PaddingMode paddingScheme, CancellationToken cancellationToken = default)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                aes.Padding = paddingScheme;

                using (var decryptor = aes.CreateDecryptor())
                using (var cs = new CryptoStream(input, decryptor, CryptoStreamMode.Read))
                {
                    await cs.CopyToAsync(output, cancellationToken);
                }
            }

            return output as MemoryStream;
        }

        private async Task<MemoryStream> DownloadFromBlobAsync(string containerName, string blobName, CancellationToken cancellationToken = default)
        {
            var containerClient = _blobServiceClient.GetBlobContainerClient(containerName);
            var blobClient = containerClient.GetBlobClient(blobName);

            using (var downloadResponse = await blobClient.DownloadAsync(cancellationToken))
            {
                return new MemoryStream(await downloadResponse.Content.ReadAsByteArrayAsync());
            }
        }

        private async Task UploadToBlobAsync(string containerName, string filePath, Stream content, CancellationToken cancellationToken = default)
        {
            var containerClient = _blobServiceClient.GetBlobContainerClient(containerName);
            var blobClient = containerClient.GetBlobClient(Path.GetFileName(filePath));

            await blobClient.UploadAsync(content, overwrite: true, cancellationToken: cancellationToken);

            // Store IV in blob metadata for later decryption
            await blobClient.SetMetadataAsync(new Dictionary<string, string>
            {
                { "iv", Convert.ToBase64String(GenerateIV()) }
            }, cancellationToken);
        }

        private byte[] ReadIVFromMetadata(Stream encryptedFileStream)
        {
            // Implement logic to read IV from metadata of the encrypted file
            return new byte[16]; // Placeholder for actual implementation
        }
    }
}
