import java.util.*;
import java.io.*;
import java.nio.file.*;
import org.apache.kafka.clients.producer.*;
import org.apache.avro.Schema;
import org.apache.avro.generic.GenericRecord;
import org.apache.avro.generic.GenericDatumReader;
import org.apache.avro.file.DataFileWriter;

public class IOTDataPipeline {

    private static final String KAFKA_BROKER = "localhost:9092";
    private static final String KAFKA_TOPIC = "iot_data_topic";
    private static final String DATA_WAREHOUSE_URL = "jdbc:mysql://localhost:3306/data_warehouse";
    private static final String USERNAME = "user";
    private static final String PASSWORD = "password";

    public static void main(String[] args) {
        Properties props = new Properties();
        props.put("bootstrap.servers", KAFKA_BROKER);
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "io.confluent.kafka.serializers.KafkaAvroSerializer");

        Producer<String, GenericRecord> producer = new KafkaProducer<>(props);

        // Example: Consume data from IoT devices and process it
        List<GenericRecord> records = consumeIOTData();
        for (GenericRecord record : records) {
            processAndLoadData(record);
        }

        producer.close();
    }

    private static List<GenericRecord> consumeIOTData() {
        // Simulate data consumption from IoT devices
        return Arrays.asList(createSampleRecord(), createSampleRecord());
    }

    private static GenericRecord createSampleRecord() {
        Schema schema = getDynamicSchema();
        GenericRecord record = new GenericData.Record(schema);
        // Populate the record with sample data
        record.put("sensor_id", "12345");
        record.put("timestamp", System.currentTimeMillis());
        record.put("value", 42.0);
        return record;
    }

    private static Schema getDynamicSchema() {
        // Simulate dynamic schema retrieval
        Schema.Parser parser = new Schema.Parser();
        try (InputStream reader = Files.newInputStream(Paths.get("schema.avsc"))) {
            return parser.parse(new InputStreamReader(reader));
        } catch (IOException e) {
            throw new RuntimeException("Failed to load schema", e);
        }
    }

    private static void processAndLoadData(GenericRecord record) {
        // Process data
        String sensorId = record.get("sensor_id").toString();
        long timestamp = (long) record.get("timestamp");
        double value = (double) record.get("value");

        // Load data into cloud-based data warehouse
        try (Connection connection = DriverManager.getConnection(DATA_WAREHOUSE_URL, USERNAME, PASSWORD)) {
            String sql = "INSERT INTO iot_data (sensor_id, timestamp, value) VALUES (?, ?, ?)";
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setString(1, sensorId);
                statement.setLong(2, timestamp);
                statement.setDouble(3, value);
                statement.executeUpdate();
            }
        } catch (SQLException e) {
            // Handle database exceptions
            System.err.println("Error loading data into data warehouse: " + e.getMessage());
        }

        // Log the processed data for auditing and monitoring
        System.out.println("Processed data: Sensor ID = " + sensorId + ", Timestamp = " + timestamp + ", Value = " + value);
    }
}
