// Data ingestion pipeline class
public class DataIngestionPipeline {
    private List<DataSource> sources;
    private StorageSystem storage;

    public DataIngestionPipeline(List<DataSource> sources, StorageSystem storage) {
        this.sources = sources;
        this.storage = storage;
    }

    public void startPipeline() {
        for (DataSource source : sources) {
            new Thread(() -> source.ingestData()).start();
        }
    }

    private class DataProcessor implements Runnable {
        @Override
        public void run() {
            while (true) {
                // Code to process data and store in storage system
                try {
                    // Simulate data processing
                    Thread.sleep(100);
                    storage.storeData("Processed data");
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    public void addDataSource(DataSource source) {
        sources.add(source);
    }

    public void removeDataSource(DataSource source) {
        sources.remove(source);
    }
}

// Example usage
public class Main {
    public static void main(String[] args) {
        DataSource restApiSource = new RESTAPIDataSource();
        DataSource messageQueueSource = new MessageQueueDataSource();
        StorageSystem storage = new CentralizedStorage();

        DataIngestionPipeline pipeline = new DataIngestionPipeline(
            Arrays.asList(restApiSource, messageQueueSource), storage
        );

        pipeline.startPipeline();
    }
}
