using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Azure.Storage.Blobs; // Placeholder for actual cloud storage service integration

public interface ICryptoService
{
    byte[] Encrypt(byte[] data, byte[] key, byte[] iv);
    byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv);
}

public class AesCryptoService : ICryptoService
{
    public byte[] Encrypt(byte[] data, byte[] key, byte[] iv)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msEncrypt = new MemoryStream())
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    csEncrypt.Write(data, 0, data.Length);
                }
                return msEncrypt.ToArray();
            }
        }
    }

    public byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream ms = new MemoryStream())
                    {
                        csDecrypt.CopyTo(ms);
                        return ms.ToArray();
                    }
                }
            }
        }
    }
}

public interface ICloudStorageService
{
    Task UploadAsync(string containerName, string blobName, byte[] data);
    Task<byte[]> DownloadAsync(string containerName, string blobName);
}

public class AzureBlobStorageService : ICloudStorageService
{
    private readonly BlobContainerClient _containerClient;

    public AzureBlobStorageService(BlobServiceClient blobServiceClient, string containerName)
    {
        _containerClient = blobServiceClient.GetBlobContainerClient(containerName);
    }

    public async Task UploadAsync(string blobName, byte[] data)
    {
        var blobClient = _containerClient.GetBlobClient(blobName);
        await blobClient.UploadAsync(new MemoryStream(data), overwrite: true);
    }

    public async Task<byte[]> DownloadAsync(string blobName)
    {
        var blobClient = _containerClient.GetBlobClient(blobName);
        var downloadResponse = await blobClient.DownloadAsync();
        using (Stream stream = await downloadResponse.Value.Content.ReadAsStreamAsync())
        using (MemoryStream memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            return memoryStream.ToArray();
        }
    }
}

public class CryptoServiceManager
{
    private readonly ICryptoService _cryptoService;
    private readonly ICloudStorageService _cloudStorageService;
    private readonly ILogger<CryptoServiceManager> _logger;

    public CryptoServiceManager(ICryptoService cryptoService, ICloudStorageService cloudStorageService, ILogger<CryptoServiceManager> logger)
    {
        _cryptoService = cryptoService;
        _cloudStorageService = cloudStorageService;
        _logger = logger;
    }

    public async Task UploadEncryptedDocumentAsync(string containerName, string blobName, byte[] documentData, byte[] key, byte[] iv)
    {
        try
        {
            var encryptedData = _cryptoService.Encrypt(documentData, key, iv);
            await _cloudStorageService.UploadAsync(containerName, blobName, encryptedData);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to upload encrypted document.");
            throw;
        }
    }

    public async Task<byte[]> DownloadDecryptedDocumentAsync(string containerName, string blobName, byte[] key, byte[] iv)
    {
        try
        {
            var encryptedData = await _cloudStorageService.DownloadAsync(containerName, blobName);
            return _cryptoService.Decrypt(encryptedData, key, iv);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to download decrypted document.");
            throw;
        }
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var config = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json")
            .Build();

        var loggerFactory = LoggerFactory.Create(builder =>
        {
            builder.AddConsole();
        });

        var cryptoService = new AesCryptoService();
        var cloudStorageService = new AzureBlobStorageService(new BlobServiceClient(config["AzureBlobStorage:ConnectionString"]), config["AzureBlobStorage:ContainerName"]);
        var cryptoServiceManager = new CryptoServiceManager(cryptoService, cloudStorageService, loggerFactory.CreateLogger<CryptoServiceManager>());

        byte[] documentData = File.ReadAllBytes("document.txt");
        byte[] key = GenerateKey();
        byte[] iv = GenerateIV();

        await cryptoServiceManager.UploadEncryptedDocumentAsync("documents", "sample.txt", documentData, key, iv);

        var decryptedData = await cryptoServiceManager.DownloadDecryptedDocumentAsync("documents", "sample.txt", key, iv);
        File.WriteAllBytes("decrypted_document.txt", decryptedData);
    }

    private static byte[] GenerateKey()
    {
        using (Aes aesAlg = Aes.Create())
        {
            return aesAlg.Key;
        }
    }

    private static byte[] GenerateIV()
    {
        using (Aes aesAlg = Aes.Create())
        {
            return aesAlg.IV;
        }
    }
}
