// Worker function for processing sensor data
void processSensorData(std::queue<SensorData>& dataQueue) {
    while (true) {
        std::unique_lock<std::mutex> lock(dataQueueMutex);
        dataQueueCondition.wait(lock, []{ return !dataQueue.empty(); });
        SensorData data = dataQueue.front();
        dataQueue.pop();
        lock.unlock();

        // Process the sensor data
    }
}

int main() {
    // Create a queue to hold incoming sensor data
    std::queue<SensorData> sensorDataQueue;
    std::mutex dataQueueMutex;
    std::condition_variable dataQueueCondition;

    // Start multiple worker threads for processing data
    std::vector<std::thread> workers;
    const int numWorkers = 10;
    for (int i = 0; i < numWorkers; ++i) {
        workers.emplace_back(processSensorData, std::ref(sensorDataQueue));
    }

    // Simulate receiving sensor data and pushing it into the queue
    while (true) {
        SensorData newData;
        // Receive new data from various sources
        std::lock_guard<std::mutex> lock(dataQueueMutex);
        sensorDataQueue.push(newData);
        dataQueueCondition.notify_one();
    }

    // Join all worker threads
    for (auto& worker : workers) {
        worker.join();

    return 0;
}
