#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <atomic>
#include <future>
#include <algorithm>

class UserActivityProcessor {
public:
    UserActivityProcessor(const std::string& apiUrl, int numThreads)
        : apiUrl(apiUrl), numThreads(numThreads) {}

    void startProcessing() {
        // Initialize threads and task queue
        for (int i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back(&UserActivityProcessor::workerThread, this);
        }

        // Main processing loop
        while (true) {
            std::unique_lock<std::mutex> lock(taskQueueMutex);
            taskQueueCondition.wait(lock, [this] { return !taskQueue.empty() || stopProcessing; });
            if (!stopProcessing && !taskQueue.empty()) {
                auto task = std::move(taskQueue.front());
                taskQueue.pop();
                lock.unlock();

                // Submit task to a worker thread
                workThreadPool.submit([this, task]() { task(); });
            }
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(taskQueueMutex);
            stopProcessing = true;
        }
        taskQueueCondition.notify_all();
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

private:
    void workerThread() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(taskQueueMutex);
                taskQueueCondition.wait(lock, [this] { return !taskQueue.empty() || stopProcessing; });
                if (!stopProcessing && !taskQueue.empty()) {
                    task = std::move(taskQueue.front());
                    taskQueue.pop();
                } else {
                    return;
                }
            }
            task();
        }
    }

    const std::string apiUrl;
    int numThreads;
    std::vector<std::thread> workerThreads;
    std::queue<std::function<void()>> taskQueue;
    std::mutex taskQueueMutex;
    std::condition_variable taskQueueCondition;
    std::atomic<bool> stopProcessing{false};
    std::thread workThreadPool;
};

int main() {
    UserActivityProcessor processor("https://api.example.com/useractivity", 10);
    processor.startProcessing();
    // ... (stop processing when done)
    processor.stop();
    return 0;
}
