import java.util.*;
import java.lang.*;

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]);
        }
        return parent[p];
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);

        if (rootP == rootQ) return;

        if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = rootP;
        } else if (rank[rootP] < rank[rootQ]) {
            parent[rootP] = rootQ;
        } else {
            parent[rootQ] = rootP;
            rank[rootP]++;
        }
    }

    public boolean areDisjoint(int p, int q) {
        return find(p) != find(q);
    }
}

public class DisjointPairCounter {

    public static void countDisjointPairs(int[] array) {
        if (array == null || array.length < 2) {
            System.out.println("Array must contain at least two elements.");
            return;
        }

        UnionFind uf = new UnionFind(array.length);
        long startTime, endTime;

        for (int i = 0; i < array.length - 1; i++) {
            startTime = System.currentTimeMillis();
            for (int j = i + 1; j < array.length; j++) {
                if (uf.areDisjoint(i, j)) {
                    uf.union(i, j);
                }
            }
            endTime = System.currentTimeMillis();
            System.out.println("Pair (" + array[i] + ", " + array[j] + ") took: " + (endTime - startTime) + " ms");
        }
    }

    public static void main(String[] args) {
        int[] array = {1, 2, 3, 4, 5};
        countDisjointPairs(array);
    }
}
