#include <memory>
#include <atomic>
#include <string>
#include <chrono>
#include <algorithm>

enum class Severity {
    DEBUG, INFO, WARNING, ERROR
};

class Logger {
public:
    void log(Severity severity, const char* message, ...) {
        va_list args;
        va_start(args, message);
        vlog(severity, message, args);
        va_end(args);
    }

    void setThreshold(Severity level) {
        threshold = level;
    }

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::tuple<Severity, std::string>> queue_;
    std::atomic<bool> running_{true};
    Severity threshold{Severity::DEBUG};

    void worker() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !queue_.empty() || !running_; });
            if (!running_ && queue_.empty()) break;

            auto [severity, message] = queue_.front();
            queue_.pop();
            lock.unlock();

            if (severity >= threshold) {
                // Log to console for demonstration
                std::cout << "[" << severityToString(severity) << "] " << message << std::endl;
            }
        }
    }

    void vlog(Severity severity, const char* message, va_list args) {
        std::string formatted_message = formatMessage(message, args);
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push({severity, formatted_message});
        cv_.notify_one();
    }

    std::string formatMessage(const char* message, va_list args) {
        // Implement string formatting using vsnprintf
        return "";
    }

    std::string severityToString(Severity severity) {
        switch (severity) {
            case Severity::DEBUG: return "DEBUG";
            case Severity::INFO: return "INFO";
            case Severity::WARNING: return "WARNING";
            case Severity::ERROR: return "ERROR";
            default: return "UNKNOWN";
        }
    }

public:
    Logger() {
        std::thread t(&Logger::worker, this);
        t.detach();
    }

    ~Logger() {
        running_ = false;
        cv_.notify_all();
    }
};

int main() {
    Logger logger;
    logger.setThreshold(Severity::INFO);

    logger.log(Severity::DEBUG, "This is a debug message.");
    logger.log(Severity::INFO, "This is an info message.");
    logger.log(Severity::WARNING, "This is a warning message.");
    logger.log(Severity::ERROR, "This is an error message.");

    return 0;
}
