function asyncReduce(arr, initialValue, reducerCallback, callback) {
  let accumulator = initialValue;
  const index = arr.length - 1;

  function processElement(i) {
    if (i < 0) {
      callback(null, accumulator);
      return;
    }

    reducerCallback(accumulator, arr[i], (err, result) => {
      if (err) {
        callback(err, null);
        return;
      }
      accumulator = result;
      processElement(i - 1);
    });
  }

  processElement(index);
}
