use std::fs;
use std::io::{self, Write};
use rusty_lexer::{Lexer, Token};
use rusty_parser::{Parser, Node};

fn generate_ir(file_path: &str) -> io::Result<()> {
    let content = fs::read_to_string(file_path)?;
    let mut lexer = Lexer::new(&content);
    let tokens: Vec<Token> = lexer.lex();

    for token in &tokens {
        println!("{:?}", token);
    }

    let mut parser = Parser::new(tokens);
    let nodes: Vec<Node> = parser.parse();

    for node in &nodes {
        println!("{:?}", node);
    }

    let mut ir_file = fs::File::create("output.ll")?;
    writeln!(ir_file, "; ModuleID = 'generated_ir'")?;

    for node in nodes {
        match node {
            Node::Function(func) => {
                writeln!(ir_file, "{}", func.to_ir())?;
            }
            _ => {}
        }
    }

    Ok(())
}

fn main() -> io::Result<()> {
    generate_ir("input.grammar")?;
    Ok(())
}
```

Note: This code assumes the existence of `rusty_lexer` and `rusty_parser` crates for tokenizing and parsing, respectively. The `Node` struct is assumed to have a method `to_ir()` that generates LLVM IR code. Debugging statements print the parsed tokens and nodes, and the generated LLVM IR is written to a file named "output.ll".']

