```c
// C Code Block (Network Event Logger System)

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_CONCURRENT_EVENTS 100

typedef struct {
    int priority;
    char *event_data;
} Event;

Event event_queue[MAX_CONCURRENT_EVENTS];
int front = -1, rear = -1;

sem_t queue_mutex;
sem_t space_sem;
sem_t item_sem;

void* log_event(void* arg) {
    while (1) {
        sem_wait(&item_sem);
        sem_wait(&queue_mutex);

        // Log event
        printf("Logging event: %s\n", event_queue[front].event_data);

        front = (front + 1) % MAX_CONCURRENT_EVENTS;

        sem_post(&queue_mutex);
        sem_post(&space_sem);
    }
    return NULL;
}

void enqueue_event(Event event) {
    sem_wait(&space_sem);
    sem_wait(&queue_mutex);

    rear = (rear + 1) % MAX_CONCURRENT_EVENTS;
    event_queue[rear] = event;

    sem_post(&queue_mutex);
    sem_post(&item_sem);
}

int main() {
    pthread_t logger_thread;
    Event event;

    // Initialize semaphores
    sem_init(&queue_mutex, 0, 1);
    sem_init(&space_sem, 0, MAX_CONCURRENT_EVENTS);
    sem_init(&item_sem, 0, 0);

    // Create logger thread
    pthread_create(&logger_thread, NULL, log_event, NULL);

    // Enqueue events
    event.priority = 1;
    event.event_data = "Event 1";
    enqueue_event(event);

    event.priority = 2;
    event.event_data = "Event 2";
    enqueue_event(event);

    // Join logger thread
    pthread_join(logger_thread, NULL);

    // Destroy semaphores
    sem_destroy(&queue_mutex);
    sem_destroy(&space_sem);
    sem_destroy(&item_sem);

    return 0;
}
