    async fn update_resource(&self, api_key: &str, resource_id: &str, data: String) -> Result<(), Error> {
        let client = self.get_client(api_key).await?;
        let response = client.put(format!("{}/{}", self.config_cache.lock().unwrap()[api_key].endpoint, resource_id))
            .json(&data)
            .send()
            .await?
            .error_for_status()?;
        response.json::<()>().await.map_err(Into::into)
    }

    async fn delete_resource(&self, api_key: &str, resource_id: &str) -> Result<(), Error> {
        let client = self.get_client(api_key).await?;
        let response = client.delete(format!("{}/{}", self.config_cache.lock().unwrap()[api_key].endpoint, resource_id))
            .send()
            .await?
            .error_for_status()?;
        response.json::<()>().await.map_err(Into::into)
    }

    async fn get_client(&self, api_key: &str) -> Result<Arc<Client>, Error> {
        let mut cache = self.config_cache.lock().unwrap();
        if !cache.contains_key(api_key) {
            // Simulate fetching configuration from a dynamic source
            let config = ApiConfiguration {
                endpoint: "https://api.example.com".to_string(),
                auth_method: AuthMethod::Bearer("token".to_string()),
            };
            cache.insert(api_key.to_string(), config);
        }
        if !self.clients.contains_key(api_key) {
            let client = Arc::new(Client::builder()
                .default_headers({
                    let mut headers = reqwest::header::HeaderMap::new();
                    match &cache[api_key].auth_method {
                        AuthMethod::Basic(username, password) => {
                            let credentials = format!("{}:{}", username, password);
                            let auth_header = base64::encode(credentials);
                            headers.insert(reqwest::header::AUTHORIZATION, 
                                          reqwest::header::HeaderValue::from_str(&format!("Basic {}", auth_header)).unwrap());
                        },
                        AuthMethod::Bearer(token) => {
                            headers.insert(reqwest::header::AUTHORIZATION, 
                                          reqwest::header::HeaderValue::from_str(&format!("Bearer {}", token)).unwrap());
                        },
                        _ => (),
                    }
                    headers
                })
                .build()?);
            self.clients.insert(api_key.to_string(), client.clone());
        }
        Ok(self.clients[api_key].clone())
    }
}

#[derive(Debug)]
enum Error {
    ReqwestError(ReqwestError),
    // Add other custom error types here
}

impl From<ReqwestError> for Error {
    fn from(err: ReqwestError) -> Self {
        Error::ReqwestError(err)
    }
}
