def rate_limit(max_calls, period):
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            key = f"{request.remote_addr}-{f.__name__}"
            if not g.get('rate_limits', {}).get(key):
                g.rate_limits[key] = {'calls': 1, 'timestamp': time.time()}
            else:
                g.rate_limits[key]['calls'] += 1

            elapsed_time = time.time() - g.rate_limits[key]['timestamp']
            if elapsed_time > period:
                g.rate_limits[key]['calls'] = 1
                g.rate_limits[key]['timestamp'] = time.time()

            if g.rate_limits[key]['calls'] > max_calls:
                return jsonify({'error': 'Rate limit exceeded'}), 429

            return f(*args, **kwargs)
        return decorated_function
    return decorator

