class AuthService {
    private $providers = [];

    public function __construct() {
        // Initialize OAuth providers
        $this->providers['google'] = new Google([
            'clientId' => GOOGLE_OAUTH_ID,
            'clientSecret' => GOOGLE_OAUTH_SECRET,
            'redirectUri' => 'http://yourdomain.com/auth/callback/google',
        ]);

        $this->providers['facebook'] = new Facebook([
            'clientId' => FACEBOOK_OAUTH_ID,
            'clientSecret' => FACEBOOK_OAUTH_SECRET,
            'redirectUri' => 'http://yourdomain.com/auth/callback/facebook',
        ]);

        $this->providers['microsoft'] = new Microsoft([
            'clientId' => MICROSOFT_OAUTH_ID,
            'clientSecret' => MICROSOFT_OAUTH_SECRET,
            'redirectUri' => 'http://yourdomain.com/auth/callback/microsoft',
        ]);
    }

    public function getAuthorizationUrl($provider) {
        return $this->providers[$provider]->getAuthorizationUrl();
    }

    public function handleCallback($provider, $code) {
        try {
            // Get access token
            $token = $this->providers[$provider]->getAccessToken('authorization_code', [
                'code' => $code,
            ]);

            // Fetch user profile information
            $user = $this->providers[$provider]->getResourceOwner($token);

            return $user;
        } catch (\Exception $e) {
            // Handle errors (e.g., rate limiting, invalid token)
            return false;
        }
    }

    public function invalidateToken($provider, $accessToken) {
        try {
            $this->providers[$provider]->revokeAccessToken($accessToken);
            return true;
        } catch (\Exception $e) {
            return false;
        }
    }
}

// Usage example
$authService = new AuthService();
echo '<a href="' . $authService->getAuthorizationUrl('google') . '">Login with Google</a>';

