    @cached(cache=TTLCache(maxsize=100, ttl=cache_lifespan))
    def get_schema_version(self, schema_name):
        if not self.schema_versions[schema_name]['outdated']:
            return self.schema_versions[schema_name]['version']
        else:
            # Refresh the schema version
            self.schema_versions[schema_name]['version'] = self.refresh_schema(schema_name)
            return self.schema_versions[schema_name]['version']

    def refresh_schema(self, schema_name):
