// Define Event structure
struct Event {
    std::string timestamp;
    std::string eventType;
    std::string metadata;
};

// Event processing function prototype
void processEvent(const Event& event);

// Worker thread function to handle events
void worker(std::queue<Event>& eventQueue, std::mutex& queueMutex, std::condition_variable& queueCond, std::atomic<bool>& running) {
    while (true) {
        std::unique_lock<std::mutex> lock(queueMutex);
        queueCond.wait(lock, [&running] { return !running || !eventQueue.empty(); });
        if (!running && eventQueue.empty()) break;

        Event event = eventQueue.front();
        eventQueue.pop();
        lock.unlock();

        processEvent(event); // Process the event
    }
}

// Function to start the event processing pipeline
void startEventProcessingPipeline(int numWorkers) {
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable queueCond;
    std::atomic<bool> running(true);

    std::vector<std::thread> workers;
    for (int i = 0; i < numWorkers; ++i) {
        workers.emplace_back(worker, std::ref(eventQueue), std::ref(queueMutex), std::ref(queueCond), std::ref(running));
    }

    // Example of enqueuing events
    eventQueue.push({"2023-04-01T12:00:00", "TypeA", "Metadata1"});
    queueCond.notify_all();

    // Stop the workers gracefully
    running = false;
    for (auto& worker : workers) {
        worker.join();
    }
}

