void generate_and_store_pdu(NFAPI_CRC_INDICATION_PDU_T *pdus, int num_pdus) {
    srand(time(NULL));
    sqlite3 *db;
    char *err_msg = 0;

    // Initialize SQLite database
    if (sqlite3_open("nfapi_crc.db", &db)) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
    }

    // Create table if not exists
    const char *create_table_sql = 
        "CREATE TABLE IF NOT EXISTS PDUS ("
        "ID INTEGER PRIMARY KEY AUTOINCREMENT, "
        "RX_UE_INFORMATION_TAG INT, "
        "RNTI INT, "
        "CRC_INDICATION_REL8_TAG INT);";
    sqlite3_exec(db, create_table_sql, 0, 0, &err_msg);
    if (err_msg != 0) {
        fprintf(stderr, "SQL error: %s\n", err_msg);
        sqlite3_free(err_msg);
    }

    // Insert PDUs into the database
    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdus[i].RNTI = rand() % 500;
        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0);

