#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_EVENTS 1024
#define MAX_EVENT_SIZE 256

typedef struct {
    char timestamp[MAX_EVENT_SIZE];
    char type[MAX_EVENT_SIZE];
    void* metadata;
} Event;

Event event_queue[MAX_EVENTS];
int head = 0, tail = 0, count = 0;
pthread_mutex_t queue_lock;
pthread_cond_t not_empty, not_full;

void initialize_event_pipeline() {
    pthread_mutex_init(&queue_lock, NULL);
    pthread_cond_init(&not_empty, NULL);
    pthread_cond_init(&not_full, NULL);
}

void enqueue_event(Event event) {
    pthread_mutex_lock(&queue_lock);
    while (count == MAX_EVENTS) {
        pthread_cond_wait(&not_full, &queue_lock);
    }
    event_queue[tail] = event;
    tail = (tail + 1) % MAX_EVENTS;
    count++;
    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&queue_lock);
}

Event dequeue_event() {
    Event event;
    pthread_mutex_lock(&queue_lock);
    while (count == 0) {
        pthread_cond_wait(&not_empty, &queue_lock);
    }
    event = event_queue[head];
    head = (head + 1) % MAX_EVENTS;
    count--;
    pthread_cond_signal(&not_full);
    pthread_mutex_unlock(&queue_lock);
    return event;
}

void* process_events(void* arg) {
    while (1) {
        Event event = dequeue_event();
        // Process the event here
        printf("Processed event: %s\n", event.type);
    }
    return NULL;
}

int main() {
    initialize_event_pipeline();

    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, process_events, NULL);
    }

    // Simulate enqueuing events
    for (int i = 0; i < MAX_EVENTS; i++) {
        Event event;
        snprintf(event.timestamp, MAX_EVENT_SIZE, "Timestamp-%d", i);
        snprintf(event.type, MAX_EVENT_SIZE, "Type-%d", i % 10);
        event.metadata = NULL; // Set metadata if needed
        enqueue_event(event);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

