#define QUEUE_SIZE 1024

typedef struct {
    mqd_t queue;
    pthread_mutex_t lock;
} MessageQueue;

MessageQueue* create_message_queue(const char* name) {
    MessageQueue* queue = malloc(sizeof(MessageQueue));
    queue->queue = mq_open(name, O_CREAT | O_RDWR, 0666, NULL);
    if (queue->queue == -1) {
        perror("mq_open");
        free(queue);
        return NULL;
    }
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void destroy_message_queue(MessageQueue* queue) {
    mq_close(queue->queue);
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

void enqueue(MessageQueue* queue, const char* message) {
    pthread_mutex_lock(&queue->lock);
    mq_send(queue->queue, message, strlen(message), 0);
    pthread_mutex_unlock(&queue->lock);
}

void dequeue(MessageQueue* queue, char* buffer, size_t max_size) {
    pthread_mutex_lock(&queue->lock);
    mq_receive(queue->queue, buffer, max_size, NULL);
    pthread_mutex_unlock(&queue->lock);
}
