['```cpp
// EventProcessor.h
#pragma once

#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <functional>
#include <atomic>

class Event {
public:
    Event(int timestamp, std::string metadata, std::string payload)
        : timestamp(timestamp), metadata(metadata), payload(payload) {}

    int getTimestamp() const { return timestamp; }
    std::string getMetadata() const { return metadata; }
    std::string getPayload() const { return payload; }

private:
    int timestamp;
    std::string metadata;
    std::string payload;
};

class EventProcessor {
public:
    EventProcessor(size_t maxThreads)
        : stop(false), workers(maxThreads) {}

    ~EventProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void add(const Event& event) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            tasks.push(event);
        }
        condition.notify_one();
    }

    template<typename F>
    void add(F task) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            tasks.push(std::make_shared<F>(task));
        }
        condition.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::shared_ptr<Event>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
};

