    double value;
    Metrics(const std::string& id, double timestamp, const std::string& metadata, double value)
        : IoTData(id, timestamp, metadata), value(value) {}
};

struct StatusUpdate : public IoTData {
    std::string status;
    StatusUpdate(const std::string& id, double timestamp, const std::string& metadata, const std::string& status)
        : IoTData(id, timestamp, metadata), status(status) {}
};

struct GeolocationData : public IoTData {
    double latitude;
    double longitude;
    GeolocationData(const std::string& id, double timestamp, const std::string& metadata, double latitude, double longitude)
        : IoTData(id, timestamp, metadata), latitude(latitude), longitude(longitude) {}
};

// Define a generic data processor for various types of IoT data
class DataProcessor {
public:
    virtual void process(const Metrics& data) = 0;
    virtual void process(const StatusUpdate& data) = 0;
    virtual void process(const GeolocationData& data) = 0;
};

// Implement a specific data processor that forwards data to an analytics service
class AnalyticsService : public DataProcessor {
public:
    void process(const Metrics& data) override {
        std::cout << "Processing metrics: ID=" << data.id << ", Timestamp=" << data.timestamp 
                  << ", Value=" << data.value << ", Metadata=" << data.metadata << std::endl;
        // Code to forward data to analytics service
    }

    void process(const StatusUpdate& data) override {
        std::cout << "Processing status update: ID=" << data.id << ", Timestamp=" << data.timestamp 
                  << ", Status=" << data.status << ", Metadata=" << data.metadata << std::endl;
        // Code to forward data to analytics service
    }

    void process(const GeolocationData& data) override {
        std::cout << "Processing geolocation data: ID=" << data.id << ", Timestamp=" << data.timestamp 
                  << ", Latitude=" << data.latitude << ", Longitude=" << data.longitude << ", Metadata=" << data.metadata << std::endl;
        // Code to forward data to analytics service
    }
};

// Define a data ingestion pipeline using a thread-safe queue and multiple worker threads
class DataPipeline {
private:
    std::mutex queue_mutex;
    std::condition_variable not_empty;
    std::queue<IoTData*> data_queue;
    AnalyticsService analytics_service;

public:
    void enqueue(IoTData* data) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        data_queue.push(data);
        not_empty.notify_one();
    }

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(queue_mutex);
            not_empty.wait(lock, [this] { return !data_queue.empty(); });
            IoTData* data = data_queue.front();
            data_queue.pop();
            lock.unlock();

            // Process the data
            if (auto metrics = dynamic_cast<Metrics*>(data)) {
                analytics_service.process(*metrics);
            } else if (auto statusUpdate = dynamic_cast<StatusUpdate*>(data)) {
                analytics_service.process(*statusUpdate);
            } else if (auto geolocationData = dynamic_cast<GeolocationData*>(data)) {
                analytics_service.process(*geolocationData);
            }

            // Clean up
            delete data;
        }
    }

    DataPipeline(size_t num_workers) {
        for (size_t i = 0; i < num_workers; ++i) {
            std::thread(&DataPipeline::worker, this).detach();
        }
    }
};

int main() {
    DataPipeline pipeline(4);

    // Simulate data ingestion
    pipeline.enqueue(new Metrics("1", 1633072800.0, "Sensor A", 25.0));
    pipeline.enqueue(new StatusUpdate("2", 1633072800.0, "Device B", "online"));
    pipeline.enqueue(new GeolocationData("3", 1633072800.0, "Tracker C", 40.7128, -74.0060));

    return 0;
}
