// Define the Event structure
struct Event {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    std::string type;
    std::shared_ptr<void> metadata; // Metadata can be any data type
    int id;

    Event(std::string t, std::shared_ptr<void> m, int i) 
        : timestamp(std::chrono::system_clock::now()), type(t), metadata(m), id(i) {}
};

// Define the EventProcessor class
class EventProcessor {
public:
    using EventCallback = std::function<bool(const Event&)>;

    EventProcessor(size_t initialCapacity)
        : events(initialCapacity), maxEvents(1024 * 1024), shutdown(false) {}

    ~EventProcessor() {
        shutdown = true;
        cv.notify_all();
        for (auto& t : threads) {
            t.join();
        }
    }

    void start(int numThreads, EventCallback callback) {
        if (!threads.empty()) return; // Already started

        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this, &callback]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex);
                    cv.wait(lock, [this] { return !events.empty() || shutdown; });
                    if (shutdown && events.empty()) break;

                    Event event = std::move(events.front());
                    events.pop();
                    lock.unlock();

                    if (!callback(event)) {
                        // Handle error or retry
                        std::cerr << "Event processing failed for id: " << event.id << std::endl;
                    }
                }
            });
        }
    }

    void stop() {
        shutdown = true;
        cv.notify_all();
        for (auto& t : threads) {
            t.join();
        }
    }

    void addEvent(std::string type, std::shared_ptr<void> metadata, int id) {
        std::unique_lock<std::mutex> lock(mutex);
        if (events.size() >= maxEvents) {
            // Handle overflow or retry
            std::cerr << "Event queue overflow" << std::endl;
            return;
        }
        events.emplace_back(type, metadata, id);
        cv.notify_one();
    }

private:
    std::vector<Event> events;
    size_t maxEvents;
    bool shutdown;
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::thread> threads;
};

// Example usage
int main() {
    EventProcessor processor(1024);
    processor.start(4, [](const Event& event) -> bool {
        // Simulate event processing
        std::cout << "Processing event: " << event.id << ", Type: " << event.type << std::endl;
        return true; // Return false if processing fails
    });

    for (int i = 0; i < 10000; ++i) {
        processor.addEvent("TYPE_A", nullptr, i);
    }

    processor.stop();
    return 0;
}
```

