#include <atomic>

// Event structure
struct Event {
    std::string timestamp;
    std::string eventType;
    std::map<std::string, std::string> metadata;
    std::string id;
};

// Event Processor class
class EventProcessor {
public:
    using EventCallback = std::function<void(const Event&)>;

    EventProcessor(size_t numThreads) : stop(false), threads(numThreads), taskQueue() {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(this->queueMutex);
                    this->condition.wait(lock, [this] { return this->stop || !this->taskQueue.empty(); });
                    if (this->stop && this->taskQueue.empty()) {
                        break;
                    }
                    Event task = std::move(this->taskQueue.front());
                    this->taskQueue.pop();
                    lock.unlock();
                    processEvent(task);
                }
            });
        }
    }

    ~EventProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addEvent(const Event& event) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            taskQueue.push(event);
        }
        condition.notify_one();
    }

private:
    std::atomic<bool> stop;
    std::vector<std::thread> workers;
    std::queue<Event> taskQueue;
    std::mutex queueMutex;
    std::condition_variable condition;

    void processEvent(const Event& event) {
        // Process the event here
        std::cout << "Processing event: " << event.id << std::endl;
    }
};

// Example usage
int main() {
    EventProcessor processor(4);

    // Simulate adding events
    for (int i = 0; i < 10; ++i) {
        Event event;
        event.timestamp = "2023-04-01T" + std::to_string(i);
        event.eventType = "INFO";
        event.metadata["source"] = "App-" + std::to_string(i % 2);
        event.id = "ID-" + std::to_string(i);
        processor.addEvent(event);
    }

    return 0;
}
