// Define data source types
enum class DataSourceType { Kafka, AWS_S3, MongoDB };

// Define a generic data structure
struct DataRecord {
    DataSourceType type;
    std::string payload;
};

// Forward declare the data ingestion framework
class DataIngestionFramework;

// Worker thread to process data from a specific source
void workerThread(DataSourceType sourceType, DataIngestionFramework& framework) {
    // Simulate data processing logic for each source
    while (true) {
        std::unique_lock<std::mutex> lock(framework.dataMutex);
        framework.conditionVariable.wait(lock, [&] { return !framework.dataQueue.empty(); });
        if (sourceType == DataSourceType::Kafka && framework.dataQueue.front().type == DataSourceType::Kafka) {
            // Process Kafka data
            std::cout << "Processing Kafka data: " << framework.dataQueue.front().payload << std::endl;
            framework.dataQueue.pop();
        } else if (sourceType == DataSourceType::AWS_S3 && framework.dataQueue.front().type == DataSourceType::AWS_S3) {
            // Process AWS S3 data
            std::cout << "Processing AWS S3 data: " << framework.dataQueue.front().payload << std::endl;
            framework.dataQueue.pop();
        } else if (sourceType == DataSourceType::MongoDB && framework.dataQueue.front().type == DataSourceType::MongoDB) {
            // Process MongoDB data
            std::cout << "Processing MongoDB data: " << framework.dataQueue.front().payload << std::endl;
            framework.dataQueue.pop();
        }
    }
}

// Data ingestion framework class
class DataIngestionFramework {
public:
    DataIngestionFramework() : stop(false) {}

    void start(DataSourceType sourceType, int numWorkers) {
        for (int i = 0; i < numWorkers; ++i) {
            workers.emplace_back(workerThread, sourceType, std::ref(*this));
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(dataMutex);
            stop = true;
        }
        conditionVariable.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void pushData(const DataRecord& data) {
        std::unique_lock<std::mutex> lock(dataMutex);
        dataQueue.push(data);
        conditionVariable.notify_one();
    }

private:
    std::queue<DataRecord> dataQueue;
    std::vector<std::thread> workers;
    std::mutex dataMutex;
    std::condition_variable conditionVariable;
    bool stop;
};

int main() {
    DataIngestionFramework framework;

    // Start processing threads for each data source
    framework.start(DataSourceType::Kafka, 5);
    framework.start(DataSourceType::AWS_S3, 4);
    framework.start(DataSourceType::MongoDB, 6);

    // Simulate pushing data into the framework
    for (int i = 0; i < 100; ++i) {
        DataRecord record;
        if (i % 3 == 0) {
            record.type = DataSourceType::Kafka;
        } else if (i % 3 == 1) {
            record.type = DataSourceType::AWS_S3;
        } else {
            record.type = DataSourceType::MongoDB;
        }
        record.payload = "Data payload " + std::to_string(i);
        framework.pushData(record);
    }

    // Stop the processing threads
    framework.stop();

    return 0;
}
