typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** generateCRCIndications(int N, int* states, int numStates, void* fsa, int lastStateIndex) {
    if (N <= 0 || states == NULL || numStates <= 0 || fsa == NULL || lastStateIndex < 0) {
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation
    NFAPI_CRC_INDICATION_PDU_T** list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (list == NULL) {
        return NULL; // Handle memory allocation failure gracefully
    }

    for (int i = 0; i < N; ++i) {
        list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (list[i] == NULL) {
            // Clean up previously allocated memory before returning NULL
            for (int j = 0; j < i; ++j) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        list[i]->RX_UE_INFORMATION_TAG = states[rand() % numStates];
        list[i]->RNTI = rand();
        list[i]->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG
    }

    return list;
}
