    int CELL_ID;
    int TX_POWER_LEVEL;
};

class NFVManager {
private:
    std::vector<LTE_UARFCN_CONFIGURATION> configList;
    std::mutex mtx;
    std::condition_variable cv;
    bool stopRequested;

public:
    NFVManager() : stopRequested(false) {}

    ~NFVManager() {
        stopRequest();
        waitUntilDone();
    }

    void startManagingConfigurations(int numConfigs, int earfcnBase) {
        configList.resize(numConfigs);
        for (int i = 0; i < numConfigs; ++i) {
            configList[i].EARFCN = earfcnBase + i;
            configList[i].CELL_ID = i * 10;
            configList[i].TX_POWER_LEVEL = i % 3 == 0 ? -5 : (i % 3 == 1) ? -3 : -2;
        }
        std::thread(&NFVManager::loadConfigurations, this).detach();
    }

    void stopRequest() {
        std::lock_guard<std::mutex> lock(mtx);
        stopRequested = true;
        cv.notify_all();
    }

    void waitUntilDone() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return stopRequested; });
    }

private:
    static size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
        ((std::string*)userp)->append((char*)contents, size * nmemb);
        return size * nmemb;
    }

    bool loadConfigurationsFromAPI() {
        CURL* curl = curl_easy_init();
        if (!curl)
            return false;

        std::string readBuffer;
        curl_easy_setopt(curl, CURLOPT_URL, "http://nfv-api.com/config");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
            curl_easy_cleanup(curl);
            return false;
        }

        // Parse the JSON response and populate configList
        // This part is placeholder for actual JSON parsing logic

        curl_easy_cleanup(curl);
        return true;
    }

    void loadConfigurations() {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (loadConfigurationsFromAPI())
                break;

            ++retries;
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }

        std::unique_lock<std::mutex> lock(mtx);
        cv.notify_all();
    }
};

int main() {
    NFVManager manager;
    manager.startManagingConfigurations(10, 2500);
    // Simulate some work
    std::this_thread::sleep_for(std::chrono::seconds(5));
    manager.stopRequest();
    manager.waitUntilDone();

    return 0;
}
