    MessageProcessor(std::string logFile, size_t concurrencyLevel)
        : logFile(logFile), concurrencyLevel(concurrencyLevel), running(true) {
        for (size_t i = 0; i < concurrencyLevel; ++i) {
            workers.emplace_back(&MessageProcessor::processMessages, this);
        }
    }

    ~MessageProcessor() {
        std::unique_lock<std::mutex> lock(mutex);
        running = false;
        condition.notify_all();
        lock.unlock();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void processMessages() {
        while (true) {
            std::vector<Message> messages;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !running || !queue.empty(); });
                if (!running && queue.empty()) {
                    break;
                }
                std::swap(queue, messages);
            }

            for (auto& msg : messages) {
                try {
                    processMessage(msg);
                } catch (const std::exception& e) {
                    logError(e.what());
                }
            }
        }
    }

    bool addMessage(const Message& msg) {
        std::unique_lock<std::mutex> lock(mutex);
        if (!running || queue.size() >= concurrencyLevel * 2) {
            return false;
        }
        queue.push_back(msg);
        condition.notify_one();
        return true;
    }

