using System;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private readonly object _lock = new object();
    private Random _random;
    private float _rangeMin, _rangeMax;
    private string _dataSourceUrl = "http://example.com/data";

    public DynamicRandomValueGenerator(float min = 0.0f, float max = 1.0f)
    {
        if (min >= max)
        {
            Console.Error.WriteLine("Invalid range provided. Using default bounds.");
            _rangeMin = 0.0f;
            _rangeMax = 1.0f;
        }
        else
        {
            _rangeMin = min;
            _rangeMax = max;
        }

        _random = new Random();
    }

    public float GetRandomFloatInRange()
    {
        lock (_lock)
        {
            return (float)(_random.NextDouble() * (_rangeMax - _rangeMin) + _rangeMin);
        }
    }

    public int GetRandomIntInRange()
    {
        lock (_lock)
        {
            return _random.Next((int)_rangeMin, (int)_rangeMax + 1);
        }
    }

    public float GetExclusiveRangeMinValue() => _rangeMin;
    public float GetExclusiveRangeMaxValue() => _rangeMax;

    public async Task UpdateRangeFromDataSource()
    {
        try
        {
            using (HttpClient client = new HttpClient())
            {
                HttpResponseMessage response = await client.GetAsync(_dataSourceUrl);
                if (!response.IsSuccessStatusCode)
                {
                    throw new Exception($"Failed to fetch data from source. Status code: {response.StatusCode}");
                }

                string jsonResponse = await response.Content.ReadAsStringAsync();
                var data = JsonSerializer.Deserialize<RangeData>(jsonResponse);

                lock (_lock)
                {
                    _rangeMin = data.Min;
                    _rangeMax = data.Max;
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error updating range: {ex.Message}");
        }
    }

    private class RangeData
    {
        public float Min { get; set; }
        public float Max { get; set; }
    }
}
```

