using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class StreamingDataProcessor
{
    private List<IDataSource> _dataSources = new List<IDataSource>();
    private IExternalProcessingService _processingService;
    private CancellationTokenSource _cancellationTokenSource;
    private object _lockObject = new object();

    public StreamingDataProcessor(List<IDataSource> dataSources, ConfigurationSettings settings, IExternalProcessingService processingService)
    {
        foreach (var source in dataSources)
        {
            if (!source.IsValid())
            {
                Console.WriteLine($"Invalid data source: {source.GetType().Name}. Skipping.");
                continue;
            }
            _dataSources.Add(source);
        }

        _processingService = processingService ?? throw new ArgumentNullException(nameof(processingService));
    }

    public void AddDataSource(IDataSource dataSource)
    {
        if (dataSource.IsValid())
        {
            lock (_lockObject)
            {
                _dataSources.Add(dataSource);
            }
        }
        else
        {
            Console.WriteLine($"Invalid data source: {dataSource.GetType().Name}. Skipping.");
        }
    }

    public void RemoveDataSource(IDataSource dataSource)
    {
        lock (_lockObject)
        {
            _dataSources.Remove(dataSource);
        }
    }

    public async Task StartProcessing()
    {
        _cancellationTokenSource = new CancellationTokenSource();
        var tasks = _dataSources.Select(source => ProcessDataAsync(source, _cancellationTokenSource.Token)).ToList();

        await Task.WhenAll(tasks);
    }

    public async Task StopProcessing()
    {
        if (_cancellationTokenSource != null)
        {
            _cancellationTokenSource.Cancel();
            await Task.Delay(1000); // Wait for tasks to complete
            _cancellationTokenSource.Dispose();
        }
    }

    private async Task ProcessDataAsync(IDataSource source, CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                var dataBatch = await source.GetDataAsync(cancellationToken);
                if (dataBatch != null && dataBatch.Any())
                {
                    await _processingService.ProcessAsync(dataBatch, cancellationToken);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing data from {source.GetType().Name}: {ex.Message}");
            }

            // Simulate backpressure
            await Task.Delay(100, cancellationToken);
        }
    }

    public DataSummary GetDataSummary()
    {
        lock (_lockObject)
        {
            var summary = new DataSummary();
            foreach (var source in _dataSources)
            {
                var sourceSummary = source.GetSummary();
                summary.Add(sourceSummary);
            }
            return summary;
        }
    }
}

public interface IDataSource
{
    bool IsValid();
    Task<IEnumerable<DataItem>> GetDataAsync(CancellationToken cancellationToken);
    DataSummary GetSummary();
}

public interface IExternalProcessingService
{
    Task ProcessAsync(IEnumerable<DataItem> dataBatch, CancellationToken cancellationToken);
}

public class ConfigurationSettings { /* Configuration settings implementation */ }

public class DataItem { /* Data item implementation */ }

public class DataSummary { /* Data summary implementation */ }
```

