class Job {
public:
    int id;
    std::string platform;
    int complexity;
    bool isCritical;

    Job(int id, std::string platform, int complexity, bool isCritical)
        : id(id), platform(platform), complexity(complexity), isCritical(isCritical) {}
};

class DynamicMediaProcessingService {
private:
    std::queue<Job> jobQueue;
    std::vector<std::thread> workers;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool stop;

public:
    DynamicMediaProcessingService(int numWorkers) : stop(false) {
        for (int i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&DynamicMediaProcessingService::workerThread, this);
        }
    }

    ~DynamicMediaProcessingService() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        cv.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void enqueueJob(const Job& job) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            jobQueue.push(job);
        }
        cv.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            Job job;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !jobQueue.empty() || stop; });
                if (stop && jobQueue.empty()) {
                    return;
                }
                job = jobQueue.front();
                jobQueue.pop();
            }
            processJob(job);
        }
    }

    void processJob(const Job& job) {
        // Simulate job processing
        std::cout << "Processing job " << job.id << " on platform " << job.platform
                  << " with complexity " << job.complexity << std::endl;
        // Add actual job processing logic here
    }
};

int main() {
    DynamicMediaProcessingService service(10);

    for (int i = 0; i < 50; ++i) {
        Job job(i, "platform" + std::to_string(i % 3), i % 20, i % 10 == 0);
        service.enqueueJob(job);
    }

    return 0;
}
```

