# Import necessary libraries
from flask import Flask, request, jsonify
import stripe  # Assuming Stripe as one of the payment gateways

app = Flask(__name__)

# Initialize Stripe with your API key
stripe.api_key = 'your_stripe_api_key'

# Define a route for creating subscriptions
@app.route('/create_subscription', methods=['POST'])
def create_subscription():
    data = request.get_json()
    try:
        # Create a subscription using Stripe
        stripe.Subscription.create(
            customer=data['customer_id'],
            items=[{'plan': data['plan_id']}]
        )
        return jsonify({'message': 'Subscription created successfully'}), 201
    except stripe.error.StripeError as e:
        return jsonify({'error': str(e)}), 500

# Define a route for updating subscriptions
@app.route('/update_subscription', methods=['POST'])
def update_subscription():
    data = request.get_json()
    try:
        # Update subscription details using Stripe
        stripe.Subscription.modify(
            data['subscription_id'],
            items=[{'id': data['item_id'], 'plan': data['new_plan_id']}]
        )
        return jsonify({'message': 'Subscription updated successfully'}), 200
    except stripe.error.StripeError as e:
        return jsonify({'error': str(e)}), 500

# Define a route for canceling subscriptions
@app.route('/cancel_subscription', methods=['POST'])
def cancel_subscription():
    data = request.get_json()
    try:
        # Cancel the subscription using Stripe
        stripe.Subscription.delete(data['subscription_id'])
        return jsonify({'message': 'Subscription canceled successfully'}), 200
    except stripe.error.StripeError as e:
        return jsonify({'error': str(e)}), 500

# Run the Flask application
if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

