// Define the main microservice struct with dependencies
struct Microservice {
    apis: Vec<Api>,
    config: Config,
    database: Database,
}

impl Microservice {
    // Constructor to initialize the microservice
    fn new(apis: Vec<Api>, config: Config, database: Database) -> Self {
        Microservice { apis, config, database }
    }

    // Method to handle CRUD operations
    async fn handle_request(&self, request: Request) -> Result<Response> {
        let api = self.select_api(request.api_name)?;
        let response = api.send_request(request.clone()).await?;
        Ok(response)
    }

    // Method to select the appropriate API based on the request
    fn select_api(&self, api_name: &str) -> Result<&Api> {
        for api in &self.apis {
            if api.name == api_name {
                return Ok(api);
            }
        }
        Err(Error::new(ErrorKind::Other, "API not found"))
    }
}

// Define the API struct with authentication and rate limiting
struct Api {
    name: String,
    auth: Auth,
    rate_limiter: RateLimiter,
    client: Client,
}

impl Api {
    // Constructor to initialize an API instance
    fn new(name: &str, auth: Auth, rate_limiter: RateLimiter) -> Self {
        Api {
            name: name.to_string(),
            auth,
            rate_limiter,
            client: Client::new(),
        }
    }

    // Method to send a request to the API
    async fn send_request(&self, request: Request) -> Result<Response> {
        self.rate_limiter.limit().await?;
        let headers = self.auth.get_headers();
        let response = self.client.request(request.clone(), &headers).await?;
        Ok(response)
    }
