import logging
from concurrent.futures import ThreadPoolExecutor
from elasticsearch import Elasticsearch

class AsyncLogRecord:
    def __init__(self, message, level):
        self.message = message
        self.level = level

class LoggingFramework:
    def __init__(self, elasticsearch_url, log_levels):
        self.elasticsearch = Elasticsearch(elasticsearch_url)
        self.log_levels = log_levels
        self.executor = ThreadPoolExecutor(max_workers=10)

    def log(self, message, level):
        if level in self.log_levels:
            record = AsyncLogRecord(message, level)
            self.executor.submit(self.send_log, record)

    def send_log(self, record):
        log_entry = {
            'message': record.message,
            'level': record.level
        }
        try:
            self.elasticsearch.index(index='logs', body=log_entry)
        except Exception as e:
            print(f"Failed to log message: {record.message}, error: {e}")

# Usage example
log_levels = {'info', 'warning', 'error'}
logging_framework = LoggingFramework('http://elasticsearch:9200', log_levels)
logging_framework.log("User login successful", "info")
