public class DynamicRandomValueGenerator
{
    private readonly ConcurrentDictionary<string, Random> _randomGenerators = new();
    private HttpClient _httpClient;
    private string _seedUri;

    public DynamicRandomValueGenerator(string seedUri)
    {
        _seedUri = seedUri;
        _httpClient = new HttpClient();
    }

    public async Task<int> GetRandomInteger(int min, int max)
    {
        return GenerateRandom(min, max);
    }

    public async Task<float> GetRandomFloat(float min, float max)
    {
        return GenerateRandom(min, max);
    }

    private Random GetRandomGenerator()
    {
        var seed = DateTime.UtcNow.Ticks.GetHashCode();
        if (!_randomGenerators.ContainsKey(seed.ToString()))
        {
            _randomGenerators[seed.ToString()] = new Random(seed);
        }
        return _randomGenerators[seed.ToString()];
    }

    private int GenerateRandom(int min, int max)
    {
        var randomGenerator = GetRandomGenerator();
        return randomGenerator.Next(min, max + 1);
    }

    private float GenerateRandom(float min, float max)
    {
        var randomGenerator = GetRandomGenerator();
        return (float)(randomGenerator.NextDouble() * (max - min)) + min;
    }
}

