import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.Producer;
import org.apache.kafka.clients.producer.ProducerRecord;

import java.time.Duration;
import java.util.Collections;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DataIngestionPipeline {

    public static void main(String[] args) {
        // Kafka consumer configuration
        Properties consumerProps = new Properties();
        consumerProps.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        consumerProps.put(ConsumerConfig.GROUP_ID_CONFIG, "data-ingestion-group");
        consumerProps.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringDeserializer");
        consumerProps.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, "org.apache.kafka.common.serialization.StringDeserializer");

        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(consumerProps);
        consumer.subscribe(Collections.singletonList("iot-data-topic"));

        // Kafka producer configuration
        Properties producerProps = new Properties();
        producerProps.put("bootstrap.servers", "localhost:9092");
        producerProps.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        producerProps.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

        Producer<String, String> producer = new KafkaProducer<>(producerProps);

        // Executor service for handling data processing
        ExecutorService executorService = Executors.newFixedThreadPool(10);

        try {
            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
                for (ConsumerRecord<String, String> record : records) {
                    executorService.submit(() -> processRecord(record, producer));
                }
            }
        } finally {
            consumer.close();
            producer.close();
            executorService.shutdown();
        }
    }

    private static void processRecord(ConsumerRecord<String, String> record, Producer<String, String> producer) {
        // Data transformation logic
        String transformedData = transformData(record.value());

        // Data loading into data warehouse
        producer.send(new ProducerRecord<>("data-warehouse-topic", record.key(), transformedData));
    }

    private static String transformData(String rawData) {
        // Implement transformation logic here
        return rawData.toUpperCase();
    }
}
```

This code provides a basic framework for a data ingestion pipeline using Apache Kafka. It includes a Kafka consumer to subscribe to IoT data, a Kafka producer to send transformed data to a data warehouse topic, and an executor service to handle parallel processing of records. The `transformData` method is where you would implement your specific transformation logic.']

