using System;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private readonly Random _random;
    private int _minRange;
    private int _maxRange;

    public DynamicRandomValueGenerator(int minRange, int maxRange)
    {
        if (minRange >= maxRange)
            throw new ArgumentException("Min range must be less than max range.");

        _minRange = minRange;
        _maxRange = maxRange;
        _random = new Random();
    }

    public void UpdateRange(int minRange, int maxRange)
    {
        if (minRange >= maxRange)
            throw new ArgumentException("Min range must be less than max range.");

        lock (_random)
        {
            _minRange = minRange;
            _maxRange = maxRange;
        }
    }

    public int GenerateRandomValue()
    {
        lock (_random)
        {
            return _random.Next(_minRange, _maxRange + 1);
        }
    }
}
