import json
from typing import Any, Dict, Optional

class TradingStrategyConfig:
    def __init__(self, strategy_name: str, parameters: Dict[str, Any]):
        self.strategy_name = strategy_name
        self.parameters = parameters

    def to_json(self) -> str:
        return json.dumps({"strategy_name": self.strategy_name, "parameters": self.parameters})

    @classmethod
    def from_json(cls, json_str: str) -> 'TradingStrategyConfig':
        data = json.loads(json_str)
        return cls(data['strategy_name'], data['parameters'])

def serialize_config(config: TradingStrategyConfig, version: int = 1) -> bytes:
    try:
        config_dict = {
            "version": version,
            "data": config.to_json()
        }
        return json.dumps(config_dict).encode('utf-8')
    except Exception as e:
        print(f"Error serializing configuration: {e}")
        raise

def deserialize_config(data: bytes, version: int) -> TradingStrategyConfig:
    try:
        config_str = data.decode('utf-8')
        config_data = json.loads(config_str)
        if config_data['version'] != version:
            raise ValueError(f"Version mismatch: expected {version}, got {config_data['version']}")
        config_json = config_data['data']
        return TradingStrategyConfig.from_json(config_json)
    except Exception as e:
        print(f"Error deserializing configuration: {e}")
        raise

# Example usage
config = TradingStrategyConfig("MovingAverageCross", {"short_window": 50, "long_window": 200})
serialized_config = serialize_config(config)
deserialized_config = deserialize_config(serialized_config, config.strategy_name)

print(deserialized_config.to_json())
```

This utility provides methods to serialize and deserialize a `TradingStrategyConfig` object to/from JSON. It includes versioning for backward compatibility and handles exceptions gracefully. The functions use the `json` module for serialization and deserialization, ensuring proper handling of JSON data.']

