#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_THREADS 10
#define MAX_STRUCTURES 100

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *pdu_list[MAX_STRUCTURES];
int pdu_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* generatePdu(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (pdu_count >= MAX_STRUCTURES) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_pdu->rx_ue_information_tag = rand() % 1000;
        new_pdu->rnti = rand() % 256;
        new_pdu->crc_indication_rel8_tag = rand() % 2;
        pdu_list[pdu_count++] = new_pdu;
        pthread_mutex_unlock(&mutex);
        usleep(1000); // Simulate data processing time
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, generatePdu, NULL) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < pdu_count; ++i) {
        free(pdu_list[i]);
    }

    return EXIT_SUCCESS;
}
```

