['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define NFAPI CRC Indication PDU structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the list of PDUs
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the list structure with mutex for thread safety
typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

// Function to initialize the list
void initList(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert a new PDU into the list
void insertPdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }
    newNode->data = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to generate a random CRCFLAG
unsigned char generateRandomCrcFlag() {
    return rand() % 2; // Randomly set to either 0 or 1
}

// Thread function to generate PDUs and insert into the list
void* threadFunction(void* arg) {
    List* list = (List*)arg;
    srand(time(0)); // Seed for random number generation

    for (int i = 0; i < 1000; ++i) { // Example: generate 1000 PDUs
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 256;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 100;
        pdu.CRCFLAG = generateRandomCrcFlag();

        insertPdu(list, pdu);
    }

    return NULL;
}

// Function to free the list and its nodes
void freeList(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    List myList;
    initList(&myList);

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, threadFunction, &myList);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    freeList(&myList);

    return 0;
}
```']

