#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <yaml.h>

#define MAX_THREADS 10
#define MAX_STRUCTURES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PduList {
    NFAPI_CRC_INDICATION_PDU_T *pduArray[MAX_STRUCTURES];
    pthread_mutex_t lock;
    int size;
} PduList;

void initPduList(PduList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
}

int addPduToList(PduList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->pduArray[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* generateRandomPdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;
    return pdu;
}

void* generateNfapiPduList(void *arg) {
    PduList *list = (PduList*)arg;
    while(1) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = generateRandomPdu();
        addPduToList(list, pdu);
        // Simulate data generation interval
        usleep(1000); // 1 ms
    }
}

int main() {
    PduList list;
    initPduList(&list);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, generateNfapiPduList, &list);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

