#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/rand.h>

#define NUM_THREADS 10
#define MAX_PDU_LIST_SIZE 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T pduList[MAX_PDU_LIST_SIZE];
int pduListSize = 0;
pthread_mutex_t mutex;

void generateNfapiPduList(int numElements) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numElements; i++) {
        if (pduListSize >= MAX_PDU_LIST_SIZE) {
            printf("Error: PDU list is full\n");
            break;
        }
        pduList[pduListSize].RX_UE_INFORMATION_TAG = rand() % 10000;
        pduList[pduListSize].RNTI = (uint16_t)(rand() % 4095);
        pduList[pduListSize].CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);
        pduListSize++;
    }
    pthread_mutex_unlock(&mutex);
}

void* threadFunc(void* arg) {
    int numElements = *(int*)arg;
    generateNfapiPduList(numElements);
    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    srand(time(NULL));

    for (int i = 0; i < NUM_THREADS; i++) {
        int* numElements = malloc(sizeof(int));
        *numElements = rand() % 100 + 1;
        pthread_create(&threads[i], NULL, threadFunc, numElements);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Generated %d PDUs\n", pduListSize);

    return 0;
}
