import json
from typing import Dict

class ImageMetadata:
    def __init__(self, image_id: str, resolution: int, timestamp: float, location: Dict[str, float]):
        self.image_id = image_id
        self.resolution = resolution
        self.timestamp = timestamp
        self.location = location

def serialize_metadata(metadata: ImageMetadata) -> str:
    try:
        return json.dumps({
            "image_id": metadata.image_id,
            "resolution": metadata.resolution,
            "timestamp": metadata.timestamp,
            "location": {
                "latitude": metadata.location["latitude"],
                "longitude": metadata.location["longitude"]
            }
        }, indent=4)
    except Exception as e:
        print(f"Error serializing metadata: {e}")
        return None

def deserialize_metadata(metadata_str: str) -> ImageMetadata:
    try:
        data = json.loads(metadata_str)
        return ImageMetadata(
            image_id=data["image_id"],
            resolution=data["resolution"],
            timestamp=data["timestamp"],
            location={"latitude": data["location"]["latitude"], "longitude": data["location"]["longitude"]}
        )
    except Exception as e:
        print(f"Error deserializing metadata: {e}")
        return None
```

