// tests/transaction.test.js
const request = require('supertest');
const app = require('../app');

describe('Transaction API', () => {
  it('should create a new transaction', async () => {
    const response = await request(app)
      .post('/transactions')
      .send({ amount: 100, currency: 'USD', paymentMethod: 'card' });
    expect(response.status).toBe(201);
    expect(response.body.amount).toBe(100);
    expect(response.body.currency).toBe('USD');
    expect(response.body.paymentMethod).toBe('card');
    expect(response.body.status).toBe('pending');
  });

  it('should get a transaction by ID', async () => {
    const response = await request(app)
      .post('/transactions')
      .send({ amount: 100, currency: 'USD', paymentMethod: 'card' });
    const transactionId = response.body._id;
    const getResponse = await request(app).get(`/transactions/${transactionId}`);
    expect(getResponse.status).toBe(200);
    expect(getResponse.body.amount).toBe(100);
    expect(getResponse.body.currency).toBe('USD');
    expect(getResponse.body.paymentMethod).toBe('card');
    expect(getResponse.body.status).toBe('pending');
  });

  it('should return 404 for non-existent transaction', async () => {
    const response = await request(app).get('/transactions/nonexistentid');
    expect(response.status).toBe(404);
    expect(response.body.message).toBe('Transaction not found');
  });
});
