    std::string type;
    void* metadata;
};

// Define external service interface
class ExternalService {
public:
    virtual ~ExternalService() = default;
    virtual bool submit(const Event& event) = 0;
    virtual bool isAvailable() const = 0;
};

// Implement specific external services (example)
class LoggingFramework : public ExternalService {
public:
    bool submit(const Event& event) override { return true; }
    bool isAvailable() const override { return true; }
};

class EventProcessingService : public ExternalService {
public:
    bool submit(const Event& event) override { return true; }
    bool isAvailable() const override { return true; }
};

// Define event processor
class EventProcessor {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;
    std::vector<std::shared_ptr<ExternalService>> services;
    std::atomic<bool> running;

public:
    EventProcessor(const std::vector<std::shared_ptr<ExternalService>>& serviceList) 
        : services(serviceList), running(false) {}

    void start() {
        running = true;
        for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
            std::thread([this]() {
                while (running.load()) {
                    Event event;
                    if (popEvent(event)) {
                        submitToServices(event);
                    }
                }
            }).detach();
        }
    }

    void stop() {
        running.store(false);
        queueCondition.notify_all();
    }

    bool pushEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        queueCondition.notify_one();
        return true;
    }

private:
    bool popEvent(Event& event) {
        std::unique_lock<std::mutex> lock(queueMutex);
        while (eventQueue.empty() && running.load()) {
            queueCondition.wait(lock);
        }
        if (!eventQueue.empty()) {
            event = eventQueue.front();
            eventQueue.pop();
            return true;
        }
        return false;
    }

    void submitToServices(const Event& event) {
        for (const auto& service : services) {
            if (service->isAvailable() && !service->submit(event)) {
                // Handle submission failure
            }
        }
    }
};

// Main function to demonstrate usage
int main() {
    std::vector<std::shared_ptr<ExternalService>> services = {
        std::make_shared<LoggingFramework>(),
        std::make_shared<EventProcessingService>()
    };

    EventProcessor processor(services);
    processor.start();

    // Simulate event generation and processing
    for (size_t i = 0; i < 1000; ++i) {
        Event event;
        event.timestamp = time(nullptr);
        event.type = "INFO";
        event.metadata = nullptr;
        processor.pushEvent(event);
    }

    processor.stop();
    return 0;
}
