#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <chrono>
#include <functional>
#include <memory>

class Event {
public:
    std::string timestamp;
    std::string type;
    std::unordered_map<std::string, std::string> metadata;

    Event(std::string ts, std::string ty, std::unordered_map<std::string, std::string> md)
        : timestamp(ts), type(ty), metadata(md) {}
};

class EventProcessor {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool stopProcessing;

public:
    EventProcessor() : stopProcessing(false) {}

    void addEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        cv.notify_one();
    }

    void processEvents(std::function<void(const Event&)> handler) {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this] { return !eventQueue.empty() || stopProcessing; });

            if (stopProcessing && eventQueue.empty()) break;

            Event event = eventQueue.front();
            eventQueue.pop();

            lock.unlock();
            handler(event);

            // Simulate processing time
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stopProcessing = true;
        }
        cv.notify_all();
    }
};

class EventPipeline {
private:
    EventProcessor processor;
    std::vector<std::thread> workers;

public:
    EventPipeline(size_t numWorkers) : processor() {
        for (size_t i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&EventProcessor::processEvents, &processor,
                                  [](const Event& event) {
                                      // Handle event processing logic here
                                      std::cout << "Processing event: Type=" << event.type 
                                                << ", Timestamp=" << event.timestamp << std::endl;
                                  });
        }
    }

    ~EventPipeline() {
        processor.stop();
        for (auto& worker : workers) {
            if (worker.joinable()) worker.join();
        }
    }

    void addEvent(const Event& event) {
        processor.addEvent(event);
    }
};

int main() {
    EventPipeline pipeline(4);

    // Simulate adding events
    pipeline.addEvent(Event("2023-10-01T12:00:00Z", "Login", {{"user_id", "123"}}));
    pipeline.addEvent(Event("2023-10-01T12:05:00Z", "Logout", {{"user_id", "123"}}));
    pipeline.addEvent(Event("2023-10-01T12:10:00Z", "DataUpdate", {{"data_id", "456"}}));

    return 0;
}
```

