class Event {
public:
    std::string type;
    std::time_t timestamp;
    std::map<std::string, std::string> metadata;
};

class EventProcessor {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool running;

public:
    EventProcessor() : running(true) {}

    void start() {
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                condition.wait(lock, [this] { return !eventQueue.empty() || !running; });
                if (!running && eventQueue.empty()) break;

                Event event = eventQueue.front();
                eventQueue.pop();
                lock.unlock();

                processEvent(event);
            }
        }).detach();
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            running = false;
        }
        condition.notify_all();
    }

    void enqueueEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        condition.notify_one();
    }

private:
    void processEvent(const Event& event) {
        // Simulate processing
        std::cout << "Processing event: " << event.type << " at " << event.timestamp << std::endl;
    }
};

class ExternalLogger {
public:
    static void log(const std::string& message) {
        // Log to external service
        std::cout << "Log: " << message << std::endl;
    }
};

class EventFilter {
private:
    std::set<std::string> types;
    std::time_t startTime, endTime;

public:
    void addType(const std::string& type) {
        types.insert(type);
    }

    void setRange(std::time_t start, std::time_t end) {
        startTime = start;
        endTime = end;
    }

    bool shouldProcess(const Event& event) const {
        return (types.empty() || types.find(event.type) != types.end()) &&
               (event.timestamp >= startTime && event.timestamp <= endTime);
    }
};

int main() {
    EventProcessor processor;
    EventFilter filter;

    // Add event types and time range
    filter.addType("critical");
    filter.setRange(std::time(nullptr) - 3600, std::time(nullptr));

    // Simulate receiving events
    for (int i = 0; i < 1000; ++i) {
        Event event;
        event.type = "info";
        if (i % 5 == 0) event.type = "critical";
        event.timestamp = std::time(nullptr);
        event.metadata["source"] = "service_" + std::to_string(i % 10);

        processor.enqueueEvent(event);
    }

    // Start processing
    processor.start();

    // Simulate stopping after some time
    std::this_thread::sleep_for(std::chrono::seconds(10));
    processor.stop();

    return 0;
}
