        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& record : records) {
            if (recordQueue_.size() >= batchSize) {
                processBatch();
            }
            recordQueue_.push(record);
        }
        if (!recordQueue_.empty()) {
            processBatch();
        }
    }

private:
    void processBatch() {
        std::vector<TRAFFIC_METRIC_RECORD> batch;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            while (!recordQueue_.empty() && batch.size() < batchSize) {
                batch.push_back(recordQueue_.front());
                recordQueue_.pop();
            }
        }
        // Process the batch of records
        for (const auto& record : batch) {
            processRecord(record);
        }
    }

    void processRecord(const TRAFFIC_METRIC_RECORD& record) {
        // Implement the logic to process a single traffic metric record here
    }

