// Include necessary headers
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <openssl/sha.h>
#include <cstring>

// Define the Event structure
struct Event {
    std::string timestamp;
    std::string eventType;
    std::map<std::string, std::string> metadata;
};

// Define the Logger interface
class Logger {
public:
    virtual ~Logger() {}
    virtual void log(const Event& event) = 0;
};

// Implement a thread-safe logger using a queue and condition variable
class ThreadSafeLogger : public Logger {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    bool running;

public:
    ThreadSafeLogger() : running(true) {}

    ~ThreadSafeLogger() {
        running = false;
        queueCondVar.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void log(const Event& event) override {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        queueCondVar.notify_one();
    }

    void startWorkers(size_t numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back([this]() {
                while (true) {
                    Event event;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        queueCondVar.wait(lock, [this] { return !running || !eventQueue.empty(); });
                        if (!running && eventQueue.empty()) {
                            break;
                        }
                        event = eventQueue.front();
                        eventQueue.pop();
                    }
                    // Process the event (e.g., log to a service)
                }
            });
        }
    }

private:
    std::vector<std::thread> workerThreads;
};

// Implement the FSA integration
void integrateWithFSA(int N, const NFAPI_CRC_INDICATION_PDU_T* pdus, int numStates, FSA* fsa, int lastStateIndex) {
    try {
        // Dynamically allocate memory for state list
        std::vector<int> states(numStates);
        memcpy(states.data(), pdus[lastStateIndex].stateList, numStates * sizeof(int));

        // Process the state list and log events
        ThreadSafeLogger logger;
        logger.startWorkers(4); // Start 4 worker threads

        for (int i = 0; i < N; ++i) {
            Event event;
            event.timestamp = getCurrentTimestamp();
            event.eventType = "NFAPI_CRC_INDICATION";
            event.metadata["State"] = std::to_string(states[i]);
            logger.log(event);
        }

        // Join worker threads
    } catch (const std::bad_alloc& e) {
        // Handle memory allocation failure
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
    }
}

// Helper function to get current timestamp
std::string getCurrentTimestamp() {
    auto now = std::chrono::system_clock::now();
    auto in_time_t = std::chrono::system_clock::to_time_t(now);
    return std::ctime(&in_time_t);
}
