    void storeImage(const std::string& data) override {
        // Mock storage logic
        std::cout << "Storing image: " << data << std::endl;
    }
};

class BasicProcessor : public ImageProcessor {
public:
    std::string process(const std::string& imageData) override {
        // Mock processing logic
        return imageData + "_processed";
    }
};

// Pipeline components
class ImagePipeline {
private:
    CloudService* cloudService;
    ImageProcessor* imageProcessor;
    StorageService storageService;
    std::queue<std::string> inputQueue;
    std::mutex queueMutex;
    std::condition_variable queueCond;
    bool running;

public:
    ImagePipeline(CloudService* cs, ImageProcessor* ip) : cloudService(cs), imageProcessor(ip), running(true) {
        // Start worker thread
        std::thread([this]() { processImages(); }).detach();
    }

    ~ImagePipeline() {
        running = false;
        queueCond.notify_all();
    }

    void submitImage(const std::string& imageData) {
        std::lock_guard<std::mutex> lock(queueMutex);
        inputQueue.push(imageData);
        queueCond.notify_one();
    }

private:
    void processImages() {
        while (running) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCond.wait(lock, [this] { return !inputQueue.empty() || !running; });
            if (!running && inputQueue.empty()) break;

            auto imageData = inputQueue.front();
            inputQueue.pop();
            lock.unlock();

            // Process image
            std::string processedData = imageProcessor->process(imageData);

            // Store in cloud storage
            cloudService->storeImage(processedData);
        }
    }
};

int main() {
    CloudService* cs = new StorageService();
    ImageProcessor* ip = new BasicProcessor();
    ImagePipeline pipeline(cs, ip);

    // Submit images for processing
    pipeline.submitImage("image1");
    pipeline.submitImage("image2");
    pipeline.submitImage("image3");

    return 0;
}
