#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_EVENTS 10000

typedef struct {
    int timestamp;
    char type[50];
    void* metadata;
} Event;

Event buffer[MAX_EVENTS];
int head = 0, tail = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t empty, full;

void* producer(void* arg) {
    while (1) {
        // Simulate event generation
        sem_wait(&empty);
        pthread_mutex_lock(&mutex);
        buffer[tail] = generate_event();
        tail = (tail + 1) % MAX_EVENTS;
        pthread_mutex_unlock(&mutex);
        sem_post(&full);
    }
}

void* consumer(void* arg) {
    while (1) {
        sem_wait(&full);
        pthread_mutex_lock(&mutex);
        Event event = buffer[head];
        head = (head + 1) % MAX_EVENTS;
        pthread_mutex_unlock(&mutex);
        sem_post(&empty);

        // Process and log the event
        process_and_log_event(event);
    }
}

int main() {
    pthread_t producers[5], consumers[5];

    sem_init(&empty, 0, MAX_EVENTS);
    sem_init(&full, 0, 0);

    for (int i = 0; i < 5; i++) {
        pthread_create(&producers[i], NULL, producer, NULL);
        pthread_create(&consumers[i], NULL, consumer, NULL);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(producers[i], NULL);
        pthread_join(consumers[i], NULL);
    }

    sem_destroy(&empty);
    sem_destroy(&full);

    return 0;
}
