ConnectionConfigList* create_list() {
    ConnectionConfigList* list = (ConnectionConfigList*)malloc(sizeof(ConnectionConfigList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(ConnectionConfigList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_config(ConnectionConfigList* list, NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    new_node->pdu = pdu;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_config(ConnectionConfigList* list, NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T pdu) {
