    while (current != NULL) {
        if (memcmp(&current->pdu, &pdu, sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_INDICATION_PDU_T)) == 0) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return true;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return false;
}

