#include <iostream>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>

template <typename Key, typename Value>
class DistributedCache {
private:
    struct CacheEntry {
        Value value;
        std::time_t expirationTime;
        int priority;
    };

    std::unordered_map<Key, CacheEntry> cache;
    std::mutex mtx;
    std::condition_variable cv;
    bool running;

public:
    DistributedCache() : running(true) {
        // Start eviction thread
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(mtx);
                cv.wait(lock, [this] { return !cache.empty(); });
                auto now = std::time(nullptr);
                for (auto it = cache.begin(); it != cache.end();) {
                    if (it->second.expirationTime <= now) {
                        it = cache.erase(it);
                    } else {
                        ++it;
                    }
                }
            }
        }).detach();
    }

    ~DistributedCache() {
        running = false;
        cv.notify_all();
    }

    void put(const Key& key, const Value& value, std::time_t ttl, int priority) {
        std::lock_guard<std::mutex> lock(mtx);
        cache[key] = {value, std::time(nullptr) + ttl, priority};
        cv.notify_one();
    }

    std::optional<Value> get(const Key& key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = cache.find(key);
        if (it != cache.end()) {
            auto now = std::time(nullptr);
            if (it->second.expirationTime > now) {
                return it->second.value;
            } else {
                cache.erase(it);
            }
        }
        return std::nullopt;
    }

    void remove(const Key& key) {
        std::lock_guard<std::mutex> lock(mtx);
        cache.erase(key);
    }
};

int main() {
    DistributedCache<int, std::string> cache;
    cache.put(1, "Hello", 60, 1); // Cache "Hello" for 60 seconds with priority 1
    auto result = cache.get(1);
    if (result) {
        std::cout << "Cached value: " << *result << std::endl;
    } else {
        std::cout << "Key not found in cache." << std::endl;
    }
    return 0;
}
