#include <chrono>
#include <memory>

// Define the Event structure
struct Event {
    std::string timestamp;
    std::string type;
    std::unordered_map<std::string, std::string> metadata;
    std::vector<char> payload;
};

// Define the LoggingService interface
class LoggingService {
public:
    virtual void log(const Event& event) = 0;
    virtual ~LoggingService() {}
};

// Implement a concrete logging service (e.g., Loggly)
class LogglyService : public LoggingService {
public:
    void log(const Event& event) override {
        // Simulate network communication
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Logged to Loggly: " << event.timestamp << ", " << event.type << std::endl;
    }
};

// Implement another concrete logging service (e.g., Sentry)
class SentryService : public LoggingService {
public:
    void log(const Event& event) override {
        // Simulate network communication
        std::this_thread::sleep_for(std::chrono::milliseconds(15));
        std::cout << "Logged to Sentry: " << event.timestamp << ", " << event.type << std::endl;
    }
};

// Define the EventProcessor class
class EventProcessor {
public:
    void addEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(event);
        condition_.notify_one();
    }

private:
    std::queue<Event> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;

    void worker(LoggingService* service) {
        while (true) {
            Event event;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !queue_.empty(); });
                event = queue_.front();
                queue_.pop();
            }
            service->log(event);
        }
    }

public:
    void start(LoggingService* service) {
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            threads_.emplace_back(&EventProcessor::worker, this, service);
        }
    }

    ~EventProcessor() {
        // Notify all workers to stop
        for (int i = 0; i < threads_.size(); ++i) {
            {
                std::lock_guard<std::mutex> lock(mutex_);
                condition_.notify_one();
            }
        }
        for (auto& thread : threads_) {
            thread.join();
        }
    }

private:
    std::vector<std::thread> threads_;
};

// Main function to demonstrate usage
int main() {
    LogglyService loggly;
    SentryService sentry;

    EventProcessor processor;
    processor.start(&loggly);
    processor.start(&sentry);

    // Simulate adding events
    for (int i = 0; i < 100; ++i) {
        Event event;
        event.timestamp = "2023-04-01T" + std::to_string(i);
        event.type = "Event" + std::to_string(i % 5);
        // Add more metadata and payload if needed
        processor.addEvent(event);
    }

    return 0;
}
