#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    char *metadata;
} Record;

// Define the dynamic collection of records
typedef struct {
    Record **records;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

// Function to create a new record
Record* create_record(int key, long offset, const char *metadata) {
    Record *record = (Record*) malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->offset = offset;
    record->metadata = strdup(metadata);
    return record;
}

// Function to add a record to the collection
void add_record(RecordCollection *collection, Record *record) {
    pthread_mutex_lock(&collection->mutex);
    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->mutex);
}

// Function to update an existing record in the collection
void update_record(RecordCollection *collection, int key, long new_offset, const char *new_metadata) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]->metadata);
            collection->records[i]->offset = new_offset;
            collection->records[i]->metadata = strdup(new_metadata);
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

// Function to delete a record from the collection
void delete_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i]->key == key) {
            free(collection->records[i]->metadata);
            free(collection->records[i]);
            for (size_t j = i; j < collection->size - 1; j++) {
                collection->records[j] = collection->records[j + 1];
            }
            collection->size--;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

// Function to get a record from the collection
Record* get_record(RecordCollection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i]->key == key) {
            Record *record = collection->records[i];
            pthread_mutex_unlock(&collection->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return NULL;
}

// Initialize the record collection
void init_record_collection(RecordCollection *collection, size_t initial_size) {
    collection->records = (Record**) malloc(initial_size * sizeof(Record*));
    if (!collection->records) return;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
}

// Free the record collection
void free_record_collection(RecordCollection *collection) {
    for (size_t i = 0; i < collection->size; i++) {
        free(collection->records[i]->metadata);
        free(collection->records[i]);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
}
