typedef struct {
    int key;
    long offset;
    time_t timestamp;
    unsigned int version;
} Record;

// Function to allocate memory for a new record
Record* create_record(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    record->key = key;
    record->offset = offset;
    record->timestamp = time(NULL);
    record->version = 1;
    return record;
}

// Function to free memory for a record
void free_record(Record* record) {
    if (record != NULL) {
        free(record);
    }
}

// Function to update a record with conflict resolution
void update_record(Record** records, int key, long new_offset, int *count, void (*resolve_conflict)(Record*, Record*)) {
    for (int i = 0; i < *count; i++) {
        if (records[i]->key == key) {
            resolve_conflict(records[i], create_record(key, new_offset));
            records[i]->version++;
            return;
        }
    }
    records[(*count)++] = create_record(key, new_offset);
}

// Example conflict resolution function that keeps the latest version
void default_resolve_conflict(Record* old_record, Record* new_record) {
    if (new_record->timestamp > old_record->timestamp) {
        free_record(old_record);
        *old_record = *new_record;
    } else {
        free_record(new_record);
    }
}

int main() {
    Record* records[10];
    int count = 0;

    // Example usage
    update_record(records, 1, 100, &count, default_resolve_conflict);

    for (int i = 0; i < count; i++) {
        printf("Key: %d, Offset: %ld, Timestamp: %s Version: %u\n",
               records[i]->key, records[i]->offset,
               ctime(&records[i]->timestamp), records[i]->version);
        free_record(records[i]);
    }

    return 0;
}
