// session_manager.hpp
#pragma once

#include <atomic>
#include <mutex>
#include <unordered_map>
#include <memory>
#include <thread>
#include <chrono>

class SessionManager {
public:
    SessionManager(size_t max_sessions);
    ~SessionManager();

    bool create_session(const std::string& user_id, std::string& session_id);
    void update_session(const std::string& session_id, const std::string& data);
    bool get_session_data(const std::string& session_id, std::string& data) const;
    void delete_session(const std::string& session_id);

private:
    struct Session {
        std::chrono::time_point<std::chrono::steady_clock> last_access_time;
        std::string data;
    };

    size_t max_sessions_;
    std::unordered_map<std::string, Session> sessions_;
    mutable std::mutex mutex_;
};

// session_manager.cpp
#include "session_manager.hpp"

SessionManager::SessionManager(size_t max_sessions)
    : max_sessions_(max_sessions) {
    // Start a background thread for periodic cleanup
    cleanup_thread_ = std::thread([this]() {
        while (running_) {
            std::this_thread::sleep_for(std::chrono::minutes(1));
            std::lock_guard<std::mutex> lock(mutex_);
            auto now = std::chrono::steady_clock::now();
            sessions_.erase(
                std::remove_if(sessions_.begin(), sessions_.end(),
                               [&](const std::pair<const std::string, Session>& p) {
                                   return (now - p.second.last_access_time > std::chrono::minutes(10));
                               }),
                sessions_.end());
        }
    });
}

SessionManager::~SessionManager() {
    running_ = false;
    cleanup_thread_.join();
}

bool SessionManager::create_session(const std::string& user_id, std::string& session_id) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (sessions_.size() >= max_sessions_) return false;
    session_id = generate_unique_id();
    sessions_[session_id] = {std::chrono::steady_clock::now(), "Initial Data"};
    return true;
}

void SessionManager::update_session(const std::string& session_id, const std::string& data) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = sessions_.find(session_id);
    if (it != sessions_.end()) {
        it->second.last_access_time = std::chrono::steady_clock::now();
        it->second.data = data;
    }
}

bool SessionManager::get_session_data(const std::string& session_id, std::string& data) const {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = sessions_.find(session_id);
    if (it != sessions_.end()) {
        data = it->second.data;
        return true;
    }
    return false;
}

void SessionManager::delete_session(const std::string& session_id) {
    std::lock_guard<std::mutex> lock(mutex_);
    sessions_.erase(session_id);
}

std::string generate_unique_id() {
    static size_t id_counter = 0;
    return "session_" + std::to_string(++id_counter);
}
