#include <iostream>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

class DistributedCache {
public:
    void set(const std::string& key, const std::string& value, int ttl, int priority) {
        std::lock_guard<std::mutex> lock(mutex);
        cache[key] = {value, std::chrono::system_clock::now() + std::chrono::seconds(ttl), priority};
        cv.notify_one();
    }

    std::optional<std::string> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            if (std::chrono::system_clock::now() < it->second.expiry_time) {
                return it->second.value;
            } else {
                cache.erase(it);
            }
        }
        return std::nullopt;
    }

private:
    struct CacheEntry {
        std::string value;
        std::chrono::time_point<std::chrono::system_clock> expiry_time;
        int priority;
    };

    std::unordered_map<std::string, CacheEntry> cache;
    std::mutex mutex;
    std::condition_variable cv;

    void evictionThread() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !cache.empty(); });
            auto it = std::min_element(cache.begin(), cache.end(),
                                       [](const auto& a, const auto& b) {
                                           return a.second.expiry_time < b.second.expiry_time;
                                       });
            if (std::chrono::system_clock::now() >= it->second.expiry_time) {
                cache.erase(it);
            }
        }
    }

public:
    DistributedCache() {
        eviction_thread = std::thread(&DistributedCache::evictionThread, this);
    }

    ~DistributedCache() {
        running = false;
        cv.notify_all();
        if (eviction_thread.joinable()) {
            eviction_thread.join();
        }
    }

private:
    std::thread eviction_thread;
    bool running = true;
};

int main() {
    DistributedCache cache;
    cache.set("key1", "value1", 60, 1);
    std::cout << cache.get("key1").value_or("Not Found") << std::endl;
    return 0;
}
