class AsyncClient {
public:
    using RequestId = uint32_t;
    using Response = std::string;

    struct Request {
        RequestId id;
        std::function<void(Response)> callback;
    };

private:
    std::mutex queue_mutex_;
    std::queue<Request> request_queue_;
    std::vector<std::thread> worker_threads_;
    std::atomic<bool> running_{true};
    std::condition_variable cv_;

public:
    AsyncClient(size_t num_workers) {
        for (size_t i = 0; i < num_workers; ++i) {
            worker_threads_.emplace_back(&AsyncClient::worker_thread, this);
        }
    }

    ~AsyncClient() {
        running_ = false;
        cv_.notify_all();
        for (auto& thread : worker_threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    RequestId send_request(std::function<Response()> request_func, std::function<void(Response)> callback) {
        std::unique_lock<std::mutex> lock(queue_mutex_);
        RequestId id = next_id_;
        request_queue_.emplace(id, [callback](Response response) {
            callback(response);
        });
        ++next_id_;
        cv_.notify_one();
        return id;
    }

private:
    void worker_thread() {
        while (true) {
            std::unique_lock<std::mutex> lock(queue_mutex_);
            cv_.wait(lock, [this]() { return !request_queue_.empty() || !running_; });
            if (!running_) break;

            Request request = std::move(request_queue_.front());
            request_queue_.pop();
            lock.unlock();

            try {
                Response response = request_func();
                request.callback(response);
            } catch (...) {
                // Handle error
                request.callback("Error");
            }
        }
    }

private:
    uint32_t next_id_ = 0;
};

int main() {
    AsyncClient client(4);

    auto send_request = [](std::function<Response()> request_func, std::function<void(Response)> callback) -> AsyncClient::RequestId {
        return client.send_request(request_func, callback);
    };

    send_request([]() {
        // Simulate network request
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        return "Data";
    }, [](AsyncClient::Response response) {
        std::cout << "Received: " << response << std::endl;
    });

    client.join_all();
    return 0;
}
