namespace NfapiLib {

class NFAPI_CRC_INDICATION_PDU_T {
public:
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
};

class NfapiCrcIndicationHandler {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data_;
    size_t batchSize_;
    size_t concurrencyLevel_;
    std::atomic<bool> isHealthy_{true};
    std::mutex mtx_;
    std::condition_variable cv_;

public:
    NfapiCrcIndicationHandler(size_t N, size_t batchSize, size_t concurrencyLevel)
        : data_(N), batchSize_(batchSize), concurrencyLevel_(concurrencyLevel) {
        // Initialize thread-local random number generator
        std::mt19937 gen(std::random_device{}());
        for (auto& pdu : data_) {
            pdu.RX_UE_INFORMATION_TAG = 0; // Placeholder value
            pdu.RNTI = 0; // Placeholder value
            pdu.CRC_INDICATION_REL8_TAG = gen() % 2; // Randomly generate CRCFLAG
        }
    }

    void startHandlingData(std::function<void(NFAPI_CRC_INDICATION_PDU_T)> processData) {
        std::vector<std::thread> threads;
        for (size_t i = 0; i < concurrencyLevel_; ++i) {
            threads.emplace_back([this, &processData]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(mtx_);
                    cv_.wait(lock, [this] { return !isHealthy_ || data_.empty(); });
                    if (!isHealthy_) break;
                    size_t end = std::min(data_.size(), data_.begin() + batchSize_);
                    for (auto it = data_.begin(); it < end; ++it) {
                        processData(*it);
                    }
                    data_.erase(data_.begin(), end);
                }
            });
        }
        for (auto& t : threads) {
            t.join();
        }
    }

    void checkHealth() {
        // Simulate health check
        if (!isHealthy_) {
            isHealthy_ = true;
        } else {
            // Simulate network failure
            isHealthy_ = false;
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
        cv_.notify_all();
    }

    void addData(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mtx_);
        data_.push_back(pdu);
        cv_.notify_one();
    }
};

} // namespace NfapiLib
