using Microsoft.Extensions.Logging;

public class UserProfileService
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<UserProfileService> _logger;
    private readonly ICacheService _cacheService;

    public UserProfileService(HttpClient httpClient, ILogger<UserProfileService> logger, ICacheService cacheService)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cacheService = cacheService ?? throw new ArgumentNullException(nameof(cacheService));
    }

    public async Task<IActionResult> UpdateUserProfileAsync(string userId, UserProfile updatedProfile)
    {
        try
        {
            // Validate input
            if (string.IsNullOrEmpty(userId) || updatedProfile == null)
                return new BadRequestObjectResult("Invalid user ID or profile data");

            // Check cache for existing profile
            var cachedProfile = await _cacheService.GetAsync<UserProfile>(userId);
            if (cachedProfile != null && !IsProfileChanged(cachedProfile, updatedProfile))
                return new OkObjectResult("No changes detected");

            // Update user authentication service
            var authResponse = await _httpClient.PutAsJsonAsync($"https://authservice.com/api/users/{userId}", updatedProfile);
            if (!authResponse.IsSuccessStatusCode)
                return new StatusCodeResult((int)authResponse.StatusCode);

            // Upload new image (if any)
            if (updatedProfile.Image != null)
            {
                var storageResponse = await _httpClient.PutAsJsonAsync($"https://imageservice.com/api/images/{userId}", updatedProfile.Image);
                if (!storageResponse.IsSuccessStatusCode)
                    return new StatusCodeResult((int)storageResponse.StatusCode);
            }

            // Log the update
            await _logger.LogInformation($"User profile updated for userId: {userId}");

            // Cache the updated profile
            await _cacheService.SetAsync(userId, updatedProfile);

            return new OkObjectResult("Profile updated successfully");
        }
        catch (Exception ex)
        {
            await _logger.LogError(ex, "Error updating user profile");
            return new StatusCodeResult(500);
        }
    }

    private bool IsProfileChanged(UserProfile original, UserProfile updated)
    {
        // Implement logic to compare profiles and check for changes
        return !original.Equals(updated);
    }
}

public class UserProfile
{
    public string UserId { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
    public byte[] Image { get; set; }
}

public interface ICacheService
{
    Task<T> GetAsync<T>(string key);
    Task SetAsync(string key, T value);
}
