import { v4 as uuidv4 } from 'uuid';
import axios from 'axios';

interface Preference {
  key: string;
  value: any;
  type: string;
}

interface Config {
  useLocalStorage: boolean;
  useCookies: boolean;
  useAPI: boolean;
  enableCaching: boolean;
  logLevel: 'info' | 'error' | 'debug';
}

const cache = new Map<string, any>();

async function configureUserPreferences(preferences: Preference[], config: Config): Promise<void> {
  const deviceId = localStorage.getItem('deviceId') || uuidv4();
  localStorage.setItem('deviceId', deviceId);

  for (const preference of preferences) {
    try {
      let value = preference.value;

      if (config.enableCaching && cache.has(preference.key)) {
        value = cache.get(preference.key);
      } else {
        if (config.useLocalStorage) {
          const storedValue = localStorage.getItem(preference.key);
          if (storedValue) {
            value = JSON.parse(storedValue);
          }
        }

        if (config.useCookies) {
          const cookies = document.cookie.split(';').map(cookie => cookie.trim());
          const cookieValue = cookies.find(c => c.startsWith(`${preference.key}=`));
          if (cookieValue) {
            value = JSON.parse(decodeURIComponent(cookieValue.split('=')[1]));
          }
        }

        if (config.useAPI && !value) {
          const response = await axios.get(`/api/preferences/${preference.key}`);
          value = response.data.value;
        }

        cache.set(preference.key, value);
      }

      // Update preference in all persistence layers
      if (config.useLocalStorage) localStorage.setItem(preference.key, JSON.stringify(value));
      if (config.useCookies) document.cookie = `${preference.key}=${encodeURIComponent(JSON.stringify(value))}; path=/`;
      if (config.useAPI) await axios.put(`/api/preferences/${preference.key}`, { value });

    } catch (error) {
      console.error(`Error configuring preference ${preference.key}:`, error);
      if (config.logLevel === 'debug') {
        console.debug('Fallback mechanism triggered:', preference);
        // Fallback mechanism to restore critical preferences
      }
    }
  }
}
