        return true;
    }

    private void loadResources(String languageCode) {
        new AsyncTask<Void, Void, List<LocalizedResource>>() {
            @Override
            protected List<LocalizedResource> doInBackground(Void... voids) {
                List<LocalizedResource> resources = database.localizedResourceDao().getResourcesByLanguage(languageCode);
                if (resources.isEmpty()) {
                    try {
                        List<LocalizedResource> apiResources = translationClient.fetchTranslation(languageCode);
                        database.localizedResourceDao().insertAll(apiResources);
                    } catch (IOException e) {
                        Log.e(TAG, "Failed to fetch translations: " + e.getMessage());
