#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <fstream>
#include <cstring>

// Define sensor data structure
struct SensorData {
    std::string source;
    double value;
    time_t timestamp;
};

// Queue to hold incoming sensor data
std::queue<SensorData> sensorQueue;

// Mutex and condition variable for thread synchronization
std::mutex queueMutex;
std::condition_variable notEmpty;
std::atomic<bool> stopProcessing(false);

// Function to simulate reading data from serial port
void readSerialPort() {
    // Simulate reading data
    for (int i = 0; !stopProcessing; ++i) {
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
        SensorData data = {"serial_port", static_cast<double>(i), time(nullptr)};
        std::lock_guard<std::mutex> lock(queueMutex);
        sensorQueue.push(data);
        notEmpty.notify_one();
    }
}

// Function to process sensor data
void processData() {
    while (!stopProcessing) {
        std::unique_lock<std::mutex> lock(queueMutex);
        notEmpty.wait(lock, []{ return !sensorQueue.empty() || stopProcessing; });
        if (stopProcessing && sensorQueue.empty()) break;

        SensorData data = sensorQueue.front();
        sensorQueue.pop();
        lock.unlock();

        // Process the data
        std::cout << "Processing data from: " << data.source << ", Value: " << data.value 
                  << ", Timestamp: " << data.timestamp << std::endl;

        // Simulate reprocessing delayed data points
        if (std::this_thread::get_id() == 2) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }
}

int main() {
    // Create threads to simulate serial port reading and data processing
    std::thread reader(readSerialPort);
    std::vector<std::thread> processors;
    for (int i = 0; i < 5; ++i) {
        processors.emplace_back(processData);
    }

    // Join all threads
    reader.join();
    for (auto& t : processors) {
        t.join();
    }

    stopProcessing.store(true);

    return 0;
}
```

