class NetManager {
public:
    NetManager(size_t max_connections)
        : max_connections(max_connections), current_connections(0) {}

    void connect() {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return current_connections < max_connections; });
        ++current_connections;
        // Simulate connection logic
        std::cout << "Connection established" << std::endl;
        lock.unlock();
        notify_if_needed();
    }

    void disconnect() {
        std::unique_lock<std::mutex> lock(mutex);
        --current_connections;
        // Simulate disconnection logic
        std::cout << "Connection closed" << std::endl;
        lock.unlock();
        notify_if_needed();
    }

private:
    size_t max_connections;
    size_t current_connections;
    std::mutex mutex;
    std::condition_variable condition;

    void notify_if_needed() {
        if (current_connections < max_connections) {
            condition.notify_one();
        }
    }
};

