// Event structure
struct Event {
    time_t timestamp;
    std::string type;
    std::unique_ptr<void> metadata;
};

// Event processor interface
class IEventProcessor {
public:
    virtual ~IEventProcessor() = default;
    virtual void Process(const Event& event) = 0;
};

// High-throughput event processing framework
class EventProcessingFramework {
private:
    std::vector<std::thread> workers;
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    IEventProcessor* processor;
    bool running;

public:
    EventProcessingFramework(IEventProcessor* proc, size_t workerCount = 4)
        : processor(proc), running(true) {
        for (size_t i = 0; i < workerCount; ++i) {
            workers.emplace_back([this]() { workerThread(); });
        }
    }

    ~EventProcessingFramework() {
        running = false;
        cv.notify_all();
        for (auto& thread : workers) {
            thread.join();
        }
    }

    void AddEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        cv.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            Event event;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !eventQueue.empty() || !running; });
                if (!running && eventQueue.empty()) {
                    break;
                }
                event = eventQueue.front();
                eventQueue.pop();
            }
            processor->Process(event);
        }
    }
};

