public:
    void process(const std::string& data) {
        // Implement data processing logic here
        logger.log(Logger::INFO, "Processing data: " + data);
        // Simulate data processing delay
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

private:
    Logger logger;
};

// Define a library class to integrate the above components
class NetworkLibrary {
public:
    NetworkLibrary(size_t maxThreads) : concurrencyManager(maxThreads), networkHandler(), cache() {}

    void sendRequest(const std::string& url, const std::function<void()>& callback) {
        concurrencyManager.runTask([&] { networkHandler.sendRequest(url, callback); });
    }

    void putCache(const std::string& key, const std::string& value) {
        concurrencyManager.runTask([&] { cache.put(key, value); });
    }

    std::optional<std::string> getCache(const std::string& key) {
        return concurrencyManager.runTask<std::optional<std::string>>([&] { return cache.get(key); });
    }

    void processRealTimeData(const std::string& data) {
        concurrencyManager.runTask([&] { processor.process(data); });
    }

private:
    ConcurrencyManager concurrencyManager;
    NetworkRequestHandler networkHandler;
    DistributedCache cache;
    RealTimeDataProcessor processor;
};

// Example usage
int main() {
    NetworkLibrary library(10);

    library.sendRequest("http://example.com", [] {
        std::cout << "Response received" << std::endl;
    });

    library.putCache("key", "value");

    auto value = library.getCache("key");
    if (value) {
        std::cout << "Cached value: " << *value << std::endl;
    }

    library.processRealTimeData("data to process");

    return 0;
}
