#include <iostream>
#include <fstream>
#include <string>
#include <mutex>
#include <condition_variable>

class StateSerializer {
public:
    void serialize(const std::string& state, const std::string& filename) {
        std::ofstream file(filename);
        if (file.is_open()) {
            file << state;
            file.close();
        } else {
            throw std::runtime_error("Failed to open file for writing.");
        }
    }

    std::string deserialize(const std::string& filename) {
        std::ifstream file(filename);
        std::mutex mutex;
        std::condition_variable cv;
        bool ready = false;

        std::string state;
        if (file.is_open()) {
            while (!ready) {
                cv.wait(mutex, []{ return ready; });
                if (file.is_open()) {
                    std::getline(file, state);
                    file.close();
                    ready = true;
                }
            }
        } else {
            throw std::runtime_error("Failed to open file for reading.");
        }

        return state;
    }
};

int main() {
    StateSerializer serializer;
    try {
        serializer.serialize("SampleState", "state.txt");
        std::string deserializedState = serializer.deserialize("state.txt");
        std::cout << "Deserialized State: " << deserializedState << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

