#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1000
#define EVENT_QUEUE_SIZE 500

typedef struct {
    int id;
    char type[50];
    int priority;
    // Add more fields as needed
} Event;

Event event_queue[EVENT_QUEUE_SIZE];
int front = -1, rear = -1;

pthread_mutex_t queue_mutex;
pthread_cond_t not_full, not_empty;

void init_event_processing_pipeline() {
    pthread_mutex_init(&queue_mutex, NULL);
    pthread_cond_init(&not_full, NULL);
    pthread_cond_init(&not_empty, NULL);
}

void enqueue_event(Event event) {
    pthread_mutex_lock(&queue_mutex);
    while ((rear + 1) % EVENT_QUEUE_SIZE == front) { // Queue is full
        pthread_cond_wait(&not_full, &queue_mutex);
    }
    if (front == -1) {
        front = rear = 0;
    } else {
        rear = (rear + 1) % EVENT_QUEUE_SIZE;
    }
    event_queue[rear] = event;
    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&queue_mutex);
}

Event dequeue_event() {
    Event event;
    pthread_mutex_lock(&queue_mutex);
    while (front == -1) { // Queue is empty
        pthread_cond_wait(&not_empty, &queue_mutex);
    }
    event = event_queue[front];
    if (front == rear) {
        front = rear = -1;
    } else {
        front = (front + 1) % EVENT_QUEUE_SIZE;
    }
    pthread_cond_signal(&not_full);
    pthread_mutex_unlock(&queue_mutex);
    return event;
}

void* process_events(void* arg) {
    while (1) {
        Event event = dequeue_event();
        // Process the event here
        printf("Processing event: ID=%d, Type=%s, Priority=%d\n", event.id, event.type, event.priority);
    }
}

int main() {
