#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_EVENTS 1024
#define MAX_EVENT_SIZE 512

typedef struct Event {
    char data[MAX_EVENT_SIZE];
    int priority;
} Event;

Event event_buffer[MAX_EVENTS];
int buffer_index = 0;

pthread_mutex_t mutex;
pthread_cond_t cond;
int shutdown_flag = 0;

void* process_events(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        while (buffer_index == 0 && !shutdown_flag) {
            pthread_cond_wait(&cond, &mutex);
        }

        if (shutdown_flag) {
            pthread_mutex_unlock(&mutex);
            break;
        }

        Event event = event_buffer[--buffer_index];
        pthread_mutex_unlock(&mutex);

        // Process the event
        printf("Processing event: %s Priority: %d\n", event.data, event.priority);
    }
    return NULL;
}

void enqueue_event(const char* data, int priority) {
    pthread_mutex_lock(&mutex);
    if (buffer_index < MAX_EVENTS) {
        strncpy(event_buffer[buffer_index].data, data, MAX_EVENT_SIZE);
        event_buffer[buffer_index++].priority = priority;
        pthread_cond_signal(&cond);
    } else {
        printf("Event buffer is full!\n");
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, process_events, NULL);
    }

    // Simulate event generation
    for (int i = 0; i < 10; ++i) {
        char data[50];
        snprintf(data, sizeof(data), "Event %d", i);
        enqueue_event(data, i % 3); // Priority is 0, 1, or 2
        sleep(1);
    }

    // Shutdown the system
    pthread_mutex_lock(&mutex);
    shutdown_flag = 1;
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&mutex);

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

This code snippet demonstrates a simple, scalable event processing system in C. It uses threads to handle events concurrently and a mutex along with condition variables to synchronize access to the shared buffer. The `enqueue_event` function adds new events to the buffer, and the worker threads process these events. This example is highly simplified and lacks many features required for a full-fledged, fault-tolerant system, such as integration with external services, error handling, and dynamic configuration. However, it provides a basic structure that can be expanded upon to meet the requirements of the task.']

