// Define caching strategy (LRU)
class LRUCache {
private:
    std::unordered_map<std::string, std::pair<int, std::vector<char>>> cache;
    std::list<std::string> keys;
    int capacity;

public:
    LRUCache(int cap) : capacity(cap) {}

    std::vector<char>* get(const std::string& key) {
        if (cache.find(key) == cache.end()) return nullptr;
        keys.erase(std::find(keys.begin(), keys.end(), key));
        keys.push_front(key);
        return &cache[key].second;
    }

    void put(const std::string& key, const std::vector<char>& value) {
        if (cache.size() >= capacity) {
            cache.erase(keys.back());
            keys.pop_back();
        }
        keys.push_front(key);
        cache[key] = {0, value};
    }

    bool containsKey(const std::string& key) {
        return cache.find(key) != cache.end();
    }
};

