            callback("Processed successfully", userData);
            return;
        }
        attempts++;
    }
    // Log failure after retries
    printf("Failed to process string: %s\n", input);
}

// Thread-safe function to process the input string
char* processString(const char* input, size_t sizeLimit, CallbackFunc callback, void* userData) {
    if (sizeLimit < 0) {
        fprintf(stderr, "Invalid size limit: %zu\n", sizeLimit);
        return NULL;
    }

    size_t inputLen = strlen(input);
    if (inputLen > sizeLimit) {
        char* newString = safe_malloc(inputLen + 2);
        strcpy(newString, input);
        newString[inputLen] = '/';
        newString[inputLen + 1] = '\0';
        executeAsyncTask(newString, inputLen + 1, callback, userData);
        free(newString);
    } else {
        executeAsyncTask(input, inputLen, callback, userData);
    }

    return NULL; // Return NULL in asynchronous mode
}

