#include <iostream>
#include <thread>
#include <vector>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>

// Define a simple data point structure
struct DataPoint {
    std::string source;
    double value;
};

class DataProcessor {
public:
    // Constructor
    DataProcessor() : running(true), stop(false) {}

    // Start processing thread
    void startProcessing() {
        processThread = std::thread(&DataProcessor::process, this);
    }

    // Stop processing thread
    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        processThread.join();
    }

    // Function to push data into the queue for processing
    void pushData(const DataPoint& dp) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            dataQueue.push(dp);
        }
        condition.notify_one();
    }

private:
    void process() {
        while (running) {
            DataPoint dp;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !dataQueue.empty() || stop; });
                if (stop && dataQueue.empty()) {
                    running = false;
                    break;
                }
                dp = dataQueue.front();
                dataQueue.pop();
            }
            // Process the data point
            processData(dp);
        }
    }

    void processData(const DataPoint& dp) {
        // Placeholder for processing logic
        std::cout << "Processing data from source: " << dp.source << ", value: " << dp.value << std::endl;
    }

    std::thread processThread;
    std::atomic<bool> running;
    std::atomic<bool> stop;
    std::mutex mutex;
    std::condition_variable condition;
    std::queue<DataPoint> dataQueue;
};

int main() {
    DataProcessor processor;
    processor.startProcessing();

    // Simulate pushing data
    for (int i = 0; i < 10; ++i) {
        DataPoint dp{"source" + std::to_string(i), static_cast<double>(i)};
        processor.pushData(dp);
    }

    // Stop processing after some time
    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.stopProcessing();

    return 0;
}
```

