import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class NetworkConnectionManager {
    private ConcurrentHashMap<String, LinkedList<NetworkConnectionStatusEntry>> tenantConnections;
    private ExecutorService executorService;

    public NetworkConnectionManager() {
        this.tenantConnections = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(10);
    }

    public void addTenant(String tenantId) {
        if (!tenantConnections.containsKey(tenantId)) {
            tenantConnections.put(tenantId, new LinkedList<>());
        }
    }

    public void removeTenant(String tenantId) {
        tenantConnections.remove(tenantId);
    }

    public void addConnection(String tenantId, NetworkConnectionStatusEntry entry) {
        if (tenantConnections.containsKey(tenantId)) {
            tenantConnections.get(tenantId).add(entry);
        }
    }

    public void removeConnection(String tenantId, int connectionId) {
        if (tenantConnections.containsKey(tenantId)) {
            tenantConnections.get(tenantId).removeIf(entry -> entry.getConnectionId() == connectionId);
        }
    }

    public NetworkConnectionStatusEntry getConnectionStatus(String tenantId, int connectionId) {
        if (tenantConnections.containsKey(tenantId)) {
            return tenantConnections.get(tenantId).stream()
                .filter(entry -> entry.getConnectionId() == connectionId)
                .findFirst()
                .orElse(null);
        }
        return null;
    }

    public void updateConnectionStatus(String tenantId, NetworkConnectionStatusEntry newStatus) {
        if (tenantConnections.containsKey(tenantId)) {
            tenantConnections.get(tenantId).removeIf(entry -> entry.getConnectionId() == newStatus.getConnectionId());
            tenantConnections.get(tenantId).add(newStatus);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }
}

