        std::unique_ptr<IFilePathValidator> filePathValidator;
        std::unique_ptr<IVersionedStorage> versionedStorage;
        std::unique_ptr<IConcurrencyController> concurrencyController;
        std::unique_ptr<ILogger> logger;
        std::unique_ptr<IFallbackManager> fallbackManager;

    public:
        FileOperationManager(IFilePathValidator* validator, IVersionedStorage* storage,
                             IConcurrencyController* controller, ILogger* logger_,
                             IFallbackManager* fallback_)
            : filePathValidator(validator), versionedStorage(storage),
              concurrencyController(controller), logger(logger_),
              fallbackManager(fallback_) {}

        // Function to manage file operations
        void ManageFileOperation(const std::string& filePath, const std::string& operation) {
            if (!filePathValidator->Validate(filePath)) {
                logger->LogError("Invalid file path provided.");
