            concurrencyController->AcquireLock(filePath);
            try {
                versionedStorage->ExecuteOperation(filePath, operation);
                concurrencyController->ReleaseLock(filePath);
                logger->LogInfo("File operation completed successfully.");
            } catch (const std::exception& e) {
                concurrencyController->ReleaseLock(filePath);
