import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DistributedFileProcessingSystem {

    private ExecutorService executorService;

    public DistributedFileProcessingSystem(int numberOfThreads) {
        this.executorService = Executors.newFixedThreadPool(numberOfThreads);
    }

    public void submitTask(Runnable task) {
        executorService.submit(task);
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
    }

    public static void main(String[] args) {
        DistributedFileProcessingSystem system = new DistributedFileProcessingSystem(10);

        // Submit tasks for file processing
        for (int i = 0; i < 50; i++) {
            system.submitTask(new FileProcessingTask("file" + i + ".log"));
        }

        try {
            system.shutdown();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    static class FileProcessingTask implements Runnable {
        private String fileName;

        public FileProcessingTask(String fileName) {
            this.fileName = fileName;
        }

        @Override
        public void run() {
            // Simulate file processing
            try {
                System.out.println("Processing " + fileName);
                Thread.sleep(100); // Simulate time taken to process the file
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            System.out.println(fileName + " processed");
        }
    }
}
