#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 1000

typedef struct {
    time_t timestamp;
    char type[50];
    void* metadata;
} Event;

Event eventQueue[MAX_EVENTS];
int front = -1, rear = -1;
pthread_mutex_t queueMutex;
pthread_cond_t queueCond;
int numThreads = 4;

void initEvent(Event* event) {
    event->timestamp = time(NULL);
    snprintf(event->type, sizeof(event->type), "Unknown");
    event->metadata = NULL;
}

void enqueueEvent(Event event) {
    pthread_mutex_lock(&queueMutex);
    if ((rear + 1) % MAX_EVENTS == front) {
        printf("Queue is full\n");
        pthread_mutex_unlock(&queueMutex);
        return;
    }
    if (front == -1)
        front = rear = 0;
    else
        rear = (rear + 1) % MAX_EVENTS;
    eventQueue[rear] = event;
    pthread_cond_signal(&queueCond);
    pthread_mutex_unlock(&queueMutex);
}

void* processEvents(void* arg) {
    while (1) {
        pthread_mutex_lock(&queueMutex);
        while (front == -1)
            pthread_cond_wait(&queueCond, &queueMutex);
        Event event = eventQueue[front];
        front = (front + 1) % MAX_EVENTS;
        if (front == rear)
            front = rear = -1;
        pthread_mutex_unlock(&queueMutex);

        // Process the event here
        printf("Processing event: Timestamp=%ld, Type=%s\n", event.timestamp, event.type);
    }
    return NULL;
}

int main() {
    pthread_t threads[numThreads];
    pthread_mutex_init(&queueMutex, NULL);
    pthread_cond_init(&queueCond, NULL);

    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], NULL, processEvents, NULL);
    }

    // Simulate event generation
    for (int i = 0; i < 10; i++) {
        Event newEvent;
        initEvent(&newEvent);
        enqueueEvent(newEvent);
        usleep(50000); // Sleep to simulate time passing
    }

    // Wait for all threads to finish
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&queueMutex);
    pthread_cond_destroy(&queueCond);

    return 0;
}
