    else
        rear = (rear + 1) % MAX_EVENTS;
    event_queue[rear] = event;
    pthread_mutex_unlock(&queue_lock);
}

Event dequeue_event() {
    Event event;
    pthread_mutex_lock(&queue_lock);
    if (front == -1) {
        printf("Queue is empty\n");
        return (Event){0, "", NULL};
    }
    event = event_queue[front];
    if (front == rear)
        front = rear = -1;
    else
        front = (front + 1) % MAX_EVENTS;
    pthread_mutex_unlock(&queue_lock);
    return event;
}

void* event_processor(void* arg) {
    while (1) {
        Event event = dequeue_event();
        if (event.timestamp == 0 && strcmp(event.type, "") == 0 && event.metadata == NULL)
            break;
        // Process the event here
        printf("Processing event: type=%s, timestamp=%ld\n", event.type, event.timestamp);
    }
    return NULL;
}

void init_event_processing_system() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++)
        pthread_create(&threads[i], NULL, event_processor, NULL);
    // Start listening for events from network here
}

void shutdown_event_processing_system() {
    Event end_event = {0, "", NULL};
    enqueue_event(end_event);
    for (int i = 0; i < 10; i++)
        pthread_join(threads[i], NULL);
}

int main() {
    init_event_processing_system();
    // Simulate event generation here
    shutdown_event_processing_system();
    return 0;
}
