import org.apache.spark.sql.Dataset;
import org.apache.spark.sql.Row;
import org.apache.spark.sql.SparkSession;
import org.apache.spark.streaming.Durations;
import org.apache.spark.streaming.api.java.JavaDStream;
import org.apache.spark.streaming.api.java.JavaInputDStream;
import org.apache.spark.streaming.kafka010.ConsumerStrategies;
import org.apache.spark.streaming.kafka010.KafkaUtils;
import org.apache.spark.streaming.kafka010.LocationStrategies;

import java.util.HashMap;
import java.util.Map;

public class IoTDataProcessingPipeline {
    public static void main(String[] args) {
        SparkSession spark = SparkSession.builder()
                .appName("IoT Data Processing Pipeline")
                .master("local[*]")
                .getOrCreate();

        Map<String, Object> kafkaParams = new HashMap<>();
        kafkaParams.put("bootstrap.servers", "localhost:9092");
        kafkaParams.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        kafkaParams.put("value.deserializer", "org.apache.spark.sql.Encoders$StringEncoder");
        kafkaParams.put("group.id", "iot-data-group");
        kafkaParams.put("auto.offset.reset", "latest");
        kafkaParams.put("enable.auto.commit", false);

        String[] topics = {"iot-data"};

        JavaInputDStream<ConsumerRecord<String, String>> stream = KafkaUtils.createDirectStream(
                spark.sparkContext(),
                LocationStrategies.PreferConsistent(),
                ConsumerStrategies.Subscribe(topics, kafkaParams)
        );

        JavaDStream<Row> parsedData = stream.map(record -> {
            // Parse the IoT data and create a Row object
            return parseIoTData(record.value());
        });

        Dataset<Row> aggregatedData = parsedData.groupBy("deviceId")
                .agg(
                        sum("value").alias("totalValue"),
                        avg("value").alias("averageValue"),
                        max("value").alias("maxValue"),
                        min("value").alias("minValue")
                );

        aggregatedData.writeStream()
                .outputMode("complete")
                .format("console")
                .start()
                .awaitTermination();
    }

    private static Row parseIoTData(String data) {
        // Parse the IoT data and create a Row object
        // Example: "deviceId=123,value=45.6"
        String[] parts = data.split(",");
        String deviceId = parts[0].split("=")[1];
        double value = Double.parseDouble(parts[1].split("=")[1]);
        return new Row(deviceId, value);
    }
}
