using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Cassandra;

public class FaultTolerantSqlLibrary : IFaultTolerantSqlLibrary
{
    private readonly IHttpClientFactory _httpClientFactory;
    private readonly ICassandraSessionProvider _cassandraSessionProvider;
    private readonly ILogger _logger;

    public FaultTolerantSqlLibrary(IHttpClientFactory httpClientFactory, ICassandraSessionProvider cassandraSessionProvider, ILogger logger)
    {
        _httpClientFactory = httpClientFactory;
        _cassandraSessionProvider = cassandraSessionProvider;
        _logger = logger;
    }

    public async Task<IDataReader> ExecuteSqlCommandAsync(string connectionString, string commandText, Dictionary<string, object> parameters)
    {
        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                using (var connection = new SqlConnection(connectionString))
                {
                    await connection.OpenAsync();
                    using (var command = new SqlCommand(commandText, connection))
                    {
                        parameters.ToList().ForEach(p => command.Parameters.AddWithValue(p.Key, p.Value));
                        return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to execute SQL command. Attempt {Attempt}", attempt + 1);
                if (attempt == 2) throw;
                await Task.Delay(1000 * (int)Math.Pow(2, attempt)); // Exponential backoff
            }
        }
    }

    public async Task SubmitEventAsync(string eventName, dynamic eventData)
    {
        for (int attempt = 0; attempt < 3; attempt++)
        {
            try
            {
                using var session = _cassandraSessionProvider.GetSession();
                await session.ExecuteAsync("INSERT INTO events (event_name, event_data) VALUES (@eventName, @eventData)", new { eventName, eventData });
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to submit event. Attempt {Attempt}", attempt + 1);
                if (attempt == 2) throw;
                await Task.Delay(1000 * (int)Math.Pow(2, attempt)); // Exponential backoff
            }
        }
    }

    public async Task<List<EventData>> GetUnprocessedEventsAsync()
    {
        try
        {
            using var session = _cassandraSessionProvider.GetSession();
            return (await session.ExecuteAsync("SELECT * FROM events WHERE processed = false")).GetResults().ToList();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to retrieve unprocessed events");
            throw;
        }
    }

    public async Task MarkEventsAsProcessedAsync(List<EventData> events)
    {
        try
        {
            using var session = _cassandraSessionProvider.GetSession();
            foreach (var event in events)
            {
                await session.ExecuteAsync("UPDATE events SET processed = true WHERE id = @id", new { event.Id });
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to mark events as processed");
            throw;
        }
    }

    public async Task<string> GetAccessTokenAsync(string authorityUrl, string clientId, string clientSecret)
    {
        var httpClient = _httpClientFactory.CreateClient();
        var content = new FormUrlEncodedContent(new[]
        {
            new KeyValuePair<string, string>("grant_type", "client_credentials"),
            new KeyValuePair<string, string>("scope", "api://example.com/data"),
            new KeyValuePair<string, string>("client_id", clientId),
            new KeyValuePair<string, string>("client_secret", clientSecret)
        });

        var response = await httpClient.PostAsync(authorityUrl, content);
        response.EnsureSuccessStatusCode();
        var responseBody = await response.Content.ReadAsStringAsync();
        // Parse the JSON response to extract the access token
        return JObject.Parse(responseBody)["access_token"].ToString();
    }
}

public interface IFaultTolerantSqlLibrary
{
    Task<IDataReader> ExecuteSqlCommandAsync(string connectionString, string commandText, Dictionary<string, object> parameters);
    Task SubmitEventAsync(string eventName, dynamic eventData);
    Task<List<EventData>> GetUnprocessedEventsAsync();
    Task MarkEventsAsProcessedAsync(List<EventData> events);
    Task<string> GetAccessTokenAsync(string authorityUrl, string clientId, string clientSecret);
}

public class EventData
{
    public Guid Id { get; set; }
    public string EventName { get; set; }
    public dynamic EventData { get; set; }
    public bool Processed { get; set; }
}

public interface ICassandraSessionProvider
{
    ISession GetSession();
}

public class CassandraSessionProvider : ICassandraSessionProvider
{
    private readonly Cluster _cluster;
    private readonly string[] _contactPoints;

    public CassandraSessionProvider(string[] contactPoints)
    {
        _contactPoints = contactPoints;
        _cluster = Cluster.Builder().AddContactPoints(_contactPoints).Build();
    }

    public ISession GetSession()
    {
        return _cluster.Connect("events");
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message, params object[] args);
}

public class Logger : ILogger
{
    public void LogError(Exception ex, string message, params object[] args)
    {
        Console.WriteLine($"ERROR: {string.Format(message, args)} - Exception: {ex.Message}");
    }
}
```

This code snippet provides a basic structure for the fault-tolerant SQL library. It includes methods to execute parameterized SQL commands, submit events to a Cassandra database, retrieve unprocessed events, mark events as processed, and obtain OAuth 2.0 access tokens using TLS. The library uses exponential backoff for retries and logs errors using a simple `ILogger` interface. You can extend this code by adding more features such as network partition detection, service outages handling, asynchronous programming patterns, real-time monitoring, and CLI tool functionalities as per your requirements.']

