    public Task<double> GenerateRandomDoubleAsync(string rangeKey)
    {
        var random = GetRandomGenerator(rangeKey);
        return Task.FromResult(random.NextDouble());
    }

    public Task<int> GenerateRandomIntAsync(string rangeKey)
    {
        var random = GetRandomGenerator(rangeKey);
        return Task.FromResult(random.Next(int.MaxValue));
    }

    private Random GetRandomGenerator(string rangeKey)
    {
        if (!_randomGenerators.TryGetValue(rangeKey, out var random))
        {
            _randomGenerators.TryAdd(rangeKey, new Random());
        }
        return random;
    }
}

