#include <stdlib.h>

typedef struct {
    const char* name;
    void (*cipher_init)(EVP_CIPHER_CTX*, const unsigned char*, const unsigned char*);
} CipherInfo;

typedef struct {
    const char* name;
    void (*hash_init)(SHA256_CTX*);
    int (*hash_update)(SHA256_CTX*, const unsigned char*, size_t);
    void (*hash_final)(unsigned char*, SHA256_CTX*);
} HashInfo;

CipherInfo ciphers[] = {
    {"DES-ECB", EVP_EncryptInit_ex},
    {"DES-EDE", EVP_CIPHER_meth_new(NID_des_ede3_cbc, EVP_CIPH_CBC_MODE, EVP_enc_null)},
    {"DES-EDE3", EVP_CIPHER_meth_new(NID_des_ede3_cbc, EVP_CIPH_CBC_MODE, EVP_enc_null)},
    {"CFB", EVP_EncryptInit_ex},
};

HashInfo hashes[] = {
    {"SHA-256", SHA256_Init, SHA256_Update, SHA256_Final},
};

EVP_CIPHER* get_cipher(const char* name) {
    for (size_t i = 0; i < sizeof(ciphers) / sizeof(ciphers[0]); ++i) {
        if (strcmp(ciphers[i].name, name) == 0) {
            return ciphers[i].cipher_init;
        }
    }
    return NULL;
}

SHA256_CTX* get_hash(const char* name) {
    for (size_t i = 0; i < sizeof(hashes) / sizeof(hashes[0]); ++i) {
        if (strcmp(hashes[i].name, name) == 0) {
            SHA256_CTX* ctx = (SHA256_CTX*)malloc(sizeof(SHA256_CTX));
            hashes[i].hash_init(ctx);
            return ctx;
        }
    }
    return NULL;
}

void free_hash(SHA256_CTX* ctx) {
    free(ctx);
}
