#include <iostream>
#include <vector>
#include <chrono>
#include <cmath>

// Union-Find data structure implementation
class UF {
public:
    UF(int n) : parent(n), rank(n, 0) {}

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    void unite(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

private:
    std::vector<int> parent;
    std::vector<int> rank;
};

// Function to count disjoint pairs using Union-Find
int countDisjointPairs(const std::vector<int>& arr) {
    int n = arr.size();
    UF uf(n);

    // Create a graph with edges between all pairs (i, j)
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (std::gcd(arr[i], arr[j]) == 1) { // Example condition: disjoint if gcd is 1
                uf.unite(i, j);
            }
        }
    }

    // Count the number of connected components
    std::vector<bool> visited(n, false);
    int componentCount = 0;

    for (int i = 0; i < n; ++i) {
        if (!visited[uf.find(i)]) {
            visited[uf.find(i)] = true;
            componentCount++;
        }
    }

    return componentCount - 1; // Each connected component forms a pair with every other component
}

// Wrapper function to time the disjoint pair count and print the result
void processArray(const std::vector<int>& arr) {
    auto start = std::chrono::high_resolution_clock::now();
    int disjointPairs = countDisjointPairs(arr);
    auto end = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double, std::milli> elapsed = end - start;
    std::cout << "Number of disjoint pairs: " << disjointPairs << std::endl;
    std::cout << "Time taken: " << elapsed.count() << " ms" << std::endl;
}

int main() {
    std::vector<int> arr = {2, 3, 5, 7, 11, 13};
    processArray(arr);
    return 0;
}
```

