// Define a structure for market data
struct MarketData {
    std::string symbol;
    double price;
    int importanceLevel;
};

// Define a class for the financial market data processing pipeline
class FinancialMarketPipeline {
public:
    FinancialMarketPipeline(size_t numWorkers, size_t numNodes)
        : workers(numWorkers), nodes(numNodes) {}

    void start() {
        // Start worker threads
        for (size_t i = 0; i < workers.size(); ++i) {
            workers[i] = std::thread(&FinancialMarketPipeline::workerThread, this);
        }

        // Start node processing threads
        for (size_t i = 0; i < nodes.size(); ++i) {
            nodes[i] = std::thread(&FinancialMarketPipeline::nodeProcessingThread, this);
        }
    }

    void stop() {
        // Stop worker threads
        for (auto& worker : workers) {
            worker.join();
        }

        // Stop node processing threads
        for (auto& node : nodes) {
            node.join();
        }
    }

    void addData(const MarketData& data) {
        std::lock_guard<std::mutex> lock(queueMutex);
        queue.push(data);
        dataAvailable.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            MarketData data;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                dataAvailable.wait(lock, [this] { return !queue.empty(); });
                data = queue.front();
                queue.pop();
            }
            processData(data);
        }
    }

    void nodeProcessingThread() {
        while (true) {
            MarketData data;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                dataAvailable.wait(lock, [this] { return !queue.empty(); });
                data = queue.front();
                queue.pop();
            }
            processOnNode(data);
        }
    }

    void processData(const MarketData& data) {
        // Implement data processing logic
        std::cout << "Processing data for " << data.symbol << " at price " << data.price << std::endl;
    }

    void processOnNode(const MarketData& data) {
        // Implement node-specific data processing logic
        std::cout << "Processing data on node for " << data.symbol << " at price " << data.price << std::endl;
    }

private:
    std::vector<std::thread> workers;
    std::vector<std::thread> nodes;
    std::queue<MarketData> queue;
    std::mutex queueMutex;
    std::condition_variable dataAvailable;
};

int main() {
    FinancialMarketPipeline pipeline(4, 2);
    pipeline.start();

    // Simulate adding market data
    for (int i = 0; i < 10; ++i) {
        MarketData data{std::string("AAPL") + std::to_string(i), static_cast<double>(i * 10), i % 3};
        pipeline.addData(data);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    pipeline.stop();
    return 0;
}
