#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <curl/curl.h>
#include <time.h>

#define MAX_SEMAPHORES 5000

typedef struct {
    sem_t *sem;
    char name[256];
    int usage_count;
} Semaphore;

Semaphore semaphore_pool[MAX_SEMAPHORES];
int pool_size = 0;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pool_cond = PTHREAD_COND_INITIALIZER;

void* create_semaphore(void* arg) {
    char* name = (char*)arg;
    sem_t *sem = malloc(sizeof(sem_t));
    if (sem_init(sem, 1, 0) == -1) {
        perror("Failed to initialize semaphore");
        return NULL;
    }
    pthread_mutex_lock(&pool_lock);
    while (pool_size >= MAX_SEMAPHORES) {
        pthread_cond_wait(&pool_cond, &pool_lock);
    }
    semaphore_pool[pool_size].sem = sem;
    snprintf(semaphore_pool[pool_size].name, sizeof(semaphore_pool[pool_size].name), "%s", name);
    semaphore_pool[pool_size].usage_count = 0;
    pool_size++;
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void* delete_semaphore(void* arg) {
    char* name = (char*)arg;
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (strcmp(semaphore_pool[i].name, name) == 0) {
            sem_destroy(semaphore_pool[i].sem);
            free(semaphore_pool[i].sem);
            for (int j = i; j < pool_size - 1; j++) {
                semaphore_pool[j] = semaphore_pool[j + 1];
            }
            pool_size--;
            pthread_cond_signal(&pool_cond);
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void* modify_semaphore(void* arg) {
    char* name = (char*)arg;
    int new_value = *(int*)arg + 1; // Example modification
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < pool_size; i++) {
        if (strcmp(semaphore_pool[i].name, name) == 0) {
            sem_post(semaphore_pool[i].sem);
            semaphore_pool[i].usage_count++;
            break;
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void* log_semaphore_operations(void* arg) {
    while (1) {
        for (int i = 0; i < pool_size; i++) {
            printf("Semaphore %s: Usage Count - %d\n", semaphore_pool[i].name, semaphore_pool[i].usage_count);
        }
        sleep(1); // Log every second
    }
    return NULL;
}

void* monitor_semaphore_activity(void* arg) {
    while (1) {
        for (int i = 0; i < pool_size; i++) {
            if (semaphore_pool[i].usage_count > 100) { // Example threshold
                printf("Alert: Semaphore %s usage is high\n", semaphore_pool[i].name);
            }
        }
        sleep(5); // Monitor every 5 seconds
    }
    return NULL;
}

void* integrate_with_rest_api(void* arg) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);

    curl = curl_easy_init();
    if(curl) {
        char url[1024];
        snprintf(url, sizeof(url), "https://api.example.com/semaphore/%s", (char*)arg);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return NULL;
}

int main() {
    pthread_t log_thread, monitor_thread;

    pthread_create(&log_thread, NULL, log_semaphore_operations, NULL);
    pthread_create(&monitor_thread, NULL, monitor_semaphore_activity, NULL);

    for (int i = 0; i < 10; i++) { // Example semaphore creation
        char name[256];
        snprintf(name, sizeof(name), "semaphore%d", i);
        pthread_t create_thread;
        pthread_create(&create_thread, NULL, create_semaphore, name);
    }

    for (int i = 0; i < 10; i++) { // Example semaphore modification
        int new_value = 1;
        pthread_t modify_thread;
        pthread_create(&modify_thread, NULL, modify_semaphore, &new_value);
    }

    for (int i = 0; i < 5; i++) { // Example semaphore deletion
        char name[256];
        snprintf(name, sizeof(name), "semaphore%d", i);
        pthread_t delete_thread;
        pthread_create(&delete_thread, NULL, delete_semaphore, name);
    }

    for (int i = 0; i < 3; i++) { // Example REST API integration
        char resource[256];
        snprintf(resource, sizeof(resource), "resource%d", i);
        pthread_t api_thread;
        pthread_create(&api_thread, NULL, integrate_with_rest_api, resource);
    }

    pthread_join(log_thread, NULL);
    pthread_join(monitor_thread, NULL);

    return 0;
}
