    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public float CameraSpeed { get; set; }
}

public class ConfigurationLoader
{
    private readonly IMemoryCache _cache;
    private const string XmlConfigPath = "config.xml";
    private const string JsonConfigPath = "config.json";

    public ConfigurationLoader(IMemoryCache cache)
    {
        _cache = cache;
    }

    public GameConfiguration LoadXmlConfig()
    {
        var xmlSerializer = new XmlSerializer(typeof(GameConfiguration));
        using (var reader = File.OpenText(XmlConfigPath))
        {
            return (GameConfiguration)xmlSerializer.Deserialize(reader);
        }
    }

    public GameConfiguration LoadJsonConfig()
    {
        string json;
        using (StreamReader r = new StreamReader(JsonConfigPath))
        {
            json = r.ReadToEnd();
        }
        return JsonConvert.DeserializeObject<GameConfiguration>(json);
    }

    public GameConfiguration GetConfig(bool useCache = true)
    {
        if (useCache && _cache.TryGetValue("gameConfig", out var cachedConfig))
        {
            return (GameConfiguration)cachedConfig;
        }

        var config = LoadXmlConfig();
        config.TileSize = Math.Max(config.TileSize, 32); // Ensure minimum tile size

        _cache.Set("gameConfig", config, new MemoryCacheEntryOptions
        {
            SlidingExpirationRelativeToNow = TimeSpan.FromMinutes(5)
        });

        return config;
    }
}

