<?php

// Define the base URL for OAuth 2.0 token endpoint
define('OAUTH_TOKEN_ENDPOINT', 'https://oauth.example.com/token');

// Function to get an access token using OAuth 2.0
function getAccessToken($clientId, $clientSecret) {
    $url = OAUTH_TOKEN_ENDPOINT;
    $data = [
        'grant_type' => 'client_credentials',
        'client_id' => $clientId,
        'client_secret' => $clientSecret
    ];

    $options = [
        'http' => [
            'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
            'method'  => 'POST',
            'content' => http_build_query($data),
        ],
    ];
    $context  = stream_context_create($options);
    $result   = file_get_contents($url, false, $context);
    return json_decode($result)->access_token;
}

// Function to update a resource using HTTP PUT
function updateResource($accessToken, $resourceId, $data) {
    $url = "https://api.example.com/resources/$resourceId";
    $options = [
        'http' => [
            'header'  => "Authorization: Bearer $accessToken\r\nContent-Type: application/json\r\n",
            'method'  => 'PUT',
            'content' => json_encode($data),
        ],
    ];
    $context  = stream_context_create($options);
    $result   = file_get_contents($url, false, $context);
    return json_decode($result);
}

// Function to delete a resource using HTTP DELETE
function deleteResource($accessToken, $resourceId) {
    $url = "https://api.example.com/resources/$resourceId";
    $options = [
        'http' => [
            'header'  => "Authorization: Bearer $accessToken\r\n",
            'method'  => 'DELETE',
        ],
    ];
    $context  = stream_context_create($options);
    return file_get_contents($url, false, $context);
}

// Example usage
$clientId = 'your_client_id';
$clientSecret = 'your_client_secret';
$resourceId = '12345';

$accessToken = getAccessToken($clientId, $clientSecret);

$dataToUpdate = [
    'name' => 'Updated Resource',
    'description' => 'This is an updated resource description.'
];

$response = updateResource($accessToken, $resourceId, $dataToUpdate);
echo "Update Response: " . json_encode($response) . "\n";

$response = deleteResource($accessToken, $resourceId);
echo "Delete Response: " . $response . "\n";
?>
