#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

// Define a structure for encryption operations
typedef struct {
    EVP_CIPHER_CTX *ctx;
    int encrypt_mode;
} Cipher;

// Function to create a new cipher object
Cipher* create_cipher(int mode) {
    Cipher *cipher = (Cipher *)malloc(sizeof(Cipher));
    if (!cipher) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(cipher);
        return NULL;
    }
    cipher->encrypt_mode = mode;
    return cipher;
}

// Function to initialize the cipher
int init_cipher(Cipher *cipher, const unsigned char *key, const unsigned char *iv) {
    if (EVP_CipherInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, key, iv, cipher->encrypt_mode) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        return -1;
    }
    return 0;
}

// Function to encrypt data
int encrypt_data(Cipher *cipher, const unsigned char *plaintext, int plaintext_len, unsigned char **ciphertext, int *ciphertext_len) {
    if (EVP_EncryptUpdate(cipher->ctx, *ciphertext, ciphertext_len, plaintext, plaintext_len) != 1) {
        fprintf(stderr, "Encryption failed\n");
        return -1;
    }
    return 0;
}

// Function to finalize the encryption
int finalize_cipher(Cipher *cipher, unsigned char **ciphertext, int *ciphertext_len) {
    if (EVP_EncryptFinal_ex(cipher->ctx, (*ciphertext + *ciphertext_len), ciphertext_len) != 1) {
        fprintf(stderr, "Finalization failed\n");
        return -1;
    }
    EVP_CIPHER_CTX_free(cipher->ctx);
    free(cipher);
    return 0;
}

// Example usage
int main() {
    unsigned char key[32] = { /* Your key here */ };
    unsigned char iv[16] = { /* Your IV here */ };
    unsigned char plaintext[] = "Hello, World!";
    int plaintext_len = strlen((char *)plaintext);
    unsigned char *ciphertext;
    int ciphertext_len;

    Cipher *cipher = create_cipher(1); // 1 for encryption
    if (!cipher) {
        return -1;
    }

    ciphertext_len = plaintext_len + EVP_CIPHER_BLOCK_SIZE;
    ciphertext = (unsigned char *)malloc(ciphertext_len);
    if (!ciphertext) {
        fprintf(stderr, "Memory allocation failed\n");
        finalize_cipher(cipher, NULL, &ciphertext_len);
        return -1;
    }

    if (init_cipher(cipher, key, iv) != 0 ||
        encrypt_data(cipher, plaintext, plaintext_len, &ciphertext, &ciphertext_len) != 0 ||
        finalize_cipher(cipher, &ciphertext, &ciphertext_len) != 0) {
        free(ciphertext);
        return -1;
    }

    // Output ciphertext
    printf("Ciphertext: ");
    for (int i = 0; i < ciphertext_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    free(ciphertext);
    return 0;
}
