// Define the AngularJS module
angular.module('TenantDialogService', ['ngResource', 'ngRoute'])

.config(['$routeProvider', function($routeProvider) {
    $routeProvider.when('/dialog/:tenantId', {
        templateUrl: 'partials/dialog.html',
        controller: 'DialogController'
    });
}])

.factory('DialogService', ['$resource', '$q', '$timeout', 'CacheFactory', function($resource, $q, $timeout, CacheFactory) {
    var dialogCache = CacheFactory.createCache('dialogCache');

    return {
        refreshDialogFields: function(tenantId, resourceId) {
            var cachedData = dialogCache.get(resourceId);
            if (cachedData && !isCacheExpired(cachedData.timestamp)) {
                return $q.when(cachedData.data);
            }

            return fetchNewData(tenantId, resourceId)
                .then(function(data) {
                    cacheData(resourceId, data);
                    return data;
                });
        }
    };

    function isCacheExpired(timestamp) {
        // Implement cache expiration logic
        return timestamp + (10 * 60 * 1000) < new Date().getTime(); // Example: Cache expires after 10 minutes
    }

    function fetchNewData(tenantId, resourceId) {
        var resource = $resource('/api/dialog/:tenantId/resource/:resourceId', { tenantId: '@tenantId', resourceId: '@resourceId' });
        return resource.get({}).$promise;
    }

    function cacheData(resourceId, data) {
