#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int rnti;
    int rx_ue_information_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int pdu_type;
    // other fields as per NFAPI_CRC_INDICATION_PDU_T
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PduBatch;

PduBatch* generatePduBatch(size_t batch_size) {
    PduBatch *batch = malloc(sizeof(PduBatch));
    if (batch == NULL) return NULL;

    batch->capacity = batch_size;
    batch->size = 0;
    batch->pdus = calloc(batch_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (batch->pdus == NULL) {
        free(batch);
        return NULL;
    }

    pthread_mutex_init(&batch->lock, NULL);

    return batch;
}

void destroyPduBatch(PduBatch *batch) {
    if (batch == NULL) return;

    pthread_mutex_lock(&batch->lock);
    free(batch->pdus);
    pthread_mutex_unlock(&batch->lock);

    pthread_mutex_destroy(&batch->lock);
    free(batch);
}

int addPduToBatch(PduBatch *batch, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (batch == NULL) return -1;

    pthread_mutex_lock(&batch->lock);
    if (batch->size >= batch->capacity) {
        pthread_mutex_unlock(&batch->lock);
        return -1;
    }

    batch->pdus[batch->size++] = pdu;
    pthread_mutex_unlock(&batch->lock);

    return 0;
}

