typedef struct {
    int id;
    char *message;
} Event;

typedef struct {
    pthread_mutex_t lock;
    Event *events;
    int count;
    int capacity;
} Logger;

Logger logger = {PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0};

void init_logger() {
    logger.events = (Event *)malloc(sizeof(Event) * 10);
    logger.capacity = 10;
}

void submit_event(Event event) {
    pthread_mutex_lock(&logger.lock);
    if (logger.count == logger.capacity) {
        // Resize the events array
        logger.capacity *= 2;
        logger.events = (Event *)realloc(logger.events, sizeof(Event) * logger.capacity);
    }
    logger.events[logger.count++] = event;
    pthread_mutex_unlock(&logger.lock);
}

void *event_logger_thread(void *arg) {
    while (1) {
        Event *event;
        pthread_mutex_lock(&logger.lock);
        if (logger.count > 0) {
            event = &logger.events[--logger.count];
        } else {
            pthread_mutex_unlock(&logger.lock);
            continue;
        }
        pthread_mutex_unlock(&logger.lock);

        // Submit the event to external services
        submit_to_external_service(event->message);
    }
}

