#include <iostream>
#include <string>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <memory>
#include <chrono>

// Event structure
struct Event {
    std::time_t timestamp;
    std::string type;
    std::string metadata;
};

// NoSQL database interface
class NoSqlDatabase {
public:
    virtual void store(const Event& event) = 0;
};

// Third-party logging service interface
class LoggingService {
public:
    virtual void log(const std::string& message) = 0;
};

// Event processor
class EventProcessor {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable condVar;
    bool stopProcessing;
    NoSqlDatabase* db;
    LoggingService* logger;

public:
    EventProcessor(NoSqlDatabase* db, LoggingService* logger) : db(db), logger(logger), stopProcessing(false) {}

    void start() {
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(queueMutex);
                condVar.wait(lock, [this] { return !eventQueue.empty() || stopProcessing; });
                if (stopProcessing && eventQueue.empty()) break;
                Event event = eventQueue.front();
                eventQueue.pop();
                lock.unlock();

                try {
                    db->store(event);
                    logger->log("Event processed: " + event.metadata);
                } catch (...) {
                    logger->log("Error processing event: " + event.metadata);
                }
            }
        }).detach();
    }

    void stop() {
        std::unique_lock<std::mutex> lock(queueMutex);
        stopProcessing = true;
        condVar.notify_all();
    }

    void enqueue(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        condVar.notify_one();
    }
};

// Mock NoSQL database
class MockNoSqlDatabase : public NoSqlDatabase {
public:
    void store(const Event& event) override {
        // Simulate storing event in database
        std::cout << "Storing event: " << event.metadata << std::endl;
    }
};

// Mock logging service
class MockLoggingService : public LoggingService {
public:
    void log(const std::string& message) override {
        // Simulate logging message
        std::cout << "Log: " << message << std::endl;
    }
};

int main() {
    NoSqlDatabase* db = new MockNoSqlDatabase();
    LoggingService* logger = new MockLoggingService();

    EventProcessor processor(db, logger);
    processor.start();

    // Simulate enqueuing events
    processor.enqueue({std::time(nullptr), "type1", "metadata1"});
    processor.enqueue({std::time(nullptr), "type2", "metadata2"});

    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.stop();

    delete db;
    delete logger;

    return 0;
}
```

