                if (data != null) {
                    dataAggregator.aggregate(data);
                    if (dataAggregator.shouldBatch()) {
                        databaseConnection.saveBatch(dataAggregator.getBatch());
                        dataAggregator.clearBatch();
                    }
                } else {
                    // Handle intermittent connectivity
