use rdkafka::{ClientConfig, Consumer, TopicPartitionList};
use tokio::sync::mpsc;

pub struct KafkaConsumer {
    consumer: Consumer,
}

impl KafkaConsumer {
    pub fn new(broker_addrs: &str) -> Self {
        let consumer = ClientConfig::new()
            .set("bootstrap.servers", broker_addrs)
            .create()
            .expect("Failed to create Kafka consumer");

        KafkaConsumer { consumer }
    }

    pub async fn consume(&self, topic: &str) -> mpsc::Receiver<String> {
        let (tx, rx) = mpsc::channel(100);
        self.consumer.assign(&[TopicPartitionList::from_topic_partition(topic, 0)])
            .expect("Failed to assign partitions");

        tokio::spawn(async move {
            while let Some(message) = self.consumer.poll_once(std::time::Duration::from_secs(1)) {
                match message {
                    Ok(msg) => tx.send(String::from_utf8_lossy(&msg.payload.unwrap()).into_owned()).await.unwrap(),
                    Err(e) => println!("Error consuming message: {}", e),
                }
            }
        });

        rx
    }
}

