    std::map<std::string, std::string> metadata;
    std::vector<char> payload;
};

// Event processor interface
class IEventProcessor {
public:
    virtual void processEvent(const Event& event) = 0;
    virtual ~IEventProcessor() {}
};

// Network event receiver class
class NetworkEventReceiver : public IEventProcessor {
public:
    void processEvent(const Event& event) override {
        // Logic to receive network events and queue them for processing
        std::cout << "NetworkEventReceiver received event: " << event.eventType << std::endl;
        eventQueue.push(event);
        eventCond.notify_one();
    }

private:
    std::queue<Event> eventQueue;
    std::condition_variable eventCond;
};

// Event logging service class
class LoggingService {
public:
    void logEvent(const Event& event) {
        // Logic to log event to a specific logging service
        std::cout << "LoggingService logged event: " << event.eventType << std::endl;
    }
};

// Event processor thread class
class EventProcessorThread : public IEventProcessor {
public:
    EventProcessorThread(std::shared_ptr<NetworkEventReceiver> receiver, std::vector<std::shared_ptr<LoggingService>> loggingServices)
        : receiver(receiver), loggingServices(loggingServices) {}

    void start() {
        processorThread = std::thread(&EventProcessorThread::processEvents, this);
    }

    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(eventMutex);
            eventCond.wait(lock, [this] { return !eventQueue.empty(); });
            Event event = eventQueue.front();
            eventQueue.pop();
            lock.unlock();

            for (auto& service : loggingServices) {
                service->logEvent(event);
            }
        }
    }

private:
    std::shared_ptr<NetworkEventReceiver> receiver;
    std::vector<std::shared_ptr<LoggingService>> loggingServices;
    std::queue<Event> eventQueue;
    std::mutex eventMutex;
    std::condition_variable eventCond;
    std::thread processorThread;
};

// Main function to demonstrate the pipeline
int main() {
    auto receiver = std::make_shared<NetworkEventReceiver>();
    auto loggingService1 = std::make_shared<LoggingService>();
    auto loggingService2 = std::make_shared<LoggingService>();

    EventProcessorThread processor(receiver, {loggingService1, loggingService2});
    processor.start();

    // Simulate event reception
    Event event;
    event.eventType = "TYPE_1";
    receiver->processEvent(event);

    return 0;
}
```']

