const express = require('express');
const WebSocket = require('ws');
const redis = require('redis');
const axios = require('axios');

const app = express();
const wss = new WebSocket.Server({ port: 8080 });
const client = redis.createClient();

client.on('error', (err) => {
    console.error('Redis error:', err);
});

app.use(express.json());

wss.on('connection', (ws, req) => {
    ws.on('message', async (message) => {
        const data = JSON.parse(message);
        try {
            // Process IoT data
            await client.incr('total_events');
            // Forward to analytics service
            await axios.post('https://analytics-service.com/process', data);
        } catch (error) {
            console.error('Error processing data:', error);
        }
    });

    ws.on('close', () => {
        console.log('Client disconnected');
    });
});

app.get('/events', async (req, res) => {
    try {
        const totalEvents = await client.get('total_events');
        res.json({ totalEvents: parseInt(totalEvents || 0) });
    } catch (error) {
        console.error('Error fetching events:', error);
        res.status(500).json({ message: 'Internal Server Error' });
    }
});

app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
