// Import necessary libraries
use hyper::{Client, Request, Response, Uri};
use tokio::time::{self, Duration};
use std::collections::HashMap;
use hyper_tls::HttpsConnector;
use reqwest_middleware::{ClientBuilder, Middleware, Next};
use reqwest_retry::{RetryLayer, RetryTransientStatusCodes};
use reqwest::header::USER_AGENT;

// Define a trait for API configuration
trait ApiConfig {
    fn base_url(&self) -> String;
    fn auth_token(&self) -> Option<String>;
}

// Define a struct for API client
pub struct HttpClient<C: ApiConfig> {
    client: Client,
    config: C,
}

impl<C: ApiConfig> HttpClient<C> {
    pub fn new(config: C) -> Self {
        let https_connector = HttpsConnector::new();
        let retry_layer = RetryLayer::new_with_options(RetryTransientStatusCodes::default(), time::Duration::from_secs(1));
        let client = ClientBuilder::new()
            .with(retry_layer)
            .build::<_, hyper::Body>(https_connector);

        HttpClient { client, config }
    }

    pub async fn send_request(&self, path: &str) -> Result<Response<hyper::body::Body>, reqwest::Error> {
        let uri = format!("{}{}", self.config.base_url(), path);
        let request = Request::builder()
            .uri(uri)
            .header(USER_AGENT, "RustHttpClient/1.0")
            .method("GET")
            .body(hyper::Body::empty())?;

        if let Some(token) = self.config.auth_token() {
            request.headers_mut().insert("Authorization", format!("Bearer {}", token).parse()?);
        }

        self.client.request(request).await
    }
}

// Implement API configuration for a sample API
struct SampleApiConfig {
    base_url: String,
    auth_token: Option<String>,
}

impl ApiConfig for SampleApiConfig {
    fn base_url(&self) -> String {
        self.base_url.clone()
    }

    fn auth_token(&self) -> Option<String> {
        self.auth_token.clone()
    }
}

// Example usage
#[tokio::main]
async fn main() {
    let config = SampleApiConfig {
        base_url: "https://api.example.com".to_string(),
        auth_token: Some("your_auth_token_here".to_string()),
    };

    let client = HttpClient::new(config);
    match client.send_request("/endpoint").await {
        Ok(response) => println!("Response status: {}", response.status()),
        Err(e) => eprintln!("Error sending request: {:?}", e),
    }
}
