class TextureManager {
public:
    void loadTexture(const std::string& texturePath) {
        // Simulate loading a texture from a local or remote source
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(texturePath);
        condition_.notify_one();
    }

    void startLoadingThread() {
        loadThread_ = std::thread(&TextureManager::loadWorker, this);
    }

private:
    void loadWorker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !queue_.empty(); });
            auto texturePath = queue_.front();
            queue_.pop();
            lock.unlock();

            // Simulate loading process
            std::cout << "Loading texture: " << texturePath << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    }

    std::thread loadThread_;
    std::queue<std::string> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    TextureManager manager;
    manager.startLoadingThread();

    // Simulate loading multiple textures
    for (int i = 0; i < 10; ++i) {
        manager.loadTexture("texture" + std::to_string(i) + ".png");
    }

    return 0;
}
