using System;
using System.Collections.Concurrent;
using System.Data;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;

public class DistributedTextProcessor
{
    private readonly string _filePath;
    private readonly string _databaseConnectionString;
    private readonly int _batchSize;
    private readonly ConcurrentQueue<string> _linesQueue = new ConcurrentQueue<string>();
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
    private bool _isShuttingDown;

    public DistributedTextProcessor(string filePath, string databaseConnectionString, int batchSize)
    {
        _filePath = filePath;
        _databaseConnectionString = databaseConnectionString;
        _batchSize = batchSize;
    }

    public async Task StartProcessingAsync()
    {
        while (!_isShuttingDown)
        {
            if (_linesQueue.Count < _batchSize)
            {
                try
                {
                    await LoadNextBatchAsync();
                }
                catch (Exception ex)
                {
                    // Log exception and continue processing
                }
            }

            await ProcessBatchAsync();
            await Task.Delay(100); // Throttle to avoid busy-waiting
        }
    }

    public async Task StopProcessingAsync()
    {
        _isShuttingDown = true;
        await ProcessBatchAsync(); // Ensure all batches are processed before shutting down
    }

    private async Task LoadNextBatchAsync()
    {
        using (var reader = new StreamReader(_filePath))
        {
            while (!reader.EndOfStream)
            {
                if (_linesQueue.Count >= _batchSize)
                    break;

                string line;
                if (await reader.ReadLineAsync() is { } lineValue)
                {
                    _linesQueue.Enqueue(lineValue);
                }
            }
        }
    }

    private async Task ProcessBatchAsync()
    {
        var batch = new List<string>();
        for (int i = 0; i < _batchSize && !_linesQueue.IsEmpty; i++)
        {
            if (_linesQueue.TryDequeue(out string line))
            {
                batch.Add(line);
            }
        }

        if (!batch.Any())
            return;

        using (var sha256 = SHA256.Create())
        {
            var hashes = await Task.WhenAll(batch.Select(async line =>
            {
                var hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(line));
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            }));

            using (var connection = new SqlConnection(_databaseConnectionString))
            {
                await connection.OpenAsync();
                using (var transaction = connection.BeginTransaction())
                {
                    foreach (var hash in hashes)
                    {
                        var command = new SqlCommand("INSERT INTO TextHashes (Hash) VALUES (@Hash)", connection, transaction);
                        command.Parameters.AddWithValue("@Hash", hash);
                        await command.ExecuteNonQueryAsync();
                    }

                    await transaction.CommitAsync();
                }
            }
        }
    }
}

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddHttpClient("ApiClient", client =>
        {
            client.BaseAddress = new Uri("http://api.example.com/");
            client.DefaultRequestHeaders.Accept.Clear();
            client.DefaultRequestHeaders.Accept.Add(new System.Net.Http.Headers.MediaTypeWithQualityHeaderValue("application/json"));
        });

        services.AddSingleton<DistributedTextProcessor>();
    }

    public void Configure(IApplicationBuilder app)
    {
        var processor = app.ApplicationServices.GetRequiredService<DistributedTextProcessor>();
        _ = Task.Run(async () => await processor.StartProcessingAsync());

        // Add API endpoints here
    }
}
```

This code provides a basic structure for the distributed text processing system. It uses a `ConcurrentQueue` to manage lines from the file, processes them in batches using SHA-256 hashing, and stores the results in a SQL Server database. The system includes mechanisms for graceful shutdown, error handling, and logging.

Key components:
- `DistributedTextProcessor`: Manages the reading of the text file and processing of lines.
- `Startup`: Configures dependency injection and sets up the API client.

This example can be extended with additional features such as caching strategies, message queues, comprehensive logging, and automated testing.']

