using System.Threading.Tasks;
using Microsoft.Owin.Hosting;

class TextProcessor : IDisposable
{
    private readonly DbContext _dbContext;
    private readonly ConcurrentQueue<string> _fileQueue = new ConcurrentQueue<string>();
    private HttpClient _httpClient;
    private bool _disposed;

    public TextProcessor(string connectionString)
    {
        _dbContext = new HashDbContext(connectionString);
        _httpClient = new HttpClient();
        // Start processing files from external storage
    }

    public void EnqueueFile(string filePath)
    {
        _fileQueue.Enqueue(filePath);
    }

    public async Task ProcessFilesAsync()
    {
        while (!_disposed)
        {
            if (_fileQueue.TryDequeue(out var filePath))
            {
                try
                {
                    await ProcessFileAsync(filePath);
                }
                catch (Exception ex)
                {
                    LogError(ex, $"Failed to process file: {filePath}");
                }
            }
            else
            {
                await Task.Delay(100); // No work to do, sleep for a bit
            }
        }
    }

    private async Task ProcessFileAsync(string filePath)
    {
        using (var reader = new StreamReader(filePath))
        {
            while (!reader.EndOfStream)
            {
                var line = await reader.ReadLineAsync();
                var hash = ComputeSHA256Hash(line);
                _dbContext.Hashes.Add(new Hash { Line = line, Sha256Hash = hash });
            }
        }

        await _dbContext.SaveChangesAsync();
    }

    private string ComputeSHA256Hash(string input)
    {
        using (var sha256 = SHA256.Create())
        {
            var bytes = sha256.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
            return BitConverter.ToString(bytes).Replace("-", "").ToLower();
        }
    }

    public async Task<string> GetHashAsync(string line)
    {
        try
        {
            // Check cache first
            var cachedHash = _cache.Get(line);
            if (cachedHash != null)
                return cachedHash;

            // Retrieve from database
            var dbHash = await _dbContext.Hashes.FirstOrDefaultAsync(h => h.Line == line);
            if (dbHash != null)
            {
                _cache.Add(line, dbHash.Sha256Hash);
                return dbHash.Sha256Hash;
            }

            // Call REST API if not found
            var apiResponse = await _httpClient.GetStringAsync($"https://api.example.com/hashes?line={Uri.EscapeDataString(line)}");
            var newHash = JsonConvert.DeserializeObject<HashResult>(apiResponse).Sha256Hash;

            // Store in cache and database
            _cache.Add(line, newHash);
            await _dbContext.Hashes.AddAsync(new Hash { Line = line, Sha256Hash = newHash });
            await _dbContext.SaveChangesAsync();

            return newHash;
        }
        catch (Exception ex)
        {
            LogError(ex, $"Failed to retrieve hash for line: {line}");
            throw;
        }
    }

    private void LogError(Exception ex, string message)
    {
        // Log error using a C function that uses snprintf and va_start/va_end
        var logMessage = FormatLogMessage(message, ex);
        _logFunction(logMessage);
    }

    private string FormatLogMessage(string message, Exception ex)
    {
        // Implement flexible message formatting using snprintf and va_start/va_end
        return $"Error: {message}, Exception: {ex.Message}";
    }

    public void Dispose()
    {
        _disposed = true;
        _httpClient.Dispose();
        _dbContext.Dispose();
    }
}

class HashDbContext : DbContext
{
