        apiServer.start();
        messageBrokerManager.connect();
        databaseManager.connect();
    }

    public void stop() {
        apiServer.stop();
        messageBrokerManager.disconnect();
        databaseManager.disconnect();
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public void processEvent(Event event) {
        executor.execute(() -> {
            try {
                logger.log("Processing event: " + event);
                messageBrokerManager.routeMessage(event);
                databaseManager.storeEvent(event);
            } catch (Exception e) {
                retryMechanism.handleRetry(event, e);
                logger.error("Failed to process event: " + event, e);
            }
        });
    }

