// C++ code for distributed logging and monitoring framework

#include <grpcpp/grpcpp.h>
#include "logging.grpc.pb.h"
#include <iostream>

using grpc::Server;
using grpc::ServerBuilder;
using grpc::ServerContext;
using grpc::Status;

class LoggingServiceImpl : public logging::LoggingService::Service {
    Status Log(ServerContext* context, const logging::LogRequest* request,
              logging::LogResponse* response) override {
        // Process the log message
        std::cout << "Received log: " << request->message() << std::endl;
        response->set_status("Log received");
        return Status::OK;
    }
};

void RunServer() {
    std::string server_address = "[::]:50051";
    LoggingServiceImpl service;

    ServerBuilder builder;
    builder.AddListeningPort(server_address, grpc::InsecureServerCredentials());
    builder.RegisterService(&service);
    std::unique_ptr<Server> server(builder.BuildAndStart());
    std::cout << "Starting gRPC server on port 50051" << std::endl;
    server->Wait();
}

int main(int argc, char** argv) {
    RunServer();
    return 0;
}
