#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct LTE_PHY_TEST_CONFIG_T {
    int frequency_band;
    char modulation_scheme[50];
    // Other configuration fields...
} LTE_PHY_TEST_CONFIG_T;

typedef struct ConfigNode {
    LTE_PHY_TEST_CONFIG_T config;
    struct ConfigNode* next;
} ConfigNode;

ConfigNode* pool_head = NULL;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pool_cv = PTHREAD_COND_INITIALIZER;

LTE_PHY_TEST_CONFIG_T* allocate_config() {
    pthread_mutex_lock(&pool_mutex);
    while (pool_head == NULL) {
        pthread_cond_wait(&pool_cv, &pool_mutex);
    }
    ConfigNode* node = pool_head;
    pool_head = pool_head->next;
    pthread_mutex_unlock(&pool_mutex);
    return &node->config;
}

void deallocate_config(LTE_PHY_TEST_CONFIG_T* config) {
    ConfigNode* node = (ConfigNode*)malloc(sizeof(ConfigNode));
    node->config = *config;
    node->next = pool_head;
    pthread_mutex_lock(&pool_mutex);
    pool_head = node;
    pthread_cond_signal(&pool_cv);
    pthread_mutex_unlock(&pool_mutex);
}

// Example usage
int main() {
    LTE_PHY_TEST_CONFIG_T* config = allocate_config();
    // Use the config...
    deallocate_config(config);
    return 0;
}
