class NFAPduManager {
public:
    NFAPduManager(int num_pdus, unsigned int seed, int log_level)
        : m_num_pdus(num_pdus), m_seed(seed), m_log_level(log_level) {}

    void start() {
        m_thread = std::thread(&NFAPduManager::run, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(m_mutex);
            m_stop = true;
        }
        m_condition.notify_all();
        if (m_thread.joinable()) {
            m_thread.join();
        }
    }

private:
    void run() {
        std::mt19937 generator(m_seed);
        std::uniform_int_distribution<int> distribution(0, 100);

        while (true) {
            {
                std::unique_lock<std::mutex> lock(m_mutex);
                m_condition.wait(lock, [this] { return m_stop || !m_stop; });
                if (m_stop) break;
            }

            for (int i = 0; i < m_num_pdus; ++i) {
                NFAPI_CRC_INDICATION_PDU_T pdu;
                pdu.pdu_id = distribution(generator);
                // Process pdu...
            }
        }
    }

private:
    int m_num_pdus;
    unsigned int m_seed;
    int m_log_level;
    std::thread m_thread;
    std::mutex m_mutex;
    std::condition_variable m_condition;
    bool m_stop = false;
};

int main() {
    NFAPduManager manager(100, 42, 2);
    manager.start();
    std::this_thread::sleep_for(std::chrono::seconds(10));
    manager.stop();
    return 0;
