    std::vector<std::thread> workerThreads;
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable queueCond;
    bool running;

public:
    EventProcessingFramework() : running(true) {
        // Initialize worker threads
        for (int i = 0; i < 10; ++i) {
            workerThreads.emplace_back(&EventProcessingFramework::workerThread, this);
        }
    }

    ~EventProcessingFramework() {
        running = false;
        queueCond.notify_all();
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

    void submitEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        queueCond.notify_one();
    }

    void submitFileRequest(const FileRequest& request) {
