    }

private:
    void workerThread() {
        while (running) {
            Event event;
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCond.wait(lock, [this] { return !eventQueue.empty() || !running; });
            if (!running) break;
            event = eventQueue.front();
            eventQueue.pop();
            lock.unlock();

            processor.process(event);
            messagingService.sendEvent(event);
            analyticsPlatform.logEvent(event);
            logAggregationTool.aggregateLogs({event});
        }
    }
};

int main() {
