typedef struct {
    // Define NFAPI_CRC_INDICATION_PDU_T structure here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInfo;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcFlag;
} RxDataEntry;

typedef struct {
    RxDataEntry *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NfaapiPduList;

void initNfaapiPduList(NfaapiPduList *list, size_t initialCapacity) {
    list->count = 0;
    list->capacity = initialCapacity;
    list->entries = (RxDataEntry *)malloc(initialCapacity * sizeof(RxDataEntry));
    pthread_mutex_init(&list->lock, NULL);
}

void freeNfaapiPduList(NfaapiPduList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

void addEntryToPduList(NfaapiPduList *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->entries = realloc(list->entries, list->capacity * sizeof(RxDataEntry));
    }
    // Populate new entry with data from pdu
    list->entries[list->count].rxUeInfo = pdu->rxUeInformationTag;
    list->entries[list->count].rnti = pdu->RNTI;
    list->entries[list->count].crcFlag = pdu->CRC_INDICATION_REL8_TAG;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void generateNfapiPduList(NfaapiPduList *list) {
    // Generate and add NFAPI_CRC_INDICATION_PDU_T structures to the list
    for (int i = 0; i < 100; i++) { // Example loop
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Populate pdu with random data or from other sources
        pthread_mutex_lock(&list->lock);
        addEntryToPduList(list, &pdu);
        pthread_mutex_unlock(&list->lock);
    }
}

int main() {
    NfaapiPduList list;
    initNfaapiPduList(&list, 10);

    // Simulate data generation and processing
    generateNfapiPduList(&list);

    freeNfaapiPduList(&list);
    return 0;
}
```

