import os
import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError
from google.cloud import storage
from azure.storage.blob import BlobServiceClient
from retrying import retry

class ThemeCache:
    def __init__(self):
        self.aws_client = boto3.client('s3')
        self.google_client = storage.Client()
        self.azure_client = BlobServiceClient.from_connection_string(os.getenv('AZURE_CONNECTION_STRING'))

    @retry(stop_max_attempt_number=5, wait_exponential_multiplier=1000)
    def download_theme(self, bucket_name, object_name):
        try:
            if 'aws' in bucket_name:
                response = self.aws_client.get_object(Bucket=bucket_name, Key=object_name)
                return response['Body'].read()
            elif 'google' in bucket_name:
                blob = self.google_client.bucket(bucket_name).blob(object_name)
                return blob.download_as_bytes()
            elif 'azure' in bucket_name:
                container_name, blob_name = object_name.split('/')
                blob_client = self.azure_client.get_blob_client(container=container_name, blob=blob_name)
                return blob_client.download_blob().readall()
        except (NoCredentialsError, PartialCredentialsError):
            raise Exception("Authentication failed for the specified cloud storage service")
        except Exception as e:
            raise Exception(f"Failed to download theme: {e}")

    def update_theme(self, bucket_name, object_name, new_theme_data):
        try:
            if 'aws' in bucket_name:
                self.aws_client.put_object(Bucket=bucket_name, Key=object_name, Body=new_theme_data)
            elif 'google' in bucket_name:
                blob = self.google_client.bucket(bucket_name).blob(object_name)
                blob.upload_from_string(new_theme_data)
            elif 'azure' in bucket_name:
                container_name, blob_name = object_name.split('/')
                blob_client = self.azure_client.get_blob_client(container=container_name, blob=blob_name)
                blob_client.upload_blob(new_theme_data)
        except Exception as e:
            raise Exception(f"Failed to update theme: {e}")

# Example usage
cache = ThemeCache()
theme_data = cache.download_theme('aws-bucket', 'theme.png')
cache.update_theme('azure-bucket', 'new-theme.png', theme_data)
