#include <stdlib.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t count;
    size_t max_pdus;
    pthread_mutex_t lock;
} NFAPI_PDUList;

NFAPI_PDUList* create_nfaapi_pdu_list(size_t max_pdus) {
    NFAPI_PDUList* list = (NFAPI_PDUList*)malloc(sizeof(NFAPI_PDUList));
    if (!list) return NULL;

    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(max_pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->max_pdus = max_pdus;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_nfaapi_pdu_list(NFAPI_PDUList* list) {
    if (list) {
        free(list->pdus);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_pdu_to_list(NFAPI_PDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_pdus) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->pdus[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu_from_list(NFAPI_PDUList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return NULL; // Invalid index
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->pdus[index];
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

int remove_pdu_from_list(NFAPI_PDUList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid index
    }
    for (size_t i = index; i < list->count - 1; ++i) {
        list->pdus[i] = list->pdus[i + 1];
    }
    list->count--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}
