#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    pthread_mutex_t lock;
} PduWrapper;

typedef struct {
    PduWrapper *pool;
    size_t max_pdus;
    size_t pool_size;
    pthread_mutex_t pool_lock;
} PduPool;

PduPool *create_pdu_pool(size_t max_pdus) {
    PduPool *pool = malloc(sizeof(PduPool));
    if (pool == NULL) return NULL;

    pool->max_pdus = max_pdus;
    pool->pool_size = 0;
    pool->pool = calloc(max_pdus, sizeof(PduWrapper));
    if (pool->pool == NULL) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->pool_lock, NULL);

    for (size_t i = 0; i < max_pdus; i++) {
        pthread_mutex_init(&pool->pool[i].lock, NULL);
    }

    return pool;
}

void destroy_pdu_pool(PduPool *pool) {
    if (pool == NULL) return;

    for (size_t i = 0; i < pool->max_pdus; i++) {
        pthread_mutex_destroy(&pool->pool[i].lock);
    }
    free(pool->pool);
    pthread_mutex_destroy(&pool->pool_lock);
    free(pool);
}

PduWrapper *allocate_pdu(PduPool *pool) {
    if (pool == NULL || pool->pool_size >= pool->max_pdus) return NULL;

    PduWrapper *pdu = &pool->pool[pool->pool_size];
    pthread_mutex_lock(&pool->pool_lock);
    pthread_mutex_lock(&pdu->lock);
    pool->pool_size++;
    pthread_mutex_unlock(&pool->pool_lock);

    return pdu;
}

void deallocate_pdu(PduPool *pool, PduWrapper *pdu) {
    if (pool == NULL || pdu == NULL) return;

    pthread_mutex_lock(&pdu->lock);
    pthread_mutex_lock(&pool->pool_lock);
    int index = -1;
    for (size_t i = 0; i < pool->max_pdus; i++) {
        if (&pool->pool[i] == pdu) {
            index = i;
            break;
        }
    }
    if (index != -1) {
        pool->pool_size--;
        memcpy(&pool->pool[index], &pool->pool[pool->pool_size], sizeof(PduWrapper));
        pthread_mutex_unlock(&pool->pool_lock);
    } else {
        pthread_mutex_unlock(&pool->pool_lock);
    }
    pthread_mutex_unlock(&pdu->lock);
}
