class Event {
public:
    std::chrono::system_clock::time_point timestamp;
    std::string eventType;
    std::map<std::string, std::string> metadata;

    Event(std::chrono::system_clock::time_point ts, const std::string& type, const std::map<std::string, std::string>& data)
        : timestamp(ts), eventType(type), metadata(data) {}
};

class EventLoggingService {
public:
    virtual void logEvent(const Event& event) = 0;
    virtual ~EventLoggingService() {}
};

class SecureAsyncLoggingService : public EventLoggingService {
public:
    void logEvent(const Event& event) override {
        // Simulate secure, asynchronous communication
        // Handle network failures and outages with retries
    }
};

class EventProcessingPipeline {
public:
    EventProcessingPipeline(std::shared_ptr<EventLoggingService> loggingService)
        : loggingService(loggingService), running(false) {}

    void start() {
        running = true;
        workerThread = std::thread(&EventProcessingPipeline::processEvents, this);
    }

    void stop() {
        running = false;
        condition.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

    void addEvent(const Event& event) {
        std::unique_lock<std::mutex> lock(mutex);
        events.push(event);
        condition.notify_one();
    }

private:
    std::shared_ptr<EventLoggingService> loggingService;
    std::thread workerThread;
    bool running;
    std::queue<Event> events;
    std::mutex mutex;
    std::condition_variable condition;

    void processEvents() {
        while (running) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !events.empty() || !running; });
            if (!running && events.empty()) {
                break;
            }
            Event event = events.front();
            events.pop();
            lock.unlock();

            try {
                loggingService->logEvent(event);
            } catch (const std::exception& e) {
                // Handle logging failures with retries and alerts
            }
        }
    }
};

