const express = require('express');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const cache = require('memory-cache');
const axios = require('axios');

const app = express();
app.use(cors());
app.use(express.json());

// Rate limiting middleware
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use('/api', apiLimiter);

// Request validation and normalization middleware
function validateAndNormalizeRequest(req, res, next) {
  // Add your validation and normalization logic here
  const normalizedData = { /* normalized data */ };
  req.normalizedData = normalizedData;
  next();
}

app.use(validateAndNormalizeRequest);

// Caching strategy
const cacheDuration = 60 * 1000; // 1 minute

function getCachedResponse(req, key) {
  return cache.get(key);
}

function setCachedResponse(key, response, duration) {
  cache.put(key, response, duration);
}

// Fallback mechanism for external services
async function callBackendService(url, data) {
  try {
    const response = await axios.post(url, data);
    return response.data;
  } catch (error) {
    console.error('Error calling backend service:', error);
    // Fallback logic here
    return { fallback: true, data: null };
  }
}

// Pluggable authentication middleware
const authMiddleware = async (req, res, next) => {
  const token = req.headers['authorization'];
  try {
    const decodedToken = await verifyToken(token);
    req.user = decodedToken;
    next();
  } catch (error) {
    return res.status(401).json({ message: 'Invalid token' });
  }
};

app.use(authMiddleware);

// Flexible routing mechanism
const serviceMap = {
  // Service mappings based on dynamic configurations
};

function getServiceUrl(serviceId) {
  return serviceMap[serviceId];
}

app.post('/api/service/:serviceId', async (req, res) => {
  const { serviceId } = req.params;
  const { data } = req.normalizedData;

  const serviceUrl = getServiceUrl(serviceId);
  if (!serviceUrl) {
    return res.status(404).json({ message: 'Service not found' });
  }

  const key = `${serviceId}-${JSON.stringify(data)}`;
  const cachedResponse = getCachedResponse(req, key);

  if (cachedResponse) {
    return res.json(cachedResponse);
  }

  const response = await callBackendService(serviceUrl, data);
  setCachedResponse(key, response, cacheDuration);
  res.json(response);
});

// Error handling and logging
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);
  res.status(500).json({ message: 'Internal Server Error' });
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
