import java.io.IOException;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class DNSResolver {

    public static u_char[] resolveDNS(String hostname) {
        try {
            InetAddress address = InetAddress.getByName(hostname);
            byte[] ipAddress = address.getAddress();
            return convertToUCharArray(ipAddress);
        } catch (UnknownHostException e) {
            System.err.println("Error resolving DNS for hostname: " + hostname);
            return null;
        }
    }

    private static u_char[] convertToUCharArray(byte[] byteArray) {
        u_char[] uCharArray = new u_char[byteArray.length];
        for (int i = 0; i < byteArray.length; i++) {
            uCharArray[i] = new u_char(byteArray[i]);
        }
        return uCharArray;
    }

    public static void main(String[] args) {
        String hostname = "example.com";
        u_char[] ipAddress = resolveDNS(hostname);
        if (ipAddress != null) {
            System.out.println("IP Address: " + bytesToHex(ipAddress));
        } else {
            System.out.println("Failed to resolve IP address for hostname.");
        }
    }

    private static String bytesToHex(u_char[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (u_char b : bytes) {
            sb.append(String.format("%02X ", b.getValue()));
        }
        return sb.toString().trim();
    }
}

class u_char {
    private byte value;

    public u_char(byte value) {
        this.value = value;
    }

    public byte getValue() {
        return value;
    }
}
```

