#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <atomic>
#include <string>
#include <vector>
#include <openssl/ssl.h>

class RealtimeLogAggregator {
public:
    RealtimeLogAggregator(int numWorkers, int batchSize) 
        : stop(false), numWorkers(numWorkers), batchSize(batchSize) {
        for (int i = 0; i < numWorkers; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::vector<std::string> batch;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this] { return !this->stop || !this->logQueue.empty(); });
                        if (this->stop && this->logQueue.empty()) break;
                        int count = 0;
                        while (!this->logQueue.empty() && count < batchSize) {
                            batch.push_back(this->logQueue.front());
                            this->logQueue.pop();
                            ++count;
                        }
                    }
                    processBatch(batch);
                }
            });
        }
    }

    ~RealtimeLogAggregator() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void log(const std::string& logEntry) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            logQueue.push(logEntry);
        }
        condition.notify_one();
    }

private:
    void processBatch(const std::vector<std::string>& batch) {
        // Simulate data processing
        for (const auto& log : batch) {
            std::cout << "Processing: " << log << std::endl;
        }
        // Forward to analytics service
        forwardToAnalyticsService(batch);
    }

    void forwardToAnalyticsService(const std::vector<std::string>& logs) {
        SSL_CTX* ctx = setupSSLContext();
        if (ctx != nullptr) {
            sendLogs(ctx, logs);
            SSL_CTX_free(ctx);
        }
    }

    SSL_CTX* setupSSLContext() {
        // Initialize SSL context
        return SSL_CTX_new(TLS_client_method());
