#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_KEY_SIZE 32
#define MAX_IV_SIZE 16
#define MAX_TAG_SIZE 16

typedef struct {
    unsigned char key[MAX_KEY_SIZE];
    unsigned char iv[MAX_IV_SIZE];
    unsigned char tag[MAX_TAG_SIZE];
} AES_GCM_CTX;

int aes_gcm_encrypt(const unsigned char *plaintext, size_t plaintext_len,
                   const unsigned char *aad, size_t aad_len,
                   unsigned char *ciphertext, unsigned char *tag,
                   AES_GCM_CTX *ctx) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return -1;

    if (EVP_EncryptInit_ex(cipher_ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    if (aad_len > 0 && EVP_EncryptUpdate(cipher_ctx, NULL, &aad_len, aad, aad_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    int len = 0;
    if (EVP_EncryptUpdate(cipher_ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    size_t ciphertext_len = len;

    if (EVP_EncryptFinal_ex(cipher_ctx, ciphertext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    ciphertext_len += len;

    if (EVP_CIPHER_CTX_ctrl(cipher_ctx, EVP_CTRL_GCM_SET_TAG, sizeof(ctx->tag), tag) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(cipher_ctx);
    return ciphertext_len;
}

int aes_gcm_decrypt(const unsigned char *ciphertext, size_t ciphertext_len,
                   const unsigned char *aad, size_t aad_len,
                   const unsigned char *tag, unsigned char *plaintext,
                   AES_GCM_CTX *ctx) {
    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) return -1;

    if (EVP_DecryptInit_ex(cipher_ctx, EVP_aes_256_gcm(), NULL, ctx->key, ctx->iv) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    if (aad_len > 0 && EVP_EncryptUpdate(cipher_ctx, NULL, &aad_len, aad, aad_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    int len = 0;
    if (EVP_DecryptUpdate(cipher_ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    size_t plaintext_len = len;

    if (EVP_CIPHER_CTX_ctrl(cipher_ctx, EVP_CTRL_GCM_SET_TAG, sizeof(ctx->tag), tag) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }

    if (EVP_DecryptFinal_ex(cipher_ctx, plaintext + len, &len) != 1) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(cipher_ctx);
    return plaintext_len;
}

int main() {
    unsigned char key[MAX_KEY_SIZE] = {0};
    if (!RAND_bytes(key, sizeof(key))) return -1;

    AES_GCM_CTX ctx;
    memcpy(ctx.key, key, sizeof(key));
    // Initialize IV and tag with appropriate values

    unsigned char plaintext[] = "Hello, World!";
    size_t plaintext_len = strlen(plaintext) + 1;

    unsigned char ciphertext[256];
    unsigned char tag[MAX_TAG_SIZE];

    int encrypted_len = aes_gcm_encrypt(plaintext, plaintext_len, NULL, 0,
                                        ciphertext, tag, &ctx);
    if (encrypted_len < 0) return -1;

    unsigned char decrypted_text[256];
    int decrypted_len = aes_gcm_decrypt(ciphertext, encrypted_len, NULL, 0,
                                       tag, decrypted_text, &ctx);
    if (decrypted_len < 0) return -1;

    printf("Decrypted Text: %s\n", decrypted_text);

    return 0;
}
