import { LocalStorage, Cookies } from 'js-cookie';
import axios, { AxiosInstance, AxiosError } from 'axios';

interface Preference {
  id: string;
  value: any;
}

class PreferencesService {
  private localStorageKey = 'userPreferences';
  private apiClient: AxiosInstance;
  private cookieName = 'sessionPrefs';
  private lastSyncTime: number;

  constructor(apiUrl: string) {
    this.apiClient = axios.create({
      baseURL: apiUrl,
      timeout: 5000,
    });
    this.lastSyncTime = localStorage.getItem('lastSyncTime') ? parseInt(localStorage.getItem('lastSyncTime')) : 0;
  }

  private async fetchPreferencesFromAPI(): Promise<Preference[]> {
    try {
      const response = await this.apiClient.get('/preferences');
      return response.data;
    } catch (error: AxiosError) {
      if (error.response && error.response.status === 429) {
        // Handle rate limit
      }
      console.error('Failed to fetch preferences from API', error);
      throw error;
    }
  }

  private async savePreferencesToAPI(preferences: Preference[]): Promise<void> {
    try {
      await this.apiClient.put('/preferences', preferences);
      localStorage.setItem('lastSyncTime', String(Date.now()));
    } catch (error) {
      console.error('Failed to save preferences to API', error);
      throw error;
    }
  }

  private loadPreferencesFromLocalStorage(): Preference[] {
    const prefs = LocalStorage.getItem(this.localStorageKey);
    return prefs ? JSON.parse(prefs) : [];
  }

  private savePreferencesToLocalStorage(preferences: Preference[]): void {
    LocalStorage.setItem(this.localStorageKey, JSON.stringify(preferences));
  }

  private loadPreferencesFromCookies(): Preference[] {
    const prefs = Cookies.get(this.cookieName);
    return prefs ? JSON.parse(prefs) : [];
  }

  private savePreferencesToCookies(preferences: Preference[]): void {
    Cookies.set(this.cookieName, JSON.stringify(preferences), { expires: 30 });
  }

  public async updatePreference(id: string, value: any): Promise<void> {
    const preferences = await this.getAllPreferences();
    const index = preferences.findIndex(p => p.id === id);
    if (index !== -1) {
      preferences[index].value = value;
      await this.savePreferences(preferences);
    }
  }

  public async getAllPreferences(): Promise<Preference[]> {
    let preferences: Preference[] = [];

    preferences = preferences.concat(this.loadPreferencesFromLocalStorage());
    preferences = preferences.concat(this.loadPreferencesFromCookies());

    try {
      const apiPrefs = await this.fetchPreferencesFromAPI();
      preferences = preferences.concat(apiPrefs);
      await this.savePreferences(preferences);
    } catch (error) {
      // Fallback to local storage if API is unavailable
      console.warn('Using local preferences due to API failure');
    }

    return preferences;
  }

  private async savePreferences(preferences: Preference[]): Promise<void> {
    await this.savePreferencesToLocalStorage(preferences);
    await this.savePreferencesToCookies(preferences);
    await this.savePreferencesToAPI(preferences);
  }
}

// Usage
const prefsService = new PreferencesService('https://api.example.com');
prefsService.updatePreference('theme', 'dark').then(() => {
  console.log('Preference updated successfully');
}).catch((error) => {
  console.error('Failed to update preference', error);
});
