import json
from abc import ABC, abstractmethod
from datetime import datetime

class Serializable(ABC):
    @abstractmethod
    def serialize(self) -> str:
        pass

    @classmethod
    def deserialize(cls, data: str) -> 'Serializable':
        raise NotImplementedError("Deserialization method must be implemented in subclasses")

class LogEntry(Serializable):
    def __init__(self, source: str, timestamp: datetime, message: str):
        self.source = source
        self.timestamp = timestamp
        self.message = message

    def serialize(self) -> str:
        return json.dumps({
            'source': self.source,
            'timestamp': self.timestamp.isoformat(),
            'message': self.message
        })

    @classmethod
    def deserialize(cls, data: str) -> 'LogEntry':
        try:
            log_data = json.loads(data)
            return cls(log_data['source'], datetime.fromisoformat(log_data['timestamp']), log_data['message'])
        except json.JSONDecodeError as e:
            print(f"Failed to decode JSON: {e}")
            return None

# Example usage
log_entry = LogEntry('IoT Device', datetime.now(), 'Temperature reading: 23.5°C')
serialized_log = log_entry.serialize()
print(serialized_log)

deserialized_log = LogEntry.deserialize(serialized_log)
if deserialized_log:
    print(f"Deserialized Log Entry - Source: {deserialized_log.source}, Timestamp: {deserialized_log.timestamp}, Message: {deserialized_log.message}")
```

