using System;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class StreamingDataProcessor
{
    private readonly ConcurrentQueue<StreamData> _dataQueue = new();
    private readonly Dictionary<string, DataFormatHandler> _formatHandlers = new();
    private readonly ILogger _logger;
    private Task _workerTask;
    private CancellationTokenSource _cancellationTokenSource;

    public StreamingDataProcessor(ILogger logger)
    {
        _logger = logger;
        InitializeFormatHandlers();
        StartWorker();
    }

    ~StreamingDataProcessor()
    {
        StopWorker();
    }

    public void AddData(StreamData data)
    {
        if (_dataQueue.Count < 100) // Arbitrary limit for demonstration
        {
            _dataQueue.Enqueue(data);
        }
        else
        {
            _logger.LogWarning("Data queue is full. Dropping data.");
        }
    }

    private void InitializeFormatHandlers()
    {
        _formatHandlers["json"] = new JsonFormatHandler();
        _formatHandlers["csv"] = new CsvFormatHandler();
        // Add other format handlers as needed
    }

    private async Task Worker(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            if (_dataQueue.TryDequeue(out var data))
            {
                try
                {
                    await ProcessDataAsync(data, cancellationToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing data.");
                }
            }
            else
            {
                await Task.Delay(100); // Sleep to avoid busy-waiting
            }
        }
    }

    private async Task ProcessDataAsync(StreamData data, CancellationToken cancellationToken)
    {
        if (_formatHandlers.TryGetValue(data.Format, out var handler))
        {
            var transformedData = handler.Transform(data.Content);
            await PerformAggregationAsync(transformedData, cancellationToken);
        }
        else
        {
            _logger.LogWarning($"No handler for format: {data.Format}");
        }
    }

    private async Task PerformAggregationAsync(string data, CancellationToken cancellationToken)
    {
        // Implement aggregation logic here
        _logger.LogInformation("Processing and aggregating data.");
    }

    public void StartWorker()
    {
        _cancellationTokenSource = new CancellationTokenSource();
        _workerTask = Worker(_cancellationTokenSource.Token);
    }

    public void StopWorker()
    {
        if (_workerTask != null)
        {
            _cancellationTokenSource.Cancel();
            _workerTask.Wait();
            _logger.LogInformation("Worker task stopped.");
        }
    }
}

