class NetworkMonitor {
public:
    void addLogEntry(const std::string& log) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.push_back(log);
        condition_.notify_one();
    }

    void processLogs() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !logs_.empty(); });
            auto log = logs_.back();
            logs_.pop_back();
            lock.unlock();

