class LogNormalizer {
public:
    static void normalizeLog(std::string& log, const std::unordered_map<std::string, std::string>& mapping) {
        for (const auto& [key, value] : mapping) {
            size_t pos = 0;
            while ((pos = log.find(key, pos)) != std::string::npos) {
                log.replace(pos, key.length(), value);
                pos += value.length();
            }
        }
    }
};

class DisjointPairCounter {
public:
    static int countDisjointPairs(const std::vector<int>& arr) {
        UnionFind uf(arr.size());
        for (size_t i = 0; i < arr.size(); ++i) {
            for (size_t j = i + 1; j < arr.size(); ++j) {
                if (arr[i] != arr[j]) {
                    uf.unionSet(i, j);
                }
            }
        }

        std::unordered_set<int> disjointGroups;
        for (size_t i = 0; i < arr.size(); ++i) {
            disjointGroups.insert(uf.find(i));
        }

        return disjointGroups.size();
    }
};

class UnionFind {
public:
    UnionFind(size_t size) : parent_(size), rank_(size, 1) {
        std::iota(parent_.begin(), parent_.end(), 0);
    }

    int find(int x) {
        if (parent_[x] != x) {
            parent_[x] = find(parent_[x]);
        }
        return parent_[x];
    }

    void unionSet(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank_[rootX] > rank_[rootY]) {
                parent_[rootY] = rootX;
            } else if (rank_[rootX] < rank_[rootY]) {
                parent_[rootX] = rootY;
            } else {
                parent_[rootY] = rootX;
                rank_[rootX]++;
            }
        }
    }

private:
    std::vector<int> parent_;
    std::vector<int> rank_;
};

int countDisjointPairsInArray(const std::vector<int>& arr) {
    auto start = std::chrono::high_resolution_clock::now();
    int result = DisjointPairCounter::countDisjointPairs(arr);
    auto end = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double, std::milli> ms_double = end - start;
    std::cout << "Time taken: " << ms_double.count() << " milliseconds" << std::endl;

    return result;
}

enum class LogFormat {
    JSON,
    CSV,
    STRUCTURED_EVENT_LOG
};
